    #[test]
    fn stoud_memory_stack_lowers_thread_bounds_and_trace_ownership_to_native_symbols() {
        let source = r#"
use <memory:stack>;
use <collections:result>;

stackMaterialization :: runtime {
    fn:
        run() -> bool {
            limit >> u64 <- stackLimit();
            depth >> u64 <- stackDepth();
            remaining >> u64 <- stackRemaining();
            trace >> StackTraceHandle <- stackTrace();
            frames >> u64 <- stackTraceLen(trace);
            frame >> Result<addr, MemoryError> <- stackTraceFrame(trace, 0);
            ok >> bool <- limit > 0 && depth > 0 && remaining > 0 &&
                frames > 0 && isOk(frame) && stackTraceRelease(trace);
            return ok;
        }

    ref main ->> run;

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let run = regular_function(&ir, "run");
        for target in [
            "nC.runtime.stack.stackDepth",
            "nC.runtime.stack.stackLimit",
            "nC.runtime.stack.stackRemaining",
            "nC.runtime.stack.stackTrace",
            "nC.runtime.stack.stackTraceLen",
            "nC.runtime.stack.stackTraceFrame",
            "nC.runtime.stack.stackTraceRelease",
        ] {
            assert!(
                run.call_links.iter().any(|link| {
                    link.target == target && link.kind == FunctionCallLinkKindIR::Import
                }),
                "missing import link {target}"
            );
        }

        let backend = emit_backend(&ir);
        let calls = super::source_execution_material_tests::native_call_targets(&backend);
        for target in [
            "ncc_rt_stack_depth",
            "ncc_rt_stack_limit",
            "ncc_rt_stack_remaining",
            "ncc_rt_stack_trace",
            "ncc_rt_stack_trace_len",
            "ncc_rt_stack_trace_frame",
            "ncc_rt_stack_trace_release",
        ] {
            assert!(calls.iter().any(|call| call == target), "missing {target}");
        }

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        for call in [
            "call i64 @ncc_rt_stack_depth()",
            "call i64 @ncc_rt_stack_limit()",
            "call i64 @ncc_rt_stack_remaining()",
            "call i64 @ncc_rt_stack_trace()",
            "call i64 @ncc_rt_stack_trace_len(i64",
            "call i64 @ncc_rt_stack_trace_frame(i64",
            "call i32 @ncc_rt_stack_trace_release(i64",
        ] {
            assert!(
                llvm.llvm_ir.contains(call),
                "missing {call}\n{}",
                llvm.llvm_ir
            );
        }
        for definition in [
            "define i64 @ncc_rt_stack_depth()",
            "define i64 @ncc_rt_stack_limit()",
            "define i64 @ncc_rt_stack_remaining()",
            "define i64 @ncc_rt_stack_trace()",
            "define i64 @ncc_rt_stack_trace_len(i64 %raw)",
            "define i64 @ncc_rt_stack_trace_frame(i64 %raw, i64 %index)",
            "define i32 @ncc_rt_stack_trace_release(i64 %raw)",
        ] {
            assert!(
                llvm.llvm_ir.contains(definition),
                "missing material definition {definition}"
            );
        }
        assert!(llvm
            .llvm_ir
            .contains("call void @GetCurrentThreadStackLimits"));
        assert!(llvm.llvm_ir.contains("call i16 @RtlCaptureStackBackTrace"));
        assert!(!llvm.llvm_ir.contains("declare i64 @ncc_rt_stack_depth()"));
    }

    #[test]
    fn stoud_time_clock_lowers_import_free_raw_date_clock_and_sleep() {
        let source = r#"
 clockMaterialization :: runtime {
    fn:
        measuredWork() -> bool {
            return true;
        }

         run() -> bool {
            mark >> addr <- stackMark();
            text >> p<byte> <- stackAlloc(24, 8);
            current >> p<byte> <- stackAlloc(24, 8);
            formatted >> int <- formatTimeInto(0, text, 24);
            epoch >> str <- cast(text);
            dated >> int <- dateInto(current, 24);
            start >> u64 <- monotonic();
            delta >> u64 <- elapsed(start);
            measured >> u64 <- measure(@fn(measuredWork));
            resolution >> u64 <- clockResolution();
            deadline >> int <- monotonicMs();
            sleepMs(0);
            slept >> bool <- sleepUntilMs(deadline);
            stackRestore(mark);
            return formatted == 23 && epoch == "1970-01-01 00:00:00 UTC" &&
                dated == 23 && elapsed(start) >= delta &&
                measured >= 0 && resolution > 0 && slept;
        }

    ref main ->> run;

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let run = regular_function(&ir, "run");
        for target in [
            "nC.runtime.clock.monotonic",
            "nC.runtime.clock.elapsed",
            "nC.runtime.clock.measure",
            "nC.runtime.clock.clockResolution",
            "nC.runtime.time.formatTimeInto",
            "nC.runtime.time.dateInto",
            "nC.runtime.time.sleepUntilMs",
        ] {
            assert!(
                run.call_links.iter().any(|link| {
                    link.target == target && link.kind == FunctionCallLinkKindIR::Import
                }),
                "missing import link {target}"
            );
        }

        let backend = emit_backend(&ir);
        let calls = super::source_execution_material_tests::native_call_targets(&backend);
        for target in [
            "ncc_rt_clock_monotonic",
            "ncc_rt_clock_elapsed",
            "ncc_rt_clock_measure",
            "ncc_rt_clock_resolution",
            "ncc_rt_format_time_into",
            "ncc_rt_date_into",
            "ncc_rt_sleep_until_millis",
        ] {
            assert!(
                calls.iter().any(|call| call == target),
                "missing {target}: {calls:?}"
            );
        }
        let native_run = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function)
                    if function.symbol == "clockMaterialization.run" =>
                {
                    Some(function)
                }
                _ => None,
            })
            .expect("clock run function");
        assert!(
            native_run.lowering_coverage.is_complete(),
            "clock must be completely machine-materialized: {native_run:#?}"
        );
        let object = emit_object(&backend);
        assert!(object.relocations.iter().any(|relocation| {
            relocation.section == ".text.clockMaterialization.run"
                && relocation.symbol == "clockMaterialization.measuredWork"
                && relocation.kind == BackendObjectRelocationKindIR::Abs64
        }));

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        for call in [
            "call i64 @ncc_rt_clock_monotonic()",
            "call i64 @ncc_rt_clock_elapsed(i64",
            "call i64 @ncc_rt_clock_measure(ptr",
            "call i64 @ncc_rt_clock_resolution()",
            "call i64 @ncc_rt_format_time_into(i64 0, ptr",
            "call i64 @ncc_rt_date_into(ptr",
            "call i32 @ncc_rt_sleep_until_millis(i64",
        ] {
            assert!(
                llvm.llvm_ir.contains(call),
                "missing {call}\n{}",
                llvm.llvm_ir
            );
        }
        for definition in [
            "define i64 @ncc_rt_now_seconds()",
            "define i64 @ncc_rt_monotonic_nanos()",
            "define i64 @ncc_rt_clock_measure(ptr",
            "define i64 @ncc_rt_format_time_into(i64",
            "define i64 @ncc_rt_date_into(ptr",
            "define i32 @ncc_rt_sleep_until_millis(i64",
        ] {
            assert!(llvm.llvm_ir.contains(definition), "missing {definition}");
        }
    }

