    #[test]
    fn stoud_io_read_bytes_into_lowers_array_data_capacity_and_tagged_result() {
        let source = r#"
use <io:readBytesInto>;

readBytesIntoMaterialization :: runtime {
    fn:
        run() -> bool {
            bytes >> array<byte, 4> <- [0, 0, 0, 0];
            read >> Result<int, FsError> <- readBytesInto("fixture.bin", bytes);
            return isOk(read);
        }

    ref main ->> run;

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let run = regular_function(&ir, "run");
        assert!(run.call_links.iter().any(|link| {
            link.target == "nC.runtime.fs.readBytesInto"
                && link.kind == FunctionCallLinkKindIR::Import
        }));

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        assert!(llvm
            .llvm_ir
            .contains("define i64 @ncc_rt_fsread_bytes(ptr %path, ptr %out, i64 %capacity)"));
        assert!(llvm.llvm_ir.contains("call i64 @ncc_rt_fsread_bytes(ptr"));
        assert!(llvm.llvm_ir.contains(", i64 4)"));
    }

    #[test]
    fn stoud_io_flush_lowers_all_channels_and_input_policy() {
        let source = r#"
use <io:flush>;

flushMaterialization :: runtime {
    fn:
        run() -> bool {
            configured >> bool <- autoFlushOnInput(true);
            return configured && flushBeforeInput() && flushStdout() && flushStderr() && flush();
        }

    ref main ->> run;

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let backend = emit_backend(&ir);
        let calls = super::source_execution_material_tests::native_call_targets(&backend);
        for target in [
            "ncc_rt_auto_flush_on_input",
            "ncc_rt_flush_before_input",
            "ncc_rt_flush_stdout",
            "ncc_rt_flush_stderr",
            "ncc_rt_flush_all",
        ] {
            assert!(calls.iter().any(|call| call == target), "{calls:?}");
        }

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        for target in [
            "@ncc_rt_auto_flush_on_input(i32",
            "@ncc_rt_flush_before_input()",
            "@ncc_rt_flush_stdout()",
            "@ncc_rt_flush_stderr()",
            "@ncc_rt_flush_all()",
        ] {
            assert!(llvm.llvm_ir.contains(target), "missing {target}");
        }
        assert!(llvm.llvm_ir.contains("store atomic i8"));
        assert!(!llvm.llvm_ir.contains("@GetStdHandle("));
    }

    #[test]
    fn native_prelude_lowers_to_intrinsic_and_runtime_edges_without_imports() {
        let source = r#"
package prelude_profile { profile: vendor_release; }

nativePreludeIr {
    type:
        Pair {
            public:
                left: int;
                right: byte;
            layout:
                repr(C);
        }

    stc:
        p: ptr<byte> | null;
        q: ptr<byte> | null;
        r: ptr<byte>;
        value: byte;
        now: int;

    fn:
        run() -> bool {
            public:
                @p >> ptr<byte> | null : alloc(8);
                @q >> ptr<byte> | null : calloc(2, 8);
                @p >> ptr<byte> | null : realloc(@p, 32);
                @r >> ptr<byte> : ptrOffset<byte>(@p, 1);
                ptrWrite<byte>(@r, 7);
                @value >> byte : ptrRead<byte>(@r);
                @size >> int : sizeOf<Pair>();
                @align >> int : alignOf<Pair>();
                @offset >> int : offsetOf<Pair>(right);
                atomicLoad(0);
                atomicStore(0, 1);
                fence();
                @now >> int : monotonicMs();
                sleepMs(0);
                free(@q);
                free(@p);
                return @value == 7 && @size >= 5 && @align >= 1 && @offset >= 4;
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        assert!(program.uses.is_empty());
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        assert!(ir.source_contract.is_manual_raw());
        let function = regular_function(&ir, "run");

        for target in [
            "nC.intrinsic.memory.alloc",
            "nC.intrinsic.memory.calloc",
            "nC.intrinsic.memory.realloc",
            "nC.intrinsic.memory.free",
            "nC.intrinsic.ptr.ptrOffset<byte>",
            "nC.intrinsic.ptr.ptrWrite<byte>",
            "nC.intrinsic.ptr.ptrRead<byte>",
        ] {
            let link = function
                .call_links
                .iter()
                .find(|link| link.target == target)
                .unwrap_or_else(|| panic!("missing native intrinsic edge {target}"));
            assert_eq!(link.kind, FunctionCallLinkKindIR::Intrinsic);
            assert_eq!(link.target_mode, None);
            assert!(!link.requires_bridge);
        }

        for target in [
            "nC.runtime.atomic.atomicLoad",
            "nC.runtime.atomic.atomicStore",
            "nC.runtime.atomic.atomicFence",
            "nC.runtime.time.monotonicMs",
            "nC.runtime.sleep.sleepMs",
        ] {
            let link = function
                .call_links
                .iter()
                .find(|link| link.target == target)
                .unwrap_or_else(|| panic!("missing native runtime edge {target}"));
            assert_eq!(link.kind, FunctionCallLinkKindIR::Import);
            assert_eq!(link.target_mode, Some(AbiModeClassIR::Runtime));
        }

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        assert!(llvm.llvm_ir.contains("call ptr @malloc(i64 8)"));
        assert!(llvm.llvm_ir.contains("call ptr @calloc(i64 2, i64 8)"));
        assert!(llvm.llvm_ir.contains("call ptr @realloc"));
        assert!(llvm.llvm_ir.contains("call void @free"));
        assert!(llvm.llvm_ir.contains("load atomic"));
        assert!(llvm.llvm_ir.contains("store atomic"));
        assert!(llvm.llvm_ir.contains("fence seq_cst"));
        assert!(llvm.llvm_ir.contains("call i64 @ncc_rt_monotonic_millis()"));
        assert!(llvm.llvm_ir.contains("call i32 @usleep(i32"));
    }

    #[test]
    fn requested_mobile_network_io_sys_surface_reaches_material_llvm_calls() {
        let source = r#"
materialImportsIr {
    run() -> bool {
        fswrite("a", "b");
        rename_file("a", "b");
        delete_file("b");
        registry_write("key", "value");
        registry_read("key");
        cpu_load();
        get_current_time();
        sleep(0);
        network::isWiFiConnected();
        server = network::server_open(0);
        return server != null;
    }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let program = parse_and_check(source);
        assert!(program.uses.is_empty());
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let function = regular_function(&ir, "run");
        for target in [
            "nC.runtime.fs.rename_file",
            "nC.runtime.fs.delete_file",
            "nC.runtime.system.registry_write",
            "nC.runtime.system.registry_read",
            "nC.runtime.system.cpu_load",
            "nC.runtime.time.now",
            "nC.runtime.time.sleep",
            "nC.runtime.mobileNetwork.isWiFiConnected",
            "nC.runtime.mobileNetwork.server_open",
        ] {
            assert!(
                function.call_links.iter().any(|link| link.target == target),
                "missing canonical runtime edge {target}: {:#?}",
                function.call_links
            );
        }

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        for call in [
            "call i32 @ncc_rt_fs_rename(ptr",
            "call i32 @ncc_rt_fs_delete(ptr",
            "call i32 @ncc_rt_registry_write(ptr",
            "call ptr @ncc_rt_registry_read(ptr",
            "call double @ncc_rt_system_cpu_load()",
            "call i64 @ncc_rt_now_seconds()",
            "call i32 @ncc_rt_mobile_network_is_wifi_connected_provider()",
            "call i64 @ncc_rt_network_server_open(i64 0)",
        ] {
            assert!(
                llvm.llvm_ir.contains(call),
                "missing {call}: {}",
                llvm.llvm_ir
            );
        }
    }

    #[test]
    fn compact_raw_surface_lowers_unchecked_pointer_hazards_to_llvm() {
        let source = r#"
compactRawLlvm {
    run() -> bool {
        owner <- alloc(8);
        alias: p<byte> = off<byte>(owner, 4096);
        wr<byte>(alias, 0xFF);
        free(owner);
        wr<byte>(owner, 1);
        free(owner);
        stale <- rd<byte>(alias);
        return stale == stale;
    }

    main: run;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        assert!(llvm.llvm_ir.contains("call ptr @malloc(i64 8)"));
        assert!(llvm.llvm_ir.contains("getelementptr i8, ptr"));
        assert!(!llvm.llvm_ir.contains("getelementptr inbounds"));
        assert!(llvm.llvm_ir.matches("call void @free").count() >= 2);
        assert!(llvm.llvm_ir.contains("store i8"));
        assert!(llvm.llvm_ir.contains("load i8"));
    }

    #[test]
    fn native_memory_prelude_materializes_heap_calls_in_machine_backend() {
        let source = r#"
nativeMemoryPrelude[@runtime] {
    stc:
        p: ptr<byte> | null;
        q: ptr<byte> | null;
        r: ptr<byte>;
        value: byte;
    fn:
        run() -> bool {
            public:
                @p >> ptr<byte> | null : alloc(8);
                @q >> ptr<byte> | null : calloc(2, 8);
                @p >> ptr<byte> | null : realloc(@p, 32);
                @r >> ptr<byte> : ptrOffset<byte>(@p, 1);
                ptrWrite<byte>(@r, 7);
                @value >> byte : ptrRead<byte>(@r);
                free(@q);
                free(@p);
                return @value == 7;
        }
        ref main ->> @fn(run);
        fa:
            return true;
}
"#;
        let program = parse_and_check(source);
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let backend = emit_backend(&ir);
        let calls = super::source_execution_material_tests::native_call_targets(&backend);
        for target in ["malloc", "calloc", "realloc", "free"] {
            assert!(
                calls.iter().any(|call| call == target),
                "{target}: {calls:?}"
            );
        }
    }

    #[test]
    fn raw_pointer_arithmetic_and_optional_audit_are_codegen_neutral() {
        let source = r#"
rawPointerCodegen {
    stc:
        owner: addr;

    fn:
        run(index: int) -> bool {
            public:
                @owner >> addr : alloc(16);
                @shifted >> p<int> : pOffset<int>(@owner, @index);
                pWrite<int>(@shifted, 7);
                free(@owner);
                free(@owner);
                return pDiff<int>(@shifted, @owner) == @index;
        }

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(source).expect("raw pointer fixture must lex");
        let program = ncc_parser::parse(tokens).expect("raw pointer fixture must parse");
        ncc_sema::analyze(&program).expect("normal raw compilation must admit hazards");

        let before = mct_emit_llvm_module(&lower_with_backend_profile(
            program.clone(),
            BackendLoweringProfileIR::nc_sysv64(),
        ));
        let audit = ncc_sema::analyze_with_explicit_pointer_checks(&program);
        assert!(
            audit.is_err(),
            "the opt-in auditor must observe double free"
        );
        ncc_sema::analyze(&program).expect("the auditor must restore normal raw semantics");
        let after = mct_emit_llvm_module(&lower_with_backend_profile(
            program,
            BackendLoweringProfileIR::nc_sysv64(),
        ));

        assert_eq!(
            before.llvm_ir, after.llvm_ir,
            "audit changed generated LLVM"
        );
        let address_lines = before
            .llvm_ir
            .lines()
            .filter(|line| line.contains("getelementptr i8") || line.contains("mul i64"))
            .collect::<Vec<_>>();
        assert!(!address_lines.is_empty(), "{}", before.llvm_ir);
        for line in address_lines {
            assert!(
                !line.contains("inbounds"),
                "raw address was constrained: {line}"
            );
            assert!(
                !line.contains(" nsw "),
                "raw overflow was constrained: {line}"
            );
            assert!(
                !line.contains(" nuw "),
                "raw overflow was constrained: {line}"
            );
        }
    }

    fn pointer_target_profile(target: &str) -> BackendLoweringProfileIR {
        let mut profile = match target {
            "aarch64-unknown-linux-gnu" | "armv7a-none-eabi" => {
                BackendLoweringProfileIR::nc_aarch64_linux()
            }
            _ => BackendLoweringProfileIR::nc_sysv64(),
        };
        match target {
            "x86_64-unknown-linux-gnu" => {}
            "i386-unknown-linux-gnu" => {
                profile.target_spec.target_triple = target.into();
                profile.target_spec.isa = BackendIsaIR::X86;
                profile.target_spec.abi = BackendAbiModelIR::I386SysV;
                profile.target_spec.object_format = BackendObjectFormatIR::Elf32;
                profile.target_spec.data_layout = BackendDataLayoutIR::i386_sysv();
                profile.target_spec.pointer_width = 32;
            }
            "aarch64-unknown-linux-gnu" => {
                profile.target_spec.target_triple = target.into();
                profile.target_spec.object_format = BackendObjectFormatIR::Elf64;
            }
            "armv7a-none-eabi" => {
                profile.target_spec.target_triple = target.into();
                profile.target_spec.target_family = BackendTargetFamilyIR::Freestanding;
                profile.target_spec.isa = BackendIsaIR::ArmV7;
                profile.target_spec.abi = BackendAbiModelIR::Aapcs32;
                profile.target_spec.object_format = BackendObjectFormatIR::Elf32;
                profile.target_spec.data_layout = BackendDataLayoutIR::ilp32();
                profile.target_spec.pointer_width = 32;
                profile.target_spec.runtime_model = BackendRuntimeModelIR::Freestanding;
                profile.target_spec.host_services = BackendHostServicesIR::BareMetal;
            }
            "riscv32-unknown-elf" => {
                profile.target_spec.target_triple = target.into();
                profile.target_spec.target_family = BackendTargetFamilyIR::Freestanding;
                profile.target_spec.isa = BackendIsaIR::RiscV32;
                profile.target_spec.abi = BackendAbiModelIR::Ilp32;
                profile.target_spec.object_format = BackendObjectFormatIR::Elf32;
                profile.target_spec.data_layout = BackendDataLayoutIR::ilp32();
                profile.target_spec.pointer_width = 32;
                profile.target_spec.runtime_model = BackendRuntimeModelIR::Freestanding;
                profile.target_spec.host_services = BackendHostServicesIR::BareMetal;
            }
            "riscv64-unknown-elf" => {
                profile.target_spec.target_triple = target.into();
                profile.target_spec.target_family = BackendTargetFamilyIR::Freestanding;
                profile.target_spec.isa = BackendIsaIR::RiscV64;
                profile.target_spec.abi = BackendAbiModelIR::RiscV64;
                profile.target_spec.object_format = BackendObjectFormatIR::Elf64;
                profile.target_spec.data_layout = BackendDataLayoutIR::lp64();
                profile.target_spec.pointer_width = 64;
                profile.target_spec.runtime_model = BackendRuntimeModelIR::Freestanding;
                profile.target_spec.host_services = BackendHostServicesIR::BareMetal;
            }
            _ => panic!("unsupported pointer test target {target}"),
        }
        profile
    }

    #[test]
    fn raw_pointer_domains_widths_ptrdiff_and_aggregate_stride_lower_on_six_targets() {
        let source = r#"
pointerTargetIr {
    type:
        Packet {
            public:
                tag: int;
                flags: byte;
                wide: qword;
            layout:
                repr(C);
        }

    fn:
        run(base: int, index: int) -> isize {
            public:
                @cpu >> p<Packet> : ptrFromAddr<Packet>(@base);
                @mmio >> p<Packet, mmio> : ptrCast<Packet, mmio>(@cpu);
                @dma >> p<Packet, dma, 32> : ptrCast<Packet, dma, 32>(@mmio);
                @physical16 >> p<byte, physical, 16> : ptrCast<byte, physical, 16>(@cpu);
                @gpu128 >> p<byte, gpu, 128> : ptrCast<byte, gpu, 128>(@cpu);
                @firmware64 >> p<byte, firmware, 64> : ptrCast<byte, firmware, 64>(@cpu);
                @next >> p<Packet, mmio> : ptrOffset<Packet>(@mmio, @index);
                @flex >> p<Packet[]> : ptrCast<Packet[]>(@cpu);
                @flexNext >> p<Packet[]> : ptrOffset<Packet[]>(@flex, @index);
                @fixed >> p<array<Packet, 4>> : ptrCast<array<Packet, 4>>(@cpu);
                @fixedNext >> p<array<Packet, 4>> : ptrOffset<array<Packet, 4>>(@fixed, @index);
                @tag >> int : ptrRead<int>(@mmio);
                ptrWrite<int>(@mmio, @tag);
                @distance >> isize : ptrDiff<Packet>(@next, @mmio);
                @ordered >> bool : @dma < @cpu;
                return @distance;
        }

    fa:
        return true;
}
"#;
        let targets = [
            ("x86_64-unknown-linux-gnu", 64usize),
            ("i386-unknown-linux-gnu", 32usize),
            ("aarch64-unknown-linux-gnu", 64usize),
            ("armv7a-none-eabi", 32usize),
            ("riscv32-unknown-elf", 32usize),
            ("riscv64-unknown-elf", 64usize),
        ];
        for (target, bits) in targets {
            let program = parse_and_check(source);
            let ir = lower_with_backend_profile_exact(program, pointer_target_profile(target));
            let module = mct_emit_llvm_module(&ir);
            assert_eq!(
                module.status, "llvm_adapter_emitted",
                "{target}: {:?}\n{}",
                module.diagnostics, module.llvm_ir
            );
            assert!(
                module.diagnostics.is_empty(),
                "{target}: {:?}\n{}",
                module.diagnostics,
                module.llvm_ir
            );
            assert!(module
                .llvm_ir
                .contains(&format!("target triple = \"{target}\"")));
            assert!(module.llvm_ir.contains(&format!("-p1:{bits}:{bits}")));
            assert!(module.llvm_ir.contains("-p35:32:32"));
            assert!(module.llvm_ir.contains("ptr addrspace(1)"));
            assert!(module.llvm_ir.contains("ptr addrspace(18)"));
            assert!(!module.llvm_ir.contains("-p132:128:128"));
            assert!(module.llvm_ir.contains("alloca i128"));
            let dma_address_space = if bits == 32 { 3 } else { 35 };
            assert!(module
                .llvm_ir
                .contains(&format!("ptr addrspace({dma_address_space})")));
            let raw_geps = module
                .llvm_ir
                .lines()
                .filter(|line| line.contains("getelementptr i8, ptr addrspace(1)"))
                .collect::<Vec<_>>();
            assert!(!raw_geps.is_empty(), "{target}: {}", module.llvm_ir);
            assert!(raw_geps.iter().all(|line| !line.contains("inbounds")));
            assert!(raw_geps
                .iter()
                .any(|line| line.contains(&format!("i{bits} "))));
            assert!(
                module.llvm_ir.contains(&format!("mul i{bits}")),
                "{target}: {}",
                module.llvm_ir
            );
            assert!(
                module.llvm_ir.contains("size=16"),
                "{target}: {}",
                module.llvm_ir
            );
            assert!(
                module.llvm_ir.contains(", 16"),
                "{target}: {}",
                module.llvm_ir
            );
            assert!(
                module.llvm_ir.contains(", 64"),
                "{target}: {}",
                module.llvm_ir
            );
            assert!(module.llvm_ir.contains(&format!("trunc i{bits}")));
            assert!(module.llvm_ir.contains(&format!("zext i{bits}")));
            assert!(module.llvm_ir.contains(&format!("icmp ult i{bits}")));
            assert!(module
                .llvm_ir
                .contains(&format!("ptrtoint ptr addrspace(1)")));
            assert!(module
                .llvm_ir
                .contains("load volatile i32, ptr addrspace(1)"));
            assert!(module.llvm_ir.contains("store volatile i32"));
            if std::process::Command::new("clang")
                .arg("--version")
                .output()
                .is_ok()
            {
                let nonce = std::process::id();
                let stem = target.replace(['-', '.'], "_");
                let llvm_path =
                    std::env::temp_dir().join(format!("ncc_pointer_multitarget_{nonce}_{stem}.ll"));
                let object_path =
                    std::env::temp_dir().join(format!("ncc_pointer_multitarget_{nonce}_{stem}.o"));
                std::fs::write(&llvm_path, &module.llvm_ir).expect("write pointer LLVM fixture");
                let output = std::process::Command::new("clang")
                    .arg(format!("--target={target}"))
                    .args(["-Wno-override-module", "-c", "-x", "ir"])
                    .arg(&llvm_path)
                    .arg("-o")
                    .arg(&object_path)
                    .output()
                    .expect("run clang pointer object validation");
                assert!(
                    output.status.success(),
                    "{target}: clang rejected pointer module:\n{}\n{}",
                    String::from_utf8_lossy(&output.stdout),
                    String::from_utf8_lossy(&output.stderr)
                );
                assert!(
                    std::fs::metadata(&object_path).is_ok_and(|metadata| metadata.len() > 0),
                    "{target}: clang did not emit an object"
                );
                let _ = std::fs::remove_file(llvm_path);
                let _ = std::fs::remove_file(object_path);
            }
        }
    }

    #[test]
    fn local_function_keeps_precedence_in_ir() {
        let source = r#"
shadowPreludeIr {
    fn:
        jsonParse(text: str) -> bool {
            public:
                return strEq(@text, "local");
        }

        run() -> bool {
            public:
                return jsonParse("local");
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#;
        let ir = lower(parse_and_check(source));
        let function = regular_function(&ir, "run");
        let local = function
            .call_links
            .iter()
            .find(|link| link.target == "jsonParse")
            .expect("local shadow call edge");
        assert_eq!(local.kind, FunctionCallLinkKindIR::Unknown);
        assert!(!function
            .call_links
            .iter()
            .any(|link| link.target == "nC.runtime.json.jsonParse"));
        let body = format!("{:#?}", function.body);
        assert!(body.contains("target: \"jsonParse\""), "{body}");
        assert!(!body.contains("nC.runtime.json.jsonParse"), "{body}");
    }

    #[test]
    fn ir_prelude_context_gate_matches_hosted_root_and_runtime_contract() {
        let program = parse_and_check(
            r#"
hostedIndex {
    fn:
        run() -> bool {
            public:
                return jsonValidate("{}");
        }
}
"#,
        );
        let index = RuntimeCallResolutionIndexIR::from_program(&program);
        let symbols = HashMap::new();
        for context in [
            Context::Machine,
            Context::Primitive,
            Context::Kernel,
            Context::System,
        ] {
            assert!(catalog_runtime_unqualified_target(
                "jsonParse",
                1,
                &Some(context),
                &index,
                &symbols,
            )
            .is_none());
        }
        assert_eq!(
            catalog_runtime_unqualified_target("jsonParse", 1, &None, &index, &symbols),
            Some("nC.runtime.json.jsonParse".to_string())
        );
        for context in [Context::Root, Context::Runtime] {
            assert_eq!(
                catalog_runtime_unqualified_target(
                    "jsonParse",
                    1,
                    &Some(context),
                    &index,
                    &symbols,
                ),
                Some("nC.runtime.json.jsonParse".to_string())
            );
        }
    }

