pub enum MctBackendProviderIR {
    NccNative,
    Llvm,
    Gcc,
    Rustc,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MctBackendStatusIR {
    Integrated,
    AdapterIntegrated,
    ExternalBridgeContractDefined,
    PlannedAdapter,
    ForbiddenForMode,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MctCapabilityIR {
    ModalContainerTranslate,
    FunctionIr,
    TypeLayout,
    PointerOps,
    MemRegionOps,
    ControlFlow,
    Simd,
    AutoVectorization,
    AtomicsVolatile,
    FfiC,
    FfiCpp,
    RustExternC,
    ObjectEmit,
    ExecutableLink,
    DebugUnwind,
    OptimizerPipeline,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MctDiagnosticSeverityIR {
    Info,
    Warning,
    Error,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MctDiagnosticIR(ncc_diagnostics::CanonicalDiagnostic);

impl MctDiagnosticIR {
    pub fn new(code: &'static str, severity: MctDiagnosticSeverityIR, message: String) -> Self {
        let canonical_severity = match severity {
            MctDiagnosticSeverityIR::Info => ncc_diagnostics::DiagnosticSeverity::Note,
            MctDiagnosticSeverityIR::Warning => ncc_diagnostics::DiagnosticSeverity::Warning,
            MctDiagnosticSeverityIR::Error => ncc_diagnostics::DiagnosticSeverity::Error,
        };
        Self(
            ncc_diagnostics::stage0_registered_diagnostic(canonical_severity, code, message)
                .with_phase(mct_diagnostic_phase(code))
                .with_domain(ncc_diagnostics::DiagnosticDomain::Mct),
        )
    }

    pub fn canonical(&self) -> &ncc_diagnostics::CanonicalDiagnostic {
        &self.0
    }

    pub fn is_error(&self) -> bool {
        matches!(
            self.0.severity,
            ncc_diagnostics::DiagnosticSeverity::Error | ncc_diagnostics::DiagnosticSeverity::Fatal
        )
    }
}

impl std::ops::Deref for MctDiagnosticIR {
    type Target = ncc_diagnostics::CanonicalDiagnostic;

    fn deref(&self) -> &Self::Target {
        self.canonical()
    }
}

fn mct_diagnostic_phase(code: &str) -> &'static str {
    if code.contains("LLVM") {
        "mct.llvm"
    } else if code.contains("ABI") {
        "mct.abi"
    } else if code.contains("OBJECT") || code.contains("COFF") || code.contains("ELF") {
        "mct.object"
    } else if code.contains("LINK") {
        "mct.link"
    } else if code.contains("OPT") || code.contains("PASS") {
        "mct.optimizer"
    } else {
        "mct"
    }
}

