pub struct BackendObjectIR {
    pub target: BackendTargetIR,
    pub target_spec: BackendTargetSpecIR,
    pub sections: Vec<BackendObjectSectionIR>,
    pub symbols: Vec<BackendObjectSymbolIR>,
    pub relocations: Vec<BackendObjectRelocationIR>,
}

impl BackendObjectIR {
    pub fn unresolved_symbols(&self) -> Vec<String> {
        let mut unresolved = self
            .relocations
            .iter()
            .filter_map(|rel| {
                if self.symbols.iter().any(|sym| sym.name == rel.symbol) {
                    None
                } else {
                    Some(rel.symbol.clone())
                }
            })
            .collect::<Vec<_>>();
        unresolved.sort();
        unresolved.dedup();
        unresolved
    }
}

