#[allow(clippy::too_many_arguments)]
fn type_abi_matrix_row(
    family: &'static str,
    kind: BackendTypeAbiMatrixKindIR,
    examples: &[&'static str],
    storage_class: Option<BackendTypeStorageClassIR>,
    llvm_storage: &'static str,
    size_64: &'static str,
    align_64: &'static str,
    abi_surface: &'static str,
    native_status: &'static str,
    source_of_truth: &'static str,
) -> BackendTypeAbiMatrixRowIR {
    BackendTypeAbiMatrixRowIR {
        family,
        kind,
        examples: examples.to_vec(),
        storage_class,
        llvm_storage,
        size_64,
        align_64,
        abi_surface,
        native_status,
        source_of_truth,
    }
}

