#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FunctionVisibilityIR {
    Default,
    Public,
    Internal,
    Private,
    Strictly,
}

pub fn render_function_visibility(visibility: FunctionVisibilityIR) -> &'static str {
    match visibility {
        FunctionVisibilityIR::Default => "default",
        FunctionVisibilityIR::Public => "public",
        FunctionVisibilityIR::Internal => "internal",
        FunctionVisibilityIR::Private => "private",
        FunctionVisibilityIR::Strictly => "strictly",
    }
}

fn llvm_function_visibility_prefix(visibility: FunctionVisibilityIR) -> &'static str {
    match visibility {
        FunctionVisibilityIR::Internal => "hidden ",
        FunctionVisibilityIR::Private | FunctionVisibilityIR::Strictly => "private ",
        FunctionVisibilityIR::Default | FunctionVisibilityIR::Public => "",
    }
}

fn backend_function_symbol_visibility(
    visibility: FunctionVisibilityIR,
) -> BackendSymbolVisibilityIR {
    match visibility {
        FunctionVisibilityIR::Private | FunctionVisibilityIR::Strictly => {
            BackendSymbolVisibilityIR::Local
        }
        FunctionVisibilityIR::Default
        | FunctionVisibilityIR::Public
        | FunctionVisibilityIR::Internal => BackendSymbolVisibilityIR::Global,
    }
}

