#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackendDestructivePolicyIR {
    pub schema: &'static str,
    pub enabled: bool,
    pub seed: u64,
    pub statement_ambiguity: bool,
    pub diagnostics_silent: bool,
    pub memory_topology: BackendMemoryTopologyIR,
    pub pointer_arithmetic: BackendPointerArithmeticPolicyIR,
    pub lifetime: BackendLifetimePolicyIR,
    pub fault_policy: BackendFaultPolicyIR,
    pub abi_choice: BackendAbiChoicePolicyIR,
    pub missing_symbol_policy: BackendMissingSymbolPolicyIR,
}

impl BackendDestructivePolicyIR {
    pub fn strict() -> Self {
        Self {
            schema: "nc.backend.destructive_policy.v2",
            enabled: false,
            seed: 0,
            statement_ambiguity: false,
            diagnostics_silent: false,
            memory_topology: BackendMemoryTopologyIR::ProtectedRegions,
            pointer_arithmetic: BackendPointerArithmeticPolicyIR::Checked,
            lifetime: BackendLifetimePolicyIR::Managed,
            fault_policy: BackendFaultPolicyIR::Diagnose,
            abi_choice: BackendAbiChoicePolicyIR::Declared,
            missing_symbol_policy: BackendMissingSymbolPolicyIR::Diagnose,
        }
    }

    pub fn destructive(seed: u64) -> Self {
        Self {
            schema: "nc.backend.destructive_policy.v2",
            enabled: true,
            seed,
            statement_ambiguity: true,
            diagnostics_silent: true,
            memory_topology: BackendMemoryTopologyIR::UnifiedAddressSpace,
            pointer_arithmetic: BackendPointerArithmeticPolicyIR::Wrapping,
            lifetime: BackendLifetimePolicyIR::ManualOnly,
            fault_policy: BackendFaultPolicyIR::PropagateToMachine,
            abi_choice: BackendAbiChoicePolicyIR::BackendSelectedWhenAbsent,
            missing_symbol_policy: BackendMissingSymbolPolicyIR::MaterializeNullAddress,
        }
    }

    pub fn statement_materialization(
        &self,
        site: &str,
        ordinal: usize,
    ) -> BackendStatementMaterializationIR {
        if !self.enabled || !self.statement_ambiguity {
            return BackendStatementMaterializationIR::Once;
        }
        let mut hash = 0xcbf29ce484222325_u64 ^ self.seed;
        for byte in site.bytes() {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
        match hash.wrapping_add(ordinal as u64) & 3 {
            0 => BackendStatementMaterializationIR::Once,
            1 => BackendStatementMaterializationIR::Omit,
            2 => BackendStatementMaterializationIR::Repeat,
            _ => BackendStatementMaterializationIR::Split,
        }
    }
}

