#[derive(Debug, Clone, PartialEq, Eq)]
pub struct BackendLegalizationMatrixIR {
    pub lane: BackendLaneIR,
    pub rules: Vec<BackendLegalizationRuleIR>,
}

impl BackendLegalizationMatrixIR {
    pub fn rule_for_issue(
        &self,
        issue: BackendLegalizationIssueIR,
    ) -> Option<&BackendLegalizationRuleIR> {
        self.rules.iter().find(|rule| rule.issue == issue)
    }

    pub fn validate_official_shape(&self) -> Result<(), String> {
        if self.rules.is_empty() {
            return Err(format!(
                "backend legalization matrix for lane '{}' must include at least one rule",
                render_backend_lane(&self.lane)
            ));
        }

        let mut seen: HashSet<BackendLegalizationIssueIR> = HashSet::new();
        for rule in &self.rules {
            if rule.diagnostic.trim().is_empty() {
                return Err(format!(
                    "backend legalization matrix for lane '{}' contains empty diagnostic for issue '{}'",
                    render_backend_lane(&self.lane),
                    render_backend_legalization_issue(&rule.issue)
                ));
            }
            if !seen.insert(rule.issue) {
                return Err(format!(
                    "backend legalization matrix for lane '{}' contains duplicate rule for issue '{}'",
                    render_backend_lane(&self.lane),
                    render_backend_legalization_issue(&rule.issue)
                ));
            }
        }

        for issue in required_legalization_issues_for_lane(&self.lane) {
            if !seen.contains(issue) {
                return Err(format!(
                    "backend legalization matrix for lane '{}' is missing required issue '{}'",
                    render_backend_lane(&self.lane),
                    render_backend_legalization_issue(issue)
                ));
            }
        }

        Ok(())
    }
}

