pub fn backend_cpu_tuning_profile_from_mct(
    microarchitecture: &MctCpuMicroarchitectureIR,
    fine_profile: &MctCpuFineTuningProfileIR,
    host_detected: bool,
    selection_reason: impl Into<String>,
) -> BackendCpuTuningProfileIR {
    BackendCpuTuningProfileIR {
        schema: "nc.backend.cpu_tuning_profile.v1",
        status: "closed",
        microarchitecture_id: microarchitecture.id.into(),
        fine_tuning_profile_id: fine_profile.id.into(),
        target: microarchitecture.target.into(),
        vendor: microarchitecture.vendor.into(),
        family: microarchitecture.family.into(),
        llvm_target_cpu: microarchitecture.llvm_target_cpu.into(),
        llvm_tune_cpu: microarchitecture.llvm_tune_cpu.into(),
        target_features: microarchitecture
            .target_features
            .iter()
            .map(|feature| (*feature).into())
            .collect(),
        preferred_vector_width_bits: backend_native_cpu_tuning_preferred_vector_width(
            microarchitecture,
            fine_profile,
        ),
        issue_width: microarchitecture.issue_width,
        reorder_window: microarchitecture.reorder_window,
        load_latency_cycles: microarchitecture.load_latency_cycles,
        store_forward_latency_cycles: microarchitecture.store_forward_latency_cycles,
        branch_mispredict_penalty_cycles: microarchitecture.branch_mispredict_penalty_cycles,
        cache_line_bytes: microarchitecture.cache_line_bytes,
        supports_fma: microarchitecture.supports_fma,
        supports_gather_scatter: microarchitecture.supports_gather_scatter,
        scheduling_model: microarchitecture.scheduling_model.into(),
        native_microarchitecture: backend_native_microarchitecture_for_mct_cpu(
            microarchitecture.id,
        ),
        host_detected,
        selection_reason: selection_reason.into(),
    }
}

pub fn backend_default_cpu_microarchitecture_for_target(target: &BackendTargetIR) -> &'static str {
    match target {
        BackendTargetIR::X86_64 => "x86_64-v2",
        BackendTargetIR::AArch64 => "aarch64-generic",
        BackendTargetIR::Wasm32 => "wasm32-generic",
    }
}

pub fn backend_cpu_tuning_profile_for_backend_target(
    target: &BackendTargetIR,
) -> BackendCpuTuningProfileIR {
    backend_cpu_tuning_profile_from_name_for_target(
        backend_default_cpu_microarchitecture_for_target(target),
        target,
        "baseline",
    )
    .expect("backend default CPU tuning profile must be valid for every backend target")
}

pub fn backend_cpu_tuning_profile_from_name_for_target(
    name: &str,
    target: &BackendTargetIR,
    fine_tuning_profile_id: &str,
) -> Result<BackendCpuTuningProfileIR, String> {
    let microarchitecture_id = backend_cpu_tuning_alias_to_mct_id(name, Some(target))
        .ok_or_else(|| format!("unknown backend CPU tuning profile '{}'", name))?;
    let microarchitecture =
        mct_cpu_microarchitecture_by_id(microarchitecture_id).ok_or_else(|| {
            format!(
                "backend CPU tuning profile '{}' is not present in the MCT CPU catalog",
                microarchitecture_id
            )
        })?;
    let fine_profile =
        mct_cpu_fine_tuning_profile_by_id(fine_tuning_profile_id).ok_or_else(|| {
            format!(
                "unknown backend CPU fine tuning profile '{}'",
                fine_tuning_profile_id
            )
        })?;
    let expected = backend_cpu_target_label_for_backend_target(target).unwrap_or("unsupported");
    if microarchitecture.target != expected {
        return Err(format!(
            "backend CPU profile '{}' targets '{}', incompatible with backend target '{}'",
            microarchitecture.id, microarchitecture.target, expected
        ));
    }
    Ok(backend_cpu_tuning_profile_from_mct(
        &microarchitecture,
        &fine_profile,
        false,
        format!("explicit-cpu-profile:{}", name),
    ))
}

pub fn backend_cpu_tuning_profile_for_host_target(
    target: &BackendTargetIR,
    fine_tuning_profile_id: &str,
) -> Result<BackendCpuTuningProfileIR, String> {
    let (host_id, host_detected) = backend_detect_host_cpu_microarchitecture_id_for_target(target)
        .map(|id| (id, true))
        .unwrap_or_else(|| {
            (
                backend_default_cpu_microarchitecture_for_target(target).into(),
                false,
            )
        });
    let mut profile =
        backend_cpu_tuning_profile_from_name_for_target(&host_id, target, fine_tuning_profile_id)?;
    profile.host_detected = host_detected;
    profile.selection_reason = if host_detected {
        format!("host-cpu-detected:{host_id}")
    } else {
        format!("host-cpu-unavailable-target-default:{host_id}")
    };
    Ok(profile)
}

pub fn backend_cpu_tuning_catalog() -> Vec<BackendCpuTuningProfileIR> {
    let fine_profile = mct_cpu_fine_tuning_profile_by_id("throughput")
        .expect("throughput CPU fine tuning profile must be cataloged");
    mct_cpu_microarchitectures()
        .iter()
        .map(|microarchitecture| {
            backend_cpu_tuning_profile_from_mct(
                microarchitecture,
                &fine_profile,
                false,
                "catalog-throughput",
            )
        })
        .collect()
}

pub fn backend_cpu_tuning_alias_to_mct_id(
    name: &str,
    target: Option<&BackendTargetIR>,
) -> Option<&'static str> {
    let normalized = name.trim().replace(['_', '.'], "-").to_ascii_lowercase();
    match normalized.as_str() {
        "generic" | "baseline" => target.map(backend_default_cpu_microarchitecture_for_target),
        "x86-64" | "x86-64-v1" | "x86-64-baseline" | "x86_64-v1" => Some("x86_64-v1"),
        "x86-64-v2" | "x86_64-v2" => Some("x86_64-v2"),
        "x86-64-v3" | "x86_64-v3" => Some("x86_64-v3"),
        "x86-64-v4" | "x86_64-v4" => Some("x86_64-v4"),
        "skylake" | "intel-skylake" | "intel-skylake-client" => Some("intel-skylake"),
        "icelake" | "ice-lake" | "intel-icelake" | "intel-icelake-client" => {
            Some("intel-icelake-client")
        }
        "zen3" | "znver3" | "amd-zen3" | "amd-znver3" => Some("amd-znver3"),
        "zen4" | "znver4" | "amd-zen4" | "amd-znver4" => Some("amd-znver4"),
        "aarch64" | "arm64" | "aarch64-generic" | "arm64-generic" => Some("aarch64-generic"),
        "apple-m1" | "m1" => Some("apple-m1"),
        "apple-m2" | "m2" => Some("apple-m2"),
        "neoverse-n1" | "n1" => Some("neoverse-n1"),
        "neoverse-v1" | "v1" => Some("neoverse-v1"),
        "riscv64" | "risc-v64" | "rv64" | "rv64gc" | "riscv64-generic" => Some("riscv64-generic"),
        "sifive-u74" | "u74" => Some("sifive-u74"),
        "wasm32" | "wasm32-generic" | "wasi" => Some("wasm32-generic"),
        _ => mct_cpu_microarchitecture_by_id(&normalized).map(|profile| profile.id),
    }
}

fn backend_detect_host_cpu_microarchitecture_id_for_target(
    target: &BackendTargetIR,
) -> Option<String> {
    match target {
        BackendTargetIR::X86_64 => backend_detect_host_x86_cpu_microarchitecture_id(),
        BackendTargetIR::AArch64 => backend_detect_host_aarch64_cpu_microarchitecture_id(),
        BackendTargetIR::Wasm32 => Some("wasm32-generic".into()),
    }
}

#[cfg(any(target_arch = "x86", target_arch = "x86_64"))]
fn backend_detect_host_x86_cpu_microarchitecture_id() -> Option<String> {
    let avx2 = std::arch::is_x86_feature_detected!("avx2");
    let fma = std::arch::is_x86_feature_detected!("fma");
    let bmi1 = std::arch::is_x86_feature_detected!("bmi1");
    let bmi2 = std::arch::is_x86_feature_detected!("bmi2");
    let lzcnt = std::arch::is_x86_feature_detected!("lzcnt");
    let avx512 = std::arch::is_x86_feature_detected!("avx512f")
        && std::arch::is_x86_feature_detected!("avx512bw")
        && std::arch::is_x86_feature_detected!("avx512dq")
        && std::arch::is_x86_feature_detected!("avx512vl");
    let sse_v2 = std::arch::is_x86_feature_detected!("sse4.1")
        && std::arch::is_x86_feature_detected!("sse4.2")
        && std::arch::is_x86_feature_detected!("popcnt");
    let vendor = backend_detect_host_x86_vendor();
    if vendor.as_deref() == Some("amd") && avx512 {
        Some("amd-znver4".into())
    } else if vendor.as_deref() == Some("amd") && avx2 && fma && bmi1 && bmi2 && lzcnt {
        Some("amd-znver3".into())
    } else if vendor.as_deref() == Some("intel") && avx512 {
        Some("intel-icelake-client".into())
    } else if vendor.as_deref() == Some("intel") && avx2 && fma && bmi1 && bmi2 && lzcnt {
        Some("intel-skylake".into())
    } else if avx512 {
        Some("x86_64-v4".into())
    } else if avx2 && fma && bmi1 && bmi2 && lzcnt {
        Some("x86_64-v3".into())
    } else if sse_v2 {
        Some("x86_64-v2".into())
    } else {
        Some("x86_64-v1".into())
    }
}

#[cfg(not(any(target_arch = "x86", target_arch = "x86_64")))]
fn backend_detect_host_x86_cpu_microarchitecture_id() -> Option<String> {
    None
}

#[cfg(target_arch = "x86_64")]
fn backend_detect_host_x86_vendor() -> Option<String> {
    let regs = std::arch::x86_64::__cpuid(0);
    let mut bytes = Vec::new();
    bytes.extend_from_slice(&regs.ebx.to_le_bytes());
    bytes.extend_from_slice(&regs.edx.to_le_bytes());
    bytes.extend_from_slice(&regs.ecx.to_le_bytes());
    let vendor = String::from_utf8(bytes).ok()?;
    match vendor.as_str() {
        "GenuineIntel" => Some("intel".into()),
        "AuthenticAMD" => Some("amd".into()),
        _ => Some(vendor.to_ascii_lowercase()),
    }
}

#[cfg(not(target_arch = "x86_64"))]
fn backend_detect_host_x86_vendor() -> Option<String> {
    None
}

#[cfg(target_arch = "aarch64")]
fn backend_detect_host_aarch64_cpu_microarchitecture_id() -> Option<String> {
    #[cfg(target_os = "macos")]
    {
        return Some("apple-m2".into());
    }
    #[cfg(not(target_os = "macos"))]
    {
        if std::arch::is_aarch64_feature_detected!("sve") {
            Some("neoverse-v1".into())
        } else {
            Some("aarch64-generic".into())
        }
    }
}

#[cfg(not(target_arch = "aarch64"))]
fn backend_detect_host_aarch64_cpu_microarchitecture_id() -> Option<String> {
    None
}

impl BackendLoweringProfileIR {
    pub fn nc_i386_linux() -> Self {
        // The shared hosted legalization plan remains scalar, while the target
        // authority below makes every material LLVM/object decision ILP32.
        let mut profile = Self::nc_sysv64();
        profile.target_spec.target_triple = "i386-unknown-linux-gnu".into();
        profile.target_spec.isa = BackendIsaIR::X86;
        profile.target_spec.abi = BackendAbiModelIR::I386SysV;
        profile.target_spec.object_format = BackendObjectFormatIR::Elf32;
        profile.target_spec.data_layout = BackendDataLayoutIR::i386_sysv();
        profile.target_spec.pointer_width = 32;
        profile.target_spec.support_tier = BackendSupportTierIR::Tier2;
        profile
    }

    pub fn nc_i386_windows() -> Self {
        // The material target specification is authoritative for LLVM and
        // object emission. The shared scalar legalization plan remains the
        // x86 family plan until the legacy register planner is split by width.
        let mut profile = Self::nc_i386_linux();
        profile.target_spec.target_triple = "i686-pc-windows-msvc".into();
        profile.target_spec.abi = BackendAbiModelIR::I386Windows;
        profile.target_spec.object_format = BackendObjectFormatIR::Coff;
        profile.target_spec.data_layout = BackendDataLayoutIR::i386_windows();
        profile.target_spec.debug_info_model = BackendDebugInfoModelIR::Pdb;
        profile.target_spec.linker_model = BackendLinkerModelIR::HostNative;
        profile
    }

    pub fn nc_sysv64() -> Self {
        let target = BackendTargetIR::X86_64;
        let calling_convention = BackendCallingConventionIR::NcSysV64;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_win64() -> Self {
        let target = BackendTargetIR::X86_64;
        let calling_convention = BackendCallingConventionIR::NcWin64;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_aapcs64() -> Self {
        let target = BackendTargetIR::AArch64;
        let calling_convention = BackendCallingConventionIR::NcAapcs64;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_x86_64_darwin() -> Self {
        let mut profile = Self::nc_sysv64();
        profile.target_spec.target_triple = "x86_64-apple-darwin".into();
        profile.target_spec.object_format = BackendObjectFormatIR::MachO;
        profile.target_spec.debug_info_model = BackendDebugInfoModelIR::Dwarf;
        profile.target_spec.linker_model = BackendLinkerModelIR::HostNative;
        profile
    }

    pub fn nc_aarch64_linux() -> Self {
        let target = BackendTargetIR::AArch64;
        let calling_convention = BackendCallingConventionIR::NcSysV64;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_aarch64_android(api_level: u32) -> Self {
        let mut profile = Self::nc_aarch64_linux();
        profile.target_spec.target_triple = format!("aarch64-linux-android{api_level}");
        profile.target_spec.relocation_model = BackendRelocationModelIR::Pic;
        profile.target_spec.linker_model = BackendLinkerModelIR::HostNative;
        profile.target_spec.debug_info_model = BackendDebugInfoModelIR::Dwarf;
        profile
    }

    pub fn nc_aarch64_windows() -> Self {
        // Windows Arm64 follows the AArch64 register/aggregate ABI while using
        // COFF, PE and the MSVC target environment.
        let mut profile = Self::nc_aapcs64();
        profile.target_spec.target_triple = "aarch64-pc-windows-msvc".into();
        profile.target_spec.object_format = BackendObjectFormatIR::Coff;
        profile.target_spec.debug_info_model = BackendDebugInfoModelIR::Pdb;
        profile.target_spec.linker_model = BackendLinkerModelIR::HostNative;
        profile
    }

    pub fn nc_portable() -> Self {
        let target = BackendTargetIR::Wasm32;
        let calling_convention = BackendCallingConventionIR::NcPortable;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_sovereign() -> Self {
        let target = BackendTargetIR::X86_64;
        let calling_convention = BackendCallingConventionIR::NcSovereign;
        Self {
            target_spec: BackendTargetSpecIR::from_target_and_calling_convention(
                &target,
                &calling_convention,
            ),
            cpu_tuning: backend_cpu_tuning_profile_for_backend_target(&target),
            destructive_policy: BackendDestructivePolicyIR::strict(),
            target,
            calling_convention,
        }
    }

    pub fn nc_destructive() -> Self {
        let mut profile = Self::nc_sysv64();
        profile.destructive_policy = BackendDestructivePolicyIR::destructive(0x4e43_4445_5354_5255);
        profile
    }

    pub fn set_cpu_tuning(&mut self, cpu_tuning: BackendCpuTuningProfileIR) -> Result<(), String> {
        let expected =
            backend_cpu_target_label_for_backend_target(&self.target).unwrap_or("unsupported");
        if cpu_tuning.target != expected {
            return Err(format!(
                "backend CPU tuning profile '{}' targets '{}', incompatible with backend target '{}'",
                cpu_tuning.microarchitecture_id, cpu_tuning.target, expected
            ));
        }
        self.cpu_tuning = cpu_tuning;
        Ok(())
    }

    pub fn with_cpu_tuning(
        mut self,
        cpu_tuning: BackendCpuTuningProfileIR,
    ) -> Result<Self, String> {
        self.set_cpu_tuning(cpu_tuning)?;
        Ok(self)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
