#[derive(Debug, Clone, PartialEq, Eq)]
struct RuntimeCallCandidateIR {
    canonical_symbol: String,
    arity_min: usize,
    variadic: bool,
}

#[derive(Debug, Clone, Default)]
struct RuntimeCallResolutionIndexIR {
    declared_function_names: HashSet<String>,
    explicit_runtime_functions: HashMap<String, Vec<RuntimeCallCandidateIR>>,
}

fn normalized_unqualified_call_name(name: &str) -> String {
    name.split('<')
        .next()
        .unwrap_or(name)
        .trim()
        .to_ascii_lowercase()
}

fn runtime_candidate_accepts_arity(candidate: &RuntimeCallCandidateIR, arity: usize) -> bool {
    if candidate.variadic {
        arity >= candidate.arity_min
    } else {
        arity == candidate.arity_min
    }
}

impl RuntimeCallResolutionIndexIR {
    fn from_program(program: &Program) -> Self {
        let mut index = Self::default();

        for container in &program.containers {
            for section in &container.sections {
                let functions = match section {
                    Section::Fn(functions)
                    | Section::MoveFn(functions)
                    | Section::ConstFn(functions) => Some(functions),
                    _ => None,
                };
                if let Some(functions) = functions {
                    for function in functions {
                        index
                            .declared_function_names
                            .insert(normalized_unqualified_call_name(&function.name));
                    }
                }
            }
        }

        let mut add_family = |family: &'static ncc_ast::RuntimeApiFamilySpec| {
            for function in &family.functions {
                let function_name = function
                    .name
                    .split('<')
                    .next()
                    .unwrap_or(function.name.as_str());
                let canonical_symbol = ncc_ast::canonical_runtime_symbol(&format!(
                    "{}.{}",
                    family.import_path, function_name
                ));
                index
                    .explicit_runtime_functions
                    .entry(normalized_unqualified_call_name(function_name))
                    .or_default()
                    .push(RuntimeCallCandidateIR {
                        canonical_symbol,
                        arity_min: function.arity_min,
                        variadic: function.variadic,
                    });
            }
        };

        for use_decl in &program.uses {
            if let Some(family) = ncc_ast::runtime_api_find_family_by_import_path(&use_decl.path)
                .or_else(|| ncc_ast::runtime_api_find_family_by_module_path(&use_decl.path))
            {
                add_family(family);
                continue;
            }

            if use_decl.wildcard
                && (ncc_ast::import_path_matches(&use_decl.path, &["nC", "runtime"])
                    || ncc_ast::import_path_matches(&use_decl.path, &["runtime"]))
            {
                for family in ncc_ast::runtime_api_family_specs() {
                    add_family(family);
                }
            }
        }

        for candidates in index.explicit_runtime_functions.values_mut() {
            candidates.sort_by(|left, right| {
                left.canonical_symbol
                    .cmp(&right.canonical_symbol)
                    .then_with(|| left.arity_min.cmp(&right.arity_min))
                    .then_with(|| left.variadic.cmp(&right.variadic))
            });
            candidates.dedup();
        }
        index
    }

    fn explicitly_imported_target(&self, callee: &str, arity: usize) -> Option<String> {
        let candidates = self
            .explicit_runtime_functions
            .get(&normalized_unqualified_call_name(callee))?;
        let mut targets = candidates
            .iter()
            .filter(|candidate| runtime_candidate_accepts_arity(candidate, arity))
            .map(|candidate| candidate.canonical_symbol.clone())
            .collect::<Vec<_>>();
        targets.sort();
        targets.dedup();
        (targets.len() == 1).then(|| targets.remove(0))
    }
}

