pub fn render_backend_simd_microarchitecture(
    microarchitecture: BackendSimdMicroarchitectureIR,
) -> &'static str {
    match microarchitecture {
        BackendSimdMicroarchitectureIR::X86Generic => "x86-generic",
        BackendSimdMicroarchitectureIR::X86IntelSkylake => "x86-intel-skylake",
        BackendSimdMicroarchitectureIR::X86AmdZen3 => "x86-amd-zen3",
        BackendSimdMicroarchitectureIR::AArch64Generic => "aarch64-generic",
        BackendSimdMicroarchitectureIR::AArch64NeoverseN1 => "aarch64-neoverse-n1",
    }
}

pub fn backend_simd_microarchitectures_for_target(
    target: &str,
) -> Vec<BackendSimdMicroarchitectureIR> {
    match target {
        "x86_64" => vec![
            BackendSimdMicroarchitectureIR::X86Generic,
            BackendSimdMicroarchitectureIR::X86IntelSkylake,
            BackendSimdMicroarchitectureIR::X86AmdZen3,
        ],
        "aarch64" => vec![
            BackendSimdMicroarchitectureIR::AArch64Generic,
            BackendSimdMicroarchitectureIR::AArch64NeoverseN1,
        ],
        _ => Vec::new(),
    }
}

pub fn backend_simd_default_microarchitecture_for_target(
    target: &str,
) -> Option<BackendSimdMicroarchitectureIR> {
    backend_simd_microarchitectures_for_target(target)
        .into_iter()
        .next()
}

pub fn backend_simd_schedule_for(
    row: &BackendSimdInstructionEncodingIR,
    microarchitecture: BackendSimdMicroarchitectureIR,
) -> BackendSimdScheduleIR {
    let (latency_cycles, reciprocal_throughput_per_cycle, issue_domain, scheduling_note) = match (
        microarchitecture,
        row.op,
    ) {
        (_, BackendSimdOpIR::Gather) => (
            12,
            "0.25-0.50",
            "vector-memory",
            "irregular memory access; schedule after address/index readiness and avoid clustering",
        ),
        (_, BackendSimdOpIR::Scatter) => (
            14,
            "0.20-0.33",
            "vector-memory-store",
            "masked indexed store; keep late in block and preserve mask/index dependencies",
        ),
        (_, BackendSimdOpIR::LoadAligned | BackendSimdOpIR::StoreAligned) => (
            4,
            "0.50-1.00",
            "load-store",
            "alignment-sensitive memory op; hoist only when alias model proves safety",
        ),
        (_, BackendSimdOpIR::Shuffle) => (
            3,
            "0.50-1.00",
            "shuffle",
            "permute lane pressure; keep near consumers unless it unlocks load/use latency",
        ),
        (_, BackendSimdOpIR::MaskSelect) => (
            2,
            "0.50-1.00",
            "blend-mask",
            "mask-select depends on predicate vector; prefer after predicate materialization",
        ),
        (BackendSimdMicroarchitectureIR::X86IntelSkylake, BackendSimdOpIR::Mul)
        | (BackendSimdMicroarchitectureIR::X86AmdZen3, BackendSimdOpIR::Mul) => (
            4,
            "0.50",
            "fp/int-vector-mul",
            "mul latency dominates dependent chains",
        ),
        (BackendSimdMicroarchitectureIR::AArch64NeoverseN1, BackendSimdOpIR::Mul) => (
            4,
            "0.50",
            "neon-mul",
            "NEON multiply prefers independent accumulation chains",
        ),
        (_, BackendSimdOpIR::Add) => (
            3,
            "0.50-1.00",
            "vector-alu",
            "low-latency vector arithmetic; coalesce adjacent independent ops",
        ),
        (_, BackendSimdOpIR::And | BackendSimdOpIR::Or | BackendSimdOpIR::Xor) => (
            1,
            "0.50-1.00",
            "vector-bitwise",
            "cheap bitwise op; suitable for mask preparation and dependency breaking",
        ),
        (_, BackendSimdOpIR::VZeroUpper) => (
            1,
            "1.00",
            "domain-transition",
            "emit at AVX/SSE boundary to avoid transition penalty",
        ),
        (_, BackendSimdOpIR::Mul) => (
            5,
            "0.50",
            "vector-mul",
            "generic multiply scheduling; keep independent chains apart",
        ),
    };
    BackendSimdScheduleIR {
        microarchitecture,
        feature: row.feature,
        lane: row.lane,
        op: row.op,
        latency_cycles,
        reciprocal_throughput_per_cycle,
        issue_domain,
        scheduling_note,
    }
}

pub fn backend_simd_schedule_matrix() -> Vec<BackendSimdScheduleIR> {
    backend_simd_instruction_selection_matrix()
        .into_iter()
        .flat_map(|row| {
            backend_simd_microarchitectures_for_target(row.target)
                .into_iter()
                .map(move |microarch| backend_simd_schedule_for(&row, microarch))
        })
        .collect()
}

pub fn backend_cpu_tuning_supports_simd_feature(
    profile: &BackendCpuTuningProfileIR,
    feature: BackendSimdFeatureIR,
) -> bool {
    let required = match feature {
        BackendSimdFeatureIR::X86Sse => "+sse",
        BackendSimdFeatureIR::X86Sse41 => "+sse4.1",
        BackendSimdFeatureIR::X86Avx => "+avx",
        BackendSimdFeatureIR::X86Avx2 => "+avx2",
        BackendSimdFeatureIR::X86Avx512F => "+avx512f",
        BackendSimdFeatureIR::AArch64Neon => "+neon",
    };
    profile
        .target_features
        .iter()
        .any(|feature| feature == required)
}

fn backend_cpu_tuning_allows_lane_width(
    profile: &BackendCpuTuningProfileIR,
    lane: BackendSimdLaneIR,
) -> bool {
    match lane {
        BackendSimdLaneIR::F32x16 => profile.preferred_vector_width_bits >= 512,
        BackendSimdLaneIR::F32x8 | BackendSimdLaneIR::I32x8 => {
            profile.preferred_vector_width_bits >= 256
        }
        BackendSimdLaneIR::F32x4 | BackendSimdLaneIR::I32x4 | BackendSimdLaneIR::B128 => {
            profile.preferred_vector_width_bits >= 128
        }
    }
}

pub fn backend_cpu_tuning_selected_simd_rows(
    profile: &BackendCpuTuningProfileIR,
) -> Vec<BackendSimdInstructionEncodingIR> {
    backend_simd_instruction_selection_matrix()
        .into_iter()
        .filter(|row| backend_cpu_tuning_allows_simd_row(profile, row))
        .collect()
}

fn backend_cpu_tuning_allows_simd_row(
    profile: &BackendCpuTuningProfileIR,
    row: &BackendSimdInstructionEncodingIR,
) -> bool {
    row.target == profile.target
        && backend_cpu_tuning_supports_simd_feature(profile, row.feature)
        && backend_cpu_tuning_allows_lane_width(profile, row.lane)
        && (!matches!(row.op, BackendSimdOpIR::Gather | BackendSimdOpIR::Scatter)
            || profile.supports_gather_scatter)
}

pub fn backend_cpu_tuning_schedule_rows(
    profile: &BackendCpuTuningProfileIR,
) -> Vec<BackendSimdScheduleIR> {
    let Some(microarchitecture) = profile.native_microarchitecture else {
        return Vec::new();
    };
    backend_cpu_tuning_selected_simd_rows(profile)
        .iter()
        .map(|row| backend_simd_schedule_for(row, microarchitecture))
        .collect()
}

fn backend_cpu_tuned_feature_lane(
    profile: &BackendCpuTuningProfileIR,
    vector_type: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR)> {
    let microarchitecture = mct_cpu_microarchitecture_by_id(&profile.microarchitecture_id)?;
    let fine_profile = mct_cpu_fine_tuning_profile_by_id(&profile.fine_tuning_profile_id)?;
    let (feature, lane, _) =
        backend_native_cpu_tuned_feature_lane(&microarchitecture, &fine_profile, vector_type, op)?;
    if backend_cpu_tuning_supports_simd_feature(profile, feature)
        && backend_cpu_tuning_allows_lane_width(profile, lane)
    {
        Some((feature, lane))
    } else {
        None
    }
}

fn backend_cpu_tuned_schedule_microarchitecture(
    profile: &BackendCpuTuningProfileIR,
    target: &str,
) -> Option<BackendSimdMicroarchitectureIR> {
    profile
        .native_microarchitecture
        .or_else(|| backend_simd_default_microarchitecture_for_target(target))
}

pub fn lower_backend_vector_expressions(
    function: &FunctionIR,
) -> Vec<BackendVectorExpressionLoweringIR> {
    let mut plan = Vec::new();
    for stmt in &function.body {
        collect_backend_vector_expr_lowering(function, stmt, &mut plan);
    }
    plan
}

pub fn backend_auto_vectorizer_closed_patterns() -> Vec<&'static str> {
    vec![
        "vector_expression_in_loop",
        "contiguous_array_map",
        "contiguous_array_zip_add_mul_bitwise",
        "sum_reduction",
        "product_reduction",
        "indexed_gather",
        "indexed_scatter",
    ]
}

pub fn analyze_backend_auto_vectorization(function: &FunctionIR) -> BackendAutoVectorizerReportIR {
    let target = backend_simd_target_label(&function.backend_plan.target).unwrap_or("unsupported");
    let mut report = BackendAutoVectorizerReportIR {
        function: function.name.clone(),
        target,
        loops_seen: 0,
        vectorized_loops: Vec::new(),
        rejected_loops: Vec::new(),
        closed_patterns: backend_auto_vectorizer_closed_patterns(),
        no_silent_scalar_fallback: true,
        arbitrary_pattern_parity: false,
    };

    collect_backend_auto_vectorization(function, &function.body, 0, &mut report);
    report
}

