pub fn mct_translate_program(ir: &ProgramIR) -> MctTranslationReportIR {
    let units = ir
        .containers
        .iter()
        .map(mct_modal_unit_for_container)
        .collect();
    let surface_descriptors = ir.surface_descriptors.clone();
    let surface_descriptor_count = surface_descriptors.len();
    let surface_descriptor_bytes = surface_descriptors
        .iter()
        .map(|descriptor| descriptor.bytes.len())
        .sum();
    MctTranslationReportIR {
        schema: "nc.mct.translation.v1",
        status: "mct_infrastructure_contract_ready",
        target: ir.target.clone(),
        target_triple: ir.target_spec.target_triple.clone(),
        units,
        surface_descriptors,
        surface_descriptor_count,
        surface_descriptor_bytes,
        backend_contracts: mct_backend_contracts(),
        diagnostics: vec![MctDiagnosticIR::new("I_MCT_INFRASTRUCTURE_001", MctDiagnosticSeverityIR::Info, "MCT infrastructure is available as a translation contract; full LLVM/GCC/rustc parity remains gated by adapter evidence."
                .into())],
        full_llvm_parity: false,
        full_gcc_parity: false,
        full_rustc_parity: false,
        ncc_native_integrated: true,
    }
}

pub fn mct_llvm_pass_pipeline(level: MctLlvmOptimizationLevelIR) -> MctLlvmPassPipelineIR {
    let mut passes = vec![
        MctLlvmPassIR {
            name: "llvm-verify-input",
            stage: "validation",
            purpose: "validate emitted textual LLVM IR before external backend handoff",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "target-datalayout-lock",
            stage: "target",
            purpose: "bind optimizer decisions to the emitted target triple and data layout",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "raw-aa-mayalias-default",
            stage: "memory",
            purpose: "classify escaped, forged, MMIO and DMA addresses as MayAlias unless material ranges prove otherwise",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "raw-tbaa-noalias-suppression",
            stage: "memory",
            purpose: "omit TBAA, noalias and alias-scope claims that ManualRaw source did not establish",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "raw-observable-memory-barriers",
            stage: "memory",
            purpose: "retain volatile, atomic, MMIO and overlap-safe memmove operations across DCE and vectorization",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "officialize-function-attrs",
            stage: "officialization",
            purpose: "keep function attributes deterministic for object/executable smoke",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "mct-fp-intrinsic-canonicalization",
            stage: "fp",
            purpose: "canonicalize declared ft64 math calls to LLVM intrinsics or host libm calls",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "mct-fp-finite-constant-fold",
            stage: "fp",
            purpose: "fold finite literal floating-point math before LLVM handoff",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "mct-fp-dead-declaration-prune",
            stage: "fp",
            purpose: "omit LLVM FP intrinsic declarations after all calls fold away",
            enabled: true,
        },
        MctLlvmPassIR {
            name: "debug-info-preservation",
            stage: "debug",
            purpose:
                "preserve LLVM debug metadata through Clang/LLVM optimization and profiling flags",
            enabled: true,
        },
    ];

    if !matches!(level, MctLlvmOptimizationLevelIR::O0) {
        passes.extend([
            MctLlvmPassIR {
                name: "sroa",
                stage: "scalar",
                purpose: "promote aggregate allocas and expose scalar memory to LLVM",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "mem2reg",
                stage: "scalar",
                purpose: "promote eligible stack slots to SSA registers",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "instcombine",
                stage: "scalar",
                purpose: "fold local arithmetic, casts and pointer idioms",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "simplifycfg",
                stage: "cfg",
                purpose: "normalize branches and remove trivial control-flow",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "early-cse",
                stage: "scalar",
                purpose: "remove redundant local expressions before heavier passes",
                enabled: true,
            },
        ]);
    }

    if matches!(
        level,
        MctLlvmOptimizationLevelIR::O2
            | MctLlvmOptimizationLevelIR::O3
            | MctLlvmOptimizationLevelIR::Os
            | MctLlvmOptimizationLevelIR::Oz
    ) {
        passes.extend([
            MctLlvmPassIR {
                name: "reassociate",
                stage: "scalar",
                purpose: "reassociate arithmetic trees for global value optimizations",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "gvn",
                stage: "scalar",
                purpose: "eliminate redundant value computations across basic blocks",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "licm",
                stage: "loop",
                purpose: "hoist loop-invariant loads and computations when legal",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "loop-rotate",
                stage: "loop",
                purpose: "normalize loops for vectorization and branch prediction",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "dse",
                stage: "memory",
                purpose: "remove dead stores after alias-safe analysis",
                enabled: true,
            },
        ]);
    }

    if matches!(
        level,
        MctLlvmOptimizationLevelIR::O2 | MctLlvmOptimizationLevelIR::O3
    ) {
        passes.extend([
            MctLlvmPassIR {
                name: "loop-vectorize",
                stage: "vector",
                purpose: "vectorize only when LLVM proves raw memory dependences or guards them at runtime; ncc supplies no implicit noalias claim",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "slp-vectorizer",
                stage: "vector",
                purpose: "combine scalar packs only under ordinary LLVM memory legality without ncc TBAA/noalias metadata",
                enabled: true,
            },
        ]);
    }

    if matches!(
        level,
        MctLlvmOptimizationLevelIR::O2
            | MctLlvmOptimizationLevelIR::O3
            | MctLlvmOptimizationLevelIR::Os
            | MctLlvmOptimizationLevelIR::Oz
    ) {
        passes.extend([
            MctLlvmPassIR {
                name: "thinlto-prelink",
                stage: "lto",
                purpose: "prepare optimized IR for ThinLTO/full-LTO handoff through Clang",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "instrprof-generate",
                stage: "pgo",
                purpose: "support instrumentation profile generation through Clang profile runtime",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "instrprof-use",
                stage: "pgo",
                purpose: "support merged profile data consumption through Clang/LLVM",
                enabled: true,
            },
        ]);
    }

    if matches!(level, MctLlvmOptimizationLevelIR::O3) {
        passes.extend([
            MctLlvmPassIR {
                name: "loop-unroll",
                stage: "loop",
                purpose: "unroll profitable loops for high-throughput builds",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "aggressive-instcombine",
                stage: "scalar",
                purpose: "run additional scalar officialization for O3",
                enabled: true,
            },
        ]);
    }

    if matches!(
        level,
        MctLlvmOptimizationLevelIR::Os | MctLlvmOptimizationLevelIR::Oz
    ) {
        passes.extend([
            MctLlvmPassIR {
                name: "globaldce",
                stage: "size",
                purpose: "remove unreachable globals/functions for size builds",
                enabled: true,
            },
            MctLlvmPassIR {
                name: "mergefunc",
                stage: "size",
                purpose: "merge equivalent functions where the target permits it",
                enabled: matches!(level, MctLlvmOptimizationLevelIR::Os),
            },
        ]);
    }

    let (profile, clang_opt_arg, opt_passes_arg) = match level {
        MctLlvmOptimizationLevelIR::O0 => ("debug", "-O0", "default<O0>"),
        MctLlvmOptimizationLevelIR::O1 => ("release-light", "-O1", "default<O1>"),
        MctLlvmOptimizationLevelIR::O2 => ("release", "-O2", "default<O2>"),
        MctLlvmOptimizationLevelIR::O3 => ("release-aggressive", "-O3", "default<O3>"),
        MctLlvmOptimizationLevelIR::Os => ("release-size", "-Os", "default<Os>"),
        MctLlvmOptimizationLevelIR::Oz => ("release-tiny", "-Oz", "default<Oz>"),
    };
    let pass_count = passes.iter().filter(|pass| pass.enabled).count();

    MctLlvmPassPipelineIR {
        schema: "nc.mct.llvm.pass_pipeline.v1",
        status: "mct_llvm_pass_pipeline_owned",
        owner: "ncc-mct",
        level,
        profile,
        clang_opt_arg,
        opt_passes_arg,
        clang_pass_manager_args: vec![
            "<clang-default-new-pass-manager>",
            "opt -passes=<pipeline>",
        ],
        clang_lto_args: vec!["-flto=thin", "-flto=full"],
        clang_pgo_generate_args: vec!["-fprofile-generate=<dir>", "-fdebug-info-for-profiling"],
        clang_pgo_use_arg_template: "-fprofile-use=<profdata>",
        clang_debug_args: vec!["-g", "-gdwarf-5", "-fdebug-info-for-profiling"],
        pass_count,
        passes,
        diagnostics: vec![MctDiagnosticIR::new("I_MCT_LLVM_PASS_PIPELINE_001", MctDiagnosticSeverityIR::Info, format!(
                "LLVM pass pipeline is selected and owned by ncc-mct at {}; F8 applies it through Clang/LLVM new pass manager, LTO, PGO and debug metadata flags.",
                clang_opt_arg
            ))],
        full_llvm_pass_manager_parity: true,
    }
}

pub fn mct_emit_llvm_module(ir: &ProgramIR) -> MctLlvmModuleIR {
    mct_emit_llvm_module_with_pass_pipeline(
        ir,
        mct_llvm_pass_pipeline(MctLlvmOptimizationLevelIR::O0),
    )
}

pub fn mct_emit_llvm_module_with_pass_pipeline(
    ir: &ProgramIR,
    pass_pipeline: MctLlvmPassPipelineIR,
) -> MctLlvmModuleIR {
    mct_emit_llvm_module_with_debug_config(ir, pass_pipeline, mct_llvm_default_debug_config())
}

pub fn mct_llvm_default_debug_config() -> MctLlvmDebugConfigIR {
    MctLlvmDebugConfigIR {
        enabled: true,
        source_filename: "ncc_mct_llvm".into(),
        source_directory: ".".into(),
        producer: "ncc mct llvm".into(),
        dwarf_version: 5,
        debug_info_version: 3,
        emission_kind: "FullDebug",
    }
}

pub fn mct_llvm_debug_config_for_source(
    source_filename: impl Into<String>,
    source_directory: impl Into<String>,
) -> MctLlvmDebugConfigIR {
    MctLlvmDebugConfigIR {
        source_filename: source_filename.into(),
        source_directory: source_directory.into(),
        ..mct_llvm_default_debug_config()
    }
}

pub fn render_mct_cpu_tuning_intent(intent: MctCpuTuningIntentIR) -> &'static str {
    match intent {
        MctCpuTuningIntentIR::Debug => "debug",
        MctCpuTuningIntentIR::Baseline => "baseline",
        MctCpuTuningIntentIR::Latency => "latency",
        MctCpuTuningIntentIR::Throughput => "throughput",
        MctCpuTuningIntentIR::Size => "size",
    }
}

