pub fn mct_cpu_fine_tuning_profiles() -> Vec<MctCpuFineTuningProfileIR> {
    vec![
        MctCpuFineTuningProfileIR {
            id: "debug",
            intent: MctCpuTuningIntentIR::Debug,
            opt_level_hint: "O0",
            inline_policy: "minimal-inline-for-debuggability",
            unroll_policy: "off",
            vectorize_policy: "off",
            slp_policy: "off",
            prefetch_policy: "off",
            branch_policy: "preserve-source-shape",
            scheduler_policy: "preserve-debug-order",
        },
        MctCpuFineTuningProfileIR {
            id: "baseline",
            intent: MctCpuTuningIntentIR::Baseline,
            opt_level_hint: "O2",
            inline_policy: "balanced-inline",
            unroll_policy: "bounded",
            vectorize_policy: "legal-target-width",
            slp_policy: "enabled",
            prefetch_policy: "conservative",
            branch_policy: "balanced-layout",
            scheduler_policy: "target-default",
        },
        MctCpuFineTuningProfileIR {
            id: "latency",
            intent: MctCpuTuningIntentIR::Latency,
            opt_level_hint: "O2",
            inline_policy: "hot-path-inline",
            unroll_policy: "small-dependent-loops",
            vectorize_policy: "avoid-latency-expanding-vectorization",
            slp_policy: "enabled-when-shortens-critical-path",
            prefetch_policy: "demand-driven",
            branch_policy: "minimize-critical-branch-depth",
            scheduler_policy: "critical-path-first",
        },
        MctCpuFineTuningProfileIR {
            id: "throughput",
            intent: MctCpuTuningIntentIR::Throughput,
            opt_level_hint: "O3",
            inline_policy: "aggressive-hot-inline",
            unroll_policy: "throughput-unroll",
            vectorize_policy: "prefer-wide-vectorization",
            slp_policy: "aggressive",
            prefetch_policy: "streaming-when-stride-known",
            branch_policy: "layout-for-fallthrough-throughput",
            scheduler_policy: "port-pressure-and-ilp",
        },
        MctCpuFineTuningProfileIR {
            id: "size",
            intent: MctCpuTuningIntentIR::Size,
            opt_level_hint: "Oz",
            inline_policy: "size-only-inline",
            unroll_policy: "off",
            vectorize_policy: "size-profitable-only",
            slp_policy: "size-profitable-only",
            prefetch_policy: "off",
            branch_policy: "compact-layout",
            scheduler_policy: "size-preserving",
        },
    ]
}

pub fn mct_cpu_scheduling_profile(
    microarchitecture: &MctCpuMicroarchitectureIR,
    fine_profile: &MctCpuFineTuningProfileIR,
) -> MctCpuSchedulingProfileIR {
    let mut llvm_args = vec![
        format!("-{}", fine_profile.opt_level_hint),
        format!("-mcpu={}", microarchitecture.llvm_target_cpu),
        format!("-mtune={}", microarchitecture.llvm_tune_cpu),
    ];
    if !microarchitecture.target_features.is_empty() {
        llvm_args.push(format!(
            "-mattr={}",
            microarchitecture.target_features.join(",")
        ));
    }
    llvm_args.push(format!(
        "-passes={}",
        match fine_profile.intent {
            MctCpuTuningIntentIR::Debug => "default<O0>",
            MctCpuTuningIntentIR::Baseline | MctCpuTuningIntentIR::Latency => "default<O2>",
            MctCpuTuningIntentIR::Throughput => "default<O3>",
            MctCpuTuningIntentIR::Size => "default<Oz>",
        }
    ));

    MctCpuSchedulingProfileIR {
        microarchitecture_id: microarchitecture.id,
        fine_tuning_profile_id: fine_profile.id,
        target: microarchitecture.target,
        llvm_target_cpu: microarchitecture.llvm_target_cpu,
        llvm_tune_cpu: microarchitecture.llvm_tune_cpu,
        opt_level_hint: fine_profile.opt_level_hint,
        issue_width: microarchitecture.issue_width,
        preferred_vector_width_bits: microarchitecture.preferred_vector_width_bits,
        load_latency_cycles: microarchitecture.load_latency_cycles,
        branch_mispredict_penalty_cycles: microarchitecture.branch_mispredict_penalty_cycles,
        unroll_policy: fine_profile.unroll_policy,
        vectorize_policy: fine_profile.vectorize_policy,
        scheduling_model: microarchitecture.scheduling_model,
        llvm_args,
        diagnostics: vec![MctDiagnosticIR::new(
            "I_MCT_CPU_SCHED_001",
            MctDiagnosticSeverityIR::Info,
            format!(
                "{} + {} produces a deterministic MCT CPU scheduling profile.",
                microarchitecture.id, fine_profile.id
            ),
        )],
    }
}

pub fn mct_cpu_tuning_matrix() -> MctCpuTuningMatrixIR {
    let microarchitectures = mct_cpu_microarchitectures();
    let fine_tuning_profiles = mct_cpu_fine_tuning_profiles();
    let scheduling_profiles = microarchitectures
        .iter()
        .flat_map(|microarchitecture| {
            fine_tuning_profiles
                .iter()
                .map(move |profile| mct_cpu_scheduling_profile(microarchitecture, profile))
        })
        .collect::<Vec<_>>();

    MctCpuTuningMatrixIR {
        schema: "nc.mct.cpu_tuning_matrix.v1",
        status: "mct_cpu_tuning_matrix_closed",
        phase: "F11",
        microarchitecture_count: microarchitectures.len(),
        fine_tuning_profile_count: fine_tuning_profiles.len(),
        scheduling_profile_count: scheduling_profiles.len(),
        microarchitectures,
        fine_tuning_profiles,
        scheduling_profiles,
        full_llvm_cpu_universe: false,
        full_llvm_scheduler_parity: false,
        diagnostics: vec![MctDiagnosticIR::new("I_MCT_CPU_TUNING_MATRIX_001", MctDiagnosticSeverityIR::Info, "F11 closes ncc/MCT CPU tuning profiles for the declared official microarchitecture set; it does not claim every LLVM CPU model."
                .into())],
    }
}

pub fn mct_cpu_microarchitecture_by_id(id: &str) -> Option<MctCpuMicroarchitectureIR> {
    mct_cpu_microarchitectures()
        .into_iter()
        .find(|profile| profile.id.eq_ignore_ascii_case(id))
}

pub fn mct_cpu_fine_tuning_profile_by_id(id: &str) -> Option<MctCpuFineTuningProfileIR> {
    mct_cpu_fine_tuning_profiles()
        .into_iter()
        .find(|profile| profile.id.eq_ignore_ascii_case(id))
}

pub fn backend_native_microarchitecture_for_mct_cpu(
    microarchitecture_id: &str,
) -> Option<BackendSimdMicroarchitectureIR> {
    match microarchitecture_id.to_ascii_lowercase().as_str() {
        "x86_64-v1" | "x86_64-v2" => Some(BackendSimdMicroarchitectureIR::X86Generic),
        "x86_64-v3" | "x86_64-v4" | "intel-skylake" | "intel-icelake-client" => {
            Some(BackendSimdMicroarchitectureIR::X86IntelSkylake)
        }
        "amd-znver3" | "amd-znver4" => Some(BackendSimdMicroarchitectureIR::X86AmdZen3),
        "aarch64-generic" | "apple-m1" | "apple-m2" => {
            Some(BackendSimdMicroarchitectureIR::AArch64Generic)
        }
        "neoverse-n1" | "neoverse-v1" => Some(BackendSimdMicroarchitectureIR::AArch64NeoverseN1),
        _ => None,
    }
}

pub fn backend_simd_feature_supported_by_mct_cpu(
    feature: BackendSimdFeatureIR,
    microarchitecture: &MctCpuMicroarchitectureIR,
) -> bool {
    let required = match feature {
        BackendSimdFeatureIR::X86Sse => "+sse",
        BackendSimdFeatureIR::X86Sse41 => "+sse4.1",
        BackendSimdFeatureIR::X86Avx => "+avx",
        BackendSimdFeatureIR::X86Avx2 => "+avx2",
        BackendSimdFeatureIR::X86Avx512F => "+avx512f",
        BackendSimdFeatureIR::AArch64Neon => "+neon",
    };
    microarchitecture.target_features.contains(&required)
}

pub fn backend_native_cpu_tuning_bridge_for_mct_cpu(
    microarchitecture_id: &str,
) -> Result<BackendNativeCpuTuningBridgeIR, String> {
    let microarchitecture =
        mct_cpu_microarchitecture_by_id(microarchitecture_id).ok_or_else(|| {
            format!(
                "unknown MCT CPU microarchitecture '{}'",
                microarchitecture_id
            )
        })?;
    let native_microarchitecture =
        backend_native_microarchitecture_for_mct_cpu(microarchitecture.id);
    let schedule_rows = native_microarchitecture
        .map(|native| {
            backend_simd_instruction_selection_matrix()
                .into_iter()
                .filter(|row| row.target == microarchitecture.target)
                .filter(|row| {
                    backend_simd_feature_supported_by_mct_cpu(row.feature, &microarchitecture)
                })
                .map(|row| backend_simd_schedule_for(&row, native))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let schedule_row_count = schedule_rows.len();
    let mut diagnostics = Vec::new();
    let status = if native_microarchitecture.is_some() && schedule_row_count > 0 {
        diagnostics.push(MctDiagnosticIR::new(
            "I_MCT_NATIVE_CPU_TUNING_BRIDGE_001",
            MctDiagnosticSeverityIR::Info,
            format!(
                "MCT CPU profile '{}' is connected to the declared ncc native SIMD scheduler rows.",
                microarchitecture.id
            ),
        ));
        "backend_native_cpu_tuning_bridge_closed"
    } else {
        diagnostics.push(MctDiagnosticIR::new(
            "W_MCT_NATIVE_CPU_TUNING_BRIDGE_001",
            MctDiagnosticSeverityIR::Warning,
            format!(
                "MCT CPU profile '{}' has no native SIMD scheduler rows in the current ncc bridge.",
                microarchitecture.id
            ),
        ));
        "backend_native_cpu_tuning_bridge_unsupported_target"
    };

    Ok(BackendNativeCpuTuningBridgeIR {
        schema: "nc.backend.native_cpu_tuning_bridge.v1",
        status,
        phase: "F12",
        microarchitecture_id: microarchitecture.id,
        target: microarchitecture.target,
        llvm_target_cpu: microarchitecture.llvm_target_cpu,
        llvm_tune_cpu: microarchitecture.llvm_tune_cpu,
        native_microarchitecture,
        schedule_rows,
        schedule_row_count,
        object_disasm_evidence_required: true,
        full_native_scheduler_parity: false,
        diagnostics,
    })
}

pub fn backend_native_cpu_tuning_policy_for_mct_cpu(
    microarchitecture_id: &str,
    fine_tuning_profile_id: &str,
) -> Result<BackendNativeCpuTuningPolicyIR, String> {
    let microarchitecture =
        mct_cpu_microarchitecture_by_id(microarchitecture_id).ok_or_else(|| {
            format!(
                "unknown MCT CPU microarchitecture '{}'",
                microarchitecture_id
            )
        })?;
    let fine_tuning_profile = mct_cpu_fine_tuning_profile_by_id(fine_tuning_profile_id)
        .ok_or_else(|| {
            format!(
                "unknown MCT fine tuning profile '{}'",
                fine_tuning_profile_id
            )
        })?;
    let native_microarchitecture =
        backend_native_microarchitecture_for_mct_cpu(microarchitecture.id);
    let preferred_vector_width_bits =
        backend_native_cpu_tuning_preferred_vector_width(&microarchitecture, &fine_tuning_profile);
    let decisions =
        backend_native_cpu_tuning_candidate_ops(&microarchitecture, &fine_tuning_profile)
            .into_iter()
            .filter_map(|(op, vector_type)| {
                select_backend_simd_instruction_for_mct_cpu(
                    microarchitecture.id,
                    fine_tuning_profile.id,
                    vector_type,
                    op,
                )
                .ok()
                .flatten()
            })
            .collect::<Vec<_>>();
    let decision_count = decisions.len();
    let mut diagnostics = Vec::new();
    let status = if native_microarchitecture.is_some() && decision_count > 0 {
        diagnostics.push(MctDiagnosticIR::new(
            "I_MCT_NATIVE_CPU_POLICY_001",
            MctDiagnosticSeverityIR::Info,
            format!(
                "{} + {} selects concrete ncc-native SIMD instructions and schedules.",
                microarchitecture.id, fine_tuning_profile.id
            ),
        ));
        "backend_native_cpu_tuning_policy_closed"
    } else {
        diagnostics.push(MctDiagnosticIR::new(
            "W_MCT_NATIVE_CPU_POLICY_001",
            MctDiagnosticSeverityIR::Warning,
            format!(
                "{} + {} has no current ncc-native SIMD policy decisions.",
                microarchitecture.id, fine_tuning_profile.id
            ),
        ));
        "backend_native_cpu_tuning_policy_unsupported_target"
    };

    Ok(BackendNativeCpuTuningPolicyIR {
        schema: "nc.backend.native_cpu_tuning_policy.v1",
        status,
        phase: "F12",
        microarchitecture_id: microarchitecture.id,
        fine_tuning_profile_id: fine_tuning_profile.id,
        target: microarchitecture.target,
        native_microarchitecture,
        preferred_vector_width_bits,
        vectorize_policy: fine_tuning_profile.vectorize_policy,
        scheduler_policy: fine_tuning_profile.scheduler_policy,
        decisions,
        decision_count,
        full_native_scheduler_parity: false,
        diagnostics,
    })
}

pub fn select_backend_simd_instruction_for_mct_cpu(
    microarchitecture_id: &str,
    fine_tuning_profile_id: &str,
    vector_type: &'static str,
    op: BackendSimdOpIR,
) -> Result<Option<BackendNativeCpuTuningDecisionIR>, String> {
    let microarchitecture =
        mct_cpu_microarchitecture_by_id(microarchitecture_id).ok_or_else(|| {
            format!(
                "unknown MCT CPU microarchitecture '{}'",
                microarchitecture_id
            )
        })?;
    let fine_tuning_profile = mct_cpu_fine_tuning_profile_by_id(fine_tuning_profile_id)
        .ok_or_else(|| {
            format!(
                "unknown MCT fine tuning profile '{}'",
                fine_tuning_profile_id
            )
        })?;
    let Some(native_microarchitecture) =
        backend_native_microarchitecture_for_mct_cpu(microarchitecture.id)
    else {
        return Ok(None);
    };
    let Some((feature, lane, selection_reason)) = backend_native_cpu_tuned_feature_lane(
        &microarchitecture,
        &fine_tuning_profile,
        vector_type,
        op,
    ) else {
        return Ok(None);
    };
    if !backend_simd_feature_supported_by_mct_cpu(feature, &microarchitecture) {
        return Ok(None);
    }
    let Some(selected) =
        select_backend_simd_instruction_encoding(microarchitecture.target, feature, lane, op)
    else {
        return Ok(None);
    };
    let schedule = backend_simd_schedule_for(&selected, native_microarchitecture);
    Ok(Some(BackendNativeCpuTuningDecisionIR {
        op,
        vector_type,
        feature: selected.feature,
        lane: selected.lane,
        selected_mnemonic: selected.mnemonic,
        selected_asm: selected.asm,
        selected_bytes: selected.bytes,
        schedule,
        selection_reason,
    }))
}

fn backend_native_cpu_tuning_candidate_ops(
    microarchitecture: &MctCpuMicroarchitectureIR,
    fine_tuning_profile: &MctCpuFineTuningProfileIR,
) -> Vec<(BackendSimdOpIR, &'static str)> {
    if matches!(fine_tuning_profile.intent, MctCpuTuningIntentIR::Debug) {
        return vec![
            (BackendSimdOpIR::LoadAligned, "vector<dword>"),
            (BackendSimdOpIR::StoreAligned, "vector<dword>"),
            (BackendSimdOpIR::Add, "vector<dword>"),
        ];
    }
    let mut ops = vec![
        (BackendSimdOpIR::LoadAligned, "vector<dword>"),
        (BackendSimdOpIR::StoreAligned, "vector<dword>"),
        (BackendSimdOpIR::Add, "vector<dword>"),
        (BackendSimdOpIR::Mul, "vector<dword>"),
        (BackendSimdOpIR::Shuffle, "vector<dword>"),
        (BackendSimdOpIR::MaskSelect, "vector<dword>"),
    ];
    if microarchitecture.supports_gather_scatter {
        ops.push((BackendSimdOpIR::Gather, "simd<f32x8>"));
        ops.push((BackendSimdOpIR::Scatter, "simd<f32x16>"));
    }
    if microarchitecture.target == "x86_64"
        && backend_native_cpu_tuning_preferred_vector_width(microarchitecture, fine_tuning_profile)
            >= 256
    {
        ops.push((BackendSimdOpIR::VZeroUpper, "simd<f32x8>"));
    }
    ops
}

fn backend_native_cpu_tuning_preferred_vector_width(
    microarchitecture: &MctCpuMicroarchitectureIR,
    fine_tuning_profile: &MctCpuFineTuningProfileIR,
) -> usize {
    match fine_tuning_profile.intent {
        MctCpuTuningIntentIR::Debug | MctCpuTuningIntentIR::Latency => {
            microarchitecture.preferred_vector_width_bits.min(128)
        }
        MctCpuTuningIntentIR::Size => microarchitecture.preferred_vector_width_bits.min(128),
        MctCpuTuningIntentIR::Baseline => microarchitecture.preferred_vector_width_bits.min(256),
        MctCpuTuningIntentIR::Throughput => microarchitecture.preferred_vector_width_bits,
    }
}

fn backend_native_cpu_tuned_feature_lane(
    microarchitecture: &MctCpuMicroarchitectureIR,
    fine_tuning_profile: &MctCpuFineTuningProfileIR,
    vector_type: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR, &'static str)> {
    let ty = vector_type.trim().replace(' ', "").to_ascii_lowercase();
    let width =
        backend_native_cpu_tuning_preferred_vector_width(microarchitecture, fine_tuning_profile);
    match microarchitecture.target {
        "x86_64" => backend_native_x86_feature_lane(microarchitecture, &ty, width, op),
        "aarch64" => backend_native_aarch64_feature_lane(microarchitecture, &ty, op),
        _ => None,
    }
}

fn backend_native_x86_feature_lane(
    microarchitecture: &MctCpuMicroarchitectureIR,
    ty: &str,
    width: usize,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR, &'static str)> {
    let has_avx =
        backend_simd_feature_supported_by_mct_cpu(BackendSimdFeatureIR::X86Avx, microarchitecture);
    let has_avx2 =
        backend_simd_feature_supported_by_mct_cpu(BackendSimdFeatureIR::X86Avx2, microarchitecture);
    let has_avx512 = backend_simd_feature_supported_by_mct_cpu(
        BackendSimdFeatureIR::X86Avx512F,
        microarchitecture,
    );
    let has_sse41 = backend_simd_feature_supported_by_mct_cpu(
        BackendSimdFeatureIR::X86Sse41,
        microarchitecture,
    );
    let integer = backend_vector_type_is_integer(ty);
    match op {
        BackendSimdOpIR::Gather if microarchitecture.supports_gather_scatter && has_avx2 => Some((
            BackendSimdFeatureIR::X86Avx2,
            BackendSimdLaneIR::F32x8,
            "cpu-policy-avx2-gather",
        )),
        BackendSimdOpIR::Scatter if microarchitecture.supports_gather_scatter && has_avx512 => {
            Some((
                BackendSimdFeatureIR::X86Avx512F,
                BackendSimdLaneIR::F32x16,
                "cpu-policy-avx512-scatter",
            ))
        }
        BackendSimdOpIR::MaskSelect if width >= 256 && has_avx => Some((
            BackendSimdFeatureIR::X86Avx,
            BackendSimdLaneIR::F32x8,
            "cpu-policy-wide-avx-mask",
        )),
        BackendSimdOpIR::MaskSelect if has_sse41 => Some((
            BackendSimdFeatureIR::X86Sse41,
            BackendSimdLaneIR::F32x4,
            "cpu-policy-sse41-mask",
        )),
        BackendSimdOpIR::Shuffle if width >= 256 && has_avx => Some((
            BackendSimdFeatureIR::X86Avx,
            BackendSimdLaneIR::F32x8,
            "cpu-policy-wide-avx-shuffle",
        )),
        BackendSimdOpIR::Shuffle => Some((
            BackendSimdFeatureIR::X86Sse,
            BackendSimdLaneIR::F32x4,
            "cpu-policy-sse-shuffle",
        )),
        BackendSimdOpIR::Add if integer && width >= 256 && has_avx2 => Some((
            BackendSimdFeatureIR::X86Avx2,
            BackendSimdLaneIR::I32x8,
            "cpu-policy-wide-avx2-i32-add",
        )),
        BackendSimdOpIR::Mul if integer && width >= 256 && has_avx2 => Some((
            BackendSimdFeatureIR::X86Avx2,
            BackendSimdLaneIR::I32x8,
            "cpu-policy-wide-avx2-i32-mul",
        )),
        BackendSimdOpIR::Mul if integer && has_sse41 => Some((
            BackendSimdFeatureIR::X86Sse41,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-sse41-i32-mul",
        )),
        BackendSimdOpIR::Add if integer => Some((
            BackendSimdFeatureIR::X86Sse,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-sse-i32-add",
        )),
        BackendSimdOpIR::And | BackendSimdOpIR::Or | BackendSimdOpIR::Xor => Some((
            BackendSimdFeatureIR::X86Sse,
            BackendSimdLaneIR::B128,
            "cpu-policy-sse-bitwise",
        )),
        BackendSimdOpIR::LoadAligned
        | BackendSimdOpIR::StoreAligned
        | BackendSimdOpIR::Add
        | BackendSimdOpIR::Mul
            if width >= 256 && has_avx =>
        {
            Some((
                BackendSimdFeatureIR::X86Avx,
                BackendSimdLaneIR::F32x8,
                "cpu-policy-wide-avx-f32",
            ))
        }
        BackendSimdOpIR::LoadAligned
        | BackendSimdOpIR::StoreAligned
        | BackendSimdOpIR::Add
        | BackendSimdOpIR::Mul => Some((
            BackendSimdFeatureIR::X86Sse,
            BackendSimdLaneIR::F32x4,
            "cpu-policy-sse-f32",
        )),
        BackendSimdOpIR::VZeroUpper if width >= 256 && has_avx => Some((
            BackendSimdFeatureIR::X86Avx,
            BackendSimdLaneIR::B128,
            "cpu-policy-avx-sse-boundary",
        )),
        _ => None,
    }
}

fn backend_native_aarch64_feature_lane(
    microarchitecture: &MctCpuMicroarchitectureIR,
    ty: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR, &'static str)> {
    if !backend_simd_feature_supported_by_mct_cpu(
        BackendSimdFeatureIR::AArch64Neon,
        microarchitecture,
    ) {
        return None;
    }
    let integer = backend_vector_type_is_integer(ty);
    match op {
        BackendSimdOpIR::Gather | BackendSimdOpIR::Scatter
            if !microarchitecture.supports_gather_scatter =>
        {
            None
        }
        BackendSimdOpIR::Gather => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-neon-lane-gather",
        )),
        BackendSimdOpIR::Scatter => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-neon-lane-scatter",
        )),
        BackendSimdOpIR::And
        | BackendSimdOpIR::Or
        | BackendSimdOpIR::Xor
        | BackendSimdOpIR::MaskSelect => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::B128,
            "cpu-policy-neon-b128",
        )),
        BackendSimdOpIR::Shuffle if integer => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-neon-i32-shuffle",
        )),
        BackendSimdOpIR::Add | BackendSimdOpIR::Mul if integer => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::I32x4,
            "cpu-policy-neon-i32",
        )),
        BackendSimdOpIR::LoadAligned
        | BackendSimdOpIR::StoreAligned
        | BackendSimdOpIR::Add
        | BackendSimdOpIR::Mul
        | BackendSimdOpIR::Shuffle => Some((
            BackendSimdFeatureIR::AArch64Neon,
            BackendSimdLaneIR::F32x4,
            "cpu-policy-neon-f32",
        )),
        BackendSimdOpIR::VZeroUpper => None,
    }
}

pub fn mct_llvm_target_attributes_for_spec(
    spec: &BackendTargetSpecIR,
) -> MctLlvmTargetAttributesIR {
    let target_cpu = match spec.isa {
        BackendIsaIR::X86 => "i686",
        BackendIsaIR::X86_64 => "x86-64",
        BackendIsaIR::ArmV7 => "generic",
        BackendIsaIR::AArch64 => "generic",
        BackendIsaIR::Wasm32 => "generic",
        BackendIsaIR::RiscV32 => "generic-rv32",
        BackendIsaIR::RiscV64 => "generic-rv64",
    }
    .to_string();
    let target_features = match spec.isa {
        BackendIsaIR::X86 => Vec::new(),
        BackendIsaIR::X86_64 => vec![
            "+cx8".to_string(),
            "+fxsr".to_string(),
            "+mmx".to_string(),
            "+sse".to_string(),
            "+sse2".to_string(),
            "+x87".to_string(),
        ],
        BackendIsaIR::ArmV7 => vec!["+thumb2".to_string(), "+v7".to_string()],
        BackendIsaIR::AArch64 => vec!["+neon".to_string()],
        BackendIsaIR::Wasm32 => vec!["+mutable-globals".to_string(), "+sign-ext".to_string()],
        BackendIsaIR::RiscV32 => vec!["+m".to_string(), "+a".to_string(), "+c".to_string()],
        BackendIsaIR::RiscV64 => Vec::new(),
    };
    let mut function_attributes = vec![
        llvm_function_attr_flag("nounwind", "exception"),
        llvm_function_attr_kv("target-cpu", &target_cpu, "target"),
        llvm_function_attr_kv("frame-pointer", "all", "debug"),
        llvm_function_attr_kv("min-legal-vector-width", "0", "vector"),
        llvm_function_attr_kv("stack-protector-buffer-size", "8", "stack"),
    ];
    if !target_features.is_empty() {
        function_attributes.push(llvm_function_attr_kv(
            "target-features",
            &target_features.join(","),
            "target",
        ));
    }
    if matches!(
        spec.object_format,
        BackendObjectFormatIR::Elf32
            | BackendObjectFormatIR::Elf64
            | BackendObjectFormatIR::Coff
            | BackendObjectFormatIR::MachO
    ) {
        function_attributes.push(llvm_function_attr_flag("uwtable", "unwind"));
    }
    if matches!(spec.runtime_model, BackendRuntimeModelIR::Freestanding) {
        function_attributes.push(llvm_function_attr_kv("no-builtins", "true", "freestanding"));
    }
    if let Ok(stack) = ncc_machine::machine_stack_plan(&spec.target_triple) {
        if let Some(probe) = stack.probe_symbol {
            function_attributes.push(llvm_function_attr_kv("probe-stack", probe, "stack"));
        } else if stack.probe_strategy == ncc_machine::StackProbeStrategy::InlinePageTouch {
            function_attributes.push(llvm_function_attr_kv("probe-stack", "inline-asm", "stack"));
        }
        if stack.probe_strategy != ncc_machine::StackProbeStrategy::None {
            function_attributes.push(llvm_function_attr_kv(
                "stack-probe-size",
                &stack.probe_threshold_bytes.to_string(),
                "stack",
            ));
        }
    }

    let attribute_group = "#0".to_string();
    let attribute_group_ir = format!(
        "attributes {} = {{ {} }}\n",
        attribute_group,
        function_attributes
            .iter()
            .map(|attribute| attribute.llvm_ir.as_str())
            .collect::<Vec<_>>()
            .join(" ")
    );
    MctLlvmTargetAttributesIR {
        schema: "nc.mct.llvm.target_attributes.v1",
        status: "mct_llvm_target_attributes_closed",
        target_triple: spec.target_triple.clone(),
        object_format: llvm_backend_object_format_label(&spec.object_format).to_string(),
        abi: llvm_backend_abi_label(&spec.abi).to_string(),
        debug_model: llvm_backend_debug_model_label(&spec.debug_info_model).to_string(),
        attribute_group,
        target_cpu,
        tune_cpu: None,
        target_features,
        microarchitecture: None,
        fine_tuning_profile: None,
        function_attributes,
        attribute_group_ir,
        applies_to_emitted_functions: true,
        full_target_attribute_parity: false,
        diagnostics: vec![MctDiagnosticIR::new("I_MCT_LLVM_TARGET_ATTR_001", MctDiagnosticSeverityIR::Info, format!(
                "LLVM target attributes are selected for {} and applied to emitted MCT LLVM functions.",
                spec.target_triple
            ))],
    }
}

pub fn mct_llvm_target_attributes_for_cpu_tuning(
    spec: &BackendTargetSpecIR,
    microarchitecture_id: &str,
    fine_tuning_profile_id: &str,
) -> Result<MctLlvmTargetAttributesIR, String> {
    let microarchitecture =
        mct_cpu_microarchitecture_by_id(microarchitecture_id).ok_or_else(|| {
            format!(
                "unknown MCT CPU microarchitecture '{}'",
                microarchitecture_id
            )
        })?;
    let fine_tuning_profile = mct_cpu_fine_tuning_profile_by_id(fine_tuning_profile_id)
        .ok_or_else(|| {
            format!(
                "unknown MCT fine tuning profile '{}'",
                fine_tuning_profile_id
            )
        })?;
    let spec_target = mct_backend_isa_label(&spec.isa);
    if microarchitecture.target != spec_target {
        return Err(format!(
            "MCT CPU microarchitecture '{}' targets '{}', but backend target is '{}'",
            microarchitecture.id, microarchitecture.target, spec_target
        ));
    }

    let target_cpu = microarchitecture.llvm_target_cpu.to_string();
    let tune_cpu = microarchitecture.llvm_tune_cpu.to_string();
    let target_features = microarchitecture
        .target_features
        .iter()
        .map(|feature| (*feature).to_string())
        .collect::<Vec<_>>();
    let mut function_attributes = vec![
        llvm_function_attr_flag("nounwind", "exception"),
        llvm_function_attr_kv("target-cpu", &target_cpu, "target"),
        llvm_function_attr_kv("tune-cpu", &tune_cpu, "target"),
        llvm_function_attr_kv("frame-pointer", "all", "debug"),
        llvm_function_attr_kv("min-legal-vector-width", "0", "vector"),
        llvm_function_attr_kv("stack-protector-buffer-size", "8", "stack"),
    ];
    if !target_features.is_empty() {
        function_attributes.push(llvm_function_attr_kv(
            "target-features",
            &target_features.join(","),
            "target",
        ));
    }
    if matches!(
        spec.object_format,
        BackendObjectFormatIR::Elf32
            | BackendObjectFormatIR::Elf64
            | BackendObjectFormatIR::Coff
            | BackendObjectFormatIR::MachO
    ) {
        function_attributes.push(llvm_function_attr_flag("uwtable", "unwind"));
    }
    if matches!(spec.runtime_model, BackendRuntimeModelIR::Freestanding) {
        function_attributes.push(llvm_function_attr_kv("no-builtins", "true", "freestanding"));
    }
    if let Ok(stack) = ncc_machine::machine_stack_plan(&spec.target_triple) {
        if let Some(probe) = stack.probe_symbol {
            function_attributes.push(llvm_function_attr_kv("probe-stack", probe, "stack"));
        } else if stack.probe_strategy == ncc_machine::StackProbeStrategy::InlinePageTouch {
            function_attributes.push(llvm_function_attr_kv("probe-stack", "inline-asm", "stack"));
        }
        if stack.probe_strategy != ncc_machine::StackProbeStrategy::None {
            function_attributes.push(llvm_function_attr_kv(
                "stack-probe-size",
                &stack.probe_threshold_bytes.to_string(),
                "stack",
            ));
        }
    }
    let attribute_group = "#0".to_string();
    let attribute_group_ir = format!(
        "attributes {} = {{ {} }}\n",
        attribute_group,
        function_attributes
            .iter()
            .map(|attribute| attribute.llvm_ir.as_str())
            .collect::<Vec<_>>()
            .join(" ")
    );
    Ok(MctLlvmTargetAttributesIR {
        schema: "nc.mct.llvm.target_attributes.v1",
        status: "mct_llvm_target_attributes_tuned",
        target_triple: spec.target_triple.clone(),
        object_format: llvm_backend_object_format_label(&spec.object_format).to_string(),
        abi: llvm_backend_abi_label(&spec.abi).to_string(),
        debug_model: llvm_backend_debug_model_label(&spec.debug_info_model).to_string(),
        attribute_group,
        target_cpu,
        tune_cpu: Some(tune_cpu),
        target_features,
        microarchitecture: Some(microarchitecture.id),
        fine_tuning_profile: Some(fine_tuning_profile.id),
        function_attributes,
        attribute_group_ir,
        applies_to_emitted_functions: true,
        full_target_attribute_parity: false,
        diagnostics: vec![MctDiagnosticIR::new("I_MCT_LLVM_CPU_TUNING_001", MctDiagnosticSeverityIR::Info, format!(
                "LLVM target attributes are tuned for {} using microarchitecture '{}' and profile '{}'.",
                spec.target_triple, microarchitecture.id, fine_tuning_profile.id
            ))],
    })
}

