fn push_mct_llvm_statement_rows(
    rows: &mut Vec<MctLlvmConstructCoverageRowIR>,
    present: &HashSet<&'static str>,
) {
    for (construct, lowering, evidence) in [
        (
            "statement.scalar_return",
            "ret with scalar compiled expression",
            "ScalarReturn branch",
        ),
        (
            "statement.scalar_projection",
            "alloca/store projection with scalar, array or dynamic-view handling",
            "ScalarProjection branch",
        ),
        (
            "statement.scalar_expr",
            "compile expression for side effects",
            "ScalarExpr branch",
        ),
        (
            "statement.print",
            "host write/format lowering for print family",
            "emit_print",
        ),
        (
            "statement.dev",
            "metadata/no-code statement; DevTrap expression lowers to llvm.trap",
            "Dev statement branch",
        ),
        (
            "statement.if",
            "conditional branch with then/else/end labels",
            "emit_if",
        ),
        (
            "statement.while",
            "condition/body/end loop blocks",
            "emit_while",
        ),
        (
            "statement.do_while",
            "body-first loop blocks",
            "emit_do_while",
        ),
        (
            "statement.for_classic",
            "init/condition/body/step loop blocks",
            "emit_for_classic",
        ),
        (
            "statement.for_range",
            "counter loop with inclusive/step policy",
            "emit_for_range",
        ),
        (
            "statement.loop",
            "infinite loop with break/continue targets",
            "emit_loop",
        ),
        (
            "statement.repeat_until",
            "repeat loop with trailing condition",
            "emit_repeat_until",
        ),
        (
            "statement.repeat_count",
            "counted loop lowered to i64 counter",
            "emit_repeat_count",
        ),
        (
            "statement.break",
            "branch to active loop break target",
            "Break branch",
        ),
        (
            "statement.continue",
            "branch to active loop continue target",
            "Continue branch",
        ),
        (
            "statement.labeled",
            "label-aware nested statement lowering",
            "Labeled branch",
        ),
        (
            "statement.main_ref",
            "metadata consumed by main wrapper discovery",
            "llvm_emit_main_wrapper",
        ),
        (
            "statement.fn_link",
            "metadata/no-code relation statement",
            "FnLink branch",
        ),
    ] {
        push_mct_llvm_construct_row(
            rows,
            present,
            mct_llvm_construct_row_spec(
                construct,
                "statement",
                MctLlvmConstructRepresentationIR::Represented,
                lowering,
                None,
                "the LLVM adapter has an explicit lowering or metadata path for this StatementIR variant",
                evidence,
            ),
        );
    }
    push_mct_llvm_construct_row(
        rows,
        present,
        mct_llvm_construct_row_spec(
            "statement.expr_raw",
            "statement",
            MctLlvmConstructRepresentationIR::Represented,
            "raw expression statement lowers through scalar parse or llvm.trap boundary",
            None,
            "untyped/raw expression strings keep a real LLVM boundary instead of being silently dropped",
            "emit_raw_statement",
        ),
    );
    push_mct_llvm_construct_row(
        rows,
        present,
        mct_llvm_construct_row_spec(
            "statement.return_raw",
            "statement",
            MctLlvmConstructRepresentationIR::Represented,
            "raw return lowers through scalar parse or typed llvm.trap fallback",
            None,
            "raw returns preserve a concrete return ABI instead of rejecting the function at emission time",
            "emit_raw_return",
        ),
    );
}

