#[derive(Clone, Copy)]
struct MctLlvmConstructRowSpec {
    construct: &'static str,
    family: &'static str,
    status: MctLlvmConstructRepresentationIR,
    lowering: &'static str,
    diagnostic: Option<&'static str>,
    reason: &'static str,
    evidence: &'static str,
}

fn mct_llvm_construct_row_spec(
    construct: &'static str,
    family: &'static str,
    status: MctLlvmConstructRepresentationIR,
    lowering: &'static str,
    diagnostic: Option<&'static str>,
    reason: &'static str,
    evidence: &'static str,
) -> MctLlvmConstructRowSpec {
    MctLlvmConstructRowSpec {
        construct,
        family,
        status,
        lowering,
        diagnostic,
        reason,
        evidence,
    }
}

fn push_mct_llvm_construct_row(
    rows: &mut Vec<MctLlvmConstructCoverageRowIR>,
    present: &HashSet<&'static str>,
    spec: MctLlvmConstructRowSpec,
) {
    rows.push(MctLlvmConstructCoverageRowIR {
        construct: spec.construct,
        family: spec.family,
        status: spec.status,
        present_in_module: present.contains(spec.construct),
        lowering: spec.lowering,
        diagnostic: spec.diagnostic,
        reason: spec.reason,
        evidence: spec.evidence,
    });
}

fn llvm_emit_main_wrapper(
    ir: &ProgramIR,
    signatures: &HashMap<String, LlvmFunctionSignature>,
    diagnostics: &mut Vec<MctDiagnosticIR>,
    init_symbols: &[String],
    attribute_group: Option<&str>,
    capture_process_environment: bool,
) -> Option<String> {
    let mut main_refs = Vec::new();
    for container in &ir.containers {
        match container {
            ContainerIR::Regular(regular) => {
                llvm_collect_main_refs(&regular.final_body, &mut main_refs)
            }
            ContainerIR::Root(root) => {
                llvm_collect_main_refs(&root.final_body, &mut main_refs);
                llvm_collect_root_main_entries(&root.main_entries, &mut main_refs);
            }
            ContainerIR::Security(security) => {
                llvm_collect_main_refs(&security.final_body, &mut main_refs)
            }
            ContainerIR::Primitive(_) | ContainerIR::Machine(_) => {}
        }
    }
    let target = main_refs.first()?;
    if main_refs.len() > 1 {
        diagnostics.push(MctDiagnosticIR::new(
            "W_MCT_LLVM_MAIN_001",
            MctDiagnosticSeverityIR::Warning,
            format!(
                "LLVM adapter found {} main refs; using '{}'",
                main_refs.len(),
                target
            ),
        ));
    }
    let Some(signature) = signatures.get(target) else {
        diagnostics.push(MctDiagnosticIR::new(
            "E_MCT_LLVM_MAIN_001",
            MctDiagnosticSeverityIR::Error,
            format!("LLVM adapter main target '{}' has no signature", target),
        ));
        return None;
    };
    if !signature.params.is_empty() {
        diagnostics.push(MctDiagnosticIR::new(
            "E_MCT_LLVM_MAIN_002",
            MctDiagnosticSeverityIR::Error,
            format!(
                "LLVM adapter main target '{}' must not require parameters",
                target
            ),
        ));
        return None;
    }

    let mut out = String::new();
    let attr_suffix = attribute_group
        .map(|group| format!(" {group}"))
        .unwrap_or_default();
    let target = ir.target_spec.target_triple.to_ascii_lowercase();
    let receives_process_environment =
        capture_process_environment && (target.contains("linux") || target.contains("android"));
    if receives_process_environment {
        writeln!(
            out,
            "define i32 @main(i32 %ncc.argc, ptr %ncc.argv, ptr %ncc.envp){attr_suffix} {{"
        )
        .expect("write to string");
    } else {
        writeln!(out, "define i32 @main(){attr_suffix} {{").expect("write to string");
    }
    writeln!(out, "entry:").expect("write to string");
    if receives_process_environment {
        writeln!(
            out,
            "  store ptr %ncc.envp, ptr @__ncc_process_environ, align 1"
        )
        .expect("write to string");
    }
    for init_symbol in init_symbols {
        writeln!(out, "  call void @{}()", init_symbol).expect("write to string");
    }
    match signature.return_type.as_str() {
        "void" => {
            writeln!(out, "  call void @{}()", signature.symbol_name).expect("write to string");
            writeln!(out, "  ret i32 0").expect("write to string");
        }
        "i1" => {
            writeln!(out, "  %main.ret = call i1 @{}()", signature.symbol_name)
                .expect("write to string");
            writeln!(out, "  %main.ok = zext i1 %main.ret to i32").expect("write to string");
            writeln!(out, "  %main.exit = sub i32 1, %main.ok").expect("write to string");
            writeln!(out, "  ret i32 %main.exit").expect("write to string");
        }
        "i8" | "i16" => {
            writeln!(
                out,
                "  %main.ret = call {} @{}()",
                signature.return_type, signature.symbol_name
            )
            .expect("write to string");
            writeln!(
                out,
                "  %main.exit = sext {} %main.ret to i32",
                signature.return_type
            )
            .expect("write to string");
            writeln!(out, "  ret i32 %main.exit").expect("write to string");
        }
        "i32" => {
            writeln!(out, "  %main.ret = call i32 @{}()", signature.symbol_name)
                .expect("write to string");
            writeln!(out, "  ret i32 %main.ret").expect("write to string");
        }
        "i64" => {
            writeln!(out, "  %main.ret = call i64 @{}()", signature.symbol_name)
                .expect("write to string");
            writeln!(out, "  %main.exit = trunc i64 %main.ret to i32").expect("write to string");
            writeln!(out, "  ret i32 %main.exit").expect("write to string");
        }
        other => {
            diagnostics.push(MctDiagnosticIR::new(
                "E_MCT_LLVM_MAIN_003",
                MctDiagnosticSeverityIR::Error,
                format!(
                    "LLVM main return type '{}' is not executable-smoke compatible",
                    other
                ),
            ));
            return None;
        }
    }
    writeln!(out, "}}").expect("write to string");
    Some(out)
}

#[allow(clippy::too_many_arguments)]
fn llvm_emit_to_main_entry(
    ir: &ProgramIR,
    signatures: &HashMap<String, LlvmFunctionSignature>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
    global_slots: &HashMap<String, HashMap<String, LlvmLocalSlot>>,
    source_map: &ProgramSourceMapIR,
    target_attributes: &MctLlvmTargetAttributesIR,
    target_triple: &str,
    debug_builder: &mut Option<LlvmDebugBuilder>,
    diagnostics: &mut Vec<MctDiagnosticIR>,
    init_symbols: &[String],
) -> Option<(MctLlvmFunctionIR, Option<String>)> {
    let mut entries = Vec::new();
    for container in &ir.containers {
        let ContainerIR::Root(root) = container else {
            continue;
        };
        for (index, entry) in root.main_entries.iter().enumerate() {
            if matches!(
                entry.kind,
                RootMainEntryKindIR::ToMain | RootMainEntryKindIR::ToMainProfile(_)
            ) {
                entries.push((root, index, entry));
            }
        }
    }
    let (root, entry_index, entry) = entries.first().copied()?;
    if entries.len() > 1 {
        diagnostics.push(MctDiagnosticIR::new(
            "W_MCT_LLVM_MAIN_002",
            MctDiagnosticSeverityIR::Warning,
            format!(
                "LLVM adapter found {} direct to-main entries; using '{}.main.{}'.",
                entries.len(),
                root.name,
                entry_index
            ),
        ));
    }

    let signature = LlvmFunctionSignature {
        source_name: format!("{}.main", root.name),
        symbol_name: "main".to_string(),
        nc_return_type: "int".to_string(),
        return_type: "i32".to_string(),
        params: Vec::new(),
        caller_owned_coroutine_storage: None,
        closure_storage_layout: None,
        caller_owned_closure_return_storage: None,
    };
    let source_spans = source_spans_for_main_entry(source_map, &root.name, entry_index);
    let container_globals = global_slots.get(&root.name).cloned().unwrap_or_default();
    let mut emitter = LlvmFunctionEmitter::new(
        None,
        &ir.source_contract,
        &signature,
        signatures,
        struct_layouts,
        target_triple,
        container_globals,
        debug_builder.as_mut(),
        source_spans,
        Some(&target_attributes.attribute_group),
    );
    emitter.emit_entry_with_symbol_types(&entry.symbol_types);
    for init_symbol in init_symbols {
        emitter.emit(format!("call void @{}()", init_symbol));
    }
    emitter.emit_statements(&entry.body, None);
    if !emitter.terminated {
        emitter.emit_default_return();
    }
    let has_error = emitter.diagnostics.iter().any(MctDiagnosticIR::is_error);
    let status = if has_error {
        MctLlvmFunctionStatusIR::Rejected
    } else {
        MctLlvmFunctionStatusIR::Emitted
    };
    let function_ir = MctLlvmFunctionIR {
        source_name: signature.source_name.clone(),
        symbol_name: signature.symbol_name.clone(),
        visibility: FunctionVisibilityIR::Default,
        return_type: signature.return_type.clone(),
        param_types: Vec::new(),
        status,
        diagnostics: emitter.diagnostics.clone(),
    };
    let rendered = (!has_error).then(|| emitter.finish());
    Some((function_ir, rendered))
}

fn llvm_collect_root_main_entries(entries: &[RootMainEntryIR], out: &mut Vec<String>) {
    for entry in entries {
        match &entry.kind {
            RootMainEntryKindIR::RefFn(path) | RootMainEntryKindIR::SkkFn(path) => {
                if !path.is_empty() {
                    out.push(path.join("."));
                }
            }
            RootMainEntryKindIR::ToMain | RootMainEntryKindIR::ToMainProfile(_) => {}
        }
    }
}

fn llvm_emit_stc_init_functions(
    ir: &ProgramIR,
    signatures: &HashMap<String, LlvmFunctionSignature>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
    global_slots: &HashMap<String, HashMap<String, LlvmLocalSlot>>,
    static_string_inits: &HashMap<String, Vec<String>>,
    static_constant_inits: &HashMap<String, String>,
    target_triple: &str,
    attribute_group: Option<&str>,
) -> (String, Vec<String>) {
    let mut body = String::new();
    let mut init_symbols = Vec::new();
    for container in &ir.containers {
        let (container_name, init_body) = match container {
            ContainerIR::Regular(regular) => {
                (regular.name.as_str(), regular.stc_init_body.as_slice())
            }
            ContainerIR::Root(root) => (root.name.as_str(), root.stc_init_body.as_slice()),
            ContainerIR::Security(security) => {
                (security.name.as_str(), security.stc_init_body.as_slice())
            }
            ContainerIR::Primitive(_) | ContainerIR::Machine(_) => continue,
        };
        if init_body.is_empty() {
            continue;
        }
        let retained_init_body = init_body
            .iter()
            .filter(|stmt| {
                !matches!(
                    stmt,
                    StatementIR::ScalarProjection { target, .. }
                        if global_slots
                            .get(container_name)
                            .and_then(|slots| slots.get(target))
                            .is_some_and(|slot| {
                                static_string_inits.contains_key(&slot.slot)
                                    || static_constant_inits.contains_key(&slot.slot)
                            })
                )
            })
            .cloned()
            .collect::<Vec<_>>();
        if retained_init_body.is_empty() {
            continue;
        }
        let symbol_name = llvm_sanitize_symbol(&format!("__ncc_mct_init_{container_name}"));
        let signature = LlvmFunctionSignature {
            source_name: format!("{container_name}.__ncc_mct_init"),
            symbol_name: symbol_name.clone(),
            nc_return_type: "void".into(),
            return_type: "void".into(),
            params: Vec::new(),
            caller_owned_coroutine_storage: None,
            closure_storage_layout: None,
            caller_owned_closure_return_storage: None,
        };
        let mut emitter = LlvmFunctionEmitter::new(
            None,
            &ir.source_contract,
            &signature,
            signatures,
            struct_layouts,
            target_triple,
            global_slots
                .get(container_name)
                .cloned()
                .unwrap_or_default(),
            None,
            Vec::new(),
            attribute_group,
        );
        emitter.emit_entry_with_symbol_types(&HashMap::new());
        emitter.emit_statements(&retained_init_body, None);
        if !emitter.terminated {
            emitter.emit("ret void");
            emitter.terminated = true;
        }
        body.push_str(&emitter.finish());
        body.push('\n');
        init_symbols.push(symbol_name);
    }
    (body, init_symbols)
}

fn llvm_collect_main_refs(statements: &[StatementIR], out: &mut Vec<String>) {
    for stmt in statements {
        llvm_collect_main_ref_stmt(stmt, out);
    }
}

fn llvm_collect_main_ref_stmt(stmt: &StatementIR, out: &mut Vec<String>) {
    match stmt {
        StatementIR::MainRef { target, .. } => out.push(target.clone()),
        StatementIR::Labeled { stmt, .. } => llvm_collect_main_ref_stmt(stmt, out),
        _ => {}
    }
}

