    fn compile_c_string_compare(&mut self, left: &ScalarExprIR, right: &ScalarExprIR) -> LlvmValue {
        let left_ptr = self.compile_expr(left, Some("ptr"));
        let left_ptr = self.coerce_value(left_ptr, "ptr");
        let right_ptr = self.compile_expr(right, Some("ptr"));
        let right_ptr = self.coerce_value(right_ptr, "ptr");
        let cursor_slot = self.new_temp();
        let result_slot = self.new_temp();
        self.emit(format!("{cursor_slot} = alloca i64, align 8"));
        self.emit(format!("{result_slot} = alloca i64, align 8"));
        self.emit(format!("store i64 0, ptr {cursor_slot}, align 8"));

        let loop_label = self.new_label("str.compare.loop");
        let same_label = self.new_label("str.compare.same");
        let diff_label = self.new_label("str.compare.diff");
        let equal_label = self.new_label("str.compare.equal");
        let end_label = self.new_label("str.compare.end");
        self.emit(format!("br label %{loop_label}"));
        self.terminated = true;

        self.start_label(&loop_label);
        let cursor = self.new_temp();
        let left_cell = self.new_temp();
        let right_cell = self.new_temp();
        let left_byte = self.new_temp();
        let right_byte = self.new_temp();
        let same = self.new_temp();
        self.emit(format!("{cursor} = load i64, ptr {cursor_slot}, align 8"));
        self.emit(format!(
            "{left_cell} = getelementptr i8, ptr {}, i64 {cursor}",
            left_ptr.repr
        ));
        self.emit(format!(
            "{right_cell} = getelementptr i8, ptr {}, i64 {cursor}",
            right_ptr.repr
        ));
        self.emit(format!("{left_byte} = load i8, ptr {left_cell}, align 1"));
        self.emit(format!("{right_byte} = load i8, ptr {right_cell}, align 1"));
        self.emit(format!("{same} = icmp eq i8 {left_byte}, {right_byte}"));
        self.emit(format!(
            "br i1 {same}, label %{same_label}, label %{diff_label}"
        ));
        self.terminated = true;

        self.start_label(&same_label);
        let at_end = self.new_temp();
        self.emit(format!("{at_end} = icmp eq i8 {left_byte}, 0"));
        let next_label = self.new_label("str.compare.next");
        self.emit(format!(
            "br i1 {at_end}, label %{equal_label}, label %{next_label}"
        ));
        self.terminated = true;

        self.start_label(&next_label);
        let next = self.new_temp();
        self.emit(format!("{next} = add i64 {cursor}, 1"));
        self.emit(format!("store i64 {next}, ptr {cursor_slot}, align 8"));
        self.emit(format!("br label %{loop_label}"));
        self.terminated = true;

        self.start_label(&diff_label);
        let left_before = self.new_temp();
        let difference = self.new_temp();
        self.emit(format!(
            "{left_before} = icmp ult i8 {left_byte}, {right_byte}"
        ));
        self.emit(format!(
            "{difference} = select i1 {left_before}, i64 -1, i64 1"
        ));
        self.emit(format!(
            "store i64 {difference}, ptr {result_slot}, align 8"
        ));
        self.emit(format!("br label %{end_label}"));
        self.terminated = true;

        self.start_label(&equal_label);
        self.emit(format!("store i64 0, ptr {result_slot}, align 8"));
        self.emit(format!("br label %{end_label}"));
        self.terminated = true;

        self.start_label(&end_label);
        let out = self.new_temp();
        self.emit(format!("{out} = load i64, ptr {result_slot}, align 8"));
        LlvmValue {
            llvm_ty: "i64".into(),
            repr: out,
        }
    }

