fn scalar_runtime_string_returns_text_call(name: &str) -> bool {
    matches!(
        name,
        "strEmpty"
            | "strConcat"
            | "strSlice"
            | "strSubstring"
            | "strToUpper"
            | "strToLower"
            | "strFromInt"
            | "strFromBool"
            | "strFromFt64"
            | "strFromFloat"
            | "escapeAnsi"
            | "escapeJson"
            | "escapeControl"
            | "sanitizeTerminal"
            | "sanitizeLog"
            | "format"
            | "formatNamed"
            | "formatInt"
            | "formatFloat"
            | "normalizeUnicode"
            | "normalizeNfc"
            | "normalizeNfd"
            | "normalizeNfkc"
            | "normalizeNfkd"
            | "stripInvalidUnicode"
            | "unicodeMode"
            | "graphemeSlice"
            | "httpBody"
    ) || runtime_json_llvm::signature(name).is_some_and(|(_, return_ty)| return_ty == "ptr")
}

fn llvm_comment_escape(value: &str) -> String {
    value
        .chars()
        .map(|ch| match ch {
            '\n' | '\r' => ' ',
            _ => ch,
        })
        .collect()
}

fn llvm_sanitize_symbol(name: &str) -> String {
    let mut out = String::new();
    for ch in name.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() || out.as_bytes()[0].is_ascii_digit() {
        out.insert(0, '_');
    }
    out
}

fn llvm_sanitize_local(name: &str) -> String {
    llvm_sanitize_symbol(name)
}

fn llvm_parameter_local(name: &str) -> String {
    let local = llvm_sanitize_local(name);
    if local.starts_with("__ncc_") || local == "__closure_env" {
        local
    } else {
        format!("arg.{local}")
    }
}

