fn mct_modal_unit_for_container(container: &ContainerIR) -> MctModalUnitIR {
    match container {
        ContainerIR::Regular(regular) => MctModalUnitIR {
            name: regular.name.clone(),
            mode: "regular",
            function_count: regular.functions.len(),
            type_contract_count: regular.type_contracts.len(),
            primary_provider: MctBackendProviderIR::NccNative,
            eligible_providers: vec![
                MctBackendProviderIR::NccNative,
                MctBackendProviderIR::Llvm,
                MctBackendProviderIR::Gcc,
                MctBackendProviderIR::Rustc,
            ],
            diagnostics: Vec::new(),
        },
        ContainerIR::Root(root) => MctModalUnitIR {
            name: root.name.clone(),
            mode: "root",
            function_count: root.functions.len(),
            type_contract_count: 0,
            primary_provider: MctBackendProviderIR::NccNative,
            eligible_providers: vec![
                MctBackendProviderIR::NccNative,
                MctBackendProviderIR::Llvm,
                MctBackendProviderIR::Gcc,
            ],
            diagnostics: vec![MctDiagnosticIR::new(ncc_diagnostics::codes::I_MCT_ROOT_NATIVE_PRIMARY_001, MctDiagnosticSeverityIR::Info, "root containers keep ncc-native as primary provider; external backends must preserve root authority records."
                    .into())],
        },
        ContainerIR::Security(security) => MctModalUnitIR {
            name: security.name.clone(),
            mode: "security",
            function_count: security.functions.len(),
            type_contract_count: 0,
            primary_provider: MctBackendProviderIR::NccNative,
            eligible_providers: vec![
                MctBackendProviderIR::NccNative,
                MctBackendProviderIR::Llvm,
                MctBackendProviderIR::Gcc,
            ],
            diagnostics: vec![MctDiagnosticIR::new(ncc_diagnostics::codes::W_MCT_SECURITY_POLICY_BOUNDARY_001, MctDiagnosticSeverityIR::Warning, "security containers require policy/evidence preservation before external backend emission."
                    .into())],
        },
        ContainerIR::Primitive(primitive) => MctModalUnitIR {
            name: primitive.name.clone(),
            mode: "primitive",
            function_count: primitive.operations.len(),
            type_contract_count: primitive.type_aliases.len(),
            primary_provider: MctBackendProviderIR::NccNative,
            eligible_providers: vec![MctBackendProviderIR::NccNative],
            diagnostics: vec![MctDiagnosticIR::new(ncc_diagnostics::codes::E_MCT_EXTERNAL_BACKEND_FORBIDDEN_001, MctDiagnosticSeverityIR::Error, "primitive containers are native/material authority surfaces and cannot silently route through LLVM/GCC/rustc."
                    .into())],
        },
        ContainerIR::Machine(machine) => MctModalUnitIR {
            name: machine.name.clone(),
            mode: "machine",
            function_count: machine.final_ops.len(),
            type_contract_count: 0,
            primary_provider: MctBackendProviderIR::NccNative,
            eligible_providers: vec![MctBackendProviderIR::NccNative],
            diagnostics: vec![MctDiagnosticIR::new(ncc_diagnostics::codes::E_MCT_MACHINE_NATIVE_ONLY_001, MctDiagnosticSeverityIR::Error, "[@machine] remains byte/ASM authoritative and is not translated through LLVM/GCC/rustc."
                    .into())],
        },
    }
}

