fn collect_backend_auto_vectorization(
    function: &FunctionIR,
    statements: &[StatementIR],
    loop_depth: usize,
    report: &mut BackendAutoVectorizerReportIR,
) {
    for stmt in statements {
        match stmt {
            StatementIR::If {
                then_body,
                else_body,
                ..
            } => {
                collect_backend_auto_vectorization(function, then_body, loop_depth, report);
                collect_backend_auto_vectorization(function, else_body, loop_depth, report);
            }
            StatementIR::While { body, .. } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "while",
                    None,
                    None,
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::DoWhile { body, .. } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "do_while",
                    None,
                    None,
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::ForRange {
                item, end, body, ..
            } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "for_range",
                    Some(item),
                    end.as_ref()
                        .and_then(scalar_symbol_name)
                        .map(str::to_string),
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::ForClassic {
                init, step, body, ..
            } => {
                let induction = step
                    .as_deref()
                    .and_then(infer_backend_loop_induction_from_statement)
                    .or_else(|| {
                        init.as_deref()
                            .and_then(infer_backend_loop_induction_from_statement)
                    });
                analyze_backend_auto_vector_loop(
                    function,
                    "for_classic",
                    induction.as_deref(),
                    None,
                    body,
                    loop_depth + 1,
                    report,
                );
                if let Some(init) = init.as_deref() {
                    collect_backend_auto_vectorization(
                        function,
                        std::slice::from_ref(init),
                        loop_depth,
                        report,
                    );
                }
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
                if let Some(step) = step.as_deref() {
                    collect_backend_auto_vectorization(
                        function,
                        std::slice::from_ref(step),
                        loop_depth,
                        report,
                    );
                }
            }
            StatementIR::Loop { body } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "loop",
                    None,
                    None,
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::RepeatUntil { body, .. } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "repeat_until",
                    None,
                    None,
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::RepeatCount { count, body, .. } => {
                analyze_backend_auto_vector_loop(
                    function,
                    "repeat_count",
                    None,
                    count
                        .as_ref()
                        .and_then(scalar_symbol_name)
                        .map(str::to_string),
                    body,
                    loop_depth + 1,
                    report,
                );
                collect_backend_auto_vectorization(function, body, loop_depth + 1, report);
            }
            StatementIR::Labeled { stmt, .. } => collect_backend_auto_vectorization(
                function,
                std::slice::from_ref(stmt.as_ref()),
                loop_depth,
                report,
            ),
            _ => {}
        }
    }
}

fn analyze_backend_auto_vector_loop(
    function: &FunctionIR,
    loop_kind: &'static str,
    induction_symbol: Option<&str>,
    trip_count_symbol: Option<String>,
    body: &[StatementIR],
    loop_depth: usize,
    report: &mut BackendAutoVectorizerReportIR,
) {
    report.loops_seen += 1;
    let before = report.vectorized_loops.len();
    for stmt in body {
        collect_backend_auto_vector_loop_stmt(
            function,
            loop_kind,
            induction_symbol,
            trip_count_symbol.as_deref(),
            stmt,
            loop_depth,
            &mut report.vectorized_loops,
        );
    }

    if report.vectorized_loops.len() == before {
        report
            .rejected_loops
            .push(BackendAutoVectorizationRejectionIR {
                function: function.name.clone(),
                loop_kind,
                status: BackendAutoVectorizationStatusIR::Rejected,
                reason: "loop body does not match a closed auto-vectorizer pattern".into(),
                diagnostics: vec![BackendAutoVectorizationDiagnosticIR {
                    code: "E_AUTO_VEC_PATTERN_001",
                    message: "No contiguous map/zip/reduction/gather/scatter pattern was proven."
                        .into(),
                }],
            });
    }
}

fn collect_backend_auto_vector_loop_stmt(
    function: &FunctionIR,
    loop_kind: &'static str,
    induction_symbol: Option<&str>,
    trip_count_symbol: Option<&str>,
    stmt: &StatementIR,
    loop_depth: usize,
    vectorized: &mut Vec<BackendAutoVectorizedLoopIR>,
) {
    match stmt {
        StatementIR::ScalarProjection {
            target,
            ty,
            raw,
            value,
            ..
        } => {
            if let Some(lowering) =
                lower_backend_vector_projection(function, target, ty, raw, value)
            {
                vectorized.push(backend_auto_vector_loop_from_selected(
                    BackendAutoVectorLoopBuildIR {
                        function,
                        loop_kind,
                        pattern: BackendAutoVectorPatternIR::VectorExpression,
                        induction_symbol,
                        trip_count_symbol,
                        target_symbol: Some(target),
                        vector_type: ty,
                        source_symbols: backend_vector_expr_source_symbols(value),
                        simd_op: lowering.op,
                        feature: lowering.feature,
                        lane: lowering.lane,
                        selected_mnemonic: lowering.selected_mnemonic,
                        selected_asm: lowering.selected_asm,
                        selected_bytes: lowering.selected_bytes,
                        schedule: lowering.schedule,
                        loop_depth,
                        scalar_ops_per_iteration: 1,
                        diagnostics: vec![BackendAutoVectorizationDiagnosticIR {
                            code: "I_AUTO_VEC_VECTOR_EXPRESSION_001",
                            message: "Vector expression inside loop selected a concrete SIMD row."
                                .into(),
                        }],
                    },
                ));
                return;
            }
            if let Some(reduction) = analyze_backend_auto_vector_reduction(
                function,
                loop_kind,
                induction_symbol,
                trip_count_symbol,
                target,
                value,
                loop_depth,
            ) {
                vectorized.push(reduction);
            }
        }
        StatementIR::ScalarExpr { value, .. } => {
            if let Some(write) = analyze_backend_auto_vector_array_write(
                function,
                loop_kind,
                induction_symbol,
                trip_count_symbol,
                value,
                loop_depth,
            ) {
                vectorized.push(write);
            }
        }
        StatementIR::If {
            then_body,
            else_body,
            ..
        } => {
            for nested in then_body.iter().chain(else_body) {
                collect_backend_auto_vector_loop_stmt(
                    function,
                    loop_kind,
                    induction_symbol,
                    trip_count_symbol,
                    nested,
                    loop_depth,
                    vectorized,
                );
            }
        }
        StatementIR::Labeled { stmt, .. } => collect_backend_auto_vector_loop_stmt(
            function,
            loop_kind,
            induction_symbol,
            trip_count_symbol,
            stmt,
            loop_depth,
            vectorized,
        ),
        _ => {}
    }
}

fn analyze_backend_auto_vector_array_write(
    function: &FunctionIR,
    loop_kind: &'static str,
    induction_symbol: Option<&str>,
    trip_count_symbol: Option<&str>,
    expr: &ScalarExprIR,
    loop_depth: usize,
) -> Option<BackendAutoVectorizedLoopIR> {
    let ScalarExprIR::ArrayWrite {
        target,
        index,
        value,
        mem_type,
    } = expr
    else {
        return None;
    };
    let induction = induction_symbol?;
    let index_is_induction = scalar_expr_is_symbol(index, induction);
    let vector_type = backend_auto_vector_type_for_mem(*mem_type);

    let (pattern, op, scalar_ops) = if !index_is_induction {
        (
            BackendAutoVectorPatternIR::Scatter,
            BackendSimdOpIR::Scatter,
            2,
        )
    } else if backend_auto_expr_contains_indirect_read(value, induction) {
        (
            BackendAutoVectorPatternIR::Gather,
            BackendSimdOpIR::Gather,
            2,
        )
    } else if let Some(binary_op) = backend_auto_binary_zip_op(value, induction) {
        (
            BackendAutoVectorPatternIR::ContiguousZip,
            backend_auto_simd_op_from_binary(binary_op)?,
            1,
        )
    } else if backend_auto_expr_is_contiguous_read(value, induction) {
        (
            BackendAutoVectorPatternIR::ContiguousMap,
            BackendSimdOpIR::StoreAligned,
            1,
        )
    } else {
        return None;
    };

    let (selected, schedule) = backend_auto_select_simd(function, &vector_type, op)?;
    let mut source_symbols = vec![target.clone()];
    source_symbols.extend(backend_vector_expr_source_symbols(value));
    source_symbols.extend(backend_vector_expr_source_symbols(index));
    source_symbols.sort();
    source_symbols.dedup();

    Some(backend_auto_vector_loop_from_selected(
        BackendAutoVectorLoopBuildIR {
            function,
            loop_kind,
            pattern,
            induction_symbol: Some(induction),
            trip_count_symbol,
            target_symbol: Some(target),
            vector_type: &vector_type,
            source_symbols,
            simd_op: op,
            feature: selected.feature,
            lane: selected.lane,
            selected_mnemonic: selected.mnemonic,
            selected_asm: selected.asm,
            selected_bytes: selected.bytes,
            schedule,
            loop_depth,
            scalar_ops_per_iteration: scalar_ops,
            diagnostics: vec![BackendAutoVectorizationDiagnosticIR {
                code: "I_AUTO_VEC_ARRAY_PATTERN_001",
                message: "Loop array access pattern selected a concrete SIMD lowering row.".into(),
            }],
        },
    ))
}

fn analyze_backend_auto_vector_reduction(
    function: &FunctionIR,
    loop_kind: &'static str,
    induction_symbol: Option<&str>,
    trip_count_symbol: Option<&str>,
    target: &str,
    value: &ScalarExprIR,
    loop_depth: usize,
) -> Option<BackendAutoVectorizedLoopIR> {
    let induction = induction_symbol?;
    let ScalarExprIR::Binary { left, op, right } = value else {
        return None;
    };
    let (array_expr, binary_op) = if scalar_expr_is_symbol(left, target)
        && backend_auto_expr_is_contiguous_read(right, induction)
    {
        (right.as_ref(), *op)
    } else if scalar_expr_is_symbol(right, target)
        && backend_auto_expr_is_contiguous_read(left, induction)
    {
        (left.as_ref(), *op)
    } else {
        return None;
    };
    let (pattern, simd_op) = match binary_op {
        ScalarBinaryOpIR::Plus => (
            BackendAutoVectorPatternIR::ReductionSum,
            BackendSimdOpIR::Add,
        ),
        ScalarBinaryOpIR::Star => (
            BackendAutoVectorPatternIR::ReductionProduct,
            BackendSimdOpIR::Mul,
        ),
        _ => return None,
    };
    let vector_type = "vector<dword>";
    let (selected, schedule) = backend_auto_select_simd(function, vector_type, simd_op)?;
    let mut source_symbols = vec![target.to_string()];
    source_symbols.extend(backend_vector_expr_source_symbols(array_expr));
    source_symbols.sort();
    source_symbols.dedup();

    Some(backend_auto_vector_loop_from_selected(
        BackendAutoVectorLoopBuildIR {
            function,
            loop_kind,
            pattern,
            induction_symbol: Some(induction),
            trip_count_symbol,
            target_symbol: Some(target),
            vector_type,
            source_symbols,
            simd_op,
            feature: selected.feature,
            lane: selected.lane,
            selected_mnemonic: selected.mnemonic,
            selected_asm: selected.asm,
            selected_bytes: selected.bytes,
            schedule,
            loop_depth,
            scalar_ops_per_iteration: 1,
            diagnostics: vec![BackendAutoVectorizationDiagnosticIR {
                code: "I_AUTO_VEC_REDUCTION_001",
                message: "Loop-carried reduction matched a vectorizable associative pattern."
                    .into(),
            }],
        },
    ))
}

struct BackendAutoVectorLoopBuildIR<'a> {
    function: &'a FunctionIR,
    loop_kind: &'static str,
    pattern: BackendAutoVectorPatternIR,
    induction_symbol: Option<&'a str>,
    trip_count_symbol: Option<&'a str>,
    target_symbol: Option<&'a str>,
    vector_type: &'a str,
    source_symbols: Vec<String>,
    simd_op: BackendSimdOpIR,
    feature: BackendSimdFeatureIR,
    lane: BackendSimdLaneIR,
    selected_mnemonic: &'static str,
    selected_asm: &'static str,
    selected_bytes: Vec<u8>,
    schedule: BackendSimdScheduleIR,
    loop_depth: usize,
    scalar_ops_per_iteration: usize,
    diagnostics: Vec<BackendAutoVectorizationDiagnosticIR>,
}

fn backend_auto_vector_loop_from_selected(
    input: BackendAutoVectorLoopBuildIR<'_>,
) -> BackendAutoVectorizedLoopIR {
    let lanes_per_chunk = backend_simd_lane_count(input.lane);
    BackendAutoVectorizedLoopIR {
        function: input.function.name.clone(),
        loop_kind: input.loop_kind,
        pattern: input.pattern,
        status: BackendAutoVectorizationStatusIR::Vectorized,
        induction_symbol: input.induction_symbol.map(str::to_string),
        trip_count_symbol: input.trip_count_symbol.map(str::to_string),
        target_symbol: input.target_symbol.map(str::to_string),
        source_symbols: input.source_symbols,
        vector_type: input.vector_type.to_string(),
        simd_op: input.simd_op,
        target: backend_simd_target_label(&input.function.backend_plan.target)
            .unwrap_or("unsupported"),
        feature: input.feature,
        lane: input.lane,
        selected_mnemonic: input.selected_mnemonic,
        selected_asm: input.selected_asm,
        selected_bytes: input.selected_bytes,
        schedule: input.schedule,
        cost: BackendAutoVectorizationCostIR {
            scalar_ops_per_iteration: input.scalar_ops_per_iteration,
            vector_ops_per_chunk: 1,
            lanes_per_chunk,
            loop_depth_weight: input.loop_depth.max(1),
            estimated_speedup_numerator: input.scalar_ops_per_iteration * lanes_per_chunk,
            estimated_speedup_denominator: 1,
        },
        diagnostics: input.diagnostics,
    }
}

fn backend_auto_select_simd(
    function: &FunctionIR,
    vector_type: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdInstructionEncodingIR, BackendSimdScheduleIR)> {
    let target = backend_simd_target_label(&function.backend_plan.target)?;
    let (feature, lane) =
        backend_cpu_tuned_feature_lane(&function.backend_plan.cpu_tuning, vector_type, op)
            .or_else(|| backend_vector_select_feature_lane(target, vector_type, op))?;
    let selected =
        select_backend_simd_instruction_encoding(target, feature, lane, op).or_else(|| {
            backend_vector_fallback_feature_lane(target, op).and_then(
                |(fallback_feature, fallback_lane)| {
                    select_backend_simd_instruction_encoding(
                        target,
                        fallback_feature,
                        fallback_lane,
                        op,
                    )
                },
            )
        })?;
    if !backend_cpu_tuning_allows_simd_row(&function.backend_plan.cpu_tuning, &selected) {
        return None;
    }
    let microarchitecture =
        backend_cpu_tuned_schedule_microarchitecture(&function.backend_plan.cpu_tuning, target)?;
    let schedule = backend_simd_schedule_for(&selected, microarchitecture);
    Some((selected, schedule))
}

fn backend_auto_vector_type_for_mem(mem_type: ScalarMemTypeIR) -> String {
    match mem_type.width {
        ScalarMemWidthIR::Byte => "vector<byte>",
        ScalarMemWidthIR::Word => "vector<word>",
        ScalarMemWidthIR::Dword => "vector<dword>",
        ScalarMemWidthIR::Qword => "vector<qword>",
    }
    .into()
}

fn backend_simd_lane_count(lane: BackendSimdLaneIR) -> usize {
    match lane {
        BackendSimdLaneIR::F32x4 | BackendSimdLaneIR::I32x4 => 4,
        BackendSimdLaneIR::F32x8 | BackendSimdLaneIR::I32x8 => 8,
        BackendSimdLaneIR::F32x16 => 16,
        BackendSimdLaneIR::B128 => 16,
    }
}

fn backend_auto_binary_zip_op(
    expr: &ScalarExprIR,
    induction_symbol: &str,
) -> Option<ScalarBinaryOpIR> {
    let ScalarExprIR::Binary { left, op, right } = expr else {
        return None;
    };
    if backend_auto_expr_is_contiguous_read(left, induction_symbol)
        && backend_auto_expr_is_contiguous_read(right, induction_symbol)
    {
        Some(*op)
    } else {
        None
    }
}

fn backend_auto_simd_op_from_binary(op: ScalarBinaryOpIR) -> Option<BackendSimdOpIR> {
    match op {
        ScalarBinaryOpIR::Plus => Some(BackendSimdOpIR::Add),
        ScalarBinaryOpIR::Star => Some(BackendSimdOpIR::Mul),
        ScalarBinaryOpIR::BitAnd => Some(BackendSimdOpIR::And),
        ScalarBinaryOpIR::BitOr => Some(BackendSimdOpIR::Or),
        ScalarBinaryOpIR::BitXor => Some(BackendSimdOpIR::Xor),
        _ => None,
    }
}

fn backend_auto_expr_is_contiguous_read(expr: &ScalarExprIR, induction_symbol: &str) -> bool {
    matches!(
        expr,
        ScalarExprIR::ArrayRead { index, .. } if scalar_expr_is_symbol(index, induction_symbol)
    )
}

fn backend_auto_expr_contains_indirect_read(expr: &ScalarExprIR, induction_symbol: &str) -> bool {
    match expr {
        ScalarExprIR::ArrayRead { index, .. } => !scalar_expr_is_symbol(index, induction_symbol),
        ScalarExprIR::ArrayFieldRead { .. } => true,
        ScalarExprIR::Unary { expr, .. } => {
            backend_auto_expr_contains_indirect_read(expr, induction_symbol)
        }
        ScalarExprIR::Binary { left, right, .. } => {
            backend_auto_expr_contains_indirect_read(left, induction_symbol)
                || backend_auto_expr_contains_indirect_read(right, induction_symbol)
        }
        ScalarExprIR::Call { args, .. } => args
            .iter()
            .any(|arg| backend_auto_expr_contains_indirect_read(arg, induction_symbol)),
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            backend_auto_expr_contains_indirect_read(value, induction_symbol)
                || precision.as_ref().is_some_and(|precision| {
                    backend_auto_expr_contains_indirect_read(precision, induction_symbol)
                })
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            backend_auto_expr_contains_indirect_read(condition, induction_symbol)
                || backend_auto_expr_contains_indirect_read(then_expr, induction_symbol)
                || backend_auto_expr_contains_indirect_read(else_expr, induction_symbol)
        }
        _ => false,
    }
}

fn scalar_symbol_name(expr: &ScalarExprIR) -> Option<&str> {
    match expr {
        ScalarExprIR::Symbol(symbol) => Some(symbol),
        _ => None,
    }
}

fn scalar_expr_is_symbol(expr: &ScalarExprIR, symbol: &str) -> bool {
    matches!(expr, ScalarExprIR::Symbol(candidate) if candidate == symbol)
}

fn infer_backend_loop_induction_from_statement(stmt: &StatementIR) -> Option<String> {
    let StatementIR::ScalarProjection { target, value, .. } = stmt else {
        return None;
    };
    match value {
        ScalarExprIR::Binary { left, op, right }
            if matches!(op, ScalarBinaryOpIR::Plus | ScalarBinaryOpIR::Minus)
                && scalar_expr_is_symbol(left, target)
                && matches!(right.as_ref(), ScalarExprIR::Number(_)) =>
        {
            Some(target.clone())
        }
        _ => None,
    }
}

fn collect_backend_vector_expr_lowering(
    function: &FunctionIR,
    stmt: &StatementIR,
    plan: &mut Vec<BackendVectorExpressionLoweringIR>,
) {
    match stmt {
        StatementIR::ScalarProjection {
            target,
            ty,
            raw,
            value,
            ..
        } => {
            if let Some(lowering) =
                lower_backend_vector_projection(function, target, ty, raw, value)
            {
                plan.push(lowering);
            }
        }
        StatementIR::If {
            then_body,
            else_body,
            ..
        } => {
            for nested in then_body.iter().chain(else_body) {
                collect_backend_vector_expr_lowering(function, nested, plan);
            }
        }
        StatementIR::While { body, .. }
        | StatementIR::DoWhile { body, .. }
        | StatementIR::RepeatUntil { body, .. }
        | StatementIR::Loop { body }
        | StatementIR::RepeatCount { body, .. }
        | StatementIR::ForRange { body, .. } => {
            for nested in body {
                collect_backend_vector_expr_lowering(function, nested, plan);
            }
        }
        StatementIR::ForClassic {
            init, step, body, ..
        } => {
            if let Some(init) = init.as_deref() {
                collect_backend_vector_expr_lowering(function, init, plan);
            }
            for nested in body {
                collect_backend_vector_expr_lowering(function, nested, plan);
            }
            if let Some(step) = step.as_deref() {
                collect_backend_vector_expr_lowering(function, step, plan);
            }
        }
        StatementIR::Labeled { stmt, .. } => {
            collect_backend_vector_expr_lowering(function, stmt, plan);
        }
        _ => {}
    }
}

fn lower_backend_vector_projection(
    function: &FunctionIR,
    target_symbol: &str,
    vector_type: &str,
    source_expression: &str,
    value: &ScalarExprIR,
) -> Option<BackendVectorExpressionLoweringIR> {
    if !vector_type_is_register_resident(vector_type) {
        return None;
    }
    let op = backend_vector_expr_simd_op(value)?;
    let target = backend_simd_target_label(&function.backend_plan.target)?;
    let (feature, lane) =
        backend_cpu_tuned_feature_lane(&function.backend_plan.cpu_tuning, vector_type, op)
            .or_else(|| backend_vector_select_feature_lane(target, vector_type, op))?;
    let selected =
        select_backend_simd_instruction_encoding(target, feature, lane, op).or_else(|| {
            backend_vector_fallback_feature_lane(target, op).and_then(
                |(fallback_feature, fallback_lane)| {
                    select_backend_simd_instruction_encoding(
                        target,
                        fallback_feature,
                        fallback_lane,
                        op,
                    )
                },
            )
        })?;
    if !backend_cpu_tuning_allows_simd_row(&function.backend_plan.cpu_tuning, &selected) {
        return None;
    }
    let microarchitecture =
        backend_cpu_tuned_schedule_microarchitecture(&function.backend_plan.cpu_tuning, target)?;
    let schedule = backend_simd_schedule_for(&selected, microarchitecture);
    Some(BackendVectorExpressionLoweringIR {
        function: function.name.clone(),
        target_symbol: target_symbol.to_string(),
        vector_type: vector_type.to_string(),
        source_symbols: backend_vector_expr_source_symbols(value),
        source_expression: source_expression.to_string(),
        target: selected.target,
        feature: selected.feature,
        lane: selected.lane,
        op: selected.op,
        selected_mnemonic: selected.mnemonic,
        selected_asm: selected.asm,
        selected_bytes: selected.bytes,
        schedule,
    })
}

fn backend_simd_target_label(target: &BackendTargetIR) -> Option<&'static str> {
    match target {
        BackendTargetIR::X86_64 => Some("x86_64"),
        BackendTargetIR::AArch64 => Some("aarch64"),
        BackendTargetIR::Wasm32 => None,
    }
}

fn backend_vector_expr_simd_op(expr: &ScalarExprIR) -> Option<BackendSimdOpIR> {
    match expr {
        ScalarExprIR::ArrayLiteral(_) => Some(BackendSimdOpIR::LoadAligned),
        ScalarExprIR::Binary { op, .. } => match op {
            ScalarBinaryOpIR::Plus => Some(BackendSimdOpIR::Add),
            ScalarBinaryOpIR::Star => Some(BackendSimdOpIR::Mul),
            ScalarBinaryOpIR::BitAnd => Some(BackendSimdOpIR::And),
            ScalarBinaryOpIR::BitOr => Some(BackendSimdOpIR::Or),
            ScalarBinaryOpIR::BitXor => Some(BackendSimdOpIR::Xor),
            _ => None,
        },
        ScalarExprIR::Call { target, .. } => {
            let name = target
                .rsplit(['.', ':'])
                .next()
                .unwrap_or(target)
                .to_ascii_lowercase();
            match name.as_str() {
                "vectoradd" | "simdadd" | "vadd" => Some(BackendSimdOpIR::Add),
                "vectormul" | "simdmul" | "vmul" => Some(BackendSimdOpIR::Mul),
                "vectorand" | "simdand" | "vand" => Some(BackendSimdOpIR::And),
                "vectoror" | "simdor" | "vor" => Some(BackendSimdOpIR::Or),
                "vectorxor" | "simdxor" | "vxor" => Some(BackendSimdOpIR::Xor),
                "vectorshuffle" | "simdshuffle" | "shuffle" | "permute" => {
                    Some(BackendSimdOpIR::Shuffle)
                }
                "vectormaskselect" | "simdmaskselect" | "maskselect" | "blend" => {
                    Some(BackendSimdOpIR::MaskSelect)
                }
                "vectorgather" | "simdgather" | "gather" => Some(BackendSimdOpIR::Gather),
                "vectorscatter" | "simdscatter" | "scatter" => Some(BackendSimdOpIR::Scatter),
                _ => None,
            }
        }
        _ => None,
    }
}

fn backend_vector_select_feature_lane(
    target: &str,
    vector_type: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR)> {
    let ty = vector_type.trim().replace(' ', "").to_ascii_lowercase();
    match target {
        "x86_64" => match op {
            BackendSimdOpIR::Gather => {
                Some((BackendSimdFeatureIR::X86Avx2, BackendSimdLaneIR::F32x8))
            }
            BackendSimdOpIR::Scatter => {
                Some((BackendSimdFeatureIR::X86Avx512F, BackendSimdLaneIR::F32x16))
            }
            BackendSimdOpIR::MaskSelect if ty.contains("x8") || ty.contains("f32x8") => {
                Some((BackendSimdFeatureIR::X86Avx, BackendSimdLaneIR::F32x8))
            }
            BackendSimdOpIR::MaskSelect => {
                Some((BackendSimdFeatureIR::X86Sse41, BackendSimdLaneIR::F32x4))
            }
            BackendSimdOpIR::Shuffle if ty.contains("x8") || ty.contains("f32x8") => {
                Some((BackendSimdFeatureIR::X86Avx, BackendSimdLaneIR::F32x8))
            }
            BackendSimdOpIR::Shuffle => {
                Some((BackendSimdFeatureIR::X86Sse, BackendSimdLaneIR::F32x4))
            }
            BackendSimdOpIR::Add if backend_vector_type_is_integer(&ty) => {
                Some((BackendSimdFeatureIR::X86Sse, BackendSimdLaneIR::I32x4))
            }
            BackendSimdOpIR::Mul if backend_vector_type_is_integer(&ty) => {
                Some((BackendSimdFeatureIR::X86Sse41, BackendSimdLaneIR::I32x4))
            }
            BackendSimdOpIR::And | BackendSimdOpIR::Or | BackendSimdOpIR::Xor => {
                Some((BackendSimdFeatureIR::X86Sse, BackendSimdLaneIR::B128))
            }
            BackendSimdOpIR::LoadAligned
            | BackendSimdOpIR::StoreAligned
            | BackendSimdOpIR::Add
            | BackendSimdOpIR::Mul => {
                if ty.contains("x8") || ty.contains("f32x8") {
                    Some((BackendSimdFeatureIR::X86Avx, BackendSimdLaneIR::F32x8))
                } else {
                    Some((BackendSimdFeatureIR::X86Sse, BackendSimdLaneIR::F32x4))
                }
            }
            BackendSimdOpIR::VZeroUpper => {
                Some((BackendSimdFeatureIR::X86Avx, BackendSimdLaneIR::B128))
            }
        },
        "aarch64" => match op {
            BackendSimdOpIR::And
            | BackendSimdOpIR::Or
            | BackendSimdOpIR::Xor
            | BackendSimdOpIR::MaskSelect => {
                Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::B128))
            }
            BackendSimdOpIR::Gather | BackendSimdOpIR::Scatter => {
                Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::I32x4))
            }
            BackendSimdOpIR::Shuffle if backend_vector_type_is_integer(&ty) => {
                Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::I32x4))
            }
            BackendSimdOpIR::Add | BackendSimdOpIR::Mul if backend_vector_type_is_integer(&ty) => {
                Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::I32x4))
            }
            BackendSimdOpIR::LoadAligned
            | BackendSimdOpIR::StoreAligned
            | BackendSimdOpIR::Add
            | BackendSimdOpIR::Mul
            | BackendSimdOpIR::Shuffle => {
                Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::F32x4))
            }
            BackendSimdOpIR::VZeroUpper => None,
        },
        _ => None,
    }
}

fn backend_vector_fallback_feature_lane(
    target: &str,
    op: BackendSimdOpIR,
) -> Option<(BackendSimdFeatureIR, BackendSimdLaneIR)> {
    match (target, op) {
        ("aarch64", BackendSimdOpIR::Shuffle) => {
            Some((BackendSimdFeatureIR::AArch64Neon, BackendSimdLaneIR::B128))
        }
        _ => None,
    }
}

fn backend_vector_type_is_integer(normalized_ty: &str) -> bool {
    [
        "int", "i32", "u32", "dword", "sdword", "word", "byte", "qword", "i64", "u64",
    ]
    .iter()
    .any(|needle| normalized_ty.contains(needle))
}

fn backend_vector_expr_source_symbols(expr: &ScalarExprIR) -> Vec<String> {
    let mut symbols = Vec::new();
    backend_vector_collect_expr_symbols(expr, &mut symbols);
    symbols.sort();
    symbols.dedup();
    symbols
}

fn backend_vector_collect_expr_symbols(expr: &ScalarExprIR, symbols: &mut Vec<String>) {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => {
            for (_, value) in fields {
                backend_vector_collect_expr_symbols(value, symbols);
            }
        }
        ScalarExprIR::Symbol(symbol) => symbols.push(symbol.clone()),
        ScalarExprIR::PostIncrement { target, .. } => symbols.push(target.clone()),
        ScalarExprIR::FieldPostIncrement { base, .. } => symbols.push(base.clone()),
        ScalarExprIR::PointerPostIncrementRead { target, .. } => symbols.push(target.clone()),
        ScalarExprIR::ArrayLiteral(items) => {
            for item in items {
                backend_vector_collect_expr_symbols(item, symbols);
            }
        }
        ScalarExprIR::AddressOf { target } => symbols.push(target.clone()),
        ScalarExprIR::PtrRead { ptr, .. } => backend_vector_collect_expr_symbols(ptr, symbols),
        ScalarExprIR::PtrWrite { ptr, value, .. } => {
            backend_vector_collect_expr_symbols(ptr, symbols);
            backend_vector_collect_expr_symbols(value, symbols);
        }
        ScalarExprIR::PtrOffset { ptr, index, .. }
        | ScalarExprIR::PtrDiff {
            left: ptr,
            right: index,
            ..
        }
        | ScalarExprIR::RegionFromPtr {
            ptr, len: index, ..
        }
        | ScalarExprIR::RegionPtrAt {
            region: ptr, index, ..
        } => {
            backend_vector_collect_expr_symbols(ptr, symbols);
            backend_vector_collect_expr_symbols(index, symbols);
        }
        ScalarExprIR::FieldRead { base, .. } => symbols.push(base.clone()),
        ScalarExprIR::ArrayFieldRead { target, index, .. } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(index, symbols);
        }
        ScalarExprIR::EnumConstruct { payload, .. } => {
            for item in payload {
                backend_vector_collect_expr_symbols(item, symbols);
            }
        }
        ScalarExprIR::EnumTagRead { target }
        | ScalarExprIR::EnumPayloadRead { target, .. }
        | ScalarExprIR::EnumPayloadFieldRead { target, .. }
        | ScalarExprIR::EnumPayloadArrayRead { target, .. } => symbols.push(target.clone()),
        ScalarExprIR::ArrayFieldWrite {
            target,
            index,
            value,
            ..
        } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(index, symbols);
            backend_vector_collect_expr_symbols(value, symbols);
        }
        ScalarExprIR::FieldWrite { base, value, .. } => {
            symbols.push(base.clone());
            backend_vector_collect_expr_symbols(value, symbols);
        }
        ScalarExprIR::ArrayRead { target, index, .. } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(index, symbols);
        }
        ScalarExprIR::ArrayWrite {
            target,
            index,
            value,
            ..
        } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(index, symbols);
            backend_vector_collect_expr_symbols(value, symbols);
        }
        ScalarExprIR::DinArrayLen { target }
        | ScalarExprIR::DinArrayCapacity { target }
        | ScalarExprIR::DinArrayPop { target, .. } => symbols.push(target.clone()),
        ScalarExprIR::DinArrayPush { target, value, .. } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(value, symbols);
        }
        ScalarExprIR::DinArrayRealloc { target, capacity } => {
            symbols.push(target.clone());
            backend_vector_collect_expr_symbols(capacity, symbols);
        }
        ScalarExprIR::Call { args, .. } => {
            for arg in args {
                backend_vector_collect_expr_symbols(arg, symbols);
            }
        }
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            backend_vector_collect_expr_symbols(value, symbols);
            if let Some(precision) = precision {
                backend_vector_collect_expr_symbols(precision, symbols);
            }
        }
        ScalarExprIR::Unary { expr, .. } => backend_vector_collect_expr_symbols(expr, symbols),
        ScalarExprIR::Binary { left, right, .. } => {
            backend_vector_collect_expr_symbols(left, symbols);
            backend_vector_collect_expr_symbols(right, symbols);
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            backend_vector_collect_expr_symbols(condition, symbols);
            backend_vector_collect_expr_symbols(then_expr, symbols);
            backend_vector_collect_expr_symbols(else_expr, symbols);
        }
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::DevTrap { .. } => {}
    }
}

fn render_backend_atomic_rmw_mnemonic(op: BackendAtomicRmwOpIR) -> &'static str {
    match op {
        BackendAtomicRmwOpIR::Exchange => "xchg",
        BackendAtomicRmwOpIR::Add => "lock xadd",
        BackendAtomicRmwOpIR::Sub => "neg + lock xadd",
        BackendAtomicRmwOpIR::And => "lock cmpxchg and loop",
        BackendAtomicRmwOpIR::Or => "lock cmpxchg or loop",
        BackendAtomicRmwOpIR::Xor => "lock cmpxchg xor loop",
        BackendAtomicRmwOpIR::CompareExchange => "lock cmpxchg",
    }
}

fn render_backend_atomic_rmw_aarch64_mnemonic(op: BackendAtomicRmwOpIR) -> &'static str {
    match op {
        BackendAtomicRmwOpIR::Exchange => "ldxr/stxr exchange loop",
        BackendAtomicRmwOpIR::Add => "ldxr/add/stxr fetch-add loop",
        BackendAtomicRmwOpIR::Sub => "ldxr/sub/stxr fetch-sub loop",
        BackendAtomicRmwOpIR::And => "ldxr/and/stxr fetch-and loop",
        BackendAtomicRmwOpIR::Or => "ldxr/orr/stxr fetch-or loop",
        BackendAtomicRmwOpIR::Xor => "ldxr/eor/stxr fetch-xor loop",
        BackendAtomicRmwOpIR::CompareExchange => "ldxr/cmp/stxr compare-exchange loop",
    }
}

pub fn render_object_text(object: &BackendObjectIR) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "; ncc object target={} triple={} format={} sections={} symbols={} relocs={}",
        render_backend_target(&object.target),
        object.target_spec.target_triple,
        render_backend_object_format(&object.target_spec.object_format),
        object.sections.len(),
        object.symbols.len(),
        object.relocations.len()
    );

    for section in &object.sections {
        let _ = writeln!(
            out,
            "\n.section {} ; kind={} unit={} size={}B",
            section.name,
            render_object_section_kind(&section.kind),
            section.unit,
            section.size_bytes
        );
        for line in &section.lines {
            let _ = writeln!(out, "    {}", line);
        }
    }

    let _ = writeln!(out, "\n.symbols");
    for symbol in &object.symbols {
        let _ = writeln!(
            out,
            "    {} section={} offset={} visibility={}",
            symbol.name,
            symbol.section,
            symbol.offset,
            render_symbol_visibility(&symbol.visibility)
        );
    }

    let _ = writeln!(out, "\n.relocations");
    for reloc in &object.relocations {
        let _ = writeln!(
            out,
            "    section={} offset={} kind={} symbol={} addend={}",
            reloc.section,
            reloc.offset,
            render_reloc_kind(&reloc.kind),
            reloc.symbol,
            reloc.addend
        );
    }

    out
}

pub fn emit_object_elf64(object: &BackendObjectIR) -> Result<Vec<u8>, String> {
    if object.target == BackendTargetIR::Wasm32
        || object.target_spec.object_format == BackendObjectFormatIR::WasmModule
    {
        return Err(
            "object format unsupported for selected linking model: artifact 'emit-elf' is unavailable in lane 'portable'; use emit-wasm/build-wasm"
                .to_string(),
        );
    }

    let elf_machine = match object.target {
        BackendTargetIR::X86_64 => ELF_EM_X86_64,
        BackendTargetIR::AArch64 => ELF_EM_AARCH64,
        BackendTargetIR::Wasm32 => unreachable!("wasm32 is rejected before ELF emission"),
    };

    let mut specs: Vec<ElfSectionSpec> = Vec::new();

    // 1) Payload sections from typed object.
    let mut section_name_to_index: HashMap<String, usize> = HashMap::new();
    for section in &object.sections {
        let section_index = specs.len() + 1; // +1 for ELF null section.
        section_name_to_index.insert(section.name.clone(), section_index);
        let mut flags = match section.kind {
            BackendObjectSectionKindIR::Text | BackendObjectSectionKindIR::Machine => {
                ELF_SHF_ALLOC | ELF_SHF_EXECINSTR
            }
            BackendObjectSectionKindIR::Data
            | BackendObjectSectionKindIR::Bss
            | BackendObjectSectionKindIR::PerCpuData
            | BackendObjectSectionKindIR::PerCpuBss
            | BackendObjectSectionKindIR::InitArray
            | BackendObjectSectionKindIR::FiniArray => ELF_SHF_ALLOC | ELF_SHF_WRITE,
            BackendObjectSectionKindIR::TlsData | BackendObjectSectionKindIR::TlsBss => {
                ELF_SHF_ALLOC | ELF_SHF_WRITE | ELF_SHF_TLS
            }
            BackendObjectSectionKindIR::ReadOnlyData
            | BackendObjectSectionKindIR::PrimitiveMeta
            | BackendObjectSectionKindIR::TypeMeta => ELF_SHF_ALLOC,
        };
        if section.comdat.is_some() {
            flags |= ELF_SHF_GROUP;
        }
        let lines = materialize_object_section_payload(section)?;
        specs.push(ElfSectionSpec {
            name: section.name.clone(),
            sh_type: if matches!(
                section.kind,
                BackendObjectSectionKindIR::Bss
                    | BackendObjectSectionKindIR::TlsBss
                    | BackendObjectSectionKindIR::PerCpuBss
            ) {
                ELF_SHT_NOBITS
            } else {
                ELF_SHT_PROGBITS
            },
            sh_flags: flags,
            data: lines,
            virtual_size: section.size_bytes as u64,
            sh_link: 0,
            sh_info: 0,
            sh_addralign: object_section_align_bytes(section) as u64,
            sh_entsize: 0,
        });
    }

    // 2) Build symbol inventory (defined + unresolved externs).
    let mut local_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_local())
        .cloned()
        .collect::<Vec<_>>();
    let mut global_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_externally_visible())
        .cloned()
        .collect::<Vec<_>>();
    local_defined.sort_by(|a, b| a.name.cmp(&b.name));
    global_defined.sort_by(|a, b| a.name.cmp(&b.name));

    let unresolved = object.unresolved_symbols();

    if !unresolved.is_empty()
        && object
            .target_spec
            .linking_contract()
            .unresolved_symbol_policy
            == BackendUnresolvedSymbolPolicyIR::RejectUnresolvedAtBackendStage
    {
        return Err(format!(
            "symbol unresolved at backend stage: {}",
            unresolved.join(", ")
        ));
    }

    let mut sym_rows = Vec::new();
    sym_rows.push(ElfSymbolRow {
        name: String::new(),
        bind: ELF_STB_LOCAL,
        ty: ELF_STT_NOTYPE,
        shndx: 0,
        value: 0,
        size: 0,
    });

    for sym in &local_defined {
        let shndx = section_name_to_index.get(&sym.section).ok_or_else(|| {
            format!(
                "symbol '{}' points to unknown section '{}'",
                sym.name, sym.section
            )
        })?;
        sym_rows.push(ElfSymbolRow {
            name: sym.name.clone(),
            bind: ELF_STB_LOCAL,
            ty: elf_symbol_type_for_section_name(&sym.section),
            shndx: *shndx as u16,
            value: sym.offset as u64,
            size: 0,
        });
    }

    for sym in &global_defined {
        let section_index = section_name_to_index.get(&sym.section).ok_or_else(|| {
            format!(
                "symbol '{}' points to unknown section '{}'",
                sym.name, sym.section
            )
        })?;
        let section = object
            .sections
            .iter()
            .find(|section| section.name == sym.section)
            .ok_or_else(|| format!("missing symbol section '{}'", sym.section))?;
        let common = sym.visibility == BackendSymbolVisibilityIR::Common;
        sym_rows.push(ElfSymbolRow {
            name: sym.name.clone(),
            bind: if matches!(
                sym.visibility,
                BackendSymbolVisibilityIR::Weak | BackendSymbolVisibilityIR::LinkOnceOdr
            ) {
                ELF_STB_WEAK
            } else {
                ELF_STB_GLOBAL
            },
            ty: elf_symbol_type_for_section_name(&sym.section),
            shndx: if common {
                ELF_SHN_COMMON
            } else {
                *section_index as u16
            },
            value: if common {
                section.align_bytes.max(1) as u64
            } else {
                sym.offset as u64
            },
            size: section.size_bytes.saturating_sub(sym.offset) as u64,
        });
    }

    for name in unresolved {
        sym_rows.push(ElfSymbolRow {
            name,
            bind: ELF_STB_GLOBAL,
            ty: ELF_STT_NOTYPE,
            shndx: 0,
            value: 0,
            size: 0,
        });
    }

    let local_count = 1 + local_defined.len();
    let mut sym_index_by_name = HashMap::new();
    for (idx, row) in sym_rows.iter().enumerate() {
        if !row.name.is_empty() {
            sym_index_by_name.insert(row.name.clone(), idx);
        }
    }

    let mut elf_group_slots = Vec::<(usize, usize)>::new();
    let mut comdat_sections = HashMap::<String, Vec<usize>>::new();
    for section in &object.sections {
        let Some(group) = &section.comdat else {
            continue;
        };
        let section_index = section_name_to_index
            .get(&section.name)
            .copied()
            .ok_or_else(|| format!("COMDAT section '{}' is missing", section.name))?;
        comdat_sections
            .entry(group.clone())
            .or_default()
            .push(section_index);
    }
    for (group, members) in comdat_sections {
        let signature = object
            .symbols
            .iter()
            .find(|symbol| {
                symbol.visibility == BackendSymbolVisibilityIR::LinkOnceOdr
                    && members.iter().any(|section_index| {
                        section_name_to_index.get(&symbol.section) == Some(section_index)
                    })
            })
            .ok_or_else(|| format!("COMDAT group '{group}' has no linkonce_odr signature"))?;
        let signature_index = sym_index_by_name
            .get(&signature.name)
            .copied()
            .ok_or_else(|| format!("COMDAT signature '{}' is missing", signature.name))?;
        let mut data = Vec::with_capacity((members.len() + 1) * 4);
        data.extend_from_slice(&ELF_GRP_COMDAT.to_le_bytes());
        for member in members {
            data.extend_from_slice(&(member as u32).to_le_bytes());
        }
        let spec_index = specs.len();
        specs.push(ElfSectionSpec {
            name: format!(".group.{}", sanitize_backend_section_component(&group)),
            sh_type: ELF_SHT_GROUP,
            sh_flags: 0,
            virtual_size: data.len() as u64,
            data,
            sh_link: 0,
            sh_info: signature_index as u32,
            sh_addralign: 4,
            sh_entsize: 4,
        });
        elf_group_slots.push((spec_index, signature_index));
    }

    // 3) Relocation sections derived from typed relocations.
    let mut relocs_by_source: HashMap<String, Vec<&BackendObjectRelocationIR>> = HashMap::new();
    for rel in &object.relocations {
        relocs_by_source
            .entry(rel.section.clone())
            .or_default()
            .push(rel);
    }
    let mut rel_section_slots: Vec<(usize, usize)> = Vec::new(); // (spec_idx, target section idx)
    for source in &object.sections {
        let Some(relocs) = relocs_by_source.get(&source.name) else {
            continue;
        };

        let mut data = Vec::new();
        for rel in relocs {
            let sym_index = sym_index_by_name
                .get(&rel.symbol)
                .ok_or_else(|| format!("relocation references unknown symbol '{}'", rel.symbol))?;
            let rel_type = match object.target {
                BackendTargetIR::X86_64 => match rel.kind {
                    BackendObjectRelocationKindIR::CallNear32
                    | BackendObjectRelocationKindIR::JumpNear32
                    | BackendObjectRelocationKindIR::PcRel32 => ELF_R_X86_64_PC32,
                    BackendObjectRelocationKindIR::Abs32 => ELF_R_X86_64_32,
                    BackendObjectRelocationKindIR::Abs64 => ELF_R_X86_64_64,
                },
                BackendTargetIR::AArch64 => match rel.kind {
                    BackendObjectRelocationKindIR::CallNear32 => ELF_R_AARCH64_CALL26,
                    BackendObjectRelocationKindIR::JumpNear32 => ELF_R_AARCH64_JUMP26,
                    BackendObjectRelocationKindIR::Abs32 => ELF_R_AARCH64_ABS32,
                    BackendObjectRelocationKindIR::PcRel32
                    | BackendObjectRelocationKindIR::Abs64 => ELF_R_AARCH64_ABS64,
                },
                BackendTargetIR::Wasm32 => {
                    unreachable!("wasm32 is rejected before ELF relocation lowering")
                }
            };
            let r_info = ((*sym_index as u64) << 32) | rel_type as u64;
            data.extend_from_slice(&(rel.offset as u64).to_le_bytes());
            data.extend_from_slice(&r_info.to_le_bytes());
            data.extend_from_slice(&(rel.addend as i64).to_le_bytes());
        }

        let target_section_index = section_name_to_index
            .get(&source.name)
            .ok_or_else(|| format!("relocation source section '{}' is missing", source.name))?;
        let spec_idx = specs.len();
        specs.push(ElfSectionSpec {
            name: format!(".rela{}", source.name),
            sh_type: ELF_SHT_RELA,
            sh_flags: 0,
            virtual_size: data.len() as u64,
            data,
            sh_link: 0, // filled after symtab index is known
            sh_info: *target_section_index as u32,
            sh_addralign: 8,
            sh_entsize: 24,
        });
        rel_section_slots.push((spec_idx, *target_section_index));
    }

    // 4) String table + symbol table sections.
    let (strtab_bytes, str_off_by_name) =
        build_elf_string_table(sym_rows.iter().map(|s| s.name.as_str()));
    let mut symtab_bytes = Vec::new();
    for row in &sym_rows {
        let st_name = str_off_by_name.get(row.name.as_str()).copied().unwrap_or(0);
        symtab_bytes.extend_from_slice(&st_name.to_le_bytes());
        symtab_bytes.push((row.bind << 4) | (row.ty & 0x0f));
        symtab_bytes.push(0); // st_other
        symtab_bytes.extend_from_slice(&row.shndx.to_le_bytes());
        symtab_bytes.extend_from_slice(&row.value.to_le_bytes());
        symtab_bytes.extend_from_slice(&row.size.to_le_bytes());
    }

    let symtab_spec_idx = specs.len();
    specs.push(ElfSectionSpec {
        name: ".symtab".into(),
        sh_type: ELF_SHT_SYMTAB,
        sh_flags: 0,
        virtual_size: symtab_bytes.len() as u64,
        data: symtab_bytes,
        sh_link: 0, // set once strtab index is known
        sh_info: local_count as u32,
        sh_addralign: 8,
        sh_entsize: 24,
    });
    let strtab_spec_idx = specs.len();
    specs.push(ElfSectionSpec {
        name: ".strtab".into(),
        sh_type: ELF_SHT_STRTAB,
        sh_flags: 0,
        virtual_size: strtab_bytes.len() as u64,
        data: strtab_bytes,
        sh_link: 0,
        sh_info: 0,
        sh_addralign: 1,
        sh_entsize: 0,
    });

    // 5) Mark generated ELF objects as requiring a non-executable stack. This
    // is a real linker contract, not a comment: GNU-compatible linkers consume
    // this section to avoid the executable-stack fallback warning.
    specs.push(ElfSectionSpec {
        name: ".note.GNU-stack".into(),
        sh_type: ELF_SHT_PROGBITS,
        sh_flags: 0,
        virtual_size: 0,
        data: Vec::new(),
        sh_link: 0,
        sh_info: 0,
        sh_addralign: 1,
        sh_entsize: 0,
    });

    // 6) Section-name string table.
    let mut shstr_names = Vec::with_capacity(specs.len() + 1);
    shstr_names.push(String::new()); // null section
    for spec in &specs {
        shstr_names.push(spec.name.clone());
    }
    shstr_names.push(".shstrtab".into());
    let (shstrtab_bytes, shstr_off_by_name) =
        build_elf_string_table(shstr_names.iter().map(|s| s.as_str()));

    let shstrtab_spec_idx = specs.len();
    specs.push(ElfSectionSpec {
        name: ".shstrtab".into(),
        sh_type: ELF_SHT_STRTAB,
        sh_flags: 0,
        virtual_size: shstrtab_bytes.len() as u64,
        data: shstrtab_bytes,
        sh_link: 0,
        sh_info: 0,
        sh_addralign: 1,
        sh_entsize: 0,
    });

    let symtab_section_index = symtab_spec_idx + 1;
    let strtab_section_index = strtab_spec_idx + 1;
    let shstrtab_section_index = shstrtab_spec_idx + 1;
    specs[symtab_spec_idx].sh_link = strtab_section_index as u32;
    for (spec_idx, signature_idx) in elf_group_slots {
        specs[spec_idx].sh_link = symtab_section_index as u32;
        specs[spec_idx].sh_info = signature_idx as u32;
    }
    for (spec_idx, target_idx) in rel_section_slots {
        specs[spec_idx].sh_link = symtab_section_index as u32;
        specs[spec_idx].sh_info = target_idx as u32;
    }

    // 7) Layout all section payloads and final section header table.
    let ehdr_size = 64usize;
    let shdr_size = 64usize;
    let mut offsets = vec![0u64; specs.len() + 1]; // includes null section at 0
    let mut cursor = ehdr_size as u64;
    for (i, spec) in specs.iter().enumerate() {
        cursor = align_u64(cursor, spec.sh_addralign.max(1));
        offsets[i + 1] = cursor;
        cursor += spec.data.len() as u64;
    }
    let shoff = align_u64(cursor, 8);
    let shnum = (specs.len() + 1) as u16;

    let mut out = vec![0; ehdr_size];

    // ELF64 header
    out[0] = 0x7f;
    out[1] = b'E';
    out[2] = b'L';
    out[3] = b'F';
    out[4] = ELF_CLASS_64;
    out[5] = ELF_DATA_LSB;
    out[6] = ELF_VERSION_CURRENT;
    out[7] = ELF_OSABI_SYSV;
    out[8] = 0; // ABI version
                // rest of e_ident padding already zeroed
    put_u16(&mut out[16..18], ELF_ET_REL);
    put_u16(&mut out[18..20], elf_machine);
    put_u32(&mut out[20..24], ELF_EV_CURRENT as u32);
    put_u64(&mut out[24..32], 0); // e_entry
    put_u64(&mut out[32..40], 0); // e_phoff
    put_u64(&mut out[40..48], shoff);
    put_u32(&mut out[48..52], 0); // flags
    put_u16(&mut out[52..54], ehdr_size as u16);
    put_u16(&mut out[54..56], 0); // phentsize
    put_u16(&mut out[56..58], 0); // phnum
    put_u16(&mut out[58..60], shdr_size as u16);
    put_u16(&mut out[60..62], shnum);
    put_u16(&mut out[62..64], shstrtab_section_index as u16);

    // Section payloads
    for (i, spec) in specs.iter().enumerate() {
        let off = offsets[i + 1] as usize;
        if out.len() < off {
            out.resize(off, 0);
        }
        out.extend_from_slice(&spec.data);
    }
    if out.len() < shoff as usize {
        out.resize(shoff as usize, 0);
    }

    // Section headers
    let mut shdrs = vec![0; shdr_size]; // null shdr
    for spec in &specs {
        let mut sh = vec![0u8; shdr_size];
        let name_off = shstr_off_by_name
            .get(spec.name.as_str())
            .copied()
            .ok_or_else(|| format!("missing shstrtab name '{}'", spec.name))?;
        put_u32(&mut sh[0..4], name_off);
        put_u32(&mut sh[4..8], spec.sh_type);
        put_u64(&mut sh[8..16], spec.sh_flags);
        put_u64(&mut sh[16..24], 0); // sh_addr
        let idx = shdrs.len() / shdr_size; // includes null
        put_u64(&mut sh[24..32], offsets[idx]);
        put_u64(&mut sh[32..40], spec.virtual_size);
        put_u32(&mut sh[40..44], spec.sh_link);
        put_u32(&mut sh[44..48], spec.sh_info);
        put_u64(&mut sh[48..56], spec.sh_addralign.max(1));
        put_u64(&mut sh[56..64], spec.sh_entsize);
        shdrs.extend_from_slice(&sh);
    }
    out.extend_from_slice(&shdrs);
    Ok(out)
}

pub fn emit_object_coff(object: &BackendObjectIR) -> Result<Vec<u8>, String> {
    if object.target == BackendTargetIR::Wasm32
        || object.target_spec.lane() == BackendLaneIR::Portable
        || object.target_spec.object_format == BackendObjectFormatIR::WasmModule
    {
        return Err(
            "object format unsupported for selected linking model: artifact 'emit-coff' is unavailable in lane 'portable'; use emit-wasm/build-wasm"
                .to_string(),
        );
    }
    if object.target_spec.lane() == BackendLaneIR::Sovereign
        || object.target_spec.object_format == BackendObjectFormatIR::FreestandingImage
    {
        return Err(
            "object format unsupported for selected linking model: artifact 'emit-coff' is unavailable in lane 'sovereign'; use emit-sovereign/build-sovereign"
                .to_string(),
        );
    }

    let machine = match object.target {
        BackendTargetIR::X86_64 => COFF_MACHINE_X86_64,
        BackendTargetIR::AArch64 => COFF_MACHINE_ARM64,
        BackendTargetIR::Wasm32 => unreachable!("wasm32 is rejected before COFF emission"),
    };

    let mut local_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_local())
        .cloned()
        .collect::<Vec<_>>();
    let mut global_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_externally_visible())
        .cloned()
        .collect::<Vec<_>>();
    local_defined.sort_by(|a, b| a.name.cmp(&b.name));
    global_defined.sort_by(|a, b| a.name.cmp(&b.name));

    let unresolved = object.unresolved_symbols();
    if !unresolved.is_empty()
        && object
            .target_spec
            .linking_contract()
            .unresolved_symbol_policy
            == BackendUnresolvedSymbolPolicyIR::RejectUnresolvedAtBackendStage
    {
        return Err(format!(
            "symbol unresolved at backend stage: {}",
            unresolved.join(", ")
        ));
    }

    let mut section_index_by_name: HashMap<String, u16> = HashMap::new();
    let mut section_payloads: Vec<Vec<u8>> = Vec::with_capacity(object.sections.len());
    for (idx, section) in object.sections.iter().enumerate() {
        section_index_by_name.insert(section.name.clone(), (idx + 1) as u16);
        section_payloads.push(materialize_object_section_payload(section)?);
    }

    #[derive(Clone)]
    struct CoffSymbolRow {
        name: String,
        section_number: i16,
        value: u32,
        ty: u16,
        storage_class: u8,
        aux: Vec<[u8; 18]>,
    }

    let mut symbol_rows: Vec<CoffSymbolRow> = Vec::new();
    for (index, section) in object.sections.iter().enumerate() {
        if section.comdat.is_none() {
            continue;
        }
        let mut section_def = [0u8; 18];
        put_u32(&mut section_def[0..4], section.size_bytes as u32);
        let relocation_count = object
            .relocations
            .iter()
            .filter(|relocation| relocation.section == section.name)
            .count()
            .min(u16::MAX as usize) as u16;
        put_u16(&mut section_def[4..6], relocation_count);
        section_def[14] = COFF_COMDAT_SELECT_ANY;
        symbol_rows.push(CoffSymbolRow {
            name: section.name.clone(),
            section_number: (index + 1) as i16,
            value: 0,
            ty: 0,
            storage_class: COFF_STORAGE_CLASS_STATIC,
            aux: vec![section_def],
        });
    }
    for sym in &local_defined {
        let section_number = section_index_by_name.get(&sym.section).ok_or_else(|| {
            format!(
                "symbol '{}' points to unknown section '{}'",
                sym.name, sym.section
            )
        })?;
        symbol_rows.push(CoffSymbolRow {
            name: sym.name.clone(),
            section_number: *section_number as i16,
            value: sym.offset as u32,
            ty: coff_symbol_type_for_section_name(&sym.section),
            storage_class: COFF_STORAGE_CLASS_STATIC,
            aux: Vec::new(),
        });
    }
    for sym in &global_defined {
        let section_number = section_index_by_name.get(&sym.section).ok_or_else(|| {
            format!(
                "symbol '{}' points to unknown section '{}'",
                sym.name, sym.section
            )
        })?;
        let section = object
            .sections
            .iter()
            .find(|section| section.name == sym.section)
            .ok_or_else(|| format!("missing symbol section '{}'", sym.section))?;
        symbol_rows.push(CoffSymbolRow {
            name: sym.name.clone(),
            section_number: if sym.visibility == BackendSymbolVisibilityIR::Common {
                0
            } else {
                *section_number as i16
            },
            value: if sym.visibility == BackendSymbolVisibilityIR::Common {
                section.size_bytes as u32
            } else {
                sym.offset as u32
            },
            ty: coff_symbol_type_for_section_name(&sym.section),
            storage_class: COFF_STORAGE_CLASS_EXTERNAL,
            aux: Vec::new(),
        });
    }
    for sym in unresolved {
        symbol_rows.push(CoffSymbolRow {
            name: sym,
            section_number: 0,
            value: 0,
            ty: 0,
            storage_class: COFF_STORAGE_CLASS_EXTERNAL,
            aux: Vec::new(),
        });
    }

    let mut sym_index_by_name = HashMap::new();
    let mut coff_symbol_index = 0u32;
    for row in &symbol_rows {
        sym_index_by_name.insert(row.name.clone(), coff_symbol_index);
        coff_symbol_index = coff_symbol_index.saturating_add(1 + row.aux.len() as u32);
    }

    let mut relocs_by_section: HashMap<String, Vec<&BackendObjectRelocationIR>> = HashMap::new();
    for rel in &object.relocations {
        relocs_by_section
            .entry(rel.section.clone())
            .or_default()
            .push(rel);
    }

    let file_header_size = 20usize;
    let section_header_size = 40usize;
    let section_count = object.sections.len();
    let mut section_raw_ptrs = vec![0u32; section_count];
    let mut section_reloc_ptrs = vec![0u32; section_count];
    let mut section_reloc_counts = vec![0u16; section_count];
    let mut section_reloc_blobs: Vec<Vec<u8>> = vec![Vec::new(); section_count];

    let mut cursor = (file_header_size + section_count * section_header_size) as u32;
    for (idx, payload) in section_payloads.iter().enumerate() {
        if !payload.is_empty() {
            section_raw_ptrs[idx] = cursor;
            cursor = cursor.saturating_add(payload.len() as u32);
        }
    }
    for idx in 0..section_count {
        let relocs = relocs_by_section
            .get(&object.sections[idx].name)
            .cloned()
            .unwrap_or_default();
        if !relocs.is_empty() {
            section_reloc_ptrs[idx] = cursor;
            section_reloc_counts[idx] = relocs.len().min(u16::MAX as usize) as u16;
            let mut blob = Vec::with_capacity(relocs.len() * 10);
            for rel in relocs {
                let Some(sym_index) = sym_index_by_name.get(&rel.symbol).copied() else {
                    return Err(format!(
                        "relocation references unknown symbol '{}'",
                        rel.symbol
                    ));
                };
                let rel_type = coff_relocation_type_for_target_and_kind(&object.target, &rel.kind);
                blob.extend_from_slice(&(rel.offset as u32).to_le_bytes());
                blob.extend_from_slice(&sym_index.to_le_bytes());
                blob.extend_from_slice(&rel_type.to_le_bytes());
            }
            cursor = cursor.saturating_add(blob.len() as u32);
            section_reloc_blobs[idx] = blob;
        }
    }

    let pointer_to_symbol_table = cursor;
    let number_of_symbols = symbol_rows
        .iter()
        .map(|row| 1u32 + row.aux.len() as u32)
        .sum::<u32>();
    let mut symbol_blob = Vec::with_capacity(number_of_symbols as usize * 18);
    let mut coff_string_tail = Vec::new();
    let mut coff_string_offsets: HashMap<String, u32> = HashMap::new();
    let mut section_name_fields: Vec<[u8; 8]> = Vec::with_capacity(section_count);
    for section in &object.sections {
        section_name_fields.push(encode_coff_name_field(
            &section.name,
            &mut coff_string_offsets,
            &mut coff_string_tail,
        ));
    }
    for row in &symbol_rows {
        let name_field = encode_coff_symbol_name_field(
            &row.name,
            &mut coff_string_offsets,
            &mut coff_string_tail,
        );
        symbol_blob.extend_from_slice(&name_field);
        symbol_blob.extend_from_slice(&row.value.to_le_bytes());
        symbol_blob.extend_from_slice(&row.section_number.to_le_bytes());
        symbol_blob.extend_from_slice(&row.ty.to_le_bytes());
        symbol_blob.push(row.storage_class);
        symbol_blob.push(row.aux.len() as u8);
        for aux in &row.aux {
            symbol_blob.extend_from_slice(aux);
        }
    }
    let mut string_table = Vec::new();
    string_table.extend_from_slice(&((4 + coff_string_tail.len()) as u32).to_le_bytes());
    string_table.extend_from_slice(&coff_string_tail);

    let mut out = Vec::new();
    out.extend_from_slice(&machine.to_le_bytes());
    out.extend_from_slice(&(section_count as u16).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // timestamp
    out.extend_from_slice(&pointer_to_symbol_table.to_le_bytes());
    out.extend_from_slice(&number_of_symbols.to_le_bytes());
    out.extend_from_slice(&0u16.to_le_bytes()); // optional header size
    out.extend_from_slice(&0u16.to_le_bytes()); // characteristics

    for (idx, section) in object.sections.iter().enumerate() {
        out.extend_from_slice(&section_name_fields[idx]);
        out.extend_from_slice(&0u32.to_le_bytes()); // virtual size / physical
        out.extend_from_slice(&0u32.to_le_bytes()); // virtual address
        let raw_size = if matches!(
            section.kind,
            BackendObjectSectionKindIR::Bss
                | BackendObjectSectionKindIR::TlsBss
                | BackendObjectSectionKindIR::PerCpuBss
        ) {
            section.size_bytes as u32
        } else {
            section_payloads[idx].len() as u32
        };
        out.extend_from_slice(&raw_size.to_le_bytes());
        out.extend_from_slice(&section_raw_ptrs[idx].to_le_bytes());
        out.extend_from_slice(&section_reloc_ptrs[idx].to_le_bytes());
        out.extend_from_slice(&0u32.to_le_bytes()); // line number ptr
        out.extend_from_slice(&section_reloc_counts[idx].to_le_bytes());
        out.extend_from_slice(&0u16.to_le_bytes()); // line number count
        out.extend_from_slice(&coff_section_characteristics(section).to_le_bytes());
    }

    for payload in &section_payloads {
        out.extend_from_slice(payload);
    }
    for blob in &section_reloc_blobs {
        out.extend_from_slice(blob);
    }
    out.extend_from_slice(&symbol_blob);
    out.extend_from_slice(&string_table);
    Ok(out)
}

pub fn emit_object_macho64(object: &BackendObjectIR) -> Result<Vec<u8>, String> {
    if object.target == BackendTargetIR::Wasm32
        || object.target_spec.lane() == BackendLaneIR::Portable
        || object.target_spec.object_format == BackendObjectFormatIR::WasmModule
    {
        return Err(
            "object format unsupported for selected linking model: artifact 'emit-macho' is unavailable in lane 'portable'; use emit-wasm/build-wasm"
                .to_string(),
        );
    }
    if object.target_spec.lane() == BackendLaneIR::Sovereign
        || object.target_spec.object_format == BackendObjectFormatIR::FreestandingImage
    {
        return Err(
            "object format unsupported for selected linking model: artifact 'emit-macho' is unavailable in lane 'sovereign'; use emit-sovereign/build-sovereign"
                .to_string(),
        );
    }

    let (cpu_type, cpu_subtype) = match object.target {
        BackendTargetIR::X86_64 => (MACHO_CPU_TYPE_X86_64, MACHO_CPU_SUBTYPE_X86_64_ALL),
        BackendTargetIR::AArch64 => (MACHO_CPU_TYPE_ARM64, MACHO_CPU_SUBTYPE_ARM64_ALL),
        BackendTargetIR::Wasm32 => unreachable!("wasm32 is rejected before Mach-O emission"),
    };

    let mut local_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_local())
        .cloned()
        .collect::<Vec<_>>();
    let mut global_defined = object
        .symbols
        .iter()
        .filter(|s| s.visibility.is_externally_visible())
        .cloned()
        .collect::<Vec<_>>();
    local_defined.sort_by(|a, b| a.name.cmp(&b.name));
    global_defined.sort_by(|a, b| a.name.cmp(&b.name));

    let unresolved = object.unresolved_symbols();
    if !unresolved.is_empty()
        && object
            .target_spec
            .linking_contract()
            .unresolved_symbol_policy
            == BackendUnresolvedSymbolPolicyIR::RejectUnresolvedAtBackendStage
    {
        return Err(format!(
            "symbol unresolved at backend stage: {}",
            unresolved.join(", ")
        ));
    }

    let mut section_payloads = Vec::with_capacity(object.sections.len());
    let mut section_index_by_name = HashMap::new();
    for (idx, section) in object.sections.iter().enumerate() {
        section_index_by_name.insert(section.name.clone(), (idx + 1) as u8);
        section_payloads.push(materialize_object_section_payload(section)?);
    }

    #[derive(Clone)]
    struct MachOSymbolRow {
        name: String,
        n_type: u8,
        n_sect: u8,
        n_desc: u16,
        n_value: u64,
    }

    let mut symbol_rows: Vec<MachOSymbolRow> = Vec::new();
    for sym in &local_defined {
        let n_sect = section_index_by_name
            .get(&sym.section)
            .copied()
            .ok_or_else(|| {
                format!(
                    "symbol '{}' points to unknown section '{}'",
                    sym.name, sym.section
                )
            })?;
        symbol_rows.push(MachOSymbolRow {
            name: sym.name.clone(),
            n_type: MACHO_N_SECT,
            n_sect,
            n_desc: 0,
            n_value: sym.offset as u64,
        });
    }
    for sym in &global_defined {
        let n_sect = section_index_by_name
            .get(&sym.section)
            .copied()
            .ok_or_else(|| {
                format!(
                    "symbol '{}' points to unknown section '{}'",
                    sym.name, sym.section
                )
            })?;
        let section = object
            .sections
            .iter()
            .find(|section| section.name == sym.section)
            .ok_or_else(|| format!("missing symbol section '{}'", sym.section))?;
        let common = sym.visibility == BackendSymbolVisibilityIR::Common;
        symbol_rows.push(MachOSymbolRow {
            name: sym.name.clone(),
            n_type: if common {
                MACHO_N_UNDF | MACHO_N_EXT
            } else {
                MACHO_N_SECT | MACHO_N_EXT
            },
            n_sect: if common { 0 } else { n_sect },
            n_desc: if common {
                (section.align_bytes.max(1).trailing_zeros().min(15) as u16) << 8
            } else if matches!(
                sym.visibility,
                BackendSymbolVisibilityIR::Weak | BackendSymbolVisibilityIR::LinkOnceOdr
            ) {
                MACHO_N_WEAK_DEF
            } else {
                0
            },
            n_value: if common {
                section.size_bytes as u64
            } else {
                sym.offset as u64
            },
        });
    }
    for sym in unresolved {
        symbol_rows.push(MachOSymbolRow {
            name: sym,
            n_type: MACHO_N_UNDF | MACHO_N_EXT,
            n_sect: 0,
            n_desc: 0,
            n_value: 0,
        });
    }

    let mut sym_index_by_name = HashMap::new();
    for (idx, row) in symbol_rows.iter().enumerate() {
        sym_index_by_name.insert(row.name.clone(), idx as u32);
    }

    let mut relocs_by_section: HashMap<String, Vec<&BackendObjectRelocationIR>> = HashMap::new();
    for rel in &object.relocations {
        relocs_by_section
            .entry(rel.section.clone())
            .or_default()
            .push(rel);
    }

    let section_count = object.sections.len();
    let header_size = 32usize; // mach_header_64
    let segment_cmd_size = 72usize + section_count * 80usize; // segment_command_64 + section_64[]
    let symtab_cmd_size = 24usize; // symtab_command
    let sizeofcmds = segment_cmd_size + symtab_cmd_size;
    let mut cursor = (header_size + sizeofcmds) as u32;

    let mut section_data_offsets = vec![0u32; section_count];
    let mut section_reloc_offsets = vec![0u32; section_count];
    let mut section_reloc_counts = vec![0u32; section_count];
    let mut section_reloc_blobs: Vec<Vec<u8>> = vec![Vec::new(); section_count];

    for (idx, payload) in section_payloads.iter().enumerate() {
        if !payload.is_empty() {
            section_data_offsets[idx] = cursor;
            cursor = cursor.saturating_add(payload.len() as u32);
        }
        let relocs = relocs_by_section
            .get(&object.sections[idx].name)
            .cloned()
            .unwrap_or_default();
        if !relocs.is_empty() {
            section_reloc_offsets[idx] = cursor;
            section_reloc_counts[idx] = relocs.len() as u32;
            let mut blob = Vec::with_capacity(relocs.len() * 8);
            for rel in relocs {
                let Some(sym_index) = sym_index_by_name.get(&rel.symbol).copied() else {
                    return Err(format!(
                        "relocation references unknown symbol '{}'",
                        rel.symbol
                    ));
                };
                blob.extend_from_slice(&(rel.offset as i32).to_le_bytes());
                let packed = encode_macho_relocation_info(
                    sym_index,
                    macho_reloc_is_pcrel(&rel.kind),
                    macho_reloc_length_pow2(&rel.kind),
                    true,
                    macho_reloc_type_for_target_and_kind(&object.target, &rel.kind),
                );
                blob.extend_from_slice(&packed.to_le_bytes());
            }
            cursor = cursor.saturating_add(blob.len() as u32);
            section_reloc_blobs[idx] = blob;
        }
    }

    let symoff = cursor;
    let nsyms = symbol_rows.len() as u32;
    let mut string_tail = Vec::new();
    let mut string_offsets: HashMap<String, u32> = HashMap::new();
    let mut nlist_blob = Vec::with_capacity(symbol_rows.len() * 16);
    for row in &symbol_rows {
        let strx = macho_string_offset_for_name(&row.name, &mut string_offsets, &mut string_tail);
        nlist_blob.extend_from_slice(&strx.to_le_bytes());
        nlist_blob.push(row.n_type);
        nlist_blob.push(row.n_sect);
        nlist_blob.extend_from_slice(&row.n_desc.to_le_bytes());
        nlist_blob.extend_from_slice(&row.n_value.to_le_bytes());
    }
    cursor = cursor.saturating_add(nlist_blob.len() as u32);

    let stroff = cursor;
    let mut strtab = Vec::new();
    strtab.push(0);
    strtab.extend_from_slice(&string_tail);
    let strsize = strtab.len() as u32;

    let mut out = Vec::new();
    out.extend_from_slice(&MACHO_MAGIC_64.to_le_bytes());
    out.extend_from_slice(&(cpu_type as u32).to_le_bytes());
    out.extend_from_slice(&(cpu_subtype as u32).to_le_bytes());
    out.extend_from_slice(&MACHO_FILETYPE_OBJECT.to_le_bytes());
    out.extend_from_slice(&2u32.to_le_bytes()); // ncmds
    out.extend_from_slice(&(sizeofcmds as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // flags
    out.extend_from_slice(&0u32.to_le_bytes()); // reserved

    out.extend_from_slice(&MACHO_LC_SEGMENT_64.to_le_bytes());
    out.extend_from_slice(&(segment_cmd_size as u32).to_le_bytes());
    out.extend_from_slice(&[0u8; 16]); // segname
    out.extend_from_slice(&0u64.to_le_bytes()); // vmaddr
    out.extend_from_slice(&0u64.to_le_bytes()); // vmsize
    out.extend_from_slice(&0u64.to_le_bytes()); // fileoff
    out.extend_from_slice(&0u64.to_le_bytes()); // filesize
    out.extend_from_slice(&0u32.to_le_bytes()); // maxprot
    out.extend_from_slice(&0u32.to_le_bytes()); // initprot
    out.extend_from_slice(&(section_count as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // flags

    for (idx, section) in object.sections.iter().enumerate() {
        let (segname, sectname) = macho_segment_and_section_name_for_section(section, idx);
        out.extend_from_slice(&encode_macho_name_16(&sectname));
        out.extend_from_slice(&encode_macho_name_16(&segname));
        out.extend_from_slice(&0u64.to_le_bytes()); // addr
        out.extend_from_slice(&(section.size_bytes as u64).to_le_bytes());
        out.extend_from_slice(&section_data_offsets[idx].to_le_bytes());
        out.extend_from_slice(&(macho_section_align_pow2(section) as u32).to_le_bytes());
        out.extend_from_slice(&section_reloc_offsets[idx].to_le_bytes());
        out.extend_from_slice(&section_reloc_counts[idx].to_le_bytes());
        out.extend_from_slice(&macho_section_flags(section).to_le_bytes());
        out.extend_from_slice(&0u32.to_le_bytes()); // reserved1
        out.extend_from_slice(&0u32.to_le_bytes()); // reserved2
        out.extend_from_slice(&0u32.to_le_bytes()); // reserved3
    }

    out.extend_from_slice(&MACHO_LC_SYMTAB.to_le_bytes());
    out.extend_from_slice(&(symtab_cmd_size as u32).to_le_bytes());
    out.extend_from_slice(&symoff.to_le_bytes());
    out.extend_from_slice(&nsyms.to_le_bytes());
    out.extend_from_slice(&stroff.to_le_bytes());
    out.extend_from_slice(&strsize.to_le_bytes());

    for payload in &section_payloads {
        out.extend_from_slice(payload);
    }
    for blob in &section_reloc_blobs {
        out.extend_from_slice(blob);
    }
    out.extend_from_slice(&nlist_blob);
    out.extend_from_slice(&strtab);
    Ok(out)
}

pub fn emit_module_wasm32(module: &BackendModuleIR) -> Result<Vec<u8>, String> {
    if module.target_spec.lane() != BackendLaneIR::Portable
        || module.target_spec.object_format != BackendObjectFormatIR::WasmModule
    {
        return Err(
            "portable wasm emission requires lane 'portable' with object format 'wasm-module'"
                .to_string(),
        );
    }

    let functions = module
        .units
        .iter()
        .filter_map(|unit| match unit {
            BackendUnitIR::Function(func) => Some(func.symbol.clone()),
            _ => None,
        })
        .collect::<Vec<_>>();

    if functions.is_empty() {
        return Err(
            "portable wasm emission requires at least one lowered function unit".to_string(),
        );
    }

    let start_symbol = functions
        .iter()
        .find(|name| name.ends_with(".main") || *name == "root.main")
        .cloned()
        .unwrap_or_else(|| functions[0].clone());
    let start_index = functions
        .iter()
        .position(|name| *name == start_symbol)
        .ok_or("portable wasm emission could not resolve start symbol index")?;

    let mut out = Vec::new();
    out.extend_from_slice(&[0x00, 0x61, 0x73, 0x6D]); // \0asm
    out.extend_from_slice(&[0x01, 0x00, 0x00, 0x00]); // version 1

    let mut type_payload = Vec::new();
    encode_wasm_uleb_u32(1, &mut type_payload);
    type_payload.push(0x60);
    encode_wasm_uleb_u32(0, &mut type_payload);
    encode_wasm_uleb_u32(0, &mut type_payload);
    append_wasm_section(1, &type_payload, &mut out);

    let mut function_payload = Vec::new();
    encode_wasm_uleb_u32(functions.len() as u32, &mut function_payload);
    for _ in &functions {
        encode_wasm_uleb_u32(0, &mut function_payload);
    }
    append_wasm_section(3, &function_payload, &mut out);

    let mut export_payload = Vec::new();
    encode_wasm_uleb_u32((functions.len() + 1) as u32, &mut export_payload);
    encode_wasm_name("_start", &mut export_payload);
    export_payload.push(0x00);
    encode_wasm_uleb_u32(start_index as u32, &mut export_payload);
    for (index, symbol) in functions.iter().enumerate() {
        encode_wasm_name(symbol, &mut export_payload);
        export_payload.push(0x00);
        encode_wasm_uleb_u32(index as u32, &mut export_payload);
    }
    append_wasm_section(7, &export_payload, &mut out);

    let mut code_payload = Vec::new();
    encode_wasm_uleb_u32(functions.len() as u32, &mut code_payload);
    for _ in &functions {
        let mut body = Vec::new();
        encode_wasm_uleb_u32(0, &mut body);
        body.push(0x0B);
        encode_wasm_uleb_u32(body.len() as u32, &mut code_payload);
        code_payload.extend_from_slice(&body);
    }
    append_wasm_section(10, &code_payload, &mut out);

    Ok(out)
}

pub fn emit_image_sovereign(object: &BackendObjectIR) -> Result<Vec<u8>, String> {
    if object.target_spec.lane() != BackendLaneIR::Sovereign
        || object.target_spec.object_format != BackendObjectFormatIR::FreestandingImage
    {
        return Err(
            "sovereign image emission requires lane 'sovereign' with object format 'freestanding-image'"
                .to_string(),
        );
    }

    let unresolved = object.unresolved_symbols();
    if !unresolved.is_empty()
        && object
            .target_spec
            .linking_contract()
            .unresolved_symbol_policy
            == BackendUnresolvedSymbolPolicyIR::RejectUnresolvedAtBackendStage
    {
        return Err(format!(
            "symbol unresolved at backend stage: {}",
            unresolved.join(", ")
        ));
    }

    let mut out = Vec::new();
    out.extend_from_slice(b"NCSOVIMG");
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&(object.target_spec.pointer_width as u16).to_le_bytes());
    out.extend_from_slice(&(object.sections.len() as u32).to_le_bytes());
    out.extend_from_slice(&(object.symbols.len() as u32).to_le_bytes());
    out.extend_from_slice(&(object.relocations.len() as u32).to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // reserved

    for section in &object.sections {
        let payload = section.bytes.clone().unwrap_or_else(|| {
            if section.lines.is_empty() {
                Vec::new()
            } else {
                section.lines.join("\n").into_bytes()
            }
        });
        push_len_prefixed_string(&mut out, &section.name);
        out.push(sovereign_section_kind_tag(&section.kind));
        push_len_prefixed_string(&mut out, &section.unit);
        out.extend_from_slice(&(section.lines.len() as u32).to_le_bytes());
        out.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        out.extend_from_slice(&payload);
    }

    for symbol in &object.symbols {
        push_len_prefixed_string(&mut out, &symbol.name);
        push_len_prefixed_string(&mut out, &symbol.section);
        out.extend_from_slice(&(symbol.offset as u32).to_le_bytes());
        out.push(sovereign_visibility_tag(&symbol.visibility));
    }

    for reloc in &object.relocations {
        push_len_prefixed_string(&mut out, &reloc.section);
        out.extend_from_slice(&(reloc.offset as u32).to_le_bytes());
        out.push(sovereign_reloc_kind_tag(&reloc.kind));
        push_len_prefixed_string(&mut out, &reloc.symbol);
        out.extend_from_slice(&(reloc.addend as i64).to_le_bytes());
    }

    Ok(out)
}

pub fn link_image_sovereign(
    object: &BackendObjectIR,
    entry_symbol_override: Option<&str>,
) -> Result<Vec<u8>, String> {
    if object.target_spec.lane() != BackendLaneIR::Sovereign
        || object.target_spec.object_format != BackendObjectFormatIR::FreestandingImage
    {
        return Err(
            "sovereign link execution requires lane 'sovereign' with object format 'freestanding-image'"
                .to_string(),
        );
    }

    let unresolved = object.unresolved_symbols();
    if !unresolved.is_empty()
        && object
            .target_spec
            .linking_contract()
            .unresolved_symbol_policy
            == BackendUnresolvedSymbolPolicyIR::RejectUnresolvedAtBackendStage
    {
        return Err(format!(
            "symbol unresolved at backend stage: {}",
            unresolved.join(", ")
        ));
    }

    const SOVEREIGN_IMAGE_BASE: u64 = 0x0010_0000;
    const SOVEREIGN_SECTION_ALIGN: u64 = 16;

    #[derive(Clone)]
    struct LinkedSection {
        name: String,
        kind: BackendObjectSectionKindIR,
        vaddr: u64,
        payload: Vec<u8>,
    }

    #[derive(Clone)]
    struct LinkedSymbol {
        section_index: usize,
        addr: u64,
        visibility: BackendSymbolVisibilityIR,
    }

    let mut linked_sections: Vec<LinkedSection> = Vec::with_capacity(object.sections.len());
    let mut section_index_by_name: HashMap<String, usize> = HashMap::new();
    let mut next_vaddr = SOVEREIGN_IMAGE_BASE;

    for section in &object.sections {
        let has_relocs = object
            .relocations
            .iter()
            .any(|rel| rel.section == section.name);
        if section.bytes.is_none() && has_relocs {
            return Err(format!(
                "sovereign linker requires materialized native bytes for section '{}' with relocations",
                section.name
            ));
        }
        let payload = section.bytes.clone().unwrap_or_else(|| {
            if section.lines.is_empty() {
                Vec::new()
            } else {
                section.lines.join("\n").into_bytes()
            }
        });
        next_vaddr = align_u64(next_vaddr, SOVEREIGN_SECTION_ALIGN);
        let idx = linked_sections.len();
        section_index_by_name.insert(section.name.clone(), idx);
        linked_sections.push(LinkedSection {
            name: section.name.clone(),
            kind: section.kind.clone(),
            vaddr: next_vaddr,
            payload,
        });
        next_vaddr = next_vaddr.saturating_add(linked_sections[idx].payload.len() as u64);
    }

    let mut symbols_by_name: HashMap<String, LinkedSymbol> = HashMap::new();
    for symbol in &object.symbols {
        let Some(section_index) = section_index_by_name.get(&symbol.section).copied() else {
            return Err(format!(
                "symbol '{}' points to unknown section '{}'",
                symbol.name, symbol.section
            ));
        };
        let section = &linked_sections[section_index];
        if symbol.offset > section.payload.len() {
            return Err(format!(
                "symbol '{}' offset {} exceeds section '{}' payload size {}",
                symbol.name,
                symbol.offset,
                section.name,
                section.payload.len()
            ));
        }
        let addr = section.vaddr + symbol.offset as u64;
        let previous = symbols_by_name.insert(
            symbol.name.clone(),
            LinkedSymbol {
                section_index,
                addr,
                visibility: symbol.visibility.clone(),
            },
        );
        if previous.is_some() {
            return Err(format!(
                "duplicate symbol '{}' is not allowed in sovereign internal linker",
                symbol.name
            ));
        }
    }

    for reloc in &object.relocations {
        let Some(section_index) = section_index_by_name.get(&reloc.section).copied() else {
            return Err(format!(
                "relocation target section '{}' is missing for sovereign link",
                reloc.section
            ));
        };
        let Some(symbol) = symbols_by_name.get(&reloc.symbol) else {
            return Err(format!(
                "symbol unresolved at backend stage: {}",
                reloc.symbol
            ));
        };
        let section_vaddr = linked_sections[section_index].vaddr;
        let payload = &mut linked_sections[section_index].payload;
        match reloc.kind {
            BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32
            | BackendObjectRelocationKindIR::PcRel32 => {
                if reloc.offset + 4 > payload.len() {
                    return Err(format!(
                        "relocation offset out of range for section '{}': need 4 bytes at {} but size is {}",
                        reloc.section,
                        reloc.offset,
                        payload.len()
                    ));
                }
                let place = section_vaddr
                    .checked_add(reloc.offset as u64)
                    .ok_or("sovereign relocation place address overflow")?;
                let disp = (symbol.addr as i128) + (reloc.addend as i128) - (place as i128);
                if disp < i32::MIN as i128 || disp > i32::MAX as i128 {
                    return Err(format!(
                        "relocation displacement out of range for symbol '{}'",
                        reloc.symbol
                    ));
                }
                payload[reloc.offset..reloc.offset + 4]
                    .copy_from_slice(&(disp as i32).to_le_bytes());
            }
            BackendObjectRelocationKindIR::Abs32 => {
                if reloc.offset + 4 > payload.len() {
                    return Err(format!(
                        "relocation offset out of range for section '{}': need 4 bytes at {} but size is {}",
                        reloc.section,
                        reloc.offset,
                        payload.len()
                    ));
                }
                let abs = (symbol.addr as i128) + (reloc.addend as i128);
                if abs < 0 || abs > u32::MAX as i128 {
                    return Err(format!(
                        "absolute 32-bit relocation out of range for symbol '{}'",
                        reloc.symbol
                    ));
                }
                payload[reloc.offset..reloc.offset + 4]
                    .copy_from_slice(&(abs as u32).to_le_bytes());
            }
            BackendObjectRelocationKindIR::Abs64 => {
                if reloc.offset + 8 > payload.len() {
                    return Err(format!(
                        "relocation offset out of range for section '{}': need 8 bytes at {} but size is {}",
                        reloc.section,
                        reloc.offset,
                        payload.len()
                    ));
                }
                let abs = (symbol.addr as i128) + (reloc.addend as i128);
                if abs < 0 || abs > u64::MAX as i128 {
                    return Err(format!(
                        "absolute relocation out of range for symbol '{}'",
                        reloc.symbol
                    ));
                }
                payload[reloc.offset..reloc.offset + 8]
                    .copy_from_slice(&(abs as u64).to_le_bytes());
            }
        }
    }

    let entry_symbol_name = select_sovereign_entry_symbol(object, entry_symbol_override)?;
    let Some(entry_symbol) = symbols_by_name.get(&entry_symbol_name) else {
        return Err(format!(
            "sovereign entry symbol '{}' not found in linked object symbol table",
            entry_symbol_name
        ));
    };

    let mut out = Vec::new();
    out.extend_from_slice(b"NCSOVLNK");
    out.extend_from_slice(&1u16.to_le_bytes());
    out.extend_from_slice(&(object.target_spec.pointer_width as u16).to_le_bytes());
    out.extend_from_slice(&(linked_sections.len() as u32).to_le_bytes());
    out.extend_from_slice(&(symbols_by_name.len() as u32).to_le_bytes());
    out.extend_from_slice(&(object.relocations.len() as u32).to_le_bytes());
    out.extend_from_slice(&entry_symbol.addr.to_le_bytes());
    out.extend_from_slice(&SOVEREIGN_IMAGE_BASE.to_le_bytes());
    out.extend_from_slice(&0u64.to_le_bytes()); // image_size (patched at end)

    for section in &linked_sections {
        push_len_prefixed_string(&mut out, &section.name);
        out.push(sovereign_section_kind_tag(&section.kind));
        out.extend_from_slice(&section.vaddr.to_le_bytes());
        out.extend_from_slice(&(section.payload.len() as u32).to_le_bytes());
        out.extend_from_slice(&section.payload);
    }

    let mut symbol_rows = symbols_by_name
        .iter()
        .map(|(name, sym)| (name.clone(), sym.clone()))
        .collect::<Vec<_>>();
    symbol_rows.sort_by(|a, b| a.0.cmp(&b.0));
    for (name, symbol) in symbol_rows {
        push_len_prefixed_string(&mut out, &name);
        out.extend_from_slice(&symbol.addr.to_le_bytes());
        out.push(sovereign_visibility_tag(&symbol.visibility));
        out.extend_from_slice(&(symbol.section_index as u32).to_le_bytes());
    }

    let image_size = out.len() as u64;
    put_u64(&mut out[40..48], image_size);
    Ok(out)
}

fn append_wasm_section(section_id: u8, payload: &[u8], out: &mut Vec<u8>) {
    out.push(section_id);
    encode_wasm_uleb_u32(payload.len() as u32, out);
    out.extend_from_slice(payload);
}

fn encode_wasm_name(name: &str, out: &mut Vec<u8>) {
    encode_wasm_uleb_u32(name.len() as u32, out);
    out.extend_from_slice(name.as_bytes());
}

fn encode_wasm_uleb_u32(mut value: u32, out: &mut Vec<u8>) {
    loop {
        let mut byte = (value & 0x7f) as u8;
        value >>= 7;
        if value != 0 {
            byte |= 0x80;
        }
        out.push(byte);
        if value == 0 {
            break;
        }
    }
}

fn select_sovereign_entry_symbol(
    object: &BackendObjectIR,
    entry_symbol_override: Option<&str>,
) -> Result<String, String> {
    if let Some(entry) = entry_symbol_override {
        if object.symbols.iter().any(|symbol| symbol.name == entry) {
            return Ok(entry.to_string());
        }
        return Err(format!(
            "sovereign entry symbol '{}' not found in linked object symbol table",
            entry
        ));
    }

    let globals = object
        .symbols
        .iter()
        .filter(|symbol| symbol.visibility.is_externally_visible())
        .collect::<Vec<_>>();
    let entry_globals = globals
        .iter()
        .copied()
        .filter(|symbol| !is_stc_init_symbol(symbol.name.as_str()))
        .collect::<Vec<_>>();
    if let Some(sym) = entry_globals
        .iter()
        .copied()
        .find(|symbol| symbol.name == "root.main")
    {
        return Ok(sym.name.clone());
    }
    if let Some(sym) = entry_globals
        .iter()
        .copied()
        .find(|symbol| symbol.name.ends_with(".main"))
    {
        return Ok(sym.name.clone());
    }
    if let Some(sym) = entry_globals.first() {
        return Ok(sym.name.clone());
    }
    if let Some(sym) = object
        .symbols
        .iter()
        .find(|symbol| !is_stc_init_symbol(symbol.name.as_str()))
    {
        return Ok(sym.name.clone());
    }
    if let Some(sym) = object.symbols.first() {
        return Ok(sym.name.clone());
    }

    Err("sovereign link could not resolve default entry symbol; use --entry <symbol>".to_string())
}

fn is_stc_init_symbol(name: &str) -> bool {
    name.starts_with("__ncc_stc_init.")
}

fn push_len_prefixed_string(out: &mut Vec<u8>, value: &str) {
    out.extend_from_slice(&(value.len() as u32).to_le_bytes());
    out.extend_from_slice(value.as_bytes());
}

fn sovereign_section_kind_tag(kind: &BackendObjectSectionKindIR) -> u8 {
    match kind {
        BackendObjectSectionKindIR::Text => 1,
        BackendObjectSectionKindIR::Machine => 2,
        BackendObjectSectionKindIR::PrimitiveMeta => 3,
        BackendObjectSectionKindIR::TypeMeta => 4,
        BackendObjectSectionKindIR::ReadOnlyData => 5,
        BackendObjectSectionKindIR::Data => 6,
        BackendObjectSectionKindIR::Bss => 7,
        BackendObjectSectionKindIR::TlsData => 8,
        BackendObjectSectionKindIR::TlsBss => 9,
        BackendObjectSectionKindIR::PerCpuData => 10,
        BackendObjectSectionKindIR::PerCpuBss => 11,
        BackendObjectSectionKindIR::InitArray => 12,
        BackendObjectSectionKindIR::FiniArray => 13,
    }
}

fn sovereign_visibility_tag(visibility: &BackendSymbolVisibilityIR) -> u8 {
    match visibility {
        BackendSymbolVisibilityIR::Local => 0,
        BackendSymbolVisibilityIR::Global => 1,
        BackendSymbolVisibilityIR::Weak => 2,
        BackendSymbolVisibilityIR::Common => 3,
        BackendSymbolVisibilityIR::LinkOnceOdr => 4,
    }
}

fn sovereign_reloc_kind_tag(kind: &BackendObjectRelocationKindIR) -> u8 {
    match kind {
        BackendObjectRelocationKindIR::CallNear32 => 1,
        BackendObjectRelocationKindIR::JumpNear32 => 2,
        BackendObjectRelocationKindIR::PcRel32 => 4,
        BackendObjectRelocationKindIR::Abs32 => 5,
        BackendObjectRelocationKindIR::Abs64 => 3,
    }
}

#[derive(Debug, Clone)]
struct ElfSectionSpec {
    name: String,
    sh_type: u32,
    sh_flags: u64,
    data: Vec<u8>,
    virtual_size: u64,
    sh_link: u32,
    sh_info: u32,
    sh_addralign: u64,
    sh_entsize: u64,
}

#[derive(Debug, Clone)]
struct ElfSymbolRow {
    name: String,
    bind: u8,
    ty: u8,
    shndx: u16,
    value: u64,
    size: u64,
}

fn build_elf_string_table<'a, I>(names: I) -> (Vec<u8>, HashMap<String, u32>)
where
    I: Iterator<Item = &'a str>,
{
    let mut out = vec![0u8];
    let mut offs = HashMap::new();
    offs.insert(String::new(), 0u32);
    for name in names {
        if offs.contains_key(name) {
            continue;
        }
        let off = out.len() as u32;
        out.extend_from_slice(name.as_bytes());
        out.push(0);
        offs.insert(name.to_string(), off);
    }
    (out, offs)
}

fn elf_symbol_type_for_section_name(section: &str) -> u8 {
    if section == ".text"
        || section.starts_with(".text.")
        || section == ".machine"
        || section.starts_with(".machine.")
    {
        ELF_STT_FUNC
    } else {
        ELF_STT_OBJECT
    }
}

fn align_u64(value: u64, align: u64) -> u64 {
    if align == 0 {
        return value;
    }
    let rem = value % align;
    if rem == 0 {
        value
    } else {
        value + (align - rem)
    }
}

fn put_u16(dst: &mut [u8], value: u16) {
    dst.copy_from_slice(&value.to_le_bytes());
}

fn put_u32(dst: &mut [u8], value: u32) {
    dst.copy_from_slice(&value.to_le_bytes());
}

fn put_u64(dst: &mut [u8], value: u64) {
    dst.copy_from_slice(&value.to_le_bytes());
}

fn materialize_object_section_payload(section: &BackendObjectSectionIR) -> Result<Vec<u8>, String> {
    if matches!(
        section.kind,
        BackendObjectSectionKindIR::Bss
            | BackendObjectSectionKindIR::TlsBss
            | BackendObjectSectionKindIR::PerCpuBss
    ) {
        return Ok(Vec::new());
    }
    if let Some(bytes) = &section.bytes {
        return Ok(bytes.clone());
    }
    if matches!(
        section.kind,
        BackendObjectSectionKindIR::Text | BackendObjectSectionKindIR::Machine
    ) {
        return Err(format!(
            "executable section '{}' for unit '{}' has no native bytes; refusing to materialize backend text as machine code",
            section.name, section.unit
        ));
    }
    if section.lines.is_empty() {
        Ok(Vec::new())
    } else {
        Ok(section.lines.join("\n").into_bytes())
    }
}

fn object_section_align_bytes(section: &BackendObjectSectionIR) -> usize {
    section.align_bytes.max(1)
}

fn coff_symbol_type_for_section_name(section: &str) -> u16 {
    if section.starts_with(".text.") || section.starts_with(".machine.") {
        COFF_SYMBOL_TYPE_FUNCTION
    } else {
        0
    }
}

fn coff_relocation_type_for_target_and_kind(
    target: &BackendTargetIR,
    kind: &BackendObjectRelocationKindIR,
) -> u16 {
    match target {
        BackendTargetIR::X86_64 => match kind {
            BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32
            | BackendObjectRelocationKindIR::PcRel32 => COFF_REL_AMD64_REL32,
            BackendObjectRelocationKindIR::Abs32 => COFF_REL_AMD64_ADDR32,
            BackendObjectRelocationKindIR::Abs64 => COFF_REL_AMD64_ADDR64,
        },
        BackendTargetIR::AArch64 => match kind {
            BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32 => COFF_REL_ARM64_BRANCH26,
            BackendObjectRelocationKindIR::Abs32 => COFF_REL_ARM64_ADDR32,
            BackendObjectRelocationKindIR::PcRel32 | BackendObjectRelocationKindIR::Abs64 => {
                COFF_REL_ARM64_ADDR64
            }
        },
        BackendTargetIR::Wasm32 => 0,
    }
}

fn coff_section_characteristics(section: &BackendObjectSectionIR) -> u32 {
    let base = match &section.kind {
        BackendObjectSectionKindIR::Text | BackendObjectSectionKindIR::Machine => {
            COFF_SCN_CNT_CODE | COFF_SCN_MEM_EXECUTE | COFF_SCN_MEM_READ
        }
        BackendObjectSectionKindIR::ReadOnlyData
        | BackendObjectSectionKindIR::PrimitiveMeta
        | BackendObjectSectionKindIR::TypeMeta => COFF_SCN_CNT_INITIALIZED_DATA | COFF_SCN_MEM_READ,
        BackendObjectSectionKindIR::Data
        | BackendObjectSectionKindIR::TlsData
        | BackendObjectSectionKindIR::PerCpuData
        | BackendObjectSectionKindIR::InitArray
        | BackendObjectSectionKindIR::FiniArray => {
            COFF_SCN_CNT_INITIALIZED_DATA | COFF_SCN_MEM_READ | COFF_SCN_MEM_WRITE
        }
        BackendObjectSectionKindIR::Bss
        | BackendObjectSectionKindIR::TlsBss
        | BackendObjectSectionKindIR::PerCpuBss => {
            COFF_SCN_CNT_UNINITIALIZED_DATA | COFF_SCN_MEM_READ | COFF_SCN_MEM_WRITE
        }
    };
    let align = section.align_bytes.max(1).next_power_of_two().min(8192);
    let align_bits = ((align.trailing_zeros() + 1) as u32) << 20;
    base | align_bits
        | if section.comdat.is_some() {
            COFF_SCN_LNK_COMDAT
        } else {
            0
        }
}

fn encode_coff_name_field(
    name: &str,
    offsets: &mut HashMap<String, u32>,
    tail: &mut Vec<u8>,
) -> [u8; 8] {
    let mut raw = [0u8; 8];
    if name.len() <= 8 {
        raw[..name.len()].copy_from_slice(name.as_bytes());
        return raw;
    }

    let offset = if let Some(existing) = offsets.get(name).copied() {
        existing
    } else {
        let off = (4 + tail.len()) as u32;
        tail.extend_from_slice(name.as_bytes());
        tail.push(0);
        offsets.insert(name.to_string(), off);
        off
    };
    let encoded = format!("/{}", offset);
    let bytes = encoded.as_bytes();
    let len = bytes.len().min(8);
    raw[..len].copy_from_slice(&bytes[..len]);
    raw
}

fn encode_coff_symbol_name_field(
    name: &str,
    offsets: &mut HashMap<String, u32>,
    tail: &mut Vec<u8>,
) -> [u8; 8] {
    let mut raw = [0u8; 8];
    if name.len() <= 8 {
        raw[..name.len()].copy_from_slice(name.as_bytes());
        return raw;
    }

    let offset = if let Some(existing) = offsets.get(name).copied() {
        existing
    } else {
        let off = (4 + tail.len()) as u32;
        tail.extend_from_slice(name.as_bytes());
        tail.push(0);
        offsets.insert(name.to_string(), off);
        off
    };
    raw[4..8].copy_from_slice(&offset.to_le_bytes());
    raw
}

fn encode_macho_name_16(name: &str) -> [u8; 16] {
    let mut raw = [0u8; 16];
    let bytes = name.as_bytes();
    let len = bytes.len().min(16);
    raw[..len].copy_from_slice(&bytes[..len]);
    raw
}

fn macho_segment_and_section_name_for_section(
    section: &BackendObjectSectionIR,
    index: usize,
) -> (String, String) {
    if let Some((segment, name)) = section.name.split_once(',') {
        return (segment.trim().to_string(), name.trim().to_string());
    }
    match &section.kind {
        BackendObjectSectionKindIR::Text | BackendObjectSectionKindIR::Machine => {
            if index == 0 {
                ("__TEXT".to_string(), "__text".to_string())
            } else {
                ("__TEXT".to_string(), format!("__text{}", index))
            }
        }
        BackendObjectSectionKindIR::ReadOnlyData => {
            ("__TEXT".to_string(), format!("__const{}", index))
        }
        BackendObjectSectionKindIR::Data => ("__DATA".to_string(), format!("__data{}", index)),
        BackendObjectSectionKindIR::Bss => ("__DATA".to_string(), format!("__bss{}", index)),
        BackendObjectSectionKindIR::TlsData => {
            ("__DATA".to_string(), format!("__thread_data{}", index))
        }
        BackendObjectSectionKindIR::TlsBss => {
            ("__DATA".to_string(), format!("__thread_bss{}", index))
        }
        BackendObjectSectionKindIR::PerCpuData => {
            ("__DATA".to_string(), format!("__percpu{}", index))
        }
        BackendObjectSectionKindIR::PerCpuBss => {
            ("__DATA".to_string(), format!("__percpu_bss{}", index))
        }
        BackendObjectSectionKindIR::InitArray => {
            ("__DATA".to_string(), "__mod_init_func".to_string())
        }
        BackendObjectSectionKindIR::FiniArray => {
            ("__DATA".to_string(), "__mod_term_func".to_string())
        }
        BackendObjectSectionKindIR::PrimitiveMeta | BackendObjectSectionKindIR::TypeMeta => {
            if section.name == "__compact_unwind" {
                return ("__LD".to_string(), section.name.clone());
            }
            if section.name.starts_with("__debug_") {
                return ("__DWARF".to_string(), section.name.clone());
            }
            ("__DATA".to_string(), format!("__meta{}", index))
        }
    }
}

fn macho_section_flags(section: &BackendObjectSectionIR) -> u32 {
    if section.comdat.is_some() {
        return MACHO_SECTION_TYPE_COALESCED;
    }
    match &section.kind {
        BackendObjectSectionKindIR::Text | BackendObjectSectionKindIR::Machine => {
            MACHO_SECTION_TYPE_REGULAR | MACHO_SECTION_ATTR_SOME_INSTRUCTIONS
        }
        BackendObjectSectionKindIR::ReadOnlyData
        | BackendObjectSectionKindIR::PrimitiveMeta
        | BackendObjectSectionKindIR::TypeMeta => MACHO_SECTION_TYPE_REGULAR,
        BackendObjectSectionKindIR::Data | BackendObjectSectionKindIR::PerCpuData => {
            MACHO_SECTION_TYPE_REGULAR
        }
        BackendObjectSectionKindIR::TlsData => MACHO_SECTION_TYPE_THREAD_LOCAL_REGULAR,
        BackendObjectSectionKindIR::TlsBss => MACHO_SECTION_TYPE_THREAD_LOCAL_ZEROFILL,
        BackendObjectSectionKindIR::Bss | BackendObjectSectionKindIR::PerCpuBss => {
            MACHO_SECTION_TYPE_ZEROFILL
        }
        BackendObjectSectionKindIR::InitArray => MACHO_SECTION_TYPE_MOD_INIT_FUNC_POINTERS,
        BackendObjectSectionKindIR::FiniArray => MACHO_SECTION_TYPE_MOD_TERM_FUNC_POINTERS,
    }
}

fn macho_section_align_pow2(section: &BackendObjectSectionIR) -> u8 {
    section.align_bytes.max(1).trailing_zeros().min(31) as u8
}

fn macho_reloc_is_pcrel(kind: &BackendObjectRelocationKindIR) -> bool {
    matches!(
        kind,
        BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32
            | BackendObjectRelocationKindIR::PcRel32
    )
}

fn macho_reloc_length_pow2(kind: &BackendObjectRelocationKindIR) -> u8 {
    match kind {
        BackendObjectRelocationKindIR::CallNear32
        | BackendObjectRelocationKindIR::JumpNear32
        | BackendObjectRelocationKindIR::PcRel32 => 2,
        BackendObjectRelocationKindIR::Abs32 => 2,
        BackendObjectRelocationKindIR::Abs64 => 3,
    }
}

fn macho_reloc_type_for_target_and_kind(
    target: &BackendTargetIR,
    kind: &BackendObjectRelocationKindIR,
) -> u8 {
    match target {
        BackendTargetIR::X86_64 => match kind {
            BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32 => MACHO_X86_64_RELOC_BRANCH,
            BackendObjectRelocationKindIR::PcRel32 => MACHO_X86_64_RELOC_SIGNED,
            BackendObjectRelocationKindIR::Abs32 => MACHO_X86_64_RELOC_UNSIGNED,
            BackendObjectRelocationKindIR::Abs64 => MACHO_X86_64_RELOC_UNSIGNED,
        },
        BackendTargetIR::AArch64 => match kind {
            BackendObjectRelocationKindIR::CallNear32
            | BackendObjectRelocationKindIR::JumpNear32 => MACHO_ARM64_RELOC_BRANCH26,
            BackendObjectRelocationKindIR::PcRel32
            | BackendObjectRelocationKindIR::Abs32
            | BackendObjectRelocationKindIR::Abs64 => MACHO_ARM64_RELOC_UNSIGNED,
        },
        BackendTargetIR::Wasm32 => 0,
    }
}

fn encode_macho_relocation_info(
    symbol_index: u32,
    pcrel: bool,
    length_pow2: u8,
    extern_symbol: bool,
    reloc_type: u8,
) -> u32 {
    (symbol_index & 0x00ff_ffff)
        | ((if pcrel { 1 } else { 0 }) << 24)
        | (((length_pow2 as u32) & 0x3) << 25)
        | ((if extern_symbol { 1 } else { 0 }) << 27)
        | (((reloc_type as u32) & 0x0f) << 28)
}

fn macho_string_offset_for_name(
    name: &str,
    offsets: &mut HashMap<String, u32>,
    tail: &mut Vec<u8>,
) -> u32 {
    if let Some(existing) = offsets.get(name).copied() {
        return existing;
    }
    let off = (1 + tail.len()) as u32;
    tail.extend_from_slice(name.as_bytes());
    tail.push(0);
    offsets.insert(name.to_string(), off);
    off
}

