#[derive(Debug, Clone)]
struct BackendReadOnlyDataReloc {
    offset: usize,
    kind: BackendObjectRelocationKindIR,
    symbol: String,
    addend: isize,
}

#[derive(Debug, Clone)]
struct BackendReadOnlyDataEntry {
    symbol: String,
    line: String,
    bytes: Vec<u8>,
    relocs: Vec<BackendReadOnlyDataReloc>,
}

fn emit_stc_globals_object_unit(
    stc: &BackendStcGlobalsUnitIR,
    target: &BackendTargetIR,
    target_triple: &str,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
    relocations: &mut Vec<BackendObjectRelocationIR>,
) {
    emit_stc_init_wrapper_object_unit(stc, target, sections, symbols);

    for global in &stc.globals {
        let initialized = !matches!(global.init, BackendStcGlobalInitIR::Zero);
        let natural_align = stc_global_align_bytes(global);
        let plan = native_storage_section_plan(
            target_triple,
            &global.symbol,
            &global.storage,
            initialized,
            natural_align,
        )
        .unwrap_or_else(|error| panic!("invalid storage plan for '{}': {error}", global.symbol));
        let section_name = plan.name.clone();
        let section_kind =
            backend_section_kind_from_native(&plan.kind, plan.zero_fill, plan.writable);
        let object_comdat = plan.comdat_group.clone().or_else(|| {
            (plan.family == NativeSectionFamily::Coff
                && global.symbol_visibility == BackendSymbolVisibilityIR::Weak)
                .then(|| global.symbol.clone())
        });
        let mut lines = Vec::new();
        let mut bytes = Vec::new();

        symbols.push(BackendObjectSymbolIR {
            name: global.symbol.clone(),
            section: section_name.clone(),
            offset: 0,
            visibility: global.symbol_visibility.clone(),
        });

        match &global.init {
            BackendStcGlobalInitIR::Zero => {
                lines.push(format!(
                    "{}: ; static ty={} init=zero duration={:?}",
                    global.symbol, global.ty, global.storage.duration
                ));
                if !plan.zero_fill {
                    bytes.resize(global.storage_size_bytes.max(1), 0);
                }
            }
            BackendStcGlobalInitIR::Integer(value) => {
                lines.push(format!(
                    "{}: ; static ty={} init=int",
                    global.symbol, global.ty
                ));
                bytes.extend_from_slice(&stc_integer_storage_bytes(&global.ty, *value));
            }
            BackendStcGlobalInitIR::Bool(value) => {
                lines.push(format!(
                    "{}: ; static ty={} init=bool",
                    global.symbol, global.ty
                ));
                bytes.push(u8::from(*value));
            }
            BackendStcGlobalInitIR::StringLiteral(value) => {
                let literal = lower_text_literal_to_bytes(value);
                let bytes_symbol = format!("{}.__bytes", global.symbol);
                lines.push(format!(
                    "{}: ; static-str-slot ty={} bytes={} nul={} chars={}",
                    global.symbol,
                    global.ty,
                    literal.byte_len,
                    literal.nul_terminated_byte_len,
                    literal.scalar_count
                ));
                bytes.resize(global.storage_size_bytes.max(8), 0);
                relocations.push(BackendObjectRelocationIR {
                    section: section_name.clone(),
                    offset: 0,
                    kind: BackendObjectRelocationKindIR::Abs64,
                    symbol: bytes_symbol.clone(),
                    addend: 0,
                });
                emit_static_literal_section(
                    stc,
                    &bytes_symbol,
                    &literal.nul_terminated_bytes,
                    plan.comdat_group.clone(),
                    sections,
                    symbols,
                );
            }
            BackendStcGlobalInitIR::FixedArrayLiteral {
                elem_ty,
                len,
                bytes: literal_bytes,
            } => {
                lines.push(format!(
                    "{}: ; static ty={} init=fixed-array-literal elem={} len={} bytes={}",
                    global.symbol,
                    global.ty,
                    elem_ty,
                    len,
                    literal_bytes.len()
                ));
                bytes.extend_from_slice(literal_bytes);
                if global.storage_size_bytes > literal_bytes.len() {
                    bytes.resize(global.storage_size_bytes, 0);
                }
            }
            BackendStcGlobalInitIR::FixedStringArrayLiteral { len, values } => {
                let table_bytes = global.storage_size_bytes.max(len.saturating_mul(8)).max(1);
                lines.push(format!(
                    "{}: ; static-str-array ty={} slots={} table-bytes={}",
                    global.symbol, global.ty, len, table_bytes
                ));
                bytes.resize(table_bytes, 0);

                let mut literal_symbols = HashMap::<String, String>::new();
                for (index, value) in values.iter().enumerate() {
                    let bytes_symbol = if let Some(symbol) = literal_symbols.get(value) {
                        symbol.clone()
                    } else {
                        let literal = lower_text_literal_to_bytes(value);
                        let symbol = format!("{}.__str.{}", global.symbol, index);
                        emit_static_literal_section(
                            stc,
                            &symbol,
                            &literal.nul_terminated_bytes,
                            plan.comdat_group.clone(),
                            sections,
                            symbols,
                        );
                        literal_symbols.insert(value.clone(), symbol.clone());
                        symbol
                    };
                    relocations.push(BackendObjectRelocationIR {
                        section: section_name.clone(),
                        offset: index.saturating_mul(8),
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol: bytes_symbol.clone(),
                        addend: 0,
                    });
                }
            }
            BackendStcGlobalInitIR::DynamicArrayLiteral {
                elem_ty,
                items,
                bytes: literal_bytes,
            } => {
                let data_symbol = format!("{}.__data", global.symbol);
                lines.push(format!(
                    "{}: ; static ty={} init=dynamic-literal len={} cap={}",
                    global.symbol,
                    global.ty,
                    items.len(),
                    items.len()
                ));
                bytes.extend_from_slice(&0u64.to_le_bytes());
                if items.is_empty() {
                } else {
                    relocations.push(BackendObjectRelocationIR {
                        section: section_name.clone(),
                        offset: 0,
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol: data_symbol.clone(),
                        addend: 0,
                    });
                }
                bytes.extend_from_slice(&(items.len() as u64).to_le_bytes());
                bytes.extend_from_slice(&(items.len() as u64).to_le_bytes());

                if !items.is_empty() {
                    align_stc_data_bytes(&mut bytes, stc_dynamic_elem_align_bytes(elem_ty));
                    let data_offset = bytes.len();
                    symbols.push(BackendObjectSymbolIR {
                        name: data_symbol.clone(),
                        section: section_name.clone(),
                        offset: data_offset,
                        visibility: BackendSymbolVisibilityIR::Local,
                    });
                    lines.push(format!(
                        "{}: ; static-dynamic-data elem={} items={}",
                        data_symbol,
                        elem_ty,
                        items.len()
                    ));
                    bytes.extend_from_slice(literal_bytes);
                }
            }
        }

        let size_bytes = if plan.zero_fill {
            global.storage_size_bytes.max(1)
        } else {
            bytes.len().max(global.storage_size_bytes).max(1)
        };
        if !plan.zero_fill && bytes.len() < size_bytes {
            bytes.resize(size_bytes, 0);
        }
        sections.push(BackendObjectSectionIR {
            name: section_name,
            kind: section_kind,
            unit: stc.container.clone(),
            lines,
            bytes: (!plan.zero_fill).then_some(bytes),
            size_bytes,
            align_bytes: plan.align_bytes,
            comdat: object_comdat,
        });
    }
}

fn backend_section_kind_from_native(
    kind: &NativeSectionKind,
    zero_fill: bool,
    writable: bool,
) -> BackendObjectSectionKindIR {
    match kind {
        NativeSectionKind::Bss => BackendObjectSectionKindIR::Bss,
        NativeSectionKind::ReadOnlyData => BackendObjectSectionKindIR::ReadOnlyData,
        NativeSectionKind::TlsData => BackendObjectSectionKindIR::TlsData,
        NativeSectionKind::TlsBss => BackendObjectSectionKindIR::TlsBss,
        NativeSectionKind::PerCpuData => BackendObjectSectionKindIR::PerCpuData,
        NativeSectionKind::PerCpuBss => BackendObjectSectionKindIR::PerCpuBss,
        NativeSectionKind::InitArray => BackendObjectSectionKindIR::InitArray,
        NativeSectionKind::FiniArray => BackendObjectSectionKindIR::FiniArray,
        NativeSectionKind::Data => BackendObjectSectionKindIR::Data,
        NativeSectionKind::Custom if zero_fill => BackendObjectSectionKindIR::Bss,
        NativeSectionKind::Custom if !writable => BackendObjectSectionKindIR::ReadOnlyData,
        NativeSectionKind::Custom => BackendObjectSectionKindIR::Data,
    }
}

fn emit_static_literal_section(
    stc: &BackendStcGlobalsUnitIR,
    symbol: &str,
    bytes: &[u8],
    comdat: Option<String>,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
) {
    let section_name = format!(".rodata.{}", sanitize_backend_section_component(symbol));
    symbols.push(BackendObjectSymbolIR {
        name: symbol.to_string(),
        section: section_name.clone(),
        offset: 0,
        visibility: BackendSymbolVisibilityIR::Local,
    });
    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::ReadOnlyData,
        unit: stc.container.clone(),
        lines: vec![format!("{symbol}: ; static-literal bytes={}", bytes.len())],
        bytes: Some(bytes.to_vec()),
        size_bytes: bytes.len(),
        align_bytes: 1,
        comdat,
    });
}

fn sanitize_backend_section_component(symbol: &str) -> String {
    symbol
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn emit_stc_init_wrapper_object_unit(
    stc: &BackendStcGlobalsUnitIR,
    target: &BackendTargetIR,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
) {
    let section_name = format!(".text.{}", stc.init_symbol);
    symbols.push(BackendObjectSymbolIR {
        name: stc.init_symbol.clone(),
        section: section_name.clone(),
        offset: 0,
        visibility: BackendSymbolVisibilityIR::Global,
    });
    let mut lines = vec![format!("{}:", stc.init_symbol)];
    lines.push(format!(
        "    ; stc-init-wrapper globals={} unsupported_init={}",
        stc.globals.len(),
        stc.unsupported_init_count
    ));
    let bytes = match target {
        BackendTargetIR::X86_64 => {
            lines.push("    ret ; stc-init-static-data".to_string());
            Some(vec![0xC3])
        }
        BackendTargetIR::AArch64 => {
            lines.push("    ret ; stc-init-static-data".to_string());
            Some(encode_backend_aarch64_ret_bytes())
        }
        BackendTargetIR::Wasm32 => {
            lines.push(
                "    ret ; stc-init-static-data (native bytes pending for target)".to_string(),
            );
            None
        }
    };
    let size_bytes = bytes.as_ref().map_or(4, Vec::len);
    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::Text,
        unit: stc.container.clone(),
        lines,
        bytes,
        size_bytes,
        align_bytes: 16,
        comdat: None,
    });
}

fn stc_integer_storage_bytes(ty: &str, value: i64) -> Vec<u8> {
    match scalar_elem_size_from_type(ty) {
        1 => vec![value as u8],
        2 => (value as i16).to_le_bytes().to_vec(),
        4 => (value as i32).to_le_bytes().to_vec(),
        _ => value.to_le_bytes().to_vec(),
    }
}

fn align_stc_data_bytes(bytes: &mut Vec<u8>, align: usize) {
    let aligned = align_up(bytes.len(), align.max(1));
    if aligned > bytes.len() {
        bytes.resize(aligned, 0);
    }
}

fn stc_global_align_bytes(global: &BackendStcGlobalIR) -> usize {
    let compact = normalize_backend_type_name(&global.ty);
    if scalar_type_uses_native_fast_dynamic_descriptor(&compact)
        || compact == "str"
        || compact == "addr"
        || compact.starts_with("ptr<")
        || compact.starts_with("memRegion<")
        || global.storage_size_bytes >= 8
    {
        8
    } else if matches!(compact.as_str(), "bool" | "byte" | "char" | "i8" | "u8") {
        1
    } else if matches!(compact.as_str(), "short" | "i16" | "u16") {
        2
    } else {
        4
    }
}

fn stc_dynamic_elem_align_bytes(ty: &str) -> usize {
    let compact = normalize_backend_type_name(ty);
    if matches!(compact.as_str(), "bool" | "byte" | "char" | "i8" | "u8") {
        1
    } else if matches!(compact.as_str(), "short" | "i16" | "u16") {
        2
    } else if scalar_elem_size_from_type(&compact) >= 8 {
        8
    } else {
        4
    }
}

fn emit_function_object_unit(
    func: &BackendFunctionUnitIR,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
    relocations: &mut Vec<BackendObjectRelocationIR>,
) {
    let section_name = format!(".text.{}", func.symbol);
    let stack_reg =
        backend_stack_pointer_register_for_calling_convention(&func.plan.calling_convention);
    let frame_reg =
        backend_frame_pointer_register_for_calling_convention(&func.plan.calling_convention);
    let is_x86_64 = func.plan.target == BackendTargetIR::X86_64;
    let is_aarch64 = func.plan.target == BackendTargetIR::AArch64;
    let mut lines = vec![format!(
        "; lowering-coverage route={} materialized={}/{} complete={}",
        render_backend_function_lowering_route(func.lowering_coverage.route),
        func.lowering_coverage.materialized_statements,
        func.lowering_coverage.source_statements,
        func.lowering_coverage.is_complete()
    )];
    let mut native_bytes = Vec::new();
    let mut native_ok = func.lowering_coverage.is_complete();

    let mut fallback_offset = 0usize;
    let mut native_symbols = Vec::new();
    let mut fallback_symbols = Vec::new();
    let mut native_relocs = Vec::new();
    let mut fallback_relocs = Vec::new();
    let mut literal_symbol_by_value: HashMap<String, String> = HashMap::new();
    let mut closure_symbol_by_key: HashMap<String, String> = HashMap::new();
    let mut closure_stub_symbols = Vec::new();
    let mut rodata_entries: Vec<BackendReadOnlyDataEntry> = Vec::new();
    // Scalar call markers are typed ABI metadata and occupy no bytes. Resolve
    // labels over the complete scalar stream so control flow may cross them.
    let function_scalar_labels = if is_x86_64 {
        backend_function_scalar_label_offsets(func)
    } else {
        None
    };
    let mut scalar_stream_offset = 0usize;

    for op in &func.ops {
        match op {
            BackendFuncOpIR::Label(name) => {
                native_symbols.push(BackendObjectSymbolIR {
                    name: name.clone(),
                    section: section_name.clone(),
                    offset: native_bytes.len(),
                    visibility: if *name == func.symbol {
                        backend_function_symbol_visibility(func.visibility)
                    } else {
                        BackendSymbolVisibilityIR::Local
                    },
                });
                fallback_symbols.push(BackendObjectSymbolIR {
                    name: name.clone(),
                    section: section_name.clone(),
                    offset: fallback_offset,
                    visibility: if *name == func.symbol {
                        backend_function_symbol_visibility(func.visibility)
                    } else {
                        BackendSymbolVisibilityIR::Local
                    },
                });
                lines.push(format!("{name}:"));
            }
            BackendFuncOpIR::Call {
                target,
                arg_count,
                stack_arg_bytes,
            } => {
                let call_mnemonic = if is_x86_64 { "call" } else { "bl" };
                lines.push(format!(
                    "{} {} ; argc={} stack_args={}B",
                    call_mnemonic, target, arg_count, stack_arg_bytes
                ));
                let native_call_offset = if is_x86_64 {
                    native_bytes.len() + 1
                } else {
                    native_bytes.len()
                };
                let native_call_addend = if is_x86_64 { -4 } else { 0 };
                native_relocs.push(BackendObjectRelocationIR {
                    section: section_name.clone(),
                    offset: native_call_offset,
                    kind: BackendObjectRelocationKindIR::CallNear32,
                    symbol: target.clone(),
                    addend: native_call_addend,
                });
                let fallback_call_offset = if is_x86_64 {
                    fallback_offset + 1
                } else {
                    fallback_offset
                };
                let fallback_call_addend = if is_x86_64 { -4 } else { 0 };
                fallback_relocs.push(BackendObjectRelocationIR {
                    section: section_name.clone(),
                    offset: fallback_call_offset,
                    kind: BackendObjectRelocationKindIR::CallNear32,
                    symbol: target.clone(),
                    addend: fallback_call_addend,
                });
                if native_ok {
                    if is_x86_64 {
                        native_bytes.extend_from_slice(&[0xE8, 0x00, 0x00, 0x00, 0x00]);
                    } else if is_aarch64 {
                        encode_backend_aarch64_bl_placeholder(&mut native_bytes);
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += if is_x86_64 { 5 } else { 4 };
            }
            BackendFuncOpIR::ReturnImm { value } => {
                let return_reg = backend_return_register(&func.plan.calling_convention);
                lines.push(format!(
                    "mov {}, {} ; scalar-return",
                    render_backend_register(&return_reg),
                    value
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(dst) = backend_register_to_x86(&return_reg) {
                            encode_backend_mov_reg_imm(&mut native_bytes, dst, *value);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        if let Some(dst) = backend_register_to_aarch64(&return_reg) {
                            encode_backend_aarch64_mov_reg_imm(&mut native_bytes, dst, *value);
                        } else {
                            native_ok = false;
                        }
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += if is_x86_64 && i32::try_from(*value).is_ok() {
                    7
                } else if is_x86_64 {
                    10
                } else if is_aarch64 {
                    backend_aarch64_mov_imm_size(*value)
                } else {
                    4
                };
            }
            BackendFuncOpIR::SaveCallee(reg) => {
                lines.push(format!("push {}", render_backend_register(reg)));
                if native_ok && !encode_backend_push_reg(reg, &mut native_bytes) {
                    native_ok = false;
                }
                fallback_offset += if is_x86_64 { 1 } else { 4 };
            }
            BackendFuncOpIR::SetFramePointer => {
                lines.push(format!(
                    "mov {}, {} ; frame-pointer",
                    render_backend_register(&frame_reg),
                    render_backend_register(&stack_reg)
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(encoded) = encode_backend_mov_rbp_rsp() {
                            native_bytes.extend_from_slice(&encoded);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        encode_backend_aarch64_mov_x29_sp(&mut native_bytes);
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += if is_x86_64 { 3 } else { 4 };
            }
            BackendFuncOpIR::RestoreCallee(reg) => {
                lines.push(format!("pop {}", render_backend_register(reg)));
                if native_ok && !encode_backend_pop_reg(reg, &mut native_bytes) {
                    native_ok = false;
                }
                fallback_offset += if is_x86_64 { 1 } else { 4 };
            }
            BackendFuncOpIR::ReserveStack(bytes) => {
                lines.push(format!(
                    "sub {}, {}",
                    render_backend_register(&stack_reg),
                    bytes
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(encoded) = encode_backend_sub_rsp_imm32(*bytes) {
                            native_bytes.extend_from_slice(&encoded);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        if encode_backend_aarch64_stack_imm(&mut native_bytes, true, *bytes)
                            .is_none()
                        {
                            native_ok = false;
                        }
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += 4;
            }
            BackendFuncOpIR::ReserveCallStack(bytes) => {
                lines.push(format!(
                    "sub {}, {} ; call-stack",
                    render_backend_register(&stack_reg),
                    bytes
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(encoded) = encode_backend_sub_rsp_imm32(*bytes) {
                            native_bytes.extend_from_slice(&encoded);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        if encode_backend_aarch64_stack_imm(&mut native_bytes, true, *bytes)
                            .is_none()
                        {
                            native_ok = false;
                        }
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += 4;
            }
            BackendFuncOpIR::PrepareCallArg {
                index,
                pass_class,
                source,
                location,
                materialized,
            } => {
                lines.push(format!(
                    "; call-arg[{}] class={} src={} -> {}",
                    index,
                    render_abi_pass_class(pass_class),
                    render_function_call_arg_source(source),
                    render_call_arg_location(location)
                ));
                if native_ok && *materialized {
                    let start = native_bytes.len();
                    let encoded = encode_backend_prepare_call_arg_native(
                        func,
                        &section_name,
                        pass_class,
                        source,
                        location,
                        &mut native_bytes,
                        &mut native_relocs,
                        &mut literal_symbol_by_value,
                        &mut closure_symbol_by_key,
                        &mut closure_stub_symbols,
                        &mut rodata_entries,
                    );
                    if encoded.is_none() {
                        native_ok = false;
                    } else {
                        fallback_offset += native_bytes.len().saturating_sub(start);
                    }
                }
            }
            BackendFuncOpIR::ScalarOps { ops } => {
                for scalar_op in ops {
                    lines.push(render_backend_scalar_op_line(scalar_op));
                }
                let scalar_size = estimate_backend_scalar_ops_native_size(ops);
                if native_ok {
                    let start = native_bytes.len();
                    if function_scalar_labels
                        .as_ref()
                        .and_then(|labels| {
                            encode_backend_scalar_ops_native_with_labels(
                                ops,
                                labels,
                                scalar_stream_offset,
                                &section_name,
                                start,
                                &func.symbol,
                                &mut native_bytes,
                                &mut native_relocs,
                                &mut literal_symbol_by_value,
                                &mut rodata_entries,
                            )
                        })
                        .is_none()
                    {
                        native_ok = false;
                        fallback_offset += scalar_size;
                    } else {
                        fallback_offset += native_bytes.len().saturating_sub(start);
                    }
                } else {
                    fallback_offset += scalar_size;
                }
                scalar_stream_offset = scalar_stream_offset.saturating_add(scalar_size);
            }
            BackendFuncOpIR::ReleaseStack(bytes) => {
                lines.push(format!(
                    "add {}, {}",
                    render_backend_register(&stack_reg),
                    bytes
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(encoded) = encode_backend_add_rsp_imm32(*bytes) {
                            native_bytes.extend_from_slice(&encoded);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        if encode_backend_aarch64_stack_imm(&mut native_bytes, false, *bytes)
                            .is_none()
                        {
                            native_ok = false;
                        }
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += 4;
            }
            BackendFuncOpIR::ReleaseCallStack(bytes) => {
                lines.push(format!(
                    "add {}, {} ; call-stack",
                    render_backend_register(&stack_reg),
                    bytes
                ));
                if native_ok {
                    if is_x86_64 {
                        if let Some(encoded) = encode_backend_add_rsp_imm32(*bytes) {
                            native_bytes.extend_from_slice(&encoded);
                        } else {
                            native_ok = false;
                        }
                    } else if is_aarch64 {
                        if encode_backend_aarch64_stack_imm(&mut native_bytes, false, *bytes)
                            .is_none()
                        {
                            native_ok = false;
                        }
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += 4;
            }
            BackendFuncOpIR::BridgeEnter {
                kind,
                target_mode,
                scratch_bytes,
            } => {
                let target_mode = target_mode
                    .as_ref()
                    .map(render_abi_mode_class)
                    .unwrap_or("unknown");
                lines.push(format!(
                    "; bridge.enter kind={} target_mode={} scratch={}B",
                    render_backend_bridge_kind(kind),
                    target_mode,
                    scratch_bytes
                ));
            }
            BackendFuncOpIR::BridgeLeave { kind } => {
                lines.push(format!(
                    "; bridge.leave kind={}",
                    render_backend_bridge_kind(kind)
                ));
            }
            BackendFuncOpIR::Ret => {
                lines.push("ret".to_string());
                if native_ok {
                    if is_x86_64 {
                        native_bytes.push(0xC3);
                    } else if is_aarch64 {
                        encode_backend_aarch64_ret(&mut native_bytes);
                    } else {
                        native_ok = false;
                    }
                }
                fallback_offset += if is_x86_64 { 1 } else { 4 };
            }
        }
    }

    if native_ok {
        for symbol in &closure_stub_symbols {
            native_symbols.push(BackendObjectSymbolIR {
                name: symbol.clone(),
                section: section_name.clone(),
                offset: native_bytes.len(),
                visibility: BackendSymbolVisibilityIR::Local,
            });
            lines.push(format!("{symbol}: ; closure-value trap-stub"));
            native_bytes.extend_from_slice(&[0x0F, 0x0B, 0xC3]);
        }
    }

    let emit_rodata = native_ok && !rodata_entries.is_empty();
    let (final_symbols, final_relocs, bytes, size_bytes) = if native_ok {
        (
            native_symbols,
            native_relocs,
            Some(native_bytes.clone()),
            native_bytes.len(),
        )
    } else {
        (fallback_symbols, fallback_relocs, None, fallback_offset)
    };

    symbols.extend(final_symbols);
    relocations.extend(final_relocs);

    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::Text,
        unit: func.symbol.clone(),
        lines,
        bytes,
        size_bytes,
        align_bytes: 16,
        comdat: None,
    });

    if emit_rodata {
        emit_function_rodata_section(
            &func.symbol,
            &rodata_entries,
            sections,
            symbols,
            relocations,
        );
    }
}

fn render_backend_function_lowering_route(route: BackendFunctionLoweringRouteIR) -> &'static str {
    match route {
        BackendFunctionLoweringRouteIR::EmptyBody => "empty-body",
        BackendFunctionLoweringRouteIR::ImmediateReturn => "immediate-return",
        BackendFunctionLoweringRouteIR::ScalarRegStack => "scalar-reg-stack",
        BackendFunctionLoweringRouteIR::Deferred => "deferred",
    }
}

fn emit_function_rodata_section(
    function_symbol: &str,
    entries: &[BackendReadOnlyDataEntry],
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
    relocations: &mut Vec<BackendObjectRelocationIR>,
) {
    if entries.is_empty() {
        return;
    }

    let section_name = format!(".rodata.{function_symbol}");
    let mut lines = Vec::new();
    let mut bytes = Vec::new();

    for entry in entries {
        let offset = bytes.len();
        symbols.push(BackendObjectSymbolIR {
            name: entry.symbol.clone(),
            section: section_name.clone(),
            offset,
            visibility: BackendSymbolVisibilityIR::Local,
        });
        lines.push(entry.line.clone());
        for reloc in &entry.relocs {
            relocations.push(BackendObjectRelocationIR {
                section: section_name.clone(),
                offset: offset + reloc.offset,
                kind: reloc.kind.clone(),
                symbol: reloc.symbol.clone(),
                addend: reloc.addend,
            });
        }
        bytes.extend_from_slice(&entry.bytes);
    }

    let size_bytes = bytes.len();
    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::ReadOnlyData,
        unit: function_symbol.to_string(),
        lines,
        bytes: Some(bytes),
        size_bytes,
        align_bytes: 8,
        comdat: None,
    });
}

fn emit_machine_object_unit(
    machine: &BackendMachineUnitIR,
    target: &BackendTargetIR,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
    relocations: &mut Vec<BackendObjectRelocationIR>,
) {
    let section_name = format!(".machine.{}", machine.symbol);
    let mut lines = Vec::new();
    let mut fallback_symbols = Vec::new();
    let mut fallback_relocs = Vec::new();
    let mut fallback_offset = 0usize;

    for op in &machine.ops {
        match op {
            BackendMachineOpIR::Inst(inst) => match inst {
                MachineInstIR::Label { name } => {
                    fallback_symbols.push(BackendObjectSymbolIR {
                        name: format!("{}.{}", machine.symbol, name),
                        section: section_name.clone(),
                        offset: fallback_offset,
                        visibility: BackendSymbolVisibilityIR::Local,
                    });
                    lines.push(format!("{name}:"));
                }
                MachineInstIR::Call { target } => {
                    let rendered = render_machine_inst(inst);
                    lines.push(rendered);
                    fallback_relocs.push(BackendObjectRelocationIR {
                        section: section_name.clone(),
                        offset: fallback_offset + 1,
                        kind: BackendObjectRelocationKindIR::CallNear32,
                        symbol: resolve_machine_call_reloc_symbol(machine, target),
                        addend: -4,
                    });
                    fallback_offset += 5;
                }
                MachineInstIR::Jmp { target }
                | MachineInstIR::JmpEq { target }
                | MachineInstIR::JmpNe { target }
                | MachineInstIR::JmpGt { target }
                | MachineInstIR::JmpLt { target }
                | MachineInstIR::JmpGe { target }
                | MachineInstIR::JmpLe { target }
                | MachineInstIR::JmpOverflow { target } => {
                    lines.push(render_machine_inst(inst));
                    fallback_relocs.push(BackendObjectRelocationIR {
                        section: section_name.clone(),
                        offset: fallback_offset + 1,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                    fallback_offset += 5;
                }
                _ => {
                    lines.push(render_machine_inst(inst));
                    fallback_offset += 4;
                }
            },
            BackendMachineOpIR::Final(final_op) => {
                lines.push(render_machine_final_op(final_op));
                match final_op {
                    MachineFinalOpIR::Jmp { target } => {
                        fallback_relocs.push(BackendObjectRelocationIR {
                            section: section_name.clone(),
                            offset: fallback_offset + 1,
                            kind: BackendObjectRelocationKindIR::JumpNear32,
                            symbol: resolve_machine_label_reloc_symbol(machine, target),
                            addend: -4,
                        });
                        fallback_offset += 5;
                    }
                    MachineFinalOpIR::Ret | MachineFinalOpIR::Halt => {
                        fallback_offset += 1;
                    }
                }
            }
        }
    }

    if let Some((native_bytes, native_symbols, native_relocs)) =
        try_encode_machine_section(machine, target, &section_name)
    {
        symbols.extend(native_symbols);
        relocations.extend(native_relocs);
        sections.push(BackendObjectSectionIR {
            name: section_name,
            kind: BackendObjectSectionKindIR::Machine,
            unit: machine.symbol.clone(),
            lines,
            bytes: Some(native_bytes.clone()),
            size_bytes: native_bytes.len(),
            align_bytes: 16,
            comdat: None,
        });
    } else {
        symbols.extend(fallback_symbols);
        relocations.extend(fallback_relocs);
        sections.push(BackendObjectSectionIR {
            name: section_name,
            kind: BackendObjectSectionKindIR::Machine,
            unit: machine.symbol.clone(),
            lines,
            bytes: None,
            size_bytes: fallback_offset,
            align_bytes: 16,
            comdat: None,
        });
    }
}

fn try_encode_machine_section(
    machine: &BackendMachineUnitIR,
    target: &BackendTargetIR,
    section_name: &str,
) -> Option<(
    Vec<u8>,
    Vec<BackendObjectSymbolIR>,
    Vec<BackendObjectRelocationIR>,
)> {
    if *target != BackendTargetIR::X86_64 {
        return None;
    }

    let reg_map = build_machine_reg_map(&machine.regs)?;
    let mut bytes = Vec::new();
    let mut symbols = Vec::new();
    let mut relocs = Vec::new();

    for op in &machine.ops {
        match op {
            BackendMachineOpIR::Inst(inst) => match inst {
                MachineInstIR::Label { name } => {
                    symbols.push(BackendObjectSymbolIR {
                        name: format!("{}.{}", machine.symbol, name),
                        section: section_name.to_string(),
                        offset: bytes.len(),
                        visibility: BackendSymbolVisibilityIR::Local,
                    });
                }
                MachineInstIR::Call { target } => {
                    let call_offset = bytes.len();
                    bytes.extend_from_slice(&[0xE8, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: call_offset + 1,
                        kind: BackendObjectRelocationKindIR::CallNear32,
                        symbol: resolve_machine_call_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::Jmp { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0xE9, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 1,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpEq { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x84, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpNe { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x85, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpGt { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x8F, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpLt { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x8C, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpGe { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x8D, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpLe { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x8E, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineInstIR::JmpOverflow { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0x0F, 0x80, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 2,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                _ => encode_machine_inst_native(inst, &reg_map, &mut bytes)?,
            },
            BackendMachineOpIR::Final(final_op) => match final_op {
                MachineFinalOpIR::Jmp { target } => {
                    let jump_offset = bytes.len();
                    bytes.extend_from_slice(&[0xE9, 0x00, 0x00, 0x00, 0x00]);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: jump_offset + 1,
                        kind: BackendObjectRelocationKindIR::JumpNear32,
                        symbol: resolve_machine_label_reloc_symbol(machine, target),
                        addend: -4,
                    });
                }
                MachineFinalOpIR::Ret => bytes.push(0xC3),
                MachineFinalOpIR::Halt => bytes.push(0xF4),
            },
        }
    }

    Some((bytes, symbols, relocs))
}

fn encode_machine_inst_native(
    inst: &MachineInstIR,
    reg_map: &HashMap<String, u8>,
    out: &mut Vec<u8>,
) -> Option<()> {
    match inst {
        MachineInstIR::Load { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let mem = resolve_machine_mem_addr(src, reg_map)?;
            encode_reg_mem_mov_rm_to_reg(out, dst_reg, &mem)?;
            Some(())
        }
        MachineInstIR::Store { dst, src } => {
            let src_reg = *reg_map.get(src)?;
            let mem = resolve_machine_mem_addr(dst, reg_map)?;
            encode_reg_mem_mov_reg_to_rm(out, src_reg, &mem)?;
            Some(())
        }
        MachineInstIR::Lea { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let mem = resolve_machine_mem_addr(src, reg_map)?;
            encode_reg_mem_lea_to_reg(out, dst_reg, &mem)?;
            Some(())
        }
        MachineInstIR::Mov { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x89, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Cmp { left, right } => {
            let left_reg = *reg_map.get(left)?;
            let right_reg = *reg_map.get(right)?;
            encode_rr(out, 0x39, right_reg, left_reg);
            Some(())
        }
        MachineInstIR::Test { left, right } => {
            let left_reg = *reg_map.get(left)?;
            let right_reg = *reg_map.get(right)?;
            encode_rr(out, 0x85, right_reg, left_reg);
            Some(())
        }
        MachineInstIR::Bsf { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr_0f(out, 0xBC, dst_reg, src_reg);
            Some(())
        }
        MachineInstIR::Bsr { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr_0f(out, 0xBD, dst_reg, src_reg);
            Some(())
        }
        MachineInstIR::Add { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x01, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Sub { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x29, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Mul { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr_0f(out, 0xAF, dst_reg, src_reg);
            Some(())
        }
        MachineInstIR::Adc { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x11, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Sbb { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x19, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::And { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x21, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Or { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x09, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Xor { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x31, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::Shl { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            if src_reg == 1 {
                encode_shift_cl(out, 4, dst_reg);
                return Some(());
            }
            encode_shift_rotate_variable_count(out, reg_map, dst_reg, src_reg, 4)
        }
        MachineInstIR::Shr { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            if src_reg == 1 {
                encode_shift_cl(out, 5, dst_reg);
                return Some(());
            }
            encode_shift_rotate_variable_count(out, reg_map, dst_reg, src_reg, 5)
        }
        MachineInstIR::Sar { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            if src_reg == 1 {
                encode_shift_cl(out, 7, dst_reg);
                return Some(());
            }
            encode_shift_rotate_variable_count(out, reg_map, dst_reg, src_reg, 7)
        }
        MachineInstIR::Rol { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            if src_reg == 1 {
                encode_shift_cl(out, 0, dst_reg);
                return Some(());
            }
            encode_shift_rotate_variable_count(out, reg_map, dst_reg, src_reg, 0)
        }
        MachineInstIR::Ror { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            if src_reg == 1 {
                encode_shift_cl(out, 1, dst_reg);
                return Some(());
            }
            encode_shift_rotate_variable_count(out, reg_map, dst_reg, src_reg, 1)
        }
        MachineInstIR::Xchg { dst, src } => {
            let dst_reg = *reg_map.get(dst)?;
            let src_reg = *reg_map.get(src)?;
            encode_rr(out, 0x87, src_reg, dst_reg);
            Some(())
        }
        MachineInstIR::NotBin { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_group_ff_f7(out, 0xF7, 2, reg_num);
            Some(())
        }
        MachineInstIR::Bswap { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_bswap_reg(out, reg_num);
            Some(())
        }
        MachineInstIR::NegBin { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_group_ff_f7(out, 0xF7, 3, reg_num);
            Some(())
        }
        MachineInstIR::Inc { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_group_ff_f7(out, 0xFF, 0, reg_num);
            Some(())
        }
        MachineInstIR::Dec { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_group_ff_f7(out, 0xFF, 1, reg_num);
            Some(())
        }
        MachineInstIR::Push { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_push_reg_num(reg_num, out);
            Some(())
        }
        MachineInstIR::Pop { reg } => {
            let reg_num = *reg_map.get(reg)?;
            encode_pop_reg_num(reg_num, out);
            Some(())
        }
        MachineInstIR::VmxOn { region } => encode_machine_virtualization_mem(
            out,
            Some(0xF3),
            &[0x0F, 0xC7],
            6,
            &resolve_machine_mem_addr(region, reg_map)?,
        ),
        MachineInstIR::VmxOff => {
            out.extend_from_slice(&[0x0F, 0x01, 0xC4]);
            Some(())
        }
        MachineInstIR::VmClear { region } => encode_machine_virtualization_mem(
            out,
            Some(0x66),
            &[0x0F, 0xC7],
            6,
            &resolve_machine_mem_addr(region, reg_map)?,
        ),
        MachineInstIR::VmPtrLoad { region } => encode_machine_virtualization_mem(
            out,
            None,
            &[0x0F, 0xC7],
            6,
            &resolve_machine_mem_addr(region, reg_map)?,
        ),
        MachineInstIR::VmPtrStore { destination } => encode_machine_virtualization_mem(
            out,
            None,
            &[0x0F, 0xC7],
            7,
            &resolve_machine_mem_addr(destination, reg_map)?,
        ),
        MachineInstIR::VmRead { destination, field } => {
            let field = *reg_map.get(field)?;
            encode_machine_virtualization_rm(out, None, &[0x0F, 0x78], field, destination, reg_map)
        }
        MachineInstIR::VmWrite { value, field } => {
            let value = *reg_map.get(value)?;
            encode_machine_virtualization_rm(out, None, &[0x0F, 0x79], value, field, reg_map)
        }
        MachineInstIR::InvEpt { kind, descriptor } => encode_machine_virtualization_mem(
            out,
            Some(0x66),
            &[0x0F, 0x38, 0x80],
            *reg_map.get(kind)?,
            &resolve_machine_mem_addr(descriptor, reg_map)?,
        ),
        MachineInstIR::InvVpid { kind, descriptor } => encode_machine_virtualization_mem(
            out,
            Some(0x66),
            &[0x0F, 0x38, 0x81],
            *reg_map.get(kind)?,
            &resolve_machine_mem_addr(descriptor, reg_map)?,
        ),
        MachineInstIR::VmCall => {
            out.extend_from_slice(&[0x0F, 0x01, 0xC1]);
            Some(())
        }
        MachineInstIR::VmLaunch => {
            out.extend_from_slice(&[0x0F, 0x01, 0xC2]);
            Some(())
        }
        MachineInstIR::VmResume => {
            out.extend_from_slice(&[0x0F, 0x01, 0xC3]);
            Some(())
        }
        MachineInstIR::VmRun => {
            out.extend_from_slice(&[0x0F, 0x01, 0xD8]);
            Some(())
        }
        MachineInstIR::VmmCall => {
            out.extend_from_slice(&[0x0F, 0x01, 0xD9]);
            Some(())
        }
        MachineInstIR::VmLoad => {
            out.extend_from_slice(&[0x0F, 0x01, 0xDA]);
            Some(())
        }
        MachineInstIR::VmSave => {
            out.extend_from_slice(&[0x0F, 0x01, 0xDB]);
            Some(())
        }
        MachineInstIR::StGi => {
            out.extend_from_slice(&[0x0F, 0x01, 0xDC]);
            Some(())
        }
        MachineInstIR::ClGi => {
            out.extend_from_slice(&[0x0F, 0x01, 0xDD]);
            Some(())
        }
        MachineInstIR::InvLpga => {
            out.extend_from_slice(&[0x0F, 0x01, 0xDF]);
            Some(())
        }
        MachineInstIR::Ret => {
            out.push(0xC3);
            Some(())
        }
        MachineInstIR::Nop => {
            out.push(0x90);
            Some(())
        }
        MachineInstIR::Wait => {
            out.push(0x9B);
            Some(())
        }
        MachineInstIR::Halt => {
            out.push(0xF4);
            Some(())
        }
        MachineInstIR::Label { .. }
        | MachineInstIR::Call { .. }
        | MachineInstIR::Jmp { .. }
        | MachineInstIR::JmpEq { .. }
        | MachineInstIR::JmpNe { .. }
        | MachineInstIR::JmpGt { .. }
        | MachineInstIR::JmpLt { .. }
        | MachineInstIR::JmpGe { .. }
        | MachineInstIR::JmpLe { .. }
        | MachineInstIR::JmpOverflow { .. } => Some(()),
    }
}

fn resolve_machine_call_reloc_symbol(
    machine: &BackendMachineUnitIR,
    target: &MachineCallTargetIR,
) -> String {
    match target {
        MachineCallTargetIR::Label(label) => resolve_machine_label_reloc_symbol(machine, label),
        MachineCallTargetIR::RootPath(path) => path.join("."),
    }
}

fn resolve_machine_label_reloc_symbol(machine: &BackendMachineUnitIR, label: &str) -> String {
    if machine.labels.iter().any(|x| x == label) || machine_ops_define_label(machine, label) {
        format!("{}.{}", machine.symbol, label)
    } else {
        label.to_string()
    }
}

fn machine_ops_define_label(machine: &BackendMachineUnitIR, label: &str) -> bool {
    machine.ops.iter().any(|op| {
        matches!(
            op,
            BackendMachineOpIR::Inst(MachineInstIR::Label { name }) if name == label
        )
    })
}

fn build_machine_reg_map(regs: &[String]) -> Option<HashMap<String, u8>> {
    if regs.is_empty() {
        return None;
    }

    let mut map = HashMap::new();
    let mut used = [false; 16];
    for reg in regs {
        if let Some(phys) = machine_reg_name_to_x86(reg) {
            if used[phys as usize] {
                return None;
            }
            map.insert(reg.clone(), phys);
            used[phys as usize] = true;
        }
    }

    // Keep RCX late in fallback assignment order so shift/rotate can usually
    // use CL as scratch, but still allow full 16-register mapping when needed.
    let preferred = [10u8, 11, 12, 13, 14, 15, 8, 9, 0, 3, 2, 6, 7, 5, 4, 1];
    let mut cursor = 0usize;
    for reg in regs {
        if map.contains_key(reg) {
            continue;
        }
        while cursor < preferred.len() && used[preferred[cursor] as usize] {
            cursor += 1;
        }
        if cursor >= preferred.len() {
            return None;
        }
        let phys = preferred[cursor];
        map.insert(reg.clone(), phys);
        used[phys as usize] = true;
    }
    Some(map)
}

fn encode_shift_rotate_variable_count(
    out: &mut Vec<u8>,
    reg_map: &HashMap<String, u8>,
    dst_reg: u8,
    src_reg: u8,
    group: u8,
) -> Option<()> {
    if src_reg == 1 {
        encode_shift_cl(out, group, dst_reg);
        return Some(());
    }

    if dst_reg == 1 {
        let scratch = pick_machine_scratch_reg(reg_map, &[1, src_reg])?;
        // Preserve dst value (rcx), load variable count into cl, shift preserved dst, restore rcx.
        encode_rr(out, 0x89, 1, scratch);
        encode_rr(out, 0x89, src_reg, 1);
        encode_shift_cl(out, group, scratch);
        encode_rr(out, 0x89, scratch, 1);
        return Some(());
    }

    if rcx_owned_by_symbol(reg_map) {
        let scratch = pick_machine_scratch_reg(reg_map, &[1, src_reg, dst_reg])?;
        // Preserve owner of rcx, use cl for variable count, then restore rcx owner value.
        encode_rr(out, 0x89, 1, scratch);
        encode_rr(out, 0x89, src_reg, 1);
        encode_shift_cl(out, group, dst_reg);
        encode_rr(out, 0x89, scratch, 1);
        return Some(());
    }

    encode_rr(out, 0x89, src_reg, 1);
    encode_shift_cl(out, group, dst_reg);
    Some(())
}

fn rcx_owned_by_symbol(reg_map: &HashMap<String, u8>) -> bool {
    reg_map.values().any(|phys| *phys == 1)
}

fn pick_machine_scratch_reg(reg_map: &HashMap<String, u8>, forbidden: &[u8]) -> Option<u8> {
    let mut used = [false; 16];
    for phys in reg_map.values() {
        used[*phys as usize] = true;
    }
    for phys in forbidden {
        used[*phys as usize] = true;
    }

    let preference = [11u8, 10, 12, 13, 14, 15, 9, 8, 3, 2, 6, 7, 5, 4, 0, 1];
    preference
        .iter()
        .copied()
        .find(|phys| !used[*phys as usize])
}

fn machine_reg_name_to_x86(name: &str) -> Option<u8> {
    match name {
        "rax" | "ax" => Some(0),
        "rcx" | "cx" => Some(1),
        "rdx" | "dx" => Some(2),
        "rbx" | "bx" => Some(3),
        "rsp" | "sp" => Some(4),
        "rbp" | "bp" => Some(5),
        "rsi" | "si" => Some(6),
        "rdi" | "di" => Some(7),
        "r8" => Some(8),
        "r9" => Some(9),
        "r10" => Some(10),
        "r11" => Some(11),
        "r12" => Some(12),
        "r13" => Some(13),
        "r14" => Some(14),
        "r15" => Some(15),
        _ => None,
    }
}

fn encode_rr(out: &mut Vec<u8>, opcode: u8, reg: u8, rm: u8) {
    let rex = 0x48 | (((reg >> 3) & 1) << 2) | ((rm >> 3) & 1);
    out.push(rex);
    out.push(opcode);
    let modrm = 0b11_000_000 | ((reg & 7) << 3) | (rm & 7);
    out.push(modrm);
}

fn encode_rr_0f(out: &mut Vec<u8>, opcode2: u8, reg: u8, rm: u8) {
    let rex = 0x48 | (((reg >> 3) & 1) << 2) | ((rm >> 3) & 1);
    out.push(rex);
    out.push(0x0F);
    out.push(opcode2);
    let modrm = 0b11_000_000 | ((reg & 7) << 3) | (rm & 7);
    out.push(modrm);
}

fn encode_group_ff_f7(out: &mut Vec<u8>, opcode: u8, group: u8, rm: u8) {
    let rex = 0x48 | ((rm >> 3) & 1);
    out.push(rex);
    out.push(opcode);
    let modrm = 0b11_000_000 | ((group & 7) << 3) | (rm & 7);
    out.push(modrm);
}

fn encode_shift_cl(out: &mut Vec<u8>, group: u8, rm: u8) {
    let rex = 0x48 | ((rm >> 3) & 1);
    out.push(rex);
    out.push(0xD3);
    let modrm = 0b11_000_000 | ((group & 7) << 3) | (rm & 7);
    out.push(modrm);
}

#[derive(Debug, Clone, Copy)]
struct EncodedMachineMemAddr {
    base: u8,
    index: Option<u8>,
    scale: u8,
    disp: isize,
}

fn resolve_machine_mem_addr(
    mem: &MachineMemRefIR,
    reg_map: &HashMap<String, u8>,
) -> Option<EncodedMachineMemAddr> {
    match mem {
        MachineMemRefIR::MemReg { base } => Some(EncodedMachineMemAddr {
            base: *reg_map.get(base)?,
            index: None,
            scale: 1,
            disp: 0,
        }),
        MachineMemRefIR::MemAddr {
            base,
            index,
            scale,
            disp,
        } => {
            if !matches!(*scale, 1 | 2 | 4 | 8) {
                return None;
            }
            let index = if let Some(index_name) = index {
                let index_reg = *reg_map.get(index_name)?;
                if index_reg & 7 == 4 {
                    // rsp/r12 cannot be encoded as SIB index field.
                    return None;
                }
                Some(index_reg)
            } else {
                if *scale != 1 {
                    return None;
                }
                None
            };

            Some(EncodedMachineMemAddr {
                base: *reg_map.get(base)?,
                index,
                scale: *scale,
                disp: *disp,
            })
        }
    }
}

fn encode_machine_virtualization_rm(
    out: &mut Vec<u8>,
    legacy_prefix: Option<u8>,
    opcode: &[u8],
    reg_field: u8,
    operand: &MachineRegOrMemIR,
    reg_map: &HashMap<String, u8>,
) -> Option<()> {
    match operand {
        MachineRegOrMemIR::Reg(reg) => {
            let rm = *reg_map.get(reg)?;
            if let Some(prefix) = legacy_prefix {
                out.push(prefix);
            }
            let rex = 0x40 | (((reg_field >> 3) & 1) << 2) | ((rm >> 3) & 1);
            if rex != 0x40 {
                out.push(rex);
            }
            out.extend_from_slice(opcode);
            out.push(0b11_000_000 | ((reg_field & 7) << 3) | (rm & 7));
            Some(())
        }
        MachineRegOrMemIR::Mem(mem) => encode_machine_virtualization_mem(
            out,
            legacy_prefix,
            opcode,
            reg_field,
            &resolve_machine_mem_addr(mem, reg_map)?,
        ),
    }
}

fn encode_machine_virtualization_mem(
    out: &mut Vec<u8>,
    legacy_prefix: Option<u8>,
    opcode: &[u8],
    reg_field: u8,
    mem: &EncodedMachineMemAddr,
) -> Option<()> {
    let base = mem.base;
    let index = mem.index;
    let needs_sib = index.is_some() || (base & 7) == 4;
    let scale_bits = match mem.scale {
        1 => 0u8,
        2 => 1u8,
        4 => 2u8,
        8 => 3u8,
        _ => return None,
    };
    let (mod_bits, disp8, disp32) = if mem.disp == 0 && (base & 7) != 5 {
        (0b00, None, None)
    } else if let Ok(value) = i8::try_from(mem.disp) {
        (0b01, Some(value), None)
    } else {
        (0b10, None, Some(i32::try_from(mem.disp).ok()?))
    };

    if let Some(prefix) = legacy_prefix {
        out.push(prefix);
    }
    let rex = 0x40
        | (((reg_field >> 3) & 1) << 2)
        | (index.map(|value| (value >> 3) & 1).unwrap_or(0) << 1)
        | ((base >> 3) & 1);
    if rex != 0x40 {
        out.push(rex);
    }
    out.extend_from_slice(opcode);
    let rm = if needs_sib { 4 } else { base & 7 };
    out.push((mod_bits << 6) | ((reg_field & 7) << 3) | rm);
    if needs_sib {
        let index = index.map(|value| value & 7).unwrap_or(4);
        out.push((scale_bits << 6) | (index << 3) | (base & 7));
    }
    if let Some(value) = disp8 {
        out.push(value as u8);
    }
    if let Some(value) = disp32 {
        out.extend_from_slice(&value.to_le_bytes());
    }
    Some(())
}

fn encode_reg_mem_mov_rm_to_reg(
    out: &mut Vec<u8>,
    dst_reg: u8,
    mem: &EncodedMachineMemAddr,
) -> Option<()> {
    encode_reg_mem(out, 0x8B, dst_reg, mem)
}

fn encode_reg_mem_mov_reg_to_rm(
    out: &mut Vec<u8>,
    src_reg: u8,
    mem: &EncodedMachineMemAddr,
) -> Option<()> {
    encode_reg_mem(out, 0x89, src_reg, mem)
}

fn encode_reg_mem_lea_to_reg(
    out: &mut Vec<u8>,
    dst_reg: u8,
    mem: &EncodedMachineMemAddr,
) -> Option<()> {
    encode_reg_mem(out, 0x8D, dst_reg, mem)
}

fn encode_reg_mem_load_width_to_reg(
    out: &mut Vec<u8>,
    dst_reg: u8,
    mem: &EncodedMachineMemAddr,
    width: ScalarMemWidthIR,
    extension: ScalarMemExtensionIR,
) -> Option<()> {
    match (width, extension) {
        (ScalarMemWidthIR::Byte, ScalarMemExtensionIR::Zero) => {
            encode_reg_mem_0f_ext(out, 0xB6, dst_reg, mem, true)
        }
        (ScalarMemWidthIR::Byte, ScalarMemExtensionIR::Sign) => {
            encode_reg_mem_0f_ext(out, 0xBE, dst_reg, mem, true)
        }
        (ScalarMemWidthIR::Word, ScalarMemExtensionIR::Zero) => {
            encode_reg_mem_0f_ext(out, 0xB7, dst_reg, mem, true)
        }
        (ScalarMemWidthIR::Word, ScalarMemExtensionIR::Sign) => {
            encode_reg_mem_0f_ext(out, 0xBF, dst_reg, mem, true)
        }
        (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Sign) => {
            encode_reg_mem_ext(out, 0x63, dst_reg, mem, true, false)
        }
        (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Zero) => {
            encode_reg_mem_ext(out, 0x8B, dst_reg, mem, false, false)
        }
        (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Float) => {
            encode_reg_mem_ext(out, 0x8B, dst_reg, mem, false, false)
        }
        (ScalarMemWidthIR::Byte | ScalarMemWidthIR::Word, ScalarMemExtensionIR::Float) => None,
        (ScalarMemWidthIR::Qword, _) => encode_reg_mem_ext(out, 0x8B, dst_reg, mem, true, false),
    }
}

fn encode_reg_mem_store_width_from_reg(
    out: &mut Vec<u8>,
    src_reg: u8,
    mem: &EncodedMachineMemAddr,
    width: ScalarMemWidthIR,
) -> Option<()> {
    match width {
        ScalarMemWidthIR::Byte => encode_reg_mem_ext(out, 0x88, src_reg, mem, false, false),
        ScalarMemWidthIR::Word => encode_reg_mem_ext(out, 0x89, src_reg, mem, false, true),
        ScalarMemWidthIR::Dword => encode_reg_mem_ext(out, 0x89, src_reg, mem, false, false),
        ScalarMemWidthIR::Qword => encode_reg_mem_ext(out, 0x89, src_reg, mem, true, false),
    }
}

fn encode_rip_mem_ext_reloc_slot(
    out: &mut Vec<u8>,
    opcode_prefix: Option<u8>,
    opcode: u8,
    reg_field: u8,
    rex_w: bool,
    prefix_66: bool,
) -> Option<usize> {
    if reg_field > 15 {
        return None;
    }
    if prefix_66 {
        out.push(0x66);
    }
    out.push(0x40 | (u8::from(rex_w) << 3) | (((reg_field >> 3) & 1) << 2));
    if let Some(prefix) = opcode_prefix {
        out.push(prefix);
    }
    out.push(opcode);
    out.push(((reg_field & 7) << 3) | 0b101);
    let offset = out.len();
    out.extend_from_slice(&[0, 0, 0, 0]);
    Some(offset)
}

fn encode_rip_mem_load_reloc_slot(
    out: &mut Vec<u8>,
    dst_reg: u8,
    width: ScalarMemWidthIR,
    extension: ScalarMemExtensionIR,
) -> Option<usize> {
    match (width, extension) {
        (ScalarMemWidthIR::Byte, ScalarMemExtensionIR::Zero) => {
            encode_rip_mem_ext_reloc_slot(out, Some(0x0F), 0xB6, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Byte, ScalarMemExtensionIR::Sign) => {
            encode_rip_mem_ext_reloc_slot(out, Some(0x0F), 0xBE, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Word, ScalarMemExtensionIR::Zero) => {
            encode_rip_mem_ext_reloc_slot(out, Some(0x0F), 0xB7, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Word, ScalarMemExtensionIR::Sign) => {
            encode_rip_mem_ext_reloc_slot(out, Some(0x0F), 0xBF, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Sign) => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x63, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Zero)
        | (ScalarMemWidthIR::Dword, ScalarMemExtensionIR::Float) => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x8B, dst_reg, false, false)
        }
        (ScalarMemWidthIR::Qword, _) => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x8B, dst_reg, true, false)
        }
        (ScalarMemWidthIR::Byte | ScalarMemWidthIR::Word, ScalarMemExtensionIR::Float) => None,
    }
}

fn encode_rip_mem_store_reloc_slot(
    out: &mut Vec<u8>,
    src_reg: u8,
    width: ScalarMemWidthIR,
) -> Option<usize> {
    match width {
        ScalarMemWidthIR::Byte => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x88, src_reg, false, false)
        }
        ScalarMemWidthIR::Word => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x89, src_reg, false, true)
        }
        ScalarMemWidthIR::Dword => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x89, src_reg, false, false)
        }
        ScalarMemWidthIR::Qword => {
            encode_rip_mem_ext_reloc_slot(out, None, 0x89, src_reg, true, false)
        }
    }
}

fn encode_reg_mem(
    out: &mut Vec<u8>,
    opcode: u8,
    reg_field: u8,
    mem: &EncodedMachineMemAddr,
) -> Option<()> {
    encode_reg_mem_ext(out, opcode, reg_field, mem, true, false)
}

fn encode_reg_mem_0f_ext(
    out: &mut Vec<u8>,
    opcode2: u8,
    reg_field: u8,
    mem: &EncodedMachineMemAddr,
    rex_w: bool,
) -> Option<()> {
    encode_reg_mem_ext_prefix(out, Some(0x0F), opcode2, reg_field, mem, rex_w, false)
}

fn encode_reg_mem_ext(
    out: &mut Vec<u8>,
    opcode: u8,
    reg_field: u8,
    mem: &EncodedMachineMemAddr,
    rex_w: bool,
    prefix_66: bool,
) -> Option<()> {
    encode_reg_mem_ext_prefix(out, None, opcode, reg_field, mem, rex_w, prefix_66)
}

fn encode_reg_mem_ext_prefix(
    out: &mut Vec<u8>,
    opcode_prefix: Option<u8>,
    opcode: u8,
    reg_field: u8,
    mem: &EncodedMachineMemAddr,
    rex_w: bool,
    prefix_66: bool,
) -> Option<()> {
    let base = mem.base;
    let index = mem.index;

    let needs_sib = index.is_some() || (base & 7) == 4;
    let scale_bits = match mem.scale {
        1 => 0u8,
        2 => 1u8,
        4 => 2u8,
        8 => 3u8,
        _ => return None,
    };

    let mut mod_bits = 0b00u8;
    let mut disp8: Option<i8> = None;
    let mut disp32: Option<i32> = None;

    if mem.disp == 0 {
        if (base & 7) == 5 {
            mod_bits = 0b01;
            disp8 = Some(0);
        }
    } else if let Ok(v) = i8::try_from(mem.disp) {
        mod_bits = 0b01;
        disp8 = Some(v);
    } else {
        mod_bits = 0b10;
        disp32 = Some(i32::try_from(mem.disp).ok()?);
    }

    if prefix_66 {
        out.push(0x66);
    }
    let rex = 0x40
        | (u8::from(rex_w) << 3)
        | (((reg_field >> 3) & 1) << 2)
        | (index.map(|x| (x >> 3) & 1).unwrap_or(0) << 1)
        | ((base >> 3) & 1);
    out.push(rex);
    if let Some(prefix) = opcode_prefix {
        out.push(prefix);
    }
    out.push(opcode);

    let rm_low = if needs_sib { 0b100 } else { base & 7 };
    let modrm = (mod_bits << 6) | ((reg_field & 7) << 3) | rm_low;
    out.push(modrm);

    if needs_sib {
        let index_low = index.map(|x| x & 7).unwrap_or(0b100);
        let base_low = base & 7;
        let sib = (scale_bits << 6) | (index_low << 3) | base_low;
        out.push(sib);
    }

    match mod_bits {
        0b01 => {
            out.push(disp8.unwrap_or(0) as u8);
        }
        0b10 => {
            out.extend_from_slice(&disp32?.to_le_bytes());
        }
        _ => {}
    }

    Some(())
}

fn encode_bswap_reg(out: &mut Vec<u8>, reg: u8) {
    let rex = 0x48 | ((reg >> 3) & 1);
    out.push(rex);
    out.push(0x0F);
    out.push(0xC8 | (reg & 7));
}

fn encode_push_reg_num(reg: u8, out: &mut Vec<u8>) {
    if reg >= 8 {
        out.push(0x41);
    }
    out.push(0x50 + (reg & 7));
}

fn encode_pop_reg_num(reg: u8, out: &mut Vec<u8>) {
    if reg >= 8 {
        out.push(0x41);
    }
    out.push(0x58 + (reg & 7));
}

fn encode_backend_push_reg(reg: &BackendRegisterIR, out: &mut Vec<u8>) -> bool {
    let Some(reg_num) = backend_register_to_x86(reg) else {
        return false;
    };
    encode_push_reg_num(reg_num, out);
    true
}

fn encode_backend_pop_reg(reg: &BackendRegisterIR, out: &mut Vec<u8>) -> bool {
    let Some(reg_num) = backend_register_to_x86(reg) else {
        return false;
    };
    encode_pop_reg_num(reg_num, out);
    true
}

fn encode_backend_sub_rsp_imm32(bytes: usize) -> Option<Vec<u8>> {
    let imm = u32::try_from(bytes).ok()?;
    let mut out = vec![0x48, 0x81, 0xEC];
    out.extend_from_slice(&imm.to_le_bytes());
    Some(out)
}

fn encode_backend_add_rsp_imm32(bytes: usize) -> Option<Vec<u8>> {
    let imm = u32::try_from(bytes).ok()?;
    let mut out = vec![0x48, 0x81, 0xC4];
    out.extend_from_slice(&imm.to_le_bytes());
    Some(out)
}

fn encode_backend_mov_rbp_rsp() -> Option<Vec<u8>> {
    let rbp = backend_register_to_x86(&BackendRegisterIR::Rbp)?;
    let rsp = backend_register_to_x86(&BackendRegisterIR::Rsp)?;
    let mut out = Vec::new();
    encode_rr(&mut out, 0x89, rsp, rbp);
    Some(out)
}

fn encode_backend_load_value_location_word_to_x86_reg(
    func: &BackendFunctionUnitIR,
    location: &BackendValueLocationIR,
    word_index: usize,
    dst: u8,
    out: &mut Vec<u8>,
) -> Option<()> {
    let word_bytes = func.plan.data_layout.word_bytes;
    match location {
        BackendValueLocationIR::Register(src_reg) if word_index == 0 => {
            let src = backend_register_to_x86(src_reg)?;
            if src != dst {
                encode_rr(out, 0x89, src, dst);
            }
            Some(())
        }
        BackendValueLocationIR::Registers { registers, .. } => {
            let src_reg = registers.get(word_index)?;
            let src = backend_register_to_x86(src_reg)?;
            if src != dst {
                encode_rr(out, 0x89, src, dst);
            }
            Some(())
        }
        BackendValueLocationIR::Stack {
            byte_offset,
            byte_size,
        } if word_index == 0 && *byte_size == word_bytes => {
            let incoming_off = incoming_stack_param_base_offset(&func.plan.calling_convention)
                .checked_add(*byte_offset)?;
            let mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rbp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(incoming_off).ok()?,
            };
            encode_reg_mem_mov_rm_to_reg(out, dst, &mem)
        }
        BackendValueLocationIR::StackByValue {
            byte_offset,
            byte_size,
            ..
        } if word_index.saturating_mul(word_bytes) < *byte_size => {
            let incoming_off = incoming_stack_param_base_offset(&func.plan.calling_convention)
                .checked_add(*byte_offset)?
                .checked_add(word_index.checked_mul(word_bytes)?)?;
            let mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rbp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(incoming_off).ok()?,
            };
            encode_reg_mem_mov_rm_to_reg(out, dst, &mem)
        }
        BackendValueLocationIR::IndirectRegister {
            pointer_register, ..
        } if word_index == 0 => {
            let src = backend_register_to_x86(pointer_register)?;
            if src != dst {
                encode_rr(out, 0x89, src, dst);
            }
            Some(())
        }
        BackendValueLocationIR::IndirectStack {
            byte_offset,
            pointer_size,
            ..
        } if word_index == 0 && *pointer_size == word_bytes => {
            let incoming_off = incoming_stack_param_base_offset(&func.plan.calling_convention)
                .checked_add(*byte_offset)?;
            let mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rbp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(incoming_off).ok()?,
            };
            encode_reg_mem_mov_rm_to_reg(out, dst, &mem)
        }
        _ => None,
    }
}

fn encode_backend_pointer_to_value_location_to_x86_reg(
    func: &BackendFunctionUnitIR,
    location: &BackendValueLocationIR,
    dst: u8,
    out: &mut Vec<u8>,
) -> Option<()> {
    match location {
        BackendValueLocationIR::IndirectRegister {
            pointer_register, ..
        } => {
            let src = backend_register_to_x86(pointer_register)?;
            if src != dst {
                encode_rr(out, 0x89, src, dst);
            }
            Some(())
        }
        BackendValueLocationIR::IndirectStack { .. } => {
            encode_backend_load_value_location_word_to_x86_reg(func, location, 0, dst, out)
        }
        BackendValueLocationIR::Stack { byte_offset, .. }
        | BackendValueLocationIR::StackByValue { byte_offset, .. } => {
            let incoming_off = incoming_stack_param_base_offset(&func.plan.calling_convention)
                .checked_add(*byte_offset)?;
            let mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rbp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(incoming_off).ok()?,
            };
            encode_reg_mem_lea_to_reg(out, dst, &mem)
        }
        BackendValueLocationIR::Register(_) | BackendValueLocationIR::Registers { .. } => {
            encode_backend_load_value_location_word_to_x86_reg(func, location, 0, dst, out)
        }
        BackendValueLocationIR::Void | BackendValueLocationIR::HiddenSRet { .. } => None,
    }
}

#[allow(clippy::too_many_arguments)]
fn encode_backend_prepare_call_arg_native(
    func: &BackendFunctionUnitIR,
    section_name: &str,
    pass_class: &AbiPassClassIR,
    source: &FunctionCallArgSourceIR,
    location: &BackendCallArgLocationIR,
    out: &mut Vec<u8>,
    relocs: &mut Vec<BackendObjectRelocationIR>,
    literal_symbol_by_value: &mut HashMap<String, String>,
    closure_symbol_by_key: &mut HashMap<String, String>,
    closure_stub_symbols: &mut Vec<String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> Option<()> {
    match location {
        BackendCallArgLocationIR::Register(dst_reg) => {
            let dst = backend_register_to_x86(dst_reg)?;
            match source {
                FunctionCallArgSourceIR::Symbol(name) => {
                    if let Some(src_location) = func
                        .plan
                        .param_locations
                        .iter()
                        .find(|param| param.name == *name)
                        .map(|param| param.location.clone())
                    {
                        encode_backend_load_value_location_word_to_x86_reg(
                            func,
                            &src_location,
                            0,
                            dst,
                            out,
                        )
                    } else {
                        encode_backend_function_global_load_to_x86_reg(
                            func,
                            name,
                            dst,
                            section_name,
                            out,
                            relocs,
                        )
                        .or_else(|| {
                            encode_backend_implicit_symbol_to_x86_reg(
                                func,
                                name,
                                pass_class,
                                dst,
                                section_name,
                                out,
                                relocs,
                            )
                        })
                    }
                }
                FunctionCallArgSourceIR::NumberLiteral(raw) => {
                    let value = parse_backend_number_literal(raw)?;
                    let imm = i32::try_from(value).ok()?;
                    encode_backend_mov_reg_imm32(out, dst, imm);
                    Some(())
                }
                FunctionCallArgSourceIR::BoolLiteral(value) => {
                    let imm = if *value { 1 } else { 0 };
                    encode_backend_mov_reg_imm32(out, dst, imm);
                    Some(())
                }
                FunctionCallArgSourceIR::StringLiteral(value) => {
                    let symbol = ensure_function_literal_symbol(
                        value,
                        &func.symbol,
                        literal_symbol_by_value,
                        rodata_entries,
                    );
                    let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: imm_offset,
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol,
                        addend: 0,
                    });
                    Some(())
                }
                FunctionCallArgSourceIR::ClosureValue {
                    key,
                    param_count,
                    capture_count,
                } => {
                    if *capture_count != 0 {
                        return None;
                    }
                    let symbol = ensure_function_closure_descriptor_symbol(
                        key,
                        *param_count,
                        *capture_count,
                        &func.symbol,
                        closure_symbol_by_key,
                        closure_stub_symbols,
                        rodata_entries,
                    );
                    let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: imm_offset,
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol,
                        addend: 0,
                    });
                    Some(())
                }
                FunctionCallArgSourceIR::Expr(_) | FunctionCallArgSourceIR::MissingGenerated => {
                    None
                }
            }
        }
        BackendCallArgLocationIR::Registers {
            registers,
            byte_size,
        } => {
            let word_bytes = func.plan.data_layout.word_bytes;
            for (word_index, dst_reg) in registers.iter().enumerate() {
                if word_index.saturating_mul(word_bytes) >= *byte_size {
                    break;
                }
                let dst = backend_register_to_x86(dst_reg)?;
                match source {
                    FunctionCallArgSourceIR::Symbol(name) => {
                        if let Some(src_location) = func
                            .plan
                            .param_locations
                            .iter()
                            .find(|param| param.name == *name)
                            .map(|param| param.location.clone())
                        {
                            encode_backend_load_value_location_word_to_x86_reg(
                                func,
                                &src_location,
                                word_index,
                                dst,
                                out,
                            )?;
                        } else if word_index == 0 {
                            encode_backend_function_global_load_to_x86_reg(
                                func,
                                name,
                                dst,
                                section_name,
                                out,
                                relocs,
                            )
                            .or_else(|| {
                                encode_backend_implicit_symbol_to_x86_reg(
                                    func,
                                    name,
                                    pass_class,
                                    dst,
                                    section_name,
                                    out,
                                    relocs,
                                )
                            })?;
                        } else {
                            encode_backend_mov_reg_imm32(out, dst, 0);
                        }
                    }
                    FunctionCallArgSourceIR::StringLiteral(value) if word_index == 0 => {
                        let symbol = ensure_function_literal_symbol(
                            value,
                            &func.symbol,
                            literal_symbol_by_value,
                            rodata_entries,
                        );
                        let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
                        relocs.push(BackendObjectRelocationIR {
                            section: section_name.to_string(),
                            offset: imm_offset,
                            kind: BackendObjectRelocationKindIR::Abs64,
                            symbol,
                            addend: 0,
                        });
                    }
                    _ if word_index > 0 => encode_backend_mov_reg_imm32(out, dst, 0),
                    _ => return None,
                }
            }
            Some(())
        }
        BackendCallArgLocationIR::Stack {
            byte_offset,
            byte_size,
        } => {
            if *byte_size != 8 {
                return None;
            }
            let stack_mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rsp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(*byte_offset).ok()?,
            };
            match source {
                FunctionCallArgSourceIR::Symbol(name) => {
                    if let Some(src_location) = func
                        .plan
                        .param_locations
                        .iter()
                        .find(|param| param.name == *name)
                        .map(|param| param.location.clone())
                    {
                        let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
                        encode_backend_load_value_location_word_to_x86_reg(
                            func,
                            &src_location,
                            0,
                            scratch,
                            out,
                        )?;
                        encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)
                    } else {
                        let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
                        encode_backend_function_global_load_to_x86_reg(
                            func,
                            name,
                            scratch,
                            section_name,
                            out,
                            relocs,
                        )
                        .or_else(|| {
                            encode_backend_implicit_symbol_to_x86_reg(
                                func,
                                name,
                                pass_class,
                                scratch,
                                section_name,
                                out,
                                relocs,
                            )
                        })?;
                        encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)
                    }
                }
                FunctionCallArgSourceIR::NumberLiteral(raw) => {
                    let value = parse_backend_number_literal(raw)?;
                    let imm = i32::try_from(value).ok()?;
                    encode_backend_store_imm32_to_mem(out, &stack_mem, imm)
                }
                FunctionCallArgSourceIR::BoolLiteral(value) => {
                    let imm = if *value { 1 } else { 0 };
                    encode_backend_store_imm32_to_mem(out, &stack_mem, imm)
                }
                FunctionCallArgSourceIR::StringLiteral(value) => {
                    let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
                    let symbol = ensure_function_literal_symbol(
                        value,
                        &func.symbol,
                        literal_symbol_by_value,
                        rodata_entries,
                    );
                    let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, scratch);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: imm_offset,
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol,
                        addend: 0,
                    });
                    encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)
                }
                FunctionCallArgSourceIR::ClosureValue {
                    key,
                    param_count,
                    capture_count,
                } => {
                    if *capture_count != 0 {
                        return None;
                    }
                    let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
                    let symbol = ensure_function_closure_descriptor_symbol(
                        key,
                        *param_count,
                        *capture_count,
                        &func.symbol,
                        closure_symbol_by_key,
                        closure_stub_symbols,
                        rodata_entries,
                    );
                    let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, scratch);
                    relocs.push(BackendObjectRelocationIR {
                        section: section_name.to_string(),
                        offset: imm_offset,
                        kind: BackendObjectRelocationKindIR::Abs64,
                        symbol,
                        addend: 0,
                    });
                    encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)
                }
                FunctionCallArgSourceIR::Expr(_) | FunctionCallArgSourceIR::MissingGenerated => {
                    None
                }
            }
        }
        BackendCallArgLocationIR::StackByValue {
            byte_offset,
            byte_size,
            ..
        } => {
            let word_bytes = func.plan.data_layout.word_bytes;
            let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
            for word_index in 0..byte_size.div_ceil(word_bytes) {
                let stack_mem = EncodedMachineMemAddr {
                    base: backend_register_to_x86(&BackendRegisterIR::Rsp)?,
                    index: None,
                    scale: 1,
                    disp: isize::try_from(byte_offset.checked_add(word_index * word_bytes)?)
                        .ok()?,
                };
                match source {
                    FunctionCallArgSourceIR::Symbol(name) => {
                        let src_location = func
                            .plan
                            .param_locations
                            .iter()
                            .find(|param| param.name == *name)
                            .map(|param| param.location.clone());
                        if let Some(src_location) = src_location {
                            encode_backend_load_value_location_word_to_x86_reg(
                                func,
                                &src_location,
                                word_index,
                                scratch,
                                out,
                            )?;
                        } else if word_index == 0 {
                            encode_backend_function_global_load_to_x86_reg(
                                func,
                                name,
                                scratch,
                                section_name,
                                out,
                                relocs,
                            )
                            .or_else(|| {
                                encode_backend_implicit_symbol_to_x86_reg(
                                    func,
                                    name,
                                    pass_class,
                                    scratch,
                                    section_name,
                                    out,
                                    relocs,
                                )
                            })?;
                        } else {
                            encode_backend_mov_reg_imm32(out, scratch, 0);
                        }
                    }
                    _ if word_index == 0 => return None,
                    _ => encode_backend_mov_reg_imm32(out, scratch, 0),
                }
                encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)?;
            }
            Some(())
        }
        BackendCallArgLocationIR::IndirectRegister {
            pointer_register, ..
        } => {
            let dst = backend_register_to_x86(pointer_register)?;
            match source {
                FunctionCallArgSourceIR::Symbol(name) => {
                    let src_location = func
                        .plan
                        .param_locations
                        .iter()
                        .find(|param| param.name == *name)
                        .map(|param| param.location.clone())?;
                    encode_backend_pointer_to_value_location_to_x86_reg(
                        func,
                        &src_location,
                        dst,
                        out,
                    )
                }
                _ => None,
            }
        }
        BackendCallArgLocationIR::IndirectStack {
            byte_offset,
            pointer_size,
            ..
        } => {
            if *pointer_size != func.plan.data_layout.word_bytes {
                return None;
            }
            let scratch = backend_register_to_x86(&BackendRegisterIR::R11)?;
            match source {
                FunctionCallArgSourceIR::Symbol(name) => {
                    let src_location = func
                        .plan
                        .param_locations
                        .iter()
                        .find(|param| param.name == *name)
                        .map(|param| param.location.clone())?;
                    encode_backend_pointer_to_value_location_to_x86_reg(
                        func,
                        &src_location,
                        scratch,
                        out,
                    )?;
                }
                _ => return None,
            }
            let stack_mem = EncodedMachineMemAddr {
                base: backend_register_to_x86(&BackendRegisterIR::Rsp)?,
                index: None,
                scale: 1,
                disp: isize::try_from(*byte_offset).ok()?,
            };
            encode_reg_mem_mov_reg_to_rm(out, scratch, &stack_mem)
        }
    }
}

fn encode_backend_function_global_load_to_x86_reg(
    func: &BackendFunctionUnitIR,
    name: &str,
    dst: u8,
    section_name: &str,
    out: &mut Vec<u8>,
    relocs: &mut Vec<BackendObjectRelocationIR>,
) -> Option<()> {
    let global = func
        .scalar_globals
        .iter()
        .find(|global| global.name == name)?;
    let addr = if dst == backend_register_to_x86(&BackendRegisterIR::R11)? {
        backend_register_to_x86(&BackendRegisterIR::R10)?
    } else {
        backend_register_to_x86(&BackendRegisterIR::R11)?
    };
    let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, addr);
    relocs.push(BackendObjectRelocationIR {
        section: section_name.to_string(),
        offset: imm_offset,
        kind: BackendObjectRelocationKindIR::Abs64,
        symbol: global.symbol.clone(),
        addend: 0,
    });
    encode_reg_mem_load_width_to_reg(
        out,
        dst,
        &EncodedMachineMemAddr {
            base: addr,
            index: None,
            scale: 1,
            disp: 0,
        },
        global.mem_type.width,
        global.mem_type.extension,
    )
}

fn encode_backend_implicit_symbol_to_x86_reg(
    func: &BackendFunctionUnitIR,
    name: &str,
    pass_class: &AbiPassClassIR,
    dst: u8,
    section_name: &str,
    out: &mut Vec<u8>,
    relocs: &mut Vec<BackendObjectRelocationIR>,
) -> Option<()> {
    let symbol = implicit_stc_storage_symbol(&func.container, name);
    match pass_class {
        AbiPassClassIR::ByRef | AbiPassClassIR::PointerWord => {
            let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol,
                addend: 0,
            });
            Some(())
        }
        AbiPassClassIR::Register | AbiPassClassIR::ByValue => {
            let addr = if dst == backend_register_to_x86(&BackendRegisterIR::R11)? {
                backend_register_to_x86(&BackendRegisterIR::R10)?
            } else {
                backend_register_to_x86(&BackendRegisterIR::R11)?
            };
            let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, addr);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol,
                addend: 0,
            });
            encode_reg_mem_load_width_to_reg(
                out,
                dst,
                &EncodedMachineMemAddr {
                    base: addr,
                    index: None,
                    scale: 1,
                    disp: 0,
                },
                ScalarMemWidthIR::Qword,
                ScalarMemExtensionIR::Zero,
            )
        }
    }
}

fn implicit_stc_storage_symbol(container: &str, name: &str) -> String {
    format!(
        "__ncc_stc_{}_{}",
        sanitize_symbol_component(container),
        sanitize_symbol_component(name)
    )
}

fn ensure_function_literal_symbol(
    literal: &str,
    function_symbol: &str,
    literal_symbol_by_value: &mut HashMap<String, String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> String {
    if let Some(symbol) = literal_symbol_by_value.get(literal) {
        return symbol.clone();
    }
    let symbol = format!(
        "{function_symbol}.__strlit{}",
        literal_symbol_by_value.len()
    );
    let bytes_symbol = format!("{symbol}.__bytes");
    let literal_bytes = lower_text_literal_to_bytes(literal);
    let byte_len = literal_bytes.byte_len;
    let nul_len = literal_bytes.nul_terminated_byte_len;
    let scalar_count = literal_bytes.scalar_count;
    let bytes = literal_bytes.nul_terminated_bytes;
    let mut descriptor = Vec::with_capacity(16);
    descriptor.extend_from_slice(&0u64.to_le_bytes());
    descriptor.extend_from_slice(&(byte_len as u64).to_le_bytes());
    rodata_entries.push(BackendReadOnlyDataEntry {
        symbol: symbol.clone(),
        line: format!(
            "{}: ; string-descriptor utf8={} bytes nul={} chars={}",
            symbol, byte_len, nul_len, scalar_count
        ),
        bytes: descriptor,
        relocs: vec![BackendReadOnlyDataReloc {
            offset: 0,
            kind: BackendObjectRelocationKindIR::Abs64,
            symbol: bytes_symbol.clone(),
            addend: 0,
        }],
    });
    rodata_entries.push(BackendReadOnlyDataEntry {
        symbol: bytes_symbol,
        line: format!(
            "{}.__bytes: ; string-bytes utf8={} bytes nul={}",
            symbol, byte_len, nul_len
        ),
        bytes,
        relocs: Vec::new(),
    });
    literal_symbol_by_value.insert(literal.to_string(), symbol.clone());
    symbol
}

fn ensure_function_c_string_literal_symbol(
    literal: &str,
    function_symbol: &str,
    literal_symbol_by_value: &mut HashMap<String, String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> String {
    let key = format!("cstring:{literal}");
    if let Some(symbol) = literal_symbol_by_value.get(&key) {
        return symbol.clone();
    }
    let symbol = format!(
        "{function_symbol}.__cstring{}",
        literal_symbol_by_value.len()
    );
    let literal_bytes = lower_text_literal_to_bytes(literal);
    rodata_entries.push(BackendReadOnlyDataEntry {
        symbol: symbol.clone(),
        line: format!(
            "{}: ; c-string utf8={} bytes nul={}",
            symbol, literal_bytes.byte_len, literal_bytes.nul_terminated_byte_len
        ),
        bytes: literal_bytes.nul_terminated_bytes,
        relocs: Vec::new(),
    });
    literal_symbol_by_value.insert(key, symbol.clone());
    symbol
}

fn ensure_function_closure_descriptor_symbol(
    key: &str,
    param_count: usize,
    capture_count: usize,
    function_symbol: &str,
    closure_symbol_by_key: &mut HashMap<String, String>,
    _closure_stub_symbols: &mut Vec<String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> String {
    if let Some(symbol) = closure_symbol_by_key.get(key) {
        return symbol.clone();
    }

    let symbol = format!("{function_symbol}.__closure_descriptor_{key}");
    let invoke_symbol = format!("{function_symbol}.__closure_{key}.__invoke");

    let mut bytes = Vec::with_capacity(32);
    bytes.extend_from_slice(&0u64.to_le_bytes());
    bytes.extend_from_slice(&0u64.to_le_bytes());
    bytes.extend_from_slice(&(param_count as u64).to_le_bytes());
    bytes.extend_from_slice(&(capture_count as u64).to_le_bytes());

    rodata_entries.push(BackendReadOnlyDataEntry {
        symbol: symbol.clone(),
        line: format!(
            "{}: ; closure-descriptor params={} captures={}",
            symbol, param_count, capture_count
        ),
        bytes,
        relocs: vec![BackendReadOnlyDataReloc {
            offset: 0,
            kind: BackendObjectRelocationKindIR::Abs64,
            symbol: invoke_symbol,
            addend: 0,
        }],
    });
    closure_symbol_by_key.insert(key.to_string(), symbol.clone());
    symbol
}

fn incoming_stack_param_base_offset(calling_convention: &BackendCallingConventionIR) -> usize {
    match calling_convention {
        BackendCallingConventionIR::NcSysV64 => 16,
        BackendCallingConventionIR::NcWin64 => 48,
        BackendCallingConventionIR::NcAapcs64 => 16,
        BackendCallingConventionIR::NcPortable => 16,
        BackendCallingConventionIR::NcSovereign => 16,
    }
}

fn incoming_stack_param_rsp_base_offset(calling_convention: &BackendCallingConventionIR) -> usize {
    match calling_convention {
        BackendCallingConventionIR::NcSysV64
        | BackendCallingConventionIR::NcAapcs64
        | BackendCallingConventionIR::NcPortable
        | BackendCallingConventionIR::NcSovereign => 8,
        BackendCallingConventionIR::NcWin64 => 40,
    }
}

fn encode_backend_mov_reg_imm32(out: &mut Vec<u8>, dst_reg: u8, imm: i32) {
    let rex = 0x48 | ((dst_reg >> 3) & 1);
    out.push(rex);
    out.push(0xC7);
    out.push(0b11_000_000 | (dst_reg & 7));
    out.extend_from_slice(&imm.to_le_bytes());
}

fn encode_backend_mov_reg_imm(out: &mut Vec<u8>, dst_reg: u8, imm: i64) {
    if let Ok(imm32) = i32::try_from(imm) {
        encode_backend_mov_reg_imm32(out, dst_reg, imm32);
        return;
    }
    let rex = 0x48 | ((dst_reg >> 3) & 1);
    out.push(rex);
    out.push(0xB8 + (dst_reg & 7));
    out.extend_from_slice(&imm.to_le_bytes());
}

fn backend_register_to_aarch64(reg: &BackendRegisterIR) -> Option<u8> {
    match reg {
        BackendRegisterIR::X0 => Some(0),
        BackendRegisterIR::X1 => Some(1),
        BackendRegisterIR::X2 => Some(2),
        BackendRegisterIR::X3 => Some(3),
        BackendRegisterIR::X4 => Some(4),
        BackendRegisterIR::X5 => Some(5),
        BackendRegisterIR::X6 => Some(6),
        BackendRegisterIR::X7 => Some(7),
        BackendRegisterIR::X8 => Some(8),
        BackendRegisterIR::X9 => Some(9),
        BackendRegisterIR::X10 => Some(10),
        BackendRegisterIR::X11 => Some(11),
        BackendRegisterIR::X12 => Some(12),
        BackendRegisterIR::X13 => Some(13),
        BackendRegisterIR::X14 => Some(14),
        BackendRegisterIR::X15 => Some(15),
        BackendRegisterIR::X16 => Some(16),
        BackendRegisterIR::X17 => Some(17),
        BackendRegisterIR::X18 => Some(18),
        BackendRegisterIR::X19 => Some(19),
        BackendRegisterIR::X20 => Some(20),
        BackendRegisterIR::X21 => Some(21),
        BackendRegisterIR::X22 => Some(22),
        BackendRegisterIR::X23 => Some(23),
        BackendRegisterIR::X24 => Some(24),
        BackendRegisterIR::X25 => Some(25),
        BackendRegisterIR::X26 => Some(26),
        BackendRegisterIR::X27 => Some(27),
        BackendRegisterIR::X28 => Some(28),
        BackendRegisterIR::X29 => Some(29),
        BackendRegisterIR::X30 => Some(30),
        BackendRegisterIR::Sp => Some(31),
        _ => None,
    }
}

fn push_aarch64_word(out: &mut Vec<u8>, word: u32) {
    out.extend_from_slice(&word.to_le_bytes());
}

fn encode_backend_aarch64_ret_bytes() -> Vec<u8> {
    0xD65F03C0u32.to_le_bytes().to_vec()
}

fn encode_backend_aarch64_ret(out: &mut Vec<u8>) {
    push_aarch64_word(out, 0xD65F03C0);
}

fn encode_backend_aarch64_bl_placeholder(out: &mut Vec<u8>) {
    push_aarch64_word(out, 0x9400_0000);
}

fn encode_backend_aarch64_mov_x29_sp(out: &mut Vec<u8>) {
    push_aarch64_word(out, 0x9100_03FD);
}

fn encode_backend_aarch64_stack_imm(out: &mut Vec<u8>, subtract: bool, bytes: usize) -> Option<()> {
    if bytes == 0 {
        return Some(());
    }
    if bytes > 4095 {
        return None;
    }
    let imm12 = (bytes as u32) << 10;
    let base = if subtract { 0xD100_03FF } else { 0x9100_03FF };
    push_aarch64_word(out, base | imm12);
    Some(())
}

fn backend_aarch64_mov_imm_words(imm: i64) -> Vec<u32> {
    let value = imm as u64;
    let mut words = Vec::new();
    let mut emitted_movz = false;
    for hw in 0..4u32 {
        let chunk = ((value >> (hw * 16)) & 0xffff) as u32;
        if chunk == 0 && emitted_movz {
            continue;
        }
        if !emitted_movz {
            push_aarch64_mov_imm_word(&mut words, 0xD280_0000, hw, chunk);
            emitted_movz = true;
        } else if chunk != 0 {
            push_aarch64_mov_imm_word(&mut words, 0xF280_0000, hw, chunk);
        }
    }
    if words.is_empty() {
        push_aarch64_mov_imm_word(&mut words, 0xD280_0000, 0, 0);
    }
    words
}

fn push_aarch64_mov_imm_word(words: &mut Vec<u32>, base: u32, hw: u32, imm16: u32) {
    words.push(base | ((hw & 0b11) << 21) | ((imm16 & 0xffff) << 5));
}

fn encode_backend_aarch64_mov_reg_imm(out: &mut Vec<u8>, dst_reg: u8, imm: i64) {
    for word in backend_aarch64_mov_imm_words(imm) {
        push_aarch64_word(out, word | (dst_reg as u32 & 0b1_1111));
    }
}

fn backend_aarch64_mov_imm_size(imm: i64) -> usize {
    backend_aarch64_mov_imm_words(imm).len() * 4
}

fn encode_backend_mov_reg_imm64_reloc_slot(out: &mut Vec<u8>, dst_reg: u8) -> usize {
    let rex = 0x48 | ((dst_reg >> 3) & 1);
    let imm_offset = out.len() + 2;
    out.push(rex);
    out.push(0xB8 + (dst_reg & 7));
    out.extend_from_slice(&0i64.to_le_bytes());
    imm_offset
}

fn encode_backend_store_imm32_to_mem(
    out: &mut Vec<u8>,
    mem: &EncodedMachineMemAddr,
    imm: i32,
) -> Option<()> {
    encode_reg_mem(out, 0xC7, 0, mem)?;
    out.extend_from_slice(&imm.to_le_bytes());
    Some(())
}

fn estimate_backend_scalar_ops_native_size(ops: &[BackendScalarOpIR]) -> usize {
    ops.iter()
        .map(|op| backend_scalar_op_native_size(op).unwrap_or(4))
        .sum()
}

fn backend_scalar_op_native_size(op: &BackendScalarOpIR) -> Option<usize> {
    match op {
        BackendScalarOpIR::Label { .. } => Some(0),
        BackendScalarOpIR::LoadStringLiteralAddr { .. }
        | BackendScalarOpIR::LoadStringDescriptorAddr { .. } => Some(10),
        BackendScalarOpIR::LoadSymbolMem {
            dst,
            width,
            extension,
            ..
        } => {
            let mut tmp = Vec::new();
            encode_rip_mem_load_reloc_slot(
                &mut tmp,
                backend_register_to_x86(dst)?,
                *width,
                *extension,
            )?;
            Some(tmp.len())
        }
        BackendScalarOpIR::StoreSymbolMem { src, width, .. } => {
            let mut tmp = Vec::new();
            encode_rip_mem_store_reloc_slot(&mut tmp, backend_register_to_x86(src)?, *width)?;
            Some(tmp.len())
        }
        BackendScalarOpIR::LoadGlobalAddr { .. } => Some(10),
        BackendScalarOpIR::LoadGlobal { dst, mem_type, .. } => {
            let addr_reg = if *dst == BackendRegisterIR::R11 {
                BackendRegisterIR::R10
            } else {
                BackendRegisterIR::R11
            };
            let mut tmp = Vec::new();
            encode_backend_mov_reg_imm64_reloc_slot(&mut tmp, backend_register_to_x86(&addr_reg)?);
            encode_reg_mem_load_width_to_reg(
                &mut tmp,
                backend_register_to_x86(dst)?,
                &EncodedMachineMemAddr {
                    base: backend_register_to_x86(&addr_reg)?,
                    index: None,
                    scale: 1,
                    disp: 0,
                },
                mem_type.width,
                mem_type.extension,
            )?;
            Some(tmp.len())
        }
        BackendScalarOpIR::StoreGlobal { src, mem_type, .. } => {
            let addr_reg = if *src == BackendRegisterIR::R11 {
                BackendRegisterIR::R10
            } else {
                BackendRegisterIR::R11
            };
            let mut tmp = Vec::new();
            encode_backend_mov_reg_imm64_reloc_slot(&mut tmp, backend_register_to_x86(&addr_reg)?);
            encode_reg_mem_store_width_from_reg(
                &mut tmp,
                backend_register_to_x86(src)?,
                &EncodedMachineMemAddr {
                    base: backend_register_to_x86(&addr_reg)?,
                    index: None,
                    scale: 1,
                    disp: 0,
                },
                mem_type.width,
            )?;
            Some(tmp.len())
        }
        BackendScalarOpIR::Jump { .. } => Some(5),
        BackendScalarOpIR::JumpIfZero { reg, .. }
        | BackendScalarOpIR::JumpIfNonZero { reg, .. } => {
            let mut tmp = Vec::new();
            encode_backend_test_reg_reg(&mut tmp, backend_register_to_x86(reg)?)?;
            Some(tmp.len() + 6)
        }
        BackendScalarOpIR::CompareJump { left, right, .. } => {
            let mut tmp = Vec::new();
            encode_rr(
                &mut tmp,
                0x39,
                backend_register_to_x86(right)?,
                backend_register_to_x86(left)?,
            );
            Some(tmp.len() + 6)
        }
        BackendScalarOpIR::CompareJumpImm { left, value, .. } => {
            let mut tmp = Vec::new();
            encode_backend_cmp_reg_imm(&mut tmp, backend_register_to_x86(left)?, *value)?;
            Some(tmp.len() + 6)
        }
        BackendScalarOpIR::Call { .. } => Some(5),
        BackendScalarOpIR::CallIndirect { target, .. } => {
            let mut tmp = Vec::new();
            encode_backend_call_reg(&mut tmp, backend_register_to_x86(target)?)?;
            Some(tmp.len())
        }
        BackendScalarOpIR::Trap => Some(2),
        _ => {
            let mut tmp = Vec::new();
            encode_backend_scalar_op_native(op, &mut tmp)?;
            Some(tmp.len())
        }
    }
}

fn backend_function_scalar_label_offsets(
    function: &BackendFunctionUnitIR,
) -> Option<HashMap<String, usize>> {
    let mut labels = HashMap::new();
    let mut offset = 0usize;
    for function_op in &function.ops {
        let BackendFuncOpIR::ScalarOps { ops } = function_op else {
            continue;
        };
        for op in ops {
            if let BackendScalarOpIR::Label { name } = op {
                labels.insert(name.clone(), offset);
            } else {
                offset = offset.checked_add(backend_scalar_op_native_size(op)?)?;
            }
        }
    }
    Some(labels)
}

#[allow(clippy::too_many_arguments)]
fn encode_backend_scalar_ops_native_with_labels(
    ops: &[BackendScalarOpIR],
    labels: &HashMap<String, usize>,
    scalar_stream_base_offset: usize,
    section_name: &str,
    section_base_offset: usize,
    function_symbol: &str,
    out: &mut Vec<u8>,
    relocs: &mut Vec<BackendObjectRelocationIR>,
    literal_symbol_by_value: &mut HashMap<String, String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> Option<()> {
    let capacity = ops.iter().try_fold(0usize, |size, op| {
        size.checked_add(backend_scalar_op_native_size(op)?)
    })?;
    let mut encoded = Vec::with_capacity(capacity);
    for op in ops {
        let current_offset = scalar_stream_base_offset.checked_add(encoded.len())?;
        encode_backend_scalar_op_native_resolved(
            op,
            labels,
            current_offset,
            section_name,
            section_base_offset,
            function_symbol,
            &mut encoded,
            relocs,
            literal_symbol_by_value,
            rodata_entries,
        )?;
    }
    out.extend_from_slice(&encoded);
    Some(())
}

#[allow(clippy::too_many_arguments)]
fn encode_backend_scalar_op_native_resolved(
    op: &BackendScalarOpIR,
    labels: &HashMap<String, usize>,
    current_offset: usize,
    section_name: &str,
    section_base_offset: usize,
    function_symbol: &str,
    out: &mut Vec<u8>,
    relocs: &mut Vec<BackendObjectRelocationIR>,
    literal_symbol_by_value: &mut HashMap<String, String>,
    rodata_entries: &mut Vec<BackendReadOnlyDataEntry>,
) -> Option<()> {
    match op {
        BackendScalarOpIR::Label { .. } => Some(()),
        BackendScalarOpIR::LoadStringLiteralAddr { dst, value } => {
            let dst = backend_register_to_x86(dst)?;
            let symbol = ensure_function_c_string_literal_symbol(
                value,
                function_symbol,
                literal_symbol_by_value,
                rodata_entries,
            );
            let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol,
                addend: 0,
            });
            Some(())
        }
        BackendScalarOpIR::LoadStringDescriptorAddr { dst, value } => {
            let dst = backend_register_to_x86(dst)?;
            let symbol = ensure_function_literal_symbol(
                value,
                function_symbol,
                literal_symbol_by_value,
                rodata_entries,
            );
            let imm_offset = encode_backend_mov_reg_imm64_reloc_slot(out, dst);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol,
                addend: 0,
            });
            Some(())
        }
        BackendScalarOpIR::LoadSymbolMem {
            dst,
            symbol,
            width,
            extension,
            ..
        } => {
            let disp_offset = encode_rip_mem_load_reloc_slot(
                out,
                backend_register_to_x86(dst)?,
                *width,
                *extension,
            )?;
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + disp_offset,
                kind: BackendObjectRelocationKindIR::PcRel32,
                symbol: symbol.clone(),
                addend: -4,
            });
            Some(())
        }
        BackendScalarOpIR::StoreSymbolMem {
            symbol, src, width, ..
        } => {
            let disp_offset =
                encode_rip_mem_store_reloc_slot(out, backend_register_to_x86(src)?, *width)?;
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + disp_offset,
                kind: BackendObjectRelocationKindIR::PcRel32,
                symbol: symbol.clone(),
                addend: -4,
            });
            Some(())
        }
        BackendScalarOpIR::LoadGlobalAddr { dst, symbol } => {
            let imm_offset =
                encode_backend_mov_reg_imm64_reloc_slot(out, backend_register_to_x86(dst)?);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol: symbol.clone(),
                addend: 0,
            });
            Some(())
        }
        BackendScalarOpIR::LoadGlobal {
            dst,
            symbol,
            mem_type,
        } => {
            let addr_reg = if *dst == BackendRegisterIR::R11 {
                BackendRegisterIR::R10
            } else {
                BackendRegisterIR::R11
            };
            let imm_offset =
                encode_backend_mov_reg_imm64_reloc_slot(out, backend_register_to_x86(&addr_reg)?);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol: symbol.clone(),
                addend: 0,
            });
            encode_reg_mem_load_width_to_reg(
                out,
                backend_register_to_x86(dst)?,
                &EncodedMachineMemAddr {
                    base: backend_register_to_x86(&addr_reg)?,
                    index: None,
                    scale: 1,
                    disp: 0,
                },
                mem_type.width,
                mem_type.extension,
            )
        }
        BackendScalarOpIR::StoreGlobal {
            symbol,
            src,
            mem_type,
        } => {
            let addr_reg = if *src == BackendRegisterIR::R11 {
                BackendRegisterIR::R10
            } else {
                BackendRegisterIR::R11
            };
            let imm_offset =
                encode_backend_mov_reg_imm64_reloc_slot(out, backend_register_to_x86(&addr_reg)?);
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + imm_offset,
                kind: BackendObjectRelocationKindIR::Abs64,
                symbol: symbol.clone(),
                addend: 0,
            });
            encode_reg_mem_store_width_from_reg(
                out,
                backend_register_to_x86(src)?,
                &EncodedMachineMemAddr {
                    base: backend_register_to_x86(&addr_reg)?,
                    index: None,
                    scale: 1,
                    disp: 0,
                },
                mem_type.width,
            )
        }
        BackendScalarOpIR::Jump { label } => {
            let target = *labels.get(label)?;
            let disp = backend_rel32_displacement(target, current_offset, 5)?;
            encode_backend_jmp_rel32(out, disp);
            Some(())
        }
        BackendScalarOpIR::JumpIfZero { reg, label } => {
            let target = *labels.get(label)?;
            let reg = backend_register_to_x86(reg)?;
            let mut test = Vec::new();
            encode_backend_test_reg_reg(&mut test, reg)?;
            let disp = backend_rel32_displacement(target, current_offset + test.len(), 6)?;
            out.extend_from_slice(&test);
            encode_backend_jcc_rel32(out, 0x84, disp);
            Some(())
        }
        BackendScalarOpIR::JumpIfNonZero { reg, label } => {
            let target = *labels.get(label)?;
            let reg = backend_register_to_x86(reg)?;
            let mut test = Vec::new();
            encode_backend_test_reg_reg(&mut test, reg)?;
            let disp = backend_rel32_displacement(target, current_offset + test.len(), 6)?;
            out.extend_from_slice(&test);
            encode_backend_jcc_rel32(out, 0x85, disp);
            Some(())
        }
        BackendScalarOpIR::CompareJump {
            op,
            left,
            right,
            jump_if_true,
            label,
        } => {
            let target = *labels.get(label)?;
            let op = if *jump_if_true {
                *op
            } else {
                invert_scalar_compare_op(*op)?
            };
            let mut cmp = Vec::new();
            encode_rr(
                &mut cmp,
                0x39,
                backend_register_to_x86(right)?,
                backend_register_to_x86(left)?,
            );
            let disp = backend_rel32_displacement(target, current_offset + cmp.len(), 6)?;
            out.extend_from_slice(&cmp);
            encode_backend_jcc_rel32(out, scalar_jcc_opcode(op)?, disp);
            Some(())
        }
        BackendScalarOpIR::CompareJumpImm {
            op,
            left,
            value,
            jump_if_true,
            label,
        } => {
            let target = *labels.get(label)?;
            let op = if *jump_if_true {
                *op
            } else {
                invert_scalar_compare_op(*op)?
            };
            let mut cmp = Vec::new();
            encode_backend_cmp_reg_imm(&mut cmp, backend_register_to_x86(left)?, *value)?;
            let disp = backend_rel32_displacement(target, current_offset + cmp.len(), 6)?;
            out.extend_from_slice(&cmp);
            encode_backend_jcc_rel32(out, scalar_jcc_opcode(op)?, disp);
            Some(())
        }
        BackendScalarOpIR::Call { target, .. } => {
            relocs.push(BackendObjectRelocationIR {
                section: section_name.to_string(),
                offset: section_base_offset + out.len() + 1,
                kind: BackendObjectRelocationKindIR::CallNear32,
                symbol: target.clone(),
                addend: -4,
            });
            out.extend_from_slice(&[0xE8, 0x00, 0x00, 0x00, 0x00]);
            Some(())
        }
        BackendScalarOpIR::CallIndirect { target, .. } => {
            encode_backend_call_reg(out, backend_register_to_x86(target)?)
        }
        _ => encode_backend_scalar_op_native(op, out),
    }
}

fn backend_rel32_displacement(target: usize, instr_offset: usize, instr_len: usize) -> Option<i32> {
    let target = isize::try_from(target).ok()?;
    let next = isize::try_from(instr_offset.checked_add(instr_len)?).ok()?;
    i32::try_from(target.checked_sub(next)?).ok()
}

fn encode_backend_jmp_rel32(out: &mut Vec<u8>, disp: i32) {
    out.push(0xE9);
    out.extend_from_slice(&disp.to_le_bytes());
}

fn encode_backend_jcc_rel32(out: &mut Vec<u8>, opcode2: u8, disp: i32) {
    out.push(0x0F);
    out.push(opcode2);
    out.extend_from_slice(&disp.to_le_bytes());
}

fn encode_backend_test_reg_reg(out: &mut Vec<u8>, reg: u8) -> Option<()> {
    encode_rr(out, 0x85, reg, reg);
    Some(())
}

fn encode_backend_scalar_op_native(op: &BackendScalarOpIR, out: &mut Vec<u8>) -> Option<()> {
    match op {
        BackendScalarOpIR::Label { .. }
        | BackendScalarOpIR::LoadStringLiteralAddr { .. }
        | BackendScalarOpIR::LoadStringDescriptorAddr { .. }
        | BackendScalarOpIR::Jump { .. }
        | BackendScalarOpIR::JumpIfZero { .. }
        | BackendScalarOpIR::JumpIfNonZero { .. }
        | BackendScalarOpIR::CompareJump { .. }
        | BackendScalarOpIR::CompareJumpImm { .. }
        | BackendScalarOpIR::Call { .. }
        | BackendScalarOpIR::CallIndirect { .. }
        | BackendScalarOpIR::LoadGlobalAddr { .. }
        | BackendScalarOpIR::LoadSymbolMem { .. }
        | BackendScalarOpIR::StoreSymbolMem { .. }
        | BackendScalarOpIR::LoadGlobal { .. }
        | BackendScalarOpIR::StoreGlobal { .. } => None,
        BackendScalarOpIR::Trap => {
            out.extend_from_slice(&[0x0F, 0x0B]);
            Some(())
        }
        BackendScalarOpIR::LoadImm { dst, value } => {
            let dst = backend_register_to_x86(dst)?;
            encode_backend_mov_reg_imm(out, dst, *value);
            Some(())
        }
        BackendScalarOpIR::MovReg { dst, src } => {
            let dst = backend_register_to_x86(dst)?;
            let src = backend_register_to_x86(src)?;
            encode_rr(out, 0x89, src, dst);
            Some(())
        }
        BackendScalarOpIR::LoadStack { dst, base, offset } => {
            let dst = backend_register_to_x86(dst)?;
            let base = backend_register_to_x86(base)?;
            let mem = EncodedMachineMemAddr {
                base,
                index: None,
                scale: 1,
                disp: isize::try_from(*offset).ok()?,
            };
            encode_reg_mem_mov_rm_to_reg(out, dst, &mem)
        }
        BackendScalarOpIR::StoreStack { base, offset, src } => {
            let src = backend_register_to_x86(src)?;
            let base = backend_register_to_x86(base)?;
            let mem = EncodedMachineMemAddr {
                base,
                index: None,
                scale: 1,
                disp: isize::try_from(*offset).ok()?,
            };
            encode_reg_mem_mov_reg_to_rm(out, src, &mem)
        }
        BackendScalarOpIR::LeaStack { dst, base, offset } => {
            let dst = backend_register_to_x86(dst)?;
            let base = backend_register_to_x86(base)?;
            let mem = EncodedMachineMemAddr {
                base,
                index: None,
                scale: 1,
                disp: isize::try_from(*offset).ok()?,
            };
            encode_reg_mem_lea_to_reg(out, dst, &mem)
        }
        BackendScalarOpIR::LoadMem {
            dst,
            addr,
            width,
            extension,
            volatile: _,
        } => {
            let dst = backend_register_to_x86(dst)?;
            let addr = backend_register_to_x86(addr)?;
            let mem = EncodedMachineMemAddr {
                base: addr,
                index: None,
                scale: 1,
                disp: 0,
            };
            encode_reg_mem_load_width_to_reg(out, dst, &mem, *width, *extension)
        }
        BackendScalarOpIR::StoreMem {
            addr,
            src,
            width,
            volatile: _,
        } => {
            let addr = backend_register_to_x86(addr)?;
            let src = backend_register_to_x86(src)?;
            let mem = EncodedMachineMemAddr {
                base: addr,
                index: None,
                scale: 1,
                disp: 0,
            };
            encode_reg_mem_store_width_from_reg(out, src, &mem, *width)
        }
        BackendScalarOpIR::Unary { op, dst } => {
            let dst = backend_register_to_x86(dst)?;
            match op {
                ScalarUnaryOpIR::Plus => Some(()),
                ScalarUnaryOpIR::Minus => {
                    encode_group_ff_f7(out, 0xF7, 3, dst);
                    Some(())
                }
                ScalarUnaryOpIR::NotBin => {
                    encode_group_ff_f7(out, 0xF7, 2, dst);
                    Some(())
                }
                ScalarUnaryOpIR::Not => {
                    encode_backend_cmp_reg_imm8(out, dst, 0);
                    encode_backend_setcc_reg8(out, 0x94, dst);
                    encode_backend_movzx_reg_reg8(out, dst, dst);
                    Some(())
                }
                ScalarUnaryOpIR::TryPropagate => Some(()),
            }
        }
        BackendScalarOpIR::Binary { op, dst, src } => {
            let dst = backend_register_to_x86(dst)?;
            let src = backend_register_to_x86(src)?;
            match op {
                ScalarBinaryOpIR::Plus => {
                    if (src & 7) == 4 {
                        encode_rr(out, 0x01, src, dst);
                    } else {
                        let mem = EncodedMachineMemAddr {
                            base: dst,
                            index: Some(src),
                            scale: 1,
                            disp: 0,
                        };
                        encode_reg_mem_lea_to_reg(out, dst, &mem)?;
                    }
                }
                ScalarBinaryOpIR::Minus => encode_rr(out, 0x29, src, dst),
                ScalarBinaryOpIR::Star => encode_rr_0f(out, 0xAF, dst, src),
                ScalarBinaryOpIR::BitAnd | ScalarBinaryOpIR::AndAnd => {
                    encode_rr(out, 0x21, src, dst)
                }
                ScalarBinaryOpIR::BitOr | ScalarBinaryOpIR::OrOr => encode_rr(out, 0x09, src, dst),
                ScalarBinaryOpIR::BitXor => encode_rr(out, 0x31, src, dst),
                ScalarBinaryOpIR::ShiftLeft => {
                    encode_rr(out, 0x89, src, 1);
                    encode_shift_cl(out, 4, dst);
                }
                ScalarBinaryOpIR::ShiftRight => {
                    encode_rr(out, 0x89, src, 1);
                    encode_shift_cl(out, 7, dst);
                }
                ScalarBinaryOpIR::ShiftRightLogical => {
                    encode_rr(out, 0x89, src, 1);
                    encode_shift_cl(out, 5, dst);
                }
                _ => return None,
            }
            Some(())
        }
        BackendScalarOpIR::CheckedAddI64 { dst, src } => {
            let dst = backend_register_to_x86(dst)?;
            let src = backend_register_to_x86(src)?;
            // ADD is mandatory here: LEA does not materialize OF. JNO skips
            // the two-byte UD2 only when the signed i64 result is exact.
            encode_rr(out, 0x01, src, dst);
            out.extend_from_slice(&[0x71, 0x02, 0x0F, 0x0B]);
            Some(())
        }
        BackendScalarOpIR::BinaryImm { op, dst, value } => {
            encode_backend_binary_reg_imm(out, *op, backend_register_to_x86(dst)?, *value)
        }
        BackendScalarOpIR::ZeroExtendByte { dst, src } => {
            encode_backend_movzx_reg_reg8(
                out,
                backend_register_to_x86(dst)?,
                backend_register_to_x86(src)?,
            );
            Some(())
        }
        BackendScalarOpIR::CompareSet { op, dst, src } => {
            let dst = backend_register_to_x86(dst)?;
            let src = backend_register_to_x86(src)?;
            encode_rr(out, 0x39, src, dst);
            encode_backend_setcc_reg8(out, scalar_setcc_opcode(*op)?, dst);
            encode_backend_movzx_reg_reg8(out, dst, dst);
            Some(())
        }
        BackendScalarOpIR::CompareMove {
            op,
            dst,
            src,
            left,
            right,
        } => {
            encode_rr(
                out,
                0x39,
                backend_register_to_x86(right)?,
                backend_register_to_x86(left)?,
            );
            encode_rr_0f(
                out,
                scalar_cmov_opcode(*op)?,
                backend_register_to_x86(dst)?,
                backend_register_to_x86(src)?,
            );
            Some(())
        }
        BackendScalarOpIR::Cqo => {
            out.extend_from_slice(&[0x48, 0x99]);
            Some(())
        }
        BackendScalarOpIR::Idiv { src } => {
            let src = backend_register_to_x86(src)?;
            encode_group_ff_f7(out, 0xF7, 7, src);
            Some(())
        }
        BackendScalarOpIR::Push { src } => {
            let src = backend_register_to_x86(src)?;
            encode_push_reg_num(src, out);
            Some(())
        }
        BackendScalarOpIR::Pop { dst } => {
            let dst = backend_register_to_x86(dst)?;
            encode_pop_reg_num(dst, out);
            Some(())
        }
    }
}

fn encode_backend_call_reg(out: &mut Vec<u8>, reg: u8) -> Option<()> {
    if reg > 15 {
        return None;
    }
    if reg >= 8 {
        out.push(0x41);
    }
    out.push(0xFF);
    out.push(0xD0 | (reg & 7));
    Some(())
}

fn scalar_setcc_opcode(op: ScalarBinaryOpIR) -> Option<u8> {
    match op {
        ScalarBinaryOpIR::EqEq => Some(0x94),
        ScalarBinaryOpIR::NotEq => Some(0x95),
        ScalarBinaryOpIR::Less => Some(0x9C),
        ScalarBinaryOpIR::GreaterEq => Some(0x9D),
        ScalarBinaryOpIR::LessEq => Some(0x9E),
        ScalarBinaryOpIR::Greater => Some(0x9F),
        _ => None,
    }
}

fn scalar_jcc_opcode(op: ScalarBinaryOpIR) -> Option<u8> {
    match op {
        ScalarBinaryOpIR::EqEq => Some(0x84),
        ScalarBinaryOpIR::NotEq => Some(0x85),
        ScalarBinaryOpIR::Less => Some(0x8C),
        ScalarBinaryOpIR::GreaterEq => Some(0x8D),
        ScalarBinaryOpIR::LessEq => Some(0x8E),
        ScalarBinaryOpIR::Greater => Some(0x8F),
        _ => None,
    }
}

fn scalar_cmov_opcode(op: ScalarBinaryOpIR) -> Option<u8> {
    match op {
        ScalarBinaryOpIR::EqEq => Some(0x44),
        ScalarBinaryOpIR::NotEq => Some(0x45),
        ScalarBinaryOpIR::Less => Some(0x4C),
        ScalarBinaryOpIR::GreaterEq => Some(0x4D),
        ScalarBinaryOpIR::LessEq => Some(0x4E),
        ScalarBinaryOpIR::Greater => Some(0x4F),
        _ => None,
    }
}

fn encode_backend_group1_reg_imm(
    out: &mut Vec<u8>,
    extension: u8,
    reg: u8,
    value: i64,
) -> Option<()> {
    if reg > 15 || extension > 7 {
        return None;
    }
    out.push(0x48 | ((reg >> 3) & 1));
    if let Ok(value) = i8::try_from(value) {
        out.push(0x83);
        out.push(0xC0 | (extension << 3) | (reg & 7));
        out.push(value as u8);
        return Some(());
    }
    let value = i32::try_from(value).ok()?;
    out.push(0x81);
    out.push(0xC0 | (extension << 3) | (reg & 7));
    out.extend_from_slice(&value.to_le_bytes());
    Some(())
}

fn encode_backend_binary_reg_imm(
    out: &mut Vec<u8>,
    op: ScalarBinaryOpIR,
    reg: u8,
    value: i64,
) -> Option<()> {
    match op {
        ScalarBinaryOpIR::Plus => encode_backend_group1_reg_imm(out, 0, reg, value),
        ScalarBinaryOpIR::BitOr => encode_backend_group1_reg_imm(out, 1, reg, value),
        ScalarBinaryOpIR::BitAnd => encode_backend_group1_reg_imm(out, 4, reg, value),
        ScalarBinaryOpIR::Minus => encode_backend_group1_reg_imm(out, 5, reg, value),
        ScalarBinaryOpIR::BitXor => encode_backend_group1_reg_imm(out, 6, reg, value),
        ScalarBinaryOpIR::Star => {
            if reg > 15 {
                return None;
            }
            out.push(0x48 | (((reg >> 3) & 1) << 2) | ((reg >> 3) & 1));
            if let Ok(value) = i8::try_from(value) {
                out.push(0x6B);
                out.push(0xC0 | ((reg & 7) << 3) | (reg & 7));
                out.push(value as u8);
                return Some(());
            }
            let value = i32::try_from(value).ok()?;
            out.push(0x69);
            out.push(0xC0 | ((reg & 7) << 3) | (reg & 7));
            out.extend_from_slice(&value.to_le_bytes());
            Some(())
        }
        ScalarBinaryOpIR::ShiftLeft
        | ScalarBinaryOpIR::ShiftRight
        | ScalarBinaryOpIR::ShiftRightLogical => {
            let value = u8::try_from(value).ok()?;
            let extension = match op {
                ScalarBinaryOpIR::ShiftLeft => 4,
                ScalarBinaryOpIR::ShiftRightLogical => 5,
                ScalarBinaryOpIR::ShiftRight => 7,
                _ => unreachable!(),
            };
            out.push(0x48 | ((reg >> 3) & 1));
            out.push(0xC1);
            out.push(0xC0 | (extension << 3) | (reg & 7));
            out.push(value);
            Some(())
        }
        _ => None,
    }
}

fn encode_backend_cmp_reg_imm(out: &mut Vec<u8>, reg: u8, value: i64) -> Option<()> {
    encode_backend_group1_reg_imm(out, 7, reg, value)
}

fn encode_backend_cmp_reg_imm8(out: &mut Vec<u8>, reg: u8, imm: i8) {
    let rex = 0x48 | ((reg >> 3) & 1);
    out.push(rex);
    out.push(0x83);
    out.push(0b11_111_000 | (reg & 7));
    out.push(imm as u8);
}

fn encode_backend_setcc_reg8(out: &mut Vec<u8>, opcode2: u8, dst: u8) {
    let rex = 0x40 | ((dst >> 3) & 1);
    if dst >= 4 {
        out.push(rex);
    }
    out.push(0x0F);
    out.push(opcode2);
    out.push(0b11_000_000 | (dst & 7));
}

fn encode_backend_movzx_reg_reg8(out: &mut Vec<u8>, dst: u8, src: u8) {
    let rex = 0x48 | (((dst >> 3) & 1) << 2) | ((src >> 3) & 1);
    out.push(rex);
    out.push(0x0F);
    out.push(0xB6);
    out.push(0b11_000_000 | ((dst & 7) << 3) | (src & 7));
}

fn parse_backend_number_literal(raw: &str) -> Option<i64> {
    let compact = raw.trim().replace('_', "");
    if compact.is_empty() {
        return None;
    }
    let (negative, body) = if let Some(rest) = compact.strip_prefix('-') {
        (true, rest)
    } else if let Some(rest) = compact.strip_prefix('+') {
        (false, rest)
    } else {
        (false, compact.as_str())
    };

    let value = if let Some(hex) = body.strip_prefix("0x").or_else(|| body.strip_prefix("0X")) {
        i64::from_str_radix(hex, 16).ok()?
    } else if let Some(bin) = body.strip_prefix("0b").or_else(|| body.strip_prefix("0B")) {
        i64::from_str_radix(bin, 2).ok()?
    } else {
        body.parse::<i64>().ok()?
    };

    if negative {
        value.checked_neg()
    } else {
        Some(value)
    }
}

fn backend_register_to_x86(reg: &BackendRegisterIR) -> Option<u8> {
    match reg {
        BackendRegisterIR::Rax => Some(0),
        BackendRegisterIR::Rcx => Some(1),
        BackendRegisterIR::Rdx => Some(2),
        BackendRegisterIR::Rbx => Some(3),
        BackendRegisterIR::Rsp => Some(4),
        BackendRegisterIR::Rbp => Some(5),
        BackendRegisterIR::Rsi => Some(6),
        BackendRegisterIR::Rdi => Some(7),
        BackendRegisterIR::R8 => Some(8),
        BackendRegisterIR::R9 => Some(9),
        BackendRegisterIR::R10 => Some(10),
        BackendRegisterIR::R11 => Some(11),
        BackendRegisterIR::R12 => Some(12),
        BackendRegisterIR::R13 => Some(13),
        BackendRegisterIR::R14 => Some(14),
        BackendRegisterIR::R15 => Some(15),
        BackendRegisterIR::X0
        | BackendRegisterIR::X1
        | BackendRegisterIR::X2
        | BackendRegisterIR::X3
        | BackendRegisterIR::X4
        | BackendRegisterIR::X5
        | BackendRegisterIR::X6
        | BackendRegisterIR::X7
        | BackendRegisterIR::X8
        | BackendRegisterIR::X9
        | BackendRegisterIR::X10
        | BackendRegisterIR::X11
        | BackendRegisterIR::X12
        | BackendRegisterIR::X13
        | BackendRegisterIR::X14
        | BackendRegisterIR::X15
        | BackendRegisterIR::X16
        | BackendRegisterIR::X17
        | BackendRegisterIR::X18
        | BackendRegisterIR::X19
        | BackendRegisterIR::X20
        | BackendRegisterIR::X21
        | BackendRegisterIR::X22
        | BackendRegisterIR::X23
        | BackendRegisterIR::X24
        | BackendRegisterIR::X25
        | BackendRegisterIR::X26
        | BackendRegisterIR::X27
        | BackendRegisterIR::X28
        | BackendRegisterIR::X29
        | BackendRegisterIR::X30
        | BackendRegisterIR::Sp => None,
    }
}

fn emit_primitive_object_unit(
    primitive: &BackendPrimitiveUnitIR,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
) {
    let section_name = format!(".meta.{}", primitive.symbol);
    symbols.push(BackendObjectSymbolIR {
        name: primitive.symbol.clone(),
        section: section_name.clone(),
        offset: 0,
        visibility: BackendSymbolVisibilityIR::Global,
    });

    let target = primitive.target.as_deref().unwrap_or("unspecified-target");
    let mut lines = vec![
        format!("target {}", target),
        format!("bridges {}", primitive.bridges.len()),
        format!("capabilities {}", primitive.capabilities.len()),
        format!(
            "capability_contracts {}",
            primitive.capability_contracts.len()
        ),
        format!("bitfields {}", primitive.bitfield_contracts.len()),
        format!("operations {}", primitive.operations.len()),
        format!(
            "operation_contracts {}",
            primitive.operation_contracts.len()
        ),
        format!("anchors {}", primitive.anchors.len()),
        format!("windows {}", primitive.windows.len()),
        format!("window_contracts {}", primitive.window_contracts.len()),
        format!("signals {}", primitive.signals.len()),
        format!("signal_contracts {}", primitive.signal_contracts.len()),
        format!("ports {}", primitive.ports.len()),
        format!("port_contracts {}", primitive.port_contracts.len()),
        format!("signatures {}", primitive.signatures.len()),
        format!(
            "signature_contracts {}",
            primitive.signature_contracts.len()
        ),
        format!("entries {}", primitive.entries.len()),
        format!("entry_contracts {}", primitive.entry_contracts.len()),
    ];

    for bridge in &primitive.bridges {
        lines.push(format!(
            "bridge {}",
            render_backend_primitive_bridge_target(bridge)
        ));
    }
    for bitfield in &primitive.bitfield_contracts {
        lines.push(format!(
            "bitfield {} base={} entries={}",
            bitfield.name, bitfield.base, bitfield.entry_count
        ));
    }
    for capability in &primitive.capability_contracts {
        lines.push(format!(
            "capability {} allow={} deny={}",
            capability.name,
            capability.allow.len(),
            capability.deny.len()
        ));
    }
    for operation in &primitive.operation_contracts {
        let name = operation.name.join(".");
        lines.push(format!(
            "operation {} clauses={} capability_refs={} reads_refs={} writes_refs={}",
            name,
            operation.clause_count,
            operation.capability_refs.len(),
            operation.reads_refs.len(),
            operation.writes_refs.len()
        ));
    }
    for window in &primitive.window_contracts {
        lines.push(format!(
            "window {} clauses={} requires_signature_refs={}",
            window.name.join("."),
            window.clause_count,
            window.requires_signature_refs.len()
        ));
    }
    for signal in &primitive.signal_contracts {
        lines.push(format!(
            "signal {} clauses={} source_refs={} field_refs={}",
            signal.name.join("."),
            signal.clause_count,
            signal.source_refs.len(),
            signal.field_refs.len()
        ));
    }
    for port in &primitive.port_contracts {
        lines.push(format!(
            "port {} clauses={} bus_refs={}",
            port.name.join("."),
            port.clause_count,
            port.bus_refs.len()
        ));
    }
    for signature in &primitive.signature_contracts {
        lines.push(format!(
            "signature {} clauses={} window_refs={}",
            signature.name.join("."),
            signature.clause_count,
            signature.window_refs.len()
        ));
    }
    for entry in &primitive.entry_contracts {
        lines.push(format!(
            "entry {} clauses={} anchor_refs={} requires_refs={}",
            entry.name.join("."),
            entry.clause_count,
            entry.anchor_refs.len(),
            entry.requires_refs.len()
        ));
    }
    let payload = lines.join("\n").into_bytes();
    let size_bytes = payload.len();

    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::PrimitiveMeta,
        unit: primitive.symbol.clone(),
        lines,
        bytes: Some(payload),
        size_bytes,
        align_bytes: 1,
        comdat: None,
    });
}

fn emit_type_contract_unit(
    container: &str,
    contracts: &[TypeContractIR],
    abi_layouts: Vec<TypeAbiLayoutIR>,
) -> BackendTypeContractUnitIR {
    fn clause_item_op(
        type_name: &str,
        kind: TypeContractClauseKindIR,
        item: Option<String>,
    ) -> BackendTypeContractOpIR {
        match kind {
            TypeContractClauseKindIR::Layout => BackendTypeContractOpIR::LayoutClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Invariant => BackendTypeContractOpIR::InvariantClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Bounds => BackendTypeContractOpIR::BoundsClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Constructure => BackendTypeContractOpIR::ConstructureClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Destructure => BackendTypeContractOpIR::DestructureClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Copy => BackendTypeContractOpIR::CopyClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Clone => BackendTypeContractOpIR::CloneClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Move => BackendTypeContractOpIR::MoveClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Ffi => BackendTypeContractOpIR::FfiClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Ownership => BackendTypeContractOpIR::OwnershipClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Nullability => BackendTypeContractOpIR::NullabilityClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Methods => BackendTypeContractOpIR::MethodsClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Associated => BackendTypeContractOpIR::AssociatedClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Validate => BackendTypeContractOpIR::ValidateClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Drop => BackendTypeContractOpIR::DropClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Default => BackendTypeContractOpIR::DefaultClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Compare => BackendTypeContractOpIR::CompareClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Hash => BackendTypeContractOpIR::HashClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Debug => BackendTypeContractOpIR::DebugClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Stable => BackendTypeContractOpIR::StableClause {
                ty: type_name.to_string(),
                item,
            },
            TypeContractClauseKindIR::Fields => unreachable!("fields handled by dedicated opcodes"),
        }
    }

    fn build_type_contract_ops(contracts: &[TypeContractIR]) -> Vec<BackendTypeContractOpIR> {
        let mut ops = Vec::new();
        for contract in contracts {
            let type_name = contract.name.clone();
            ops.push(BackendTypeContractOpIR::TypeDeclStart {
                ty: type_name.clone(),
                kind: contract.kind,
                generic_param_count: contract.generic_params.len(),
                variant_count: contract.variants.len(),
            });

            for variant in &contract.variants {
                ops.push(BackendTypeContractOpIR::VariantDecl {
                    ty: type_name.clone(),
                    variant: variant.name.clone(),
                    payload_count: variant.payload.len(),
                });
                for field in &variant.payload {
                    ops.push(BackendTypeContractOpIR::VariantPayloadField {
                        ty: type_name.clone(),
                        variant: variant.name.clone(),
                        field: field.name.clone(),
                        field_ty: field.ty.clone(),
                    });
                }
            }

            for clause in &contract.clauses {
                match clause.kind {
                    TypeContractClauseKindIR::Fields => {
                        let first_visibility =
                            clause.fields.first().and_then(|field| field.visibility);
                        let visibility =
                            first_visibility.unwrap_or(TypeContractVisibilityIR::Public);
                        match visibility {
                            TypeContractVisibilityIR::Public => {
                                ops.push(BackendTypeContractOpIR::FieldsPublicDeclared {
                                    ty: type_name.clone(),
                                    field_count: clause.fields.len(),
                                });
                                for field in &clause.fields {
                                    ops.push(BackendTypeContractOpIR::FieldsPublicField {
                                        ty: type_name.clone(),
                                        field: field.name.clone(),
                                        field_ty: field.ty.clone(),
                                    });
                                }
                            }
                            TypeContractVisibilityIR::Private => {
                                ops.push(BackendTypeContractOpIR::FieldsPrivateDeclared {
                                    ty: type_name.clone(),
                                    field_count: clause.fields.len(),
                                });
                                for field in &clause.fields {
                                    ops.push(BackendTypeContractOpIR::FieldsPrivateField {
                                        ty: type_name.clone(),
                                        field: field.name.clone(),
                                        field_ty: field.ty.clone(),
                                    });
                                }
                            }
                            TypeContractVisibilityIR::Internal => {
                                ops.push(BackendTypeContractOpIR::FieldsInternalDeclared {
                                    ty: type_name.clone(),
                                    field_count: clause.fields.len(),
                                });
                                for field in &clause.fields {
                                    ops.push(BackendTypeContractOpIR::FieldsInternalField {
                                        ty: type_name.clone(),
                                        field: field.name.clone(),
                                        field_ty: field.ty.clone(),
                                    });
                                }
                            }
                            TypeContractVisibilityIR::Strictly => {
                                ops.push(BackendTypeContractOpIR::FieldsStrictlyDeclared {
                                    ty: type_name.clone(),
                                    field_count: clause.fields.len(),
                                });
                                for field in &clause.fields {
                                    ops.push(BackendTypeContractOpIR::FieldsStrictlyField {
                                        ty: type_name.clone(),
                                        field: field.name.clone(),
                                        field_ty: field.ty.clone(),
                                    });
                                }
                            }
                        }
                    }
                    _ => {
                        if clause.items.is_empty() {
                            ops.push(clause_item_op(&type_name, clause.kind, None));
                        } else {
                            for item in &clause.items {
                                ops.push(clause_item_op(
                                    &type_name,
                                    clause.kind,
                                    Some(item.clone()),
                                ));
                            }
                        }
                    }
                }
            }

            ops.push(BackendTypeContractOpIR::TypeDeclEnd {
                ty: type_name.clone(),
            });
        }
        ops
    }

    let mapped_contracts = contracts
        .iter()
        .map(|contract| {
            let field_count = contract
                .clauses
                .iter()
                .filter(|clause| clause.kind == TypeContractClauseKindIR::Fields)
                .map(|clause| clause.fields.len())
                .sum();

            BackendTypeContractIR {
                name: contract.name.clone(),
                kind: contract.kind,
                generic_param_count: contract.generic_params.len(),
                variant_count: contract.variants.len(),
                field_count,
                clause_contracts: contract
                    .clauses
                    .iter()
                    .map(|clause| BackendTypeContractClauseIR {
                        kind: clause.kind,
                        field_count: clause.fields.len(),
                        item_count: clause.items.len(),
                    })
                    .collect(),
            }
        })
        .collect();
    let ops = build_type_contract_ops(contracts);

    BackendTypeContractUnitIR {
        symbol: format!("{container}.type_contracts"),
        container: container.to_string(),
        contracts: mapped_contracts,
        abi_layouts,
        ops,
    }
}

fn emit_type_contract_object_unit(
    type_contract: &BackendTypeContractUnitIR,
    sections: &mut Vec<BackendObjectSectionIR>,
    symbols: &mut Vec<BackendObjectSymbolIR>,
) {
    let section_name = format!(".meta.type.{}", type_contract.container);
    symbols.push(BackendObjectSymbolIR {
        name: type_contract.symbol.clone(),
        section: section_name.clone(),
        offset: 0,
        visibility: BackendSymbolVisibilityIR::Global,
    });

    let mut lines = vec![
        format!("container {}", type_contract.container),
        format!("contracts {}", type_contract.contracts.len()),
    ];

    for contract in &type_contract.contracts {
        lines.push(format!(
            "type {} kind={} generics={} variants={} fields={} clauses={}",
            contract.name,
            render_type_contract_kind(contract.kind),
            contract.generic_param_count,
            contract.variant_count,
            contract.field_count,
            contract.clause_contracts.len()
        ));
        for clause in &contract.clause_contracts {
            lines.push(format!(
                "type_clause {} kind={} fields={} items={}",
                contract.name,
                render_type_contract_clause_kind(clause.kind),
                clause.field_count,
                clause.item_count
            ));
        }
    }
    lines.push(format!("abi_layouts {}", type_contract.abi_layouts.len()));
    for layout in &type_contract.abi_layouts {
        lines.push(format!(
            "type_abi {} kind={} status={} size={} align={} fields={} fingerprint={}",
            layout.qualified_name,
            render_type_contract_kind(layout.kind),
            layout.status,
            layout.size_bytes,
            layout.align_bytes,
            layout.field_count,
            layout.fingerprint
        ));
        for field in &layout.fields {
            lines.push(format!(
                "type_abi_field {}.{} index={} ty={} llvm={} offset={} size={} align={}",
                layout.qualified_name,
                field.name,
                field.index,
                field.nc_type,
                field.llvm_type,
                field.offset_bytes,
                field.size_bytes,
                field.align_bytes
            ));
        }
    }
    lines.push(format!("ops {}", type_contract.ops.len()));
    for op in &type_contract.ops {
        lines.push(format!("tc_op {}", render_backend_type_contract_op(op)));
    }

    let payload = lines.join("\n").into_bytes();
    let size_bytes = payload.len();
    sections.push(BackendObjectSectionIR {
        name: section_name,
        kind: BackendObjectSectionKindIR::TypeMeta,
        unit: type_contract.symbol.clone(),
        lines,
        bytes: Some(payload),
        size_bytes,
        align_bytes: 1,
        comdat: None,
    });
}

#[allow(clippy::too_many_arguments)]
fn emit_function_unit(
    container: &str,
    f: &FunctionIR,
    source_contract: &SourceExecutionContract,
    local_functions: &HashSet<String>,
    local_function_return_types: &HashMap<String, String>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
    scalar_globals: &[BackendFunctionGlobalSymbolIR],
    array_globals: &[BackendFunctionArrayGlobalSymbolIR],
    dynamic_globals: &[BackendFunctionDynamicGlobalSymbolIR],
    struct_globals: &[BackendFunctionStructGlobalSymbolIR],
) -> BackendFunctionUnitIR {
    let symbol = format!("{container}.{}", f.name);
    let source_statement_count = count_function_body_statements(&f.body);
    let scalar_return_imm = function_scalar_return_imm(f, scalar_globals);
    let scalar_reg_stack_plan = if scalar_return_imm.is_none() {
        function_scalar_reg_stack_plan(
            f,
            source_contract,
            &symbol,
            container,
            local_functions,
            local_function_return_types,
            struct_layouts,
            scalar_globals,
            array_globals,
            dynamic_globals,
            struct_globals,
        )
    } else {
        None
    };
    let lowering_route = if source_statement_count == 0 {
        BackendFunctionLoweringRouteIR::EmptyBody
    } else if scalar_return_imm.is_some() {
        BackendFunctionLoweringRouteIR::ImmediateReturn
    } else if scalar_reg_stack_plan.is_some() {
        BackendFunctionLoweringRouteIR::ScalarRegStack
    } else {
        BackendFunctionLoweringRouteIR::Deferred
    };
    let lowering_coverage = BackendFunctionLoweringCoverageIR {
        source_statements: source_statement_count,
        materialized_statements: if lowering_route == BackendFunctionLoweringRouteIR::Deferred {
            0
        } else {
            source_statement_count
        },
        route: lowering_route,
    };
    let mut plan = f.backend_plan.clone();
    if let Some(scalar_plan) = &scalar_reg_stack_plan {
        for reg in &scalar_plan.callee_saved_registers {
            if !plan.frame_layout.callee_saved.contains(reg) {
                plan.frame_layout.callee_saved.push(reg.clone());
            }
        }
        plan.frame_layout.callee_saved_bytes =
            plan.frame_layout.callee_saved.len() * plan.data_layout.word_bytes;
        if scalar_plan.outgoing_arg_bytes > plan.frame_layout.outgoing_arg_bytes {
            plan.frame_layout.outgoing_arg_bytes = scalar_plan.outgoing_arg_bytes;
        }
        if scalar_plan.stack_bytes > plan.frame_layout.local_spill_bytes {
            plan.frame_layout.local_spill_bytes = scalar_plan.stack_bytes;
        }
        let payload_bytes = plan.frame_layout.outgoing_arg_bytes
            + plan.frame_layout.bridge_scratch_bytes
            + plan.frame_layout.local_spill_bytes;
        let aligned_payload = align_up(payload_bytes, plan.frame_layout.stack_align_bytes);
        plan.frame_layout.total_bytes = plan.frame_layout.callee_saved_bytes + aligned_payload;
    }
    let has_native_calls = !plan.call_sites.is_empty()
        || scalar_reg_stack_plan.as_ref().is_some_and(|scalar_plan| {
            scalar_plan
                .ops
                .iter()
                .any(|op| matches!(op, BackendScalarOpIR::Call { .. }))
        });
    let frame_pointer_reg =
        backend_frame_pointer_register_for_calling_convention(&plan.calling_convention);
    let mut ops = Vec::new();
    ops.push(BackendFuncOpIR::Label(symbol.clone()));

    for reg in &plan.frame_layout.callee_saved {
        ops.push(BackendFuncOpIR::SaveCallee(reg.clone()));
        if reg == &frame_pointer_reg {
            // Stabilize incoming stack-arg addressing for call-arg marshalling.
            ops.push(BackendFuncOpIR::SetFramePointer);
        }
    }

    let mut reserve_bytes = plan
        .frame_layout
        .total_bytes
        .saturating_sub(plan.frame_layout.callee_saved_bytes);
    if has_native_calls && plan.target == BackendTargetIR::X86_64 {
        let aligned_reserve = align_x86_64_call_frame_reserve(
            reserve_bytes,
            plan.frame_layout.callee_saved_bytes,
            plan.frame_layout.stack_align_bytes,
        );
        if aligned_reserve > reserve_bytes {
            let delta = aligned_reserve - reserve_bytes;
            plan.frame_layout.local_spill_bytes += delta;
            plan.frame_layout.total_bytes += delta;
            reserve_bytes = aligned_reserve;
        }
    }
    if reserve_bytes > 0 {
        ops.push(BackendFuncOpIR::ReserveStack(reserve_bytes));
    }

    if scalar_reg_stack_plan.is_none() {
        for site in &plan.call_sites {
            if site.bridge != BackendBridgeKindIR::None {
                ops.push(BackendFuncOpIR::BridgeEnter {
                    kind: site.bridge.clone(),
                    target_mode: site.target_mode.clone(),
                    scratch_bytes: site.bridge_scratch_bytes,
                });
            }

            if site.stack_arg_bytes > 0 {
                ops.push(BackendFuncOpIR::ReserveCallStack(site.stack_arg_bytes));
            }

            for arg in &site.arg_locations {
                ops.push(BackendFuncOpIR::PrepareCallArg {
                    index: arg.index,
                    pass_class: arg.pass_class.clone(),
                    source: arg.source.clone(),
                    location: arg.location.clone(),
                    materialized: true,
                });
            }

            let call_target = if !site.target.contains('.')
                && (matches!(
                    site.kind,
                    FunctionCallLinkKindIR::Local
                        | FunctionCallLinkKindIR::SameFile
                        | FunctionCallLinkKindIR::Unknown
                ))
                && local_functions.contains(&site.target)
            {
                format!("{container}.{}", site.target)
            } else {
                site.target.clone()
            };
            ops.push(BackendFuncOpIR::Call {
                target: call_target,
                arg_count: site.arg_count,
                stack_arg_bytes: site.stack_arg_bytes,
            });

            if site.stack_arg_bytes > 0 {
                ops.push(BackendFuncOpIR::ReleaseCallStack(site.stack_arg_bytes));
            }

            if site.bridge != BackendBridgeKindIR::None {
                ops.push(BackendFuncOpIR::BridgeLeave {
                    kind: site.bridge.clone(),
                });
            }
        }
    }

    if let Some(value) = scalar_return_imm {
        ops.push(BackendFuncOpIR::ReturnImm { value });
    } else if let Some(scalar_plan) = scalar_reg_stack_plan.as_ref() {
        append_scalar_plan_ops(&mut ops, scalar_plan);
    }

    if reserve_bytes > 0 {
        ops.push(BackendFuncOpIR::ReleaseStack(reserve_bytes));
    }

    for reg in plan.frame_layout.callee_saved.iter().rev() {
        ops.push(BackendFuncOpIR::RestoreCallee(reg.clone()));
    }
    ops.push(BackendFuncOpIR::Ret);

    BackendFunctionUnitIR {
        symbol,
        container: container.to_string(),
        visibility: f.visibility,
        effects: f.effects.clone(),
        mode: f.abi.tag.mode_class.clone(),
        plan,
        lowering_coverage,
        register_allocation: scalar_reg_stack_plan
            .as_ref()
            .map(|plan| plan.register_allocation.clone())
            .unwrap_or_default(),
        scalar_globals: scalar_globals.to_vec(),
        ops,
    }
}

fn append_scalar_plan_ops(ops: &mut Vec<BackendFuncOpIR>, plan: &FunctionScalarRegStackPlan) {
    let mut cursor = 0usize;
    for marker in &plan.function_markers {
        let marker_index = marker.op_index.min(plan.ops.len());
        if cursor < marker_index {
            ops.push(BackendFuncOpIR::ScalarOps {
                ops: plan.ops[cursor..marker_index].to_vec(),
            });
        }
        ops.push(marker.op.clone());
        cursor = marker_index;
    }
    if cursor < plan.ops.len() {
        ops.push(BackendFuncOpIR::ScalarOps {
            ops: plan.ops[cursor..].to_vec(),
        });
    }
}

fn count_function_body_statements(statements: &[StatementIR]) -> usize {
    statements
        .iter()
        .map(|statement| {
            1 + match statement {
                StatementIR::If {
                    then_body,
                    else_body,
                    ..
                } => {
                    count_function_body_statements(then_body)
                        + count_function_body_statements(else_body)
                }
                StatementIR::While { body, .. }
                | StatementIR::DoWhile { body, .. }
                | StatementIR::ForRange { body, .. }
                | StatementIR::Loop { body }
                | StatementIR::RepeatUntil { body, .. }
                | StatementIR::RepeatCount { body, .. }
                | StatementIR::Defer { body } => count_function_body_statements(body),
                StatementIR::ForClassic {
                    init, step, body, ..
                } => {
                    init.as_deref().map_or(0, |stmt| {
                        count_function_body_statements(std::slice::from_ref(stmt))
                    }) + step.as_deref().map_or(0, |stmt| {
                        count_function_body_statements(std::slice::from_ref(stmt))
                    }) + count_function_body_statements(body)
                }
                StatementIR::Labeled { stmt, .. } => {
                    count_function_body_statements(std::slice::from_ref(stmt.as_ref()))
                }
                StatementIR::Match { cases, default, .. } => {
                    cases
                        .iter()
                        .map(|(_, body)| count_function_body_statements(body))
                        .sum::<usize>()
                        + count_function_body_statements(default)
                }
                _ => 0,
            }
        })
        .sum()
}

fn emit_container_state_globals_unit(
    container: &str,
    stc_init_body: &[StatementIR],
    surface_descriptors: &[MctSurfaceDescriptorIR],
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Option<BackendStcGlobalsUnitIR> {
    let mut globals_by_name: HashMap<String, BackendStcGlobalIR> = HashMap::new();
    let mut const_env: HashMap<String, ScalarEvalValue> = HashMap::new();
    let mut unsupported_init_count = 0usize;
    let container_symbol = sanitize_symbol_component(container);

    for descriptor in surface_descriptors {
        if descriptor.container != container
            || !matches!(descriptor.construct.as_str(), "stc.symbol" | "local.var")
        {
            continue;
        }
        let (Some(name), Some(ty)) = (&descriptor.symbol, &descriptor.nc_type) else {
            continue;
        };
        let target_symbol = sanitize_symbol_component(name);
        let storage = backend_storage_contract_from_descriptor(descriptor);
        let symbol_visibility = backend_storage_symbol_visibility(descriptor, &storage);
        globals_by_name
            .entry(name.clone())
            .or_insert_with(|| BackendStcGlobalIR {
                name: name.clone(),
                symbol: format!("__ncc_stc_{}_{}", container_symbol, target_symbol),
                ty: ty.clone(),
                storage_size_bytes: stc_global_storage_size_bytes(container, ty, struct_layouts),
                init: BackendStcGlobalInitIR::Zero,
                storage,
                symbol_visibility,
            });
    }

    for stmt in stc_init_body {
        let StatementIR::ScalarProjection {
            target, ty, value, ..
        } = stmt
        else {
            unsupported_init_count += 1;
            continue;
        };
        let Some(init) = backend_stc_global_init_from_scalar_expr(
            container,
            ty,
            value,
            &const_env,
            struct_layouts,
        ) else {
            unsupported_init_count += 1;
            continue;
        };
        if let Some(eval_value) = backend_stc_global_init_eval_value(&init) {
            const_env.insert(target.clone(), eval_value);
        }
        if let Some(global) = globals_by_name.get_mut(target) {
            global.ty = ty.clone();
            global.storage_size_bytes =
                stc_global_storage_size_bytes(container, ty, struct_layouts);
            global.init = init;
        } else {
            let target_symbol = sanitize_symbol_component(target);
            globals_by_name.insert(
                target.clone(),
                BackendStcGlobalIR {
                    name: target.clone(),
                    symbol: format!("__ncc_stc_{}_{}", container_symbol, target_symbol),
                    ty: ty.clone(),
                    storage_size_bytes: stc_global_storage_size_bytes(
                        container,
                        ty,
                        struct_layouts,
                    ),
                    init,
                    storage: StorageContract::default(),
                    symbol_visibility: BackendSymbolVisibilityIR::Global,
                },
            );
        }
    }

    let mut globals = globals_by_name.into_values().collect::<Vec<_>>();
    globals.sort_by(|left, right| left.name.cmp(&right.name));

    if globals.is_empty() && unsupported_init_count == 0 {
        None
    } else {
        Some(BackendStcGlobalsUnitIR {
            container: container.to_string(),
            init_symbol: format!("__ncc_stc_init.{}", container_symbol),
            globals,
            unsupported_init_count,
        })
    }
}

fn stc_global_storage_size_bytes(
    container: &str,
    ty: &str,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> usize {
    stc_storage_size_for_type(container, ty, struct_layouts)
}

fn stc_storage_size_for_type(
    container: &str,
    ty: &str,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> usize {
    let compact = ty.trim().replace(' ', "");
    if scalar_type_uses_native_fast_dynamic_descriptor(&compact) {
        // Native dynamic containers are material descriptors, not scalar
        // pointers. The backend layout is data,len,capacity so unrelated
        // globals cannot overlap in the .stc data section.
        return 3 * 8;
    }
    let (elem_ty, fixed_len) = array_type_parts_from_type(&compact);
    if let Some(len) = fixed_len {
        return stc_storage_size_for_type(container, &elem_ty, struct_layouts)
            .saturating_mul(len.max(1))
            .max(1);
    }
    let qualified = format!("{}.{}", container, compact);
    if let Some(layout) = struct_layouts
        .get(&compact)
        .or_else(|| struct_layouts.get(&qualified))
    {
        return layout.size_bytes.max(1);
    }
    let lowering = backend_type_lowering_for_type(&compact);
    lowering
        .scalar_mem_type
        .map(|_| scalar_elem_size_from_type(&compact))
        .unwrap_or_else(|| lowering.size_bytes.max(1))
        .max(1)
}

fn backend_stc_global_init_from_scalar_expr(
    container: &str,
    ty: &str,
    expr: &ScalarExprIR,
    env: &HashMap<String, ScalarEvalValue>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Option<BackendStcGlobalInitIR> {
    let (fixed_elem_ty, fixed_len) = array_type_parts_from_type(ty);
    if let Some(len) = fixed_len {
        if fixed_elem_ty.trim() == "str" {
            if let Some(values) = backend_stc_fixed_string_array_literals(len, expr) {
                return Some(BackendStcGlobalInitIR::FixedStringArrayLiteral { len, values });
            }
        }
        if let Some(bytes) = backend_stc_fixed_array_literal_bytes(
            container,
            &fixed_elem_ty,
            len,
            expr,
            env,
            struct_layouts,
        ) {
            return Some(BackendStcGlobalInitIR::FixedArrayLiteral {
                elem_ty: fixed_elem_ty,
                len,
                bytes,
            });
        }
    }
    if scalar_type_uses_native_fast_dynamic_descriptor(ty) {
        if let ScalarExprIR::ArrayLiteral(items) = expr {
            let elem_ty = scalar_dinarray_method_elem_type_from_type(ty);
            let items = flatten_scalar_array_literal_items(items);
            let bytes = backend_stc_scalar_items_bytes(
                container,
                &elem_ty,
                items.clone(),
                env,
                struct_layouts,
            )?;
            return Some(BackendStcGlobalInitIR::DynamicArrayLiteral {
                elem_ty,
                items,
                bytes,
            });
        }
    }
    if let ScalarExprIR::StringLiteral(value) = expr {
        return Some(BackendStcGlobalInitIR::StringLiteral(value.clone()));
    }
    if let Some(value) = eval_scalar_expr(expr, env) {
        return match value {
            ScalarEvalValue::Int(value) => i64::try_from(value)
                .ok()
                .map(BackendStcGlobalInitIR::Integer),
            ScalarEvalValue::Bool(value) => Some(BackendStcGlobalInitIR::Bool(value)),
        };
    }
    match expr {
        ScalarExprIR::Number(raw) => {
            parse_backend_number_literal(raw).map(BackendStcGlobalInitIR::Integer)
        }
        ScalarExprIR::Bool(value) => Some(BackendStcGlobalInitIR::Bool(*value)),
        ScalarExprIR::CharLiteral(value) => Some(BackendStcGlobalInitIR::Integer(*value as i64)),
        _ => None,
    }
}

fn backend_stc_fixed_string_array_literals(
    declared_len: usize,
    expr: &ScalarExprIR,
) -> Option<Vec<String>> {
    let ScalarExprIR::ArrayLiteral(items) = expr else {
        return None;
    };
    let values = items
        .iter()
        .map(|item| match item {
            ScalarExprIR::StringLiteral(value) => Some(value.clone()),
            _ => None,
        })
        .collect::<Option<Vec<_>>>()?;
    if values.is_empty() && declared_len == 0 {
        return Some(values);
    }
    if values.len() == declared_len {
        return Some(values);
    }
    if values.len() == 1 && declared_len > 1 {
        return Some(vec![values[0].clone(); declared_len]);
    }
    None
}

fn backend_stc_fixed_array_literal_bytes(
    container: &str,
    elem_ty: &str,
    declared_len: usize,
    expr: &ScalarExprIR,
    env: &HashMap<String, ScalarEvalValue>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Option<Vec<u8>> {
    let ScalarExprIR::ArrayLiteral(items) = expr else {
        return None;
    };
    let flat_items = flatten_scalar_array_literal_items(items);
    if flat_items.is_empty() && declared_len == 0 {
        return Some(Vec::new());
    }
    let projected_items = if flat_items.len() == declared_len {
        flat_items
    } else if flat_items.len() == 1 && declared_len > 1 {
        vec![flat_items[0].clone(); declared_len]
    } else {
        return None;
    };

    backend_stc_scalar_items_bytes(container, elem_ty, projected_items, env, struct_layouts)
}

fn backend_stc_scalar_items_bytes(
    container: &str,
    elem_ty: &str,
    items: Vec<ScalarExprIR>,
    env: &HashMap<String, ScalarEvalValue>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Option<Vec<u8>> {
    let elem_size = stc_storage_size_for_type(container, elem_ty, struct_layouts).max(1);
    let mut bytes = Vec::with_capacity(items.len().saturating_mul(elem_size));
    for item in items {
        if stc_struct_layout_for_type(container, elem_ty, struct_layouts).is_some()
            && matches!(&item, ScalarExprIR::Number(raw) if parse_backend_number_literal(raw).is_some_and(|value| value == 0))
        {
            bytes.extend_from_slice(&vec![0; elem_size]);
            continue;
        }
        let value = eval_scalar_expr(&item, env)?;
        let raw = scalar_eval_value_to_i64(value)?;
        let mut cell = stc_integer_storage_bytes(elem_ty, raw);
        if cell.len() < elem_size {
            cell.resize(elem_size, 0);
        }
        bytes.extend_from_slice(&cell[..elem_size]);
    }
    Some(bytes)
}

fn stc_struct_layout_for_type<'a>(
    container: &str,
    ty: &str,
    struct_layouts: &'a HashMap<String, LlvmStructLayout>,
) -> Option<&'a LlvmStructLayout> {
    let compact = ty.trim().replace(' ', "");
    let qualified = format!("{}.{}", container, compact);
    struct_layouts
        .get(&compact)
        .or_else(|| struct_layouts.get(&qualified))
}

fn backend_stc_global_init_eval_value(init: &BackendStcGlobalInitIR) -> Option<ScalarEvalValue> {
    match init {
        BackendStcGlobalInitIR::Integer(value) => Some(ScalarEvalValue::Int(i128::from(*value))),
        BackendStcGlobalInitIR::Bool(value) => Some(ScalarEvalValue::Bool(*value)),
        BackendStcGlobalInitIR::Zero => Some(ScalarEvalValue::Int(0)),
        BackendStcGlobalInitIR::StringLiteral(_)
        | BackendStcGlobalInitIR::FixedArrayLiteral { .. }
        | BackendStcGlobalInitIR::FixedStringArrayLiteral { .. }
        | BackendStcGlobalInitIR::DynamicArrayLiteral { .. } => None,
    }
}

fn emit_state_scalar_global_locations(
    stc_globals: Option<&BackendStcGlobalsUnitIR>,
) -> Vec<BackendFunctionGlobalSymbolIR> {
    stc_globals
        .into_iter()
        .flat_map(|unit| unit.globals.iter())
        .filter_map(|global| {
            let compact = global.ty.trim().replace(' ', "");
            let mem_type = backend_type_lowering_for_type(&compact).scalar_mem_type?;
            Some(BackendFunctionGlobalSymbolIR {
                name: global.name.clone(),
                symbol: global.symbol.clone(),
                mem_type,
            })
        })
        .collect()
}

fn emit_state_array_global_locations(
    stc_globals: Option<&BackendStcGlobalsUnitIR>,
) -> Vec<BackendFunctionArrayGlobalSymbolIR> {
    stc_globals
        .into_iter()
        .flat_map(|unit| unit.globals.iter())
        .filter_map(|global| {
            let (elem_ty, declared_len) = array_type_parts_from_type(&global.ty);
            let len = declared_len?;
            if len == 0 {
                return None;
            }
            let elem_type = scalar_mem_type_from_type(&elem_ty);
            let elem_size = scalar_elem_size_from_type(&elem_ty);
            Some(BackendFunctionArrayGlobalSymbolIR {
                name: global.name.clone(),
                symbol: global.symbol.clone(),
                elem_type,
                elem_size,
                len,
            })
        })
        .collect()
}

fn emit_state_dynamic_global_locations(
    stc_globals: Option<&BackendStcGlobalsUnitIR>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Vec<BackendFunctionDynamicGlobalSymbolIR> {
    stc_globals
        .into_iter()
        .flat_map(|unit| unit.globals.iter())
        .filter_map(|global| {
            if !scalar_type_uses_native_fast_dynamic_descriptor(&global.ty) {
                return None;
            }
            let elem_ty = scalar_dinarray_method_elem_type_from_type(&global.ty);
            let elem_size = struct_layouts
                .get(&elem_ty)
                .map(|layout| layout.size_bytes.max(1))
                .unwrap_or_else(|| scalar_elem_size_from_type(&elem_ty));
            Some(BackendFunctionDynamicGlobalSymbolIR {
                name: global.name.clone(),
                symbol: global.symbol.clone(),
                elem_type: scalar_mem_type_from_type(&elem_ty),
                elem_size,
                elem_nc_type: elem_ty,
            })
        })
        .collect()
}

fn emit_state_struct_global_locations(
    container: &str,
    stc_globals: Option<&BackendStcGlobalsUnitIR>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Vec<BackendFunctionStructGlobalSymbolIR> {
    stc_globals
        .into_iter()
        .flat_map(|unit| unit.globals.iter())
        .filter_map(|global| {
            let compact = global.ty.trim().replace(' ', "");
            let qualified = format!("{}.{}", container, compact);
            if struct_layouts.contains_key(&compact) || struct_layouts.contains_key(&qualified) {
                Some(BackendFunctionStructGlobalSymbolIR {
                    name: global.name.clone(),
                    symbol: global.symbol.clone(),
                })
            } else {
                None
            }
        })
        .collect()
}

fn sanitize_symbol_component(value: &str) -> String {
    value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '_' {
                ch
            } else {
                '_'
            }
        })
        .collect()
}

fn align_x86_64_call_frame_reserve(
    reserve_bytes: usize,
    callee_saved_bytes: usize,
    stack_align_bytes: usize,
) -> usize {
    let align = stack_align_bytes.max(1);
    let wanted_mod = (8 + align - (callee_saved_bytes % align)) % align;
    let current_mod = reserve_bytes % align;
    if current_mod == wanted_mod {
        reserve_bytes
    } else {
        reserve_bytes + ((wanted_mod + align - current_mod) % align)
    }
}

fn scalar_intrinsic_outgoing_arg_bytes(function: &FunctionIR) -> usize {
    let shadow_space = backend_call_shadow_space_bytes(
        &function.backend_plan.calling_convention,
        &function.backend_plan.data_layout,
    );
    let closure_stack_bytes = function
        .backend_plan
        .call_sites
        .iter()
        .filter(|site| {
            function.symbol_types.get(&site.target).is_some_and(|ty| {
                let compact = ty.trim().replace(' ', "");
                compact.starts_with("fn<") || compact.starts_with("fn(")
            })
        })
        .map(|site| {
            let register_count =
                backend_arg_registers(&function.backend_plan.calling_convention).len();
            let total_args = site.arg_count.saturating_add(1);
            let stack_words = total_args.saturating_sub(register_count);
            align_up(
                shadow_space + stack_words * function.backend_plan.data_layout.word_bytes,
                function.backend_plan.data_layout.word_bytes,
            )
        })
        .max()
        .unwrap_or(0);
    let ordinary_intrinsic = if function.backend_plan.target == BackendTargetIR::X86_64
        && function.backend_plan.calling_convention == BackendCallingConventionIR::NcWin64
        && (statements_have_scalar_call(&function.body)
            || statements_have_scalar_text_concat(function, &function.body))
    {
        shadow_space
    } else {
        0
    };
    ordinary_intrinsic.max(closure_stack_bytes)
}

fn function_scalar_return_imm(
    f: &FunctionIR,
    scalar_globals: &[BackendFunctionGlobalSymbolIR],
) -> Option<i64> {
    if statements_have_scalar_call(&f.body) || statements_have_scalar_memory_ops(&f.body) {
        return None;
    }
    let global_names = scalar_globals
        .iter()
        .map(|global| global.name.as_str())
        .collect::<HashSet<_>>();
    let paths = statements_scalar_return_paths(
        &f.body,
        vec![ScalarReturnPath::Active(HashMap::new())],
        &global_names,
    )?;
    let mut folded = None;
    for path in paths {
        let ScalarReturnPath::Returned(value) = path else {
            return None;
        };
        match folded {
            Some(previous) if previous != value => return None,
            Some(_) => {}
            None => folded = Some(value),
        }
    }
    folded.map(|value| {
        if f.return_type.eq_ignore_ascii_case("bool") {
            i64::from(value != 0)
        } else {
            value
        }
    })
}

fn statements_have_scalar_call(stmts: &[StatementIR]) -> bool {
    stmts.iter().any(statement_has_scalar_call)
}

fn statements_have_scalar_text_concat(function: &FunctionIR, stmts: &[StatementIR]) -> bool {
    stmts
        .iter()
        .any(|stmt| statement_has_scalar_text_concat(function, stmt))
}

fn statement_has_scalar_call(stmt: &StatementIR) -> bool {
    match stmt {
        StatementIR::ScalarReturn { value, .. }
        | StatementIR::ScalarProjection { value, .. }
        | StatementIR::ScalarExpr { value, .. } => scalar_expr_has_call(value),
        StatementIR::Print { .. } => true,
        StatementIR::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            condition.as_ref().is_some_and(scalar_expr_has_call)
                || statements_have_scalar_call(then_body)
                || statements_have_scalar_call(else_body)
        }
        StatementIR::While {
            condition, body, ..
        }
        | StatementIR::DoWhile {
            condition, body, ..
        }
        | StatementIR::RepeatUntil {
            condition, body, ..
        } => {
            condition.as_ref().is_some_and(scalar_expr_has_call)
                || statements_have_scalar_call(body)
        }
        StatementIR::ForClassic {
            init,
            condition,
            step,
            body,
            ..
        } => {
            init.as_deref().is_some_and(statement_has_scalar_call)
                || condition.as_ref().is_some_and(scalar_expr_has_call)
                || step.as_deref().is_some_and(statement_has_scalar_call)
                || statements_have_scalar_call(body)
        }
        StatementIR::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            start.as_ref().is_some_and(scalar_expr_has_call)
                || end.as_ref().is_some_and(scalar_expr_has_call)
                || step.as_ref().is_some_and(scalar_expr_has_call)
                || statements_have_scalar_call(body)
        }
        StatementIR::RepeatCount { count, body, .. } => {
            count.as_ref().is_some_and(scalar_expr_has_call) || statements_have_scalar_call(body)
        }
        StatementIR::Loop { body } => statements_have_scalar_call(body),
        StatementIR::Defer { body } => statements_have_scalar_call(body),
        StatementIR::Labeled { stmt, .. } => statement_has_scalar_call(stmt),
        StatementIR::Match {
            value,
            cases,
            default,
            ..
        } => {
            value.as_ref().is_some_and(scalar_expr_has_call)
                || cases.iter().any(|(case, body)| {
                    scalar_expr_has_call(case) || statements_have_scalar_call(body)
                })
                || statements_have_scalar_call(default)
        }
        StatementIR::Return(_)
        | StatementIR::Dev(_)
        | StatementIR::Break { .. }
        | StatementIR::Continue { .. }
        | StatementIR::MainRef { .. }
        | StatementIR::FnLink { .. }
        | StatementIR::Expr(_) => false,
    }
}

fn statement_has_scalar_text_concat(function: &FunctionIR, stmt: &StatementIR) -> bool {
    match stmt {
        StatementIR::ScalarReturn { value, .. }
        | StatementIR::ScalarProjection { value, .. }
        | StatementIR::ScalarExpr { value, .. } => scalar_expr_has_text_concat(function, value),
        StatementIR::Print { value, .. } => scalar_expr_has_text_concat(function, value),
        StatementIR::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            condition
                .as_ref()
                .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || statements_have_scalar_text_concat(function, then_body)
                || statements_have_scalar_text_concat(function, else_body)
        }
        StatementIR::While {
            condition, body, ..
        }
        | StatementIR::DoWhile {
            condition, body, ..
        }
        | StatementIR::RepeatUntil {
            condition, body, ..
        } => {
            condition
                .as_ref()
                .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || statements_have_scalar_text_concat(function, body)
        }
        StatementIR::ForClassic {
            init,
            condition,
            step,
            body,
            ..
        } => {
            init.as_deref()
                .is_some_and(|stmt| statement_has_scalar_text_concat(function, stmt))
                || condition
                    .as_ref()
                    .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || step
                    .as_deref()
                    .is_some_and(|stmt| statement_has_scalar_text_concat(function, stmt))
                || statements_have_scalar_text_concat(function, body)
        }
        StatementIR::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            start
                .as_ref()
                .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || end
                    .as_ref()
                    .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || step
                    .as_ref()
                    .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || statements_have_scalar_text_concat(function, body)
        }
        StatementIR::RepeatCount { count, body, .. } => {
            count
                .as_ref()
                .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || statements_have_scalar_text_concat(function, body)
        }
        StatementIR::Loop { body } => statements_have_scalar_text_concat(function, body),
        StatementIR::Defer { body } => statements_have_scalar_text_concat(function, body),
        StatementIR::Labeled { stmt, .. } => statement_has_scalar_text_concat(function, stmt),
        StatementIR::Match {
            value,
            cases,
            default,
            ..
        } => {
            value
                .as_ref()
                .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
                || cases.iter().any(|(case, body)| {
                    scalar_expr_has_text_concat(function, case)
                        || statements_have_scalar_text_concat(function, body)
                })
                || statements_have_scalar_text_concat(function, default)
        }
        StatementIR::Return(_)
        | StatementIR::Dev(_)
        | StatementIR::Break { .. }
        | StatementIR::Continue { .. }
        | StatementIR::MainRef { .. }
        | StatementIR::FnLink { .. }
        | StatementIR::Expr(_) => false,
    }
}

fn scalar_expr_has_text_concat(function: &FunctionIR, expr: &ScalarExprIR) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => fields
            .iter()
            .any(|(_, value)| scalar_expr_has_text_concat(function, value)),
        ScalarExprIR::Binary {
            left,
            op: ScalarBinaryOpIR::Plus,
            right,
        } => {
            scalar_expr_is_text_like(function, left)
                || scalar_expr_is_text_like(function, right)
                || scalar_expr_has_text_concat(function, left)
                || scalar_expr_has_text_concat(function, right)
        }
        ScalarExprIR::ArrayLiteral(items) => items
            .iter()
            .any(|item| scalar_expr_has_text_concat(function, item)),
        ScalarExprIR::PtrRead { ptr, .. } => scalar_expr_has_text_concat(function, ptr),
        ScalarExprIR::PtrWrite { ptr, value, .. } => {
            scalar_expr_has_text_concat(function, ptr)
                || scalar_expr_has_text_concat(function, value)
        }
        ScalarExprIR::PtrOffset { ptr, index, .. }
        | ScalarExprIR::PtrDiff {
            left: ptr,
            right: index,
            ..
        }
        | ScalarExprIR::RegionFromPtr {
            ptr, len: index, ..
        }
        | ScalarExprIR::RegionPtrAt {
            region: ptr, index, ..
        } => {
            scalar_expr_has_text_concat(function, ptr)
                || scalar_expr_has_text_concat(function, index)
        }
        ScalarExprIR::ArrayFieldRead { index, .. } => scalar_expr_has_text_concat(function, index),
        ScalarExprIR::EnumConstruct { payload, .. } => payload
            .iter()
            .any(|item| scalar_expr_has_text_concat(function, item)),
        ScalarExprIR::ArrayFieldWrite { index, value, .. }
        | ScalarExprIR::ArrayWrite { index, value, .. } => {
            scalar_expr_has_text_concat(function, index)
                || scalar_expr_has_text_concat(function, value)
        }
        ScalarExprIR::FieldWrite { value, .. } => scalar_expr_has_text_concat(function, value),
        ScalarExprIR::ArrayRead { index, .. } => scalar_expr_has_text_concat(function, index),
        ScalarExprIR::DinArrayPush { value, .. } => scalar_expr_has_text_concat(function, value),
        ScalarExprIR::DinArrayRealloc { capacity, .. } => {
            scalar_expr_has_text_concat(function, capacity)
        }
        ScalarExprIR::Call { args, .. } => args
            .iter()
            .any(|arg| scalar_expr_has_text_concat(function, arg)),
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            scalar_expr_has_text_concat(function, value)
                || precision
                    .as_deref()
                    .is_some_and(|expr| scalar_expr_has_text_concat(function, expr))
        }
        ScalarExprIR::Unary { expr, .. } => scalar_expr_has_text_concat(function, expr),
        ScalarExprIR::Binary { left, right, .. } => {
            scalar_expr_has_text_concat(function, left)
                || scalar_expr_has_text_concat(function, right)
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_expr_has_text_concat(function, condition)
                || scalar_expr_has_text_concat(function, then_expr)
                || scalar_expr_has_text_concat(function, else_expr)
        }
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::Symbol(_)
        | ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. }
        | ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::DevTrap { .. } => false,
    }
}

fn scalar_expr_is_text_like(function: &FunctionIR, expr: &ScalarExprIR) -> bool {
    match expr {
        ScalarExprIR::StringLiteral(_) | ScalarExprIR::RuntimeRender { .. } => true,
        ScalarExprIR::Symbol(name) => function
            .symbol_types
            .get(name)
            .is_some_and(|ty| ty == "str"),
        ScalarExprIR::Call { target, .. } => {
            let name = target.rsplit('.').next().unwrap_or(target);
            matches!(name, "concat")
                || scalar_runtime_string_returns_text_call(name)
                || scalar_runtime_text_wrapper_call(name)
        }
        ScalarExprIR::Binary {
            left,
            op: ScalarBinaryOpIR::Plus,
            right,
        } => scalar_expr_is_text_like(function, left) || scalar_expr_is_text_like(function, right),
        ScalarExprIR::IfElse {
            then_expr,
            else_expr,
            ..
        } => {
            scalar_expr_is_text_like(function, then_expr)
                && scalar_expr_is_text_like(function, else_expr)
        }
        _ => false,
    }
}

fn scalar_expr_has_call(expr: &ScalarExprIR) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => {
            fields.iter().any(|(_, value)| scalar_expr_has_call(value))
        }
        ScalarExprIR::Call { .. } => true,
        ScalarExprIR::RuntimeRender { .. } => true,
        ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. } => false,
        ScalarExprIR::ArrayLiteral(items) => items.iter().any(scalar_expr_has_call),
        ScalarExprIR::AddressOf { .. } => false,
        ScalarExprIR::PtrRead { ptr, .. } => scalar_expr_has_call(ptr),
        ScalarExprIR::PtrWrite { ptr, value, .. } => {
            scalar_expr_has_call(ptr) || scalar_expr_has_call(value)
        }
        ScalarExprIR::PtrOffset { ptr, index, .. }
        | ScalarExprIR::PtrDiff {
            left: ptr,
            right: index,
            ..
        }
        | ScalarExprIR::RegionFromPtr {
            ptr, len: index, ..
        }
        | ScalarExprIR::RegionPtrAt {
            region: ptr, index, ..
        } => scalar_expr_has_call(ptr) || scalar_expr_has_call(index),
        ScalarExprIR::FieldRead { .. } => false,
        ScalarExprIR::EnumConstruct { payload, .. } => payload.iter().any(scalar_expr_has_call),
        ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. } => false,
        ScalarExprIR::ArrayFieldRead { index, .. } => scalar_expr_has_call(index),
        ScalarExprIR::ArrayFieldWrite { index, value, .. } => {
            scalar_expr_has_call(index) || scalar_expr_has_call(value)
        }
        ScalarExprIR::FieldWrite { value, .. } => scalar_expr_has_call(value),
        ScalarExprIR::ArrayRead { index, .. } => scalar_expr_has_call(index),
        ScalarExprIR::ArrayWrite { index, value, .. } => {
            scalar_expr_has_call(index) || scalar_expr_has_call(value)
        }
        ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPop { .. } => false,
        ScalarExprIR::DinArrayPush { value, .. } => scalar_expr_has_call(value),
        ScalarExprIR::DinArrayRealloc { capacity, .. } => scalar_expr_has_call(capacity),
        ScalarExprIR::Unary { expr, .. } => scalar_expr_has_call(expr),
        ScalarExprIR::Binary { left, right, .. } => {
            scalar_expr_has_call(left) || scalar_expr_has_call(right)
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_expr_has_call(condition)
                || scalar_expr_has_call(then_expr)
                || scalar_expr_has_call(else_expr)
        }
        ScalarExprIR::DevTrap { .. } => true,
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::Symbol(_) => false,
    }
}

fn scalar_expr_is_simple_register_expr(expr: &ScalarExprIR) -> bool {
    matches!(
        expr,
        ScalarExprIR::Number(_)
            | ScalarExprIR::CharLiteral(_)
            | ScalarExprIR::Bool(_)
            | ScalarExprIR::Symbol(_)
    )
}

fn statements_have_scalar_memory_ops(stmts: &[StatementIR]) -> bool {
    stmts.iter().any(statement_has_scalar_memory_ops)
}

fn statement_has_scalar_memory_ops(stmt: &StatementIR) -> bool {
    match stmt {
        StatementIR::ScalarReturn { value, .. }
        | StatementIR::ScalarProjection { value, .. }
        | StatementIR::ScalarExpr { value, .. } => scalar_expr_has_memory_ops(value),
        StatementIR::Print { .. } => true,
        StatementIR::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            condition.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || statements_have_scalar_memory_ops(then_body)
                || statements_have_scalar_memory_ops(else_body)
        }
        StatementIR::While {
            condition, body, ..
        }
        | StatementIR::DoWhile {
            condition, body, ..
        }
        | StatementIR::RepeatUntil {
            condition, body, ..
        } => {
            condition.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || statements_have_scalar_memory_ops(body)
        }
        StatementIR::ForClassic {
            init,
            condition,
            step,
            body,
            ..
        } => {
            init.as_deref().is_some_and(statement_has_scalar_memory_ops)
                || condition.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || step.as_deref().is_some_and(statement_has_scalar_memory_ops)
                || statements_have_scalar_memory_ops(body)
        }
        StatementIR::ForRange {
            start,
            end,
            step,
            body,
            ..
        } => {
            start.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || end.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || step.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || statements_have_scalar_memory_ops(body)
        }
        StatementIR::RepeatCount { count, body, .. } => {
            count.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || statements_have_scalar_memory_ops(body)
        }
        StatementIR::Loop { body } => statements_have_scalar_memory_ops(body),
        StatementIR::Defer { body } => statements_have_scalar_memory_ops(body),
        StatementIR::Labeled { stmt, .. } => statement_has_scalar_memory_ops(stmt),
        StatementIR::Match {
            value,
            cases,
            default,
            ..
        } => {
            value.as_ref().is_some_and(scalar_expr_has_memory_ops)
                || cases.iter().any(|(case, body)| {
                    scalar_expr_has_memory_ops(case) || statements_have_scalar_memory_ops(body)
                })
                || statements_have_scalar_memory_ops(default)
        }
        StatementIR::Return(_)
        | StatementIR::Dev(_)
        | StatementIR::Break { .. }
        | StatementIR::Continue { .. }
        | StatementIR::MainRef { .. }
        | StatementIR::FnLink { .. }
        | StatementIR::Expr(_) => false,
    }
}

fn scalar_expr_has_memory_ops(expr: &ScalarExprIR) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => fields
            .iter()
            .any(|(_, value)| scalar_expr_has_memory_ops(value)),
        ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. } => true,
        ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::PtrRead { .. }
        | ScalarExprIR::PtrWrite { .. }
        | ScalarExprIR::PtrOffset { .. }
        | ScalarExprIR::PtrDiff { .. }
        | ScalarExprIR::RegionFromPtr { .. }
        | ScalarExprIR::RegionPtrAt { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::ArrayFieldRead { .. }
        | ScalarExprIR::EnumConstruct { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::ArrayFieldWrite { .. }
        | ScalarExprIR::FieldWrite { .. }
        | ScalarExprIR::ArrayRead { .. }
        | ScalarExprIR::ArrayWrite { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPush { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::DinArrayRealloc { .. }
        | ScalarExprIR::ArrayLiteral(_)
        | ScalarExprIR::RuntimeRender { .. } => true,
        ScalarExprIR::Call { args, .. } => args.iter().any(scalar_expr_has_memory_ops),
        ScalarExprIR::Unary { expr, .. } => scalar_expr_has_memory_ops(expr),
        ScalarExprIR::Binary { left, right, .. } => {
            scalar_expr_has_memory_ops(left) || scalar_expr_has_memory_ops(right)
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_expr_has_memory_ops(condition)
                || scalar_expr_has_memory_ops(then_expr)
                || scalar_expr_has_memory_ops(else_expr)
        }
        ScalarExprIR::StringLiteral(_) => true,
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::Symbol(_)
        | ScalarExprIR::DevTrap { .. } => false,
    }
}

fn scalar_v2_caller_saved_register_pool(
    calling_convention: &BackendCallingConventionIR,
) -> Vec<BackendRegisterIR> {
    scalar_v2_allocatable_registers(calling_convention, &HashSet::new())
        .into_iter()
        .filter(|entry| entry.preservation == ScalarRegisterPreservationV2::CallerSaved)
        .map(|entry| entry.reg)
        .collect()
}

fn scalar_v2_allocatable_registers(
    calling_convention: &BackendCallingConventionIR,
    reserved: &HashSet<BackendRegisterIR>,
) -> Vec<ScalarAllocatableRegisterV2> {
    let mut out = Vec::new();
    let mut push = |reg: BackendRegisterIR, preservation: ScalarRegisterPreservationV2| {
        if !reserved.contains(&reg) {
            out.push(ScalarAllocatableRegisterV2 { reg, preservation });
        }
    };
    match calling_convention {
        BackendCallingConventionIR::NcSysV64 | BackendCallingConventionIR::NcSovereign => {
            for reg in [
                BackendRegisterIR::R8,
                BackendRegisterIR::R9,
                BackendRegisterIR::R10,
                BackendRegisterIR::R11,
                BackendRegisterIR::Rsi,
                BackendRegisterIR::Rdi,
            ] {
                push(reg, ScalarRegisterPreservationV2::CallerSaved);
            }
            for reg in [
                BackendRegisterIR::R12,
                BackendRegisterIR::R13,
                BackendRegisterIR::R14,
                BackendRegisterIR::R15,
                BackendRegisterIR::Rbx,
            ] {
                push(reg, ScalarRegisterPreservationV2::CalleeSaved);
            }
        }
        BackendCallingConventionIR::NcWin64 => {
            for reg in [
                BackendRegisterIR::R10,
                BackendRegisterIR::R11,
                BackendRegisterIR::R8,
                BackendRegisterIR::R9,
            ] {
                push(reg, ScalarRegisterPreservationV2::CallerSaved);
            }
            for reg in [
                BackendRegisterIR::R12,
                BackendRegisterIR::R13,
                BackendRegisterIR::R14,
                BackendRegisterIR::R15,
                BackendRegisterIR::Rbx,
                BackendRegisterIR::Rsi,
                BackendRegisterIR::Rdi,
            ] {
                push(reg, ScalarRegisterPreservationV2::CalleeSaved);
            }
        }
        BackendCallingConventionIR::NcAapcs64 => {
            for reg in [
                BackendRegisterIR::X9,
                BackendRegisterIR::X10,
                BackendRegisterIR::X11,
                BackendRegisterIR::X12,
                BackendRegisterIR::X13,
                BackendRegisterIR::X14,
                BackendRegisterIR::X15,
            ] {
                push(reg, ScalarRegisterPreservationV2::CallerSaved);
            }
            for reg in [
                BackendRegisterIR::X19,
                BackendRegisterIR::X20,
                BackendRegisterIR::X21,
                BackendRegisterIR::X22,
                BackendRegisterIR::X23,
                BackendRegisterIR::X24,
                BackendRegisterIR::X25,
                BackendRegisterIR::X26,
                BackendRegisterIR::X27,
                BackendRegisterIR::X28,
            ] {
                push(reg, ScalarRegisterPreservationV2::CalleeSaved);
            }
        }
        BackendCallingConventionIR::NcPortable => {}
    }
    out
}

fn scalar_register_allocation_v2(f: &FunctionIR) -> ScalarRegisterAllocationV2 {
    scalar_register_allocation_v2_with_profile(f, &ScalarRegisterProfileGuidanceV2::default())
}

fn scalar_register_allocation_v2_with_profile(
    f: &FunctionIR,
    profile: &ScalarRegisterProfileGuidanceV2,
) -> ScalarRegisterAllocationV2 {
    if !scalar_body_is_v2_resident_eligible(&f.body) {
        return ScalarRegisterAllocationV2::default();
    }

    let liveness = scalar_register_cfg_liveness_v2(&f.body);

    let mut intervals = HashMap::new();
    for (symbol, start) in &liveness.defs {
        if liveness.address_taken.contains(symbol) {
            continue;
        }
        let Some(ty) = f.symbol_types.get(symbol) else {
            continue;
        };
        if !scalar_type_is_register_resident(ty) {
            continue;
        }
        let end = liveness.uses.get(symbol).copied().unwrap_or(*start);
        intervals.insert(symbol.clone(), ScalarLiveIntervalV2 { start: *start, end });
    }

    let mut graph = scalar_register_interference_graph(&intervals);
    scalar_register_apply_cfg_interference(&mut graph, &intervals, &liveness);
    let live_segments = scalar_register_live_segments(&intervals, &liveness);
    let interference_edges = scalar_register_interference_edge_count(&graph);
    let peak_live = scalar_register_peak_live(&intervals, &liveness);
    let ssa_values = scalar_register_ssa_values_v2(f, &intervals, &liveness);
    let coalesced_groups = scalar_register_global_copy_groups(&intervals, &graph, &liveness);
    let coalesced_group_by_symbol = scalar_register_coalesced_group_by_symbol(&coalesced_groups);
    let coalesced_group_index_by_symbol =
        scalar_register_coalesced_group_index_by_symbol(&coalesced_groups);
    let spill_costs =
        scalar_register_spill_costs(&intervals, &graph, &ssa_values, &liveness, profile);
    let mut reserved = if f.backend_plan.frame_layout.bridge_scratch_bytes > 0 {
        backend_bridge_scratch_registers(&f.backend_plan.calling_convention)
            .into_iter()
            .collect::<HashSet<_>>()
    } else {
        HashSet::new()
    };
    if statements_have_scalar_memory_ops(&f.body) {
        reserved.extend([
            BackendRegisterIR::R8,
            BackendRegisterIR::R9,
            BackendRegisterIR::R10,
            BackendRegisterIR::R11,
        ]);
    }
    let register_pool =
        scalar_v2_allocatable_registers(&f.backend_plan.calling_convention, &reserved);
    if register_pool.is_empty() {
        return ScalarRegisterAllocationV2::default();
    }
    let register_classes = register_pool
        .iter()
        .map(|entry| (entry.reg.clone(), entry.preservation))
        .collect::<HashMap<_, _>>();
    let mut resident_locals = HashMap::new();
    let mut spilled_locals = Vec::new();
    let mut rematerialized_locals = HashMap::new();
    let mut decisions = Vec::new();

    let mut ordered = intervals.keys().cloned().collect::<Vec<_>>();
    ordered.sort_by(|left, right| {
        let left_has_copy_preference = liveness.copy_preferences.contains_key(left);
        let right_has_copy_preference = liveness.copy_preferences.contains_key(right);
        let left_cost = spill_costs.get(left);
        let right_cost = spill_costs.get(right);
        let left_score = left_cost.map(|cost| cost.score).unwrap_or_default();
        let right_score = right_cost.map(|cost| cost.score).unwrap_or_default();
        let left_degree = graph.get(left).map(|edges| edges.len()).unwrap_or(0);
        let right_degree = graph.get(right).map(|edges| edges.len()).unwrap_or(0);
        right_has_copy_preference
            .cmp(&left_has_copy_preference)
            .then_with(|| right_score.cmp(&left_score))
            .then_with(|| right_degree.cmp(&left_degree))
            .then_with(|| intervals[left].start.cmp(&intervals[right].start))
            .then_with(|| intervals[left].end.cmp(&intervals[right].end))
            .then_with(|| left.cmp(right))
    });

    for symbol in ordered {
        if resident_locals.contains_key(&symbol)
            || rematerialized_locals.contains_key(&symbol)
            || spilled_locals.contains(&symbol)
        {
            continue;
        }
        let unavailable = graph
            .get(&symbol)
            .into_iter()
            .flat_map(|neighbors| neighbors.iter())
            .filter_map(|neighbor| resident_locals.get(neighbor))
            .cloned()
            .collect::<HashSet<_>>();

        let preferred = liveness
            .copy_preferences
            .get(&symbol)
            .and_then(|source| resident_locals.get(source))
            .filter(|reg| !unavailable.contains(*reg))
            .filter(|reg| {
                scalar_register_is_legal_for_symbol(
                    &symbol,
                    reg,
                    &register_classes,
                    &liveness.call_crossing_symbols,
                )
            })
            .cloned();

        let caller_choice = register_pool
            .iter()
            .filter(|entry| entry.preservation == ScalarRegisterPreservationV2::CallerSaved)
            .filter(|entry| !unavailable.contains(&entry.reg))
            .find(|entry| {
                scalar_register_is_legal_for_symbol(
                    &symbol,
                    &entry.reg,
                    &register_classes,
                    &liveness.call_crossing_symbols,
                )
            })
            .map(|entry| entry.reg.clone());
        let callee_choice = register_pool
            .iter()
            .filter(|entry| entry.preservation == ScalarRegisterPreservationV2::CalleeSaved)
            .filter(|entry| !unavailable.contains(&entry.reg))
            .find(|entry| {
                scalar_register_is_legal_for_symbol(
                    &symbol,
                    &entry.reg,
                    &register_classes,
                    &liveness.call_crossing_symbols,
                )
            })
            .map(|entry| entry.reg.clone());
        let rematerialize_before_callee = preferred.is_none()
            && caller_choice.is_none()
            && callee_choice.is_some()
            && !liveness.call_crossing_symbols.contains(&symbol)
            && scalar_register_should_rematerialize_before_callee_saved(&symbol, &spill_costs);
        let selected = if rematerialize_before_callee {
            None
        } else {
            preferred.or(caller_choice).or(callee_choice)
        };

        let Some(reg) = selected else {
            if spill_costs
                .get(&symbol)
                .map(|cost| cost.rematerializable)
                .unwrap_or(false)
            {
                if let Some(expr) = liveness.def_exprs.get(&symbol).cloned() {
                    decisions.push(scalar_register_decision(
                        &symbol,
                        &intervals,
                        &live_segments,
                        &spill_costs,
                        &liveness,
                        &coalesced_group_index_by_symbol,
                        None,
                        None,
                        true,
                        false,
                    ));
                    rematerialized_locals.insert(symbol, expr);
                    continue;
                }
            }
            decisions.push(scalar_register_decision(
                &symbol,
                &intervals,
                &live_segments,
                &spill_costs,
                &liveness,
                &coalesced_group_index_by_symbol,
                None,
                None,
                false,
                true,
            ));
            spilled_locals.push(symbol);
            continue;
        };
        let preservation = register_classes.get(&reg).copied();
        resident_locals.insert(symbol.clone(), reg.clone());
        decisions.push(scalar_register_decision(
            &symbol,
            &intervals,
            &live_segments,
            &spill_costs,
            &liveness,
            &coalesced_group_index_by_symbol,
            Some(reg.clone()),
            preservation,
            false,
            false,
        ));
        if let Some(group) = coalesced_group_by_symbol.get(&symbol) {
            for peer in group {
                if peer == &symbol || resident_locals.contains_key(peer) {
                    continue;
                }
                let peer_unavailable = graph
                    .get(peer)
                    .into_iter()
                    .flat_map(|neighbors| neighbors.iter())
                    .filter_map(|neighbor| resident_locals.get(neighbor))
                    .cloned()
                    .collect::<HashSet<_>>();
                let peer_legal = scalar_register_is_legal_for_symbol(
                    peer,
                    &reg,
                    &register_classes,
                    &liveness.call_crossing_symbols,
                );
                if !peer_unavailable.contains(&reg) && peer_legal {
                    resident_locals.insert(peer.clone(), reg.clone());
                    decisions.push(scalar_register_decision(
                        peer,
                        &intervals,
                        &live_segments,
                        &spill_costs,
                        &liveness,
                        &coalesced_group_index_by_symbol,
                        Some(reg.clone()),
                        preservation,
                        false,
                        false,
                    ));
                }
            }
        }
    }

    let callee_saved_registers =
        scalar_register_callee_saved_registers(&resident_locals, &register_classes);
    let caller_saved_residents = resident_locals
        .values()
        .filter(|reg| {
            register_classes.get(*reg).copied() == Some(ScalarRegisterPreservationV2::CallerSaved)
        })
        .count();
    let callee_saved_residents = resident_locals
        .values()
        .filter(|reg| {
            register_classes.get(*reg).copied() == Some(ScalarRegisterPreservationV2::CalleeSaved)
        })
        .count();
    let stack_traffic_bytes_avoided = scalar_register_stack_traffic_bytes_avoided(
        &resident_locals,
        &rematerialized_locals,
        &spill_costs,
    );
    let stack_traffic_bytes_emitted =
        scalar_register_stack_traffic_bytes_emitted(&spilled_locals, &spill_costs);

    ScalarRegisterAllocationV2 {
        resident_locals,
        intervals,
        live_segments,
        spilled_locals,
        rematerialized_locals,
        spill_costs,
        ssa_values,
        coalesced_groups,
        decisions,
        interference_edges,
        peak_live,
        caller_saved_residents,
        callee_saved_residents,
        callee_saved_registers,
        stack_traffic_bytes_avoided,
        stack_traffic_bytes_emitted,
        call_nodes: liveness.call_nodes,
        call_crossing_locals: liveness.call_crossing_symbols,
        enabled: true,
    }
}

fn scalar_register_interference_graph(
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
) -> HashMap<String, HashSet<String>> {
    let mut graph = intervals
        .keys()
        .map(|symbol| (symbol.clone(), HashSet::new()))
        .collect::<HashMap<_, _>>();
    let mut ordered = intervals
        .iter()
        .map(|(symbol, interval)| (symbol.clone(), *interval))
        .collect::<Vec<_>>();
    ordered.sort_by_key(|(symbol, interval)| (interval.start, interval.end, symbol.clone()));

    for left_index in 0..ordered.len() {
        for right_index in (left_index + 1)..ordered.len() {
            let (left_symbol, left_interval) = &ordered[left_index];
            let (right_symbol, right_interval) = &ordered[right_index];
            if !scalar_live_intervals_overlap(*left_interval, *right_interval) {
                continue;
            }
            graph
                .entry(left_symbol.clone())
                .or_default()
                .insert(right_symbol.clone());
            graph
                .entry(right_symbol.clone())
                .or_default()
                .insert(left_symbol.clone());
        }
    }
    graph
}

fn scalar_live_intervals_overlap(left: ScalarLiveIntervalV2, right: ScalarLiveIntervalV2) -> bool {
    left.start <= right.end && right.start <= left.end
}

fn scalar_register_interference_edge_count(graph: &HashMap<String, HashSet<String>>) -> usize {
    graph.values().map(HashSet::len).sum::<usize>() / 2
}

fn scalar_register_live_segments(
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    liveness: &ScalarCfgLivenessV2,
) -> HashMap<String, Vec<ScalarLiveSegmentV2>> {
    let mut out = HashMap::new();
    for symbol in intervals.keys() {
        let mut points = Vec::new();
        for index in 0..liveness.nodes.len() {
            let live = liveness
                .live_in
                .get(index)
                .is_some_and(|set| set.contains(symbol))
                || liveness
                    .live_out
                    .get(index)
                    .is_some_and(|set| set.contains(symbol))
                || liveness.nodes[index].defs.contains(symbol)
                || liveness.nodes[index].uses.contains(symbol);
            if live {
                points.push(index);
            }
        }
        if points.is_empty() {
            if let Some(interval) = intervals.get(symbol) {
                points.push(interval.start);
            }
        }
        points.sort_unstable();
        points.dedup();
        let mut segments: Vec<ScalarLiveSegmentV2> = Vec::new();
        for point in points {
            if let Some(last) = segments.last_mut() {
                if point <= last.end.saturating_add(1) {
                    last.end = point;
                    continue;
                }
            }
            segments.push(ScalarLiveSegmentV2 {
                start: point,
                end: point,
            });
        }
        out.insert(symbol.clone(), segments);
    }
    out
}

fn scalar_register_peak_live(
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    liveness: &ScalarCfgLivenessV2,
) -> usize {
    (0..liveness.nodes.len())
        .map(|index| {
            intervals
                .keys()
                .filter(|symbol| {
                    liveness
                        .live_in
                        .get(index)
                        .is_some_and(|set| set.contains(*symbol))
                        || liveness
                            .live_out
                            .get(index)
                            .is_some_and(|set| set.contains(*symbol))
                        || liveness.nodes[index].defs.contains(*symbol)
                        || liveness.nodes[index].uses.contains(*symbol)
                })
                .count()
        })
        .max()
        .unwrap_or(0)
}

fn scalar_register_is_legal_for_symbol(
    symbol: &str,
    reg: &BackendRegisterIR,
    register_classes: &HashMap<BackendRegisterIR, ScalarRegisterPreservationV2>,
    call_crossing_symbols: &HashSet<String>,
) -> bool {
    if call_crossing_symbols.contains(symbol) {
        return register_classes.get(reg).copied()
            == Some(ScalarRegisterPreservationV2::CalleeSaved);
    }
    register_classes.contains_key(reg)
}

fn scalar_register_should_rematerialize_before_callee_saved(
    symbol: &str,
    spill_costs: &HashMap<String, ScalarSpillCostV2>,
) -> bool {
    spill_costs.get(symbol).is_some_and(|cost| {
        cost.rematerializable && cost.loop_use_weight == 0 && cost.profile_weight == 0
    })
}

fn scalar_register_coalesced_group_index_by_symbol(
    groups: &[Vec<String>],
) -> HashMap<String, usize> {
    let mut out = HashMap::new();
    for (index, group) in groups.iter().enumerate() {
        for symbol in group {
            out.insert(symbol.clone(), index);
        }
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn scalar_register_decision(
    symbol: &str,
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    live_segments: &HashMap<String, Vec<ScalarLiveSegmentV2>>,
    spill_costs: &HashMap<String, ScalarSpillCostV2>,
    liveness: &ScalarCfgLivenessV2,
    coalesced_group_index_by_symbol: &HashMap<String, usize>,
    assigned_register: Option<BackendRegisterIR>,
    preservation: Option<ScalarRegisterPreservationV2>,
    rematerialized: bool,
    spilled: bool,
) -> ScalarRegisterDecisionV2 {
    let interval = intervals
        .get(symbol)
        .copied()
        .unwrap_or(ScalarLiveIntervalV2 { start: 0, end: 0 });
    let cost = spill_costs.get(symbol).copied();
    ScalarRegisterDecisionV2 {
        symbol: symbol.to_string(),
        interval,
        segment_count: live_segments.get(symbol).map(Vec::len).unwrap_or(0),
        assigned_register,
        preservation,
        spill_cost: cost.map(|cost| cost.score).unwrap_or(0),
        stack_traffic_bytes: cost.map(|cost| cost.estimated_stack_bytes).unwrap_or(0),
        call_crossing: liveness.call_crossing_symbols.contains(symbol),
        rematerialized,
        spilled,
        coalesced_group: coalesced_group_index_by_symbol.get(symbol).copied(),
    }
}

fn scalar_register_callee_saved_registers(
    resident_locals: &HashMap<String, BackendRegisterIR>,
    register_classes: &HashMap<BackendRegisterIR, ScalarRegisterPreservationV2>,
) -> Vec<BackendRegisterIR> {
    let mut regs = resident_locals
        .values()
        .filter(|reg| {
            register_classes.get(*reg).copied() == Some(ScalarRegisterPreservationV2::CalleeSaved)
        })
        .cloned()
        .collect::<Vec<_>>();
    regs.sort_by_key(render_backend_register);
    regs.dedup();
    regs
}

fn scalar_register_stack_traffic_bytes_avoided(
    resident_locals: &HashMap<String, BackendRegisterIR>,
    rematerialized_locals: &HashMap<String, ScalarExprIR>,
    spill_costs: &HashMap<String, ScalarSpillCostV2>,
) -> usize {
    resident_locals
        .keys()
        .chain(rematerialized_locals.keys())
        .filter_map(|symbol| spill_costs.get(symbol))
        .map(|cost| cost.estimated_stack_bytes)
        .sum()
}

fn scalar_register_stack_traffic_bytes_emitted(
    spilled_locals: &[String],
    spill_costs: &HashMap<String, ScalarSpillCostV2>,
) -> usize {
    spilled_locals
        .iter()
        .filter_map(|symbol| spill_costs.get(symbol))
        .map(|cost| cost.estimated_stack_bytes)
        .sum()
}

#[derive(Debug, Clone, Default)]
struct ScalarCfgLivenessV2 {
    nodes: Vec<ScalarCfgNodeV2>,
    live_in: Vec<HashSet<String>>,
    live_out: Vec<HashSet<String>>,
    call_nodes: HashSet<usize>,
    call_crossing_symbols: HashSet<String>,
    defs: HashMap<String, usize>,
    uses: HashMap<String, usize>,
    use_weights: HashMap<String, usize>,
    loop_use_weights: HashMap<String, usize>,
    def_counts: HashMap<String, usize>,
    def_exprs: HashMap<String, ScalarExprIR>,
    address_taken: HashSet<String>,
    copy_preferences: HashMap<String, String>,
}

#[derive(Debug, Clone, Default)]
struct ScalarCfgNodeV2 {
    defs: HashSet<String>,
    uses: HashSet<String>,
    successors: Vec<usize>,
    has_call: bool,
}

#[derive(Debug, Clone)]
struct ScalarCfgLoopTargetV2 {
    label: Option<String>,
    break_target: Option<usize>,
    continue_target: Option<usize>,
}

#[derive(Default)]
struct ScalarCfgBuilderV2 {
    nodes: Vec<ScalarCfgNodeV2>,
    defs: HashMap<String, usize>,
    uses: HashMap<String, usize>,
    use_weights: HashMap<String, usize>,
    loop_use_weights: HashMap<String, usize>,
    def_counts: HashMap<String, usize>,
    def_exprs: HashMap<String, ScalarExprIR>,
    address_taken: HashSet<String>,
    copy_preferences: HashMap<String, String>,
    loop_depth: usize,
}

fn scalar_register_cfg_liveness_v2(stmts: &[StatementIR]) -> ScalarCfgLivenessV2 {
    let mut builder = ScalarCfgBuilderV2::default();
    let loops = Vec::new();
    let _entry = builder.build_block(stmts, None, &loops);
    let (live_in, live_out) = scalar_register_solve_cfg_liveness(&builder.nodes);
    let call_nodes = builder
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(index, node)| node.has_call.then_some(index))
        .collect::<HashSet<_>>();
    let call_crossing_symbols =
        scalar_register_call_crossing_symbols(&call_nodes, &live_in, &live_out);
    ScalarCfgLivenessV2 {
        nodes: builder.nodes,
        live_in,
        live_out,
        call_nodes,
        call_crossing_symbols,
        defs: builder.defs,
        uses: builder.uses,
        use_weights: builder.use_weights,
        loop_use_weights: builder.loop_use_weights,
        def_counts: builder.def_counts,
        def_exprs: builder.def_exprs,
        address_taken: builder.address_taken,
        copy_preferences: builder.copy_preferences,
    }
}

impl ScalarCfgBuilderV2 {
    fn build_block(
        &mut self,
        stmts: &[StatementIR],
        next: Option<usize>,
        loops: &[ScalarCfgLoopTargetV2],
    ) -> Option<usize> {
        let mut current_next = next;
        for stmt in stmts.iter().rev() {
            current_next = self.build_stmt(stmt, current_next, loops, None);
        }
        current_next
    }

    fn build_stmt(
        &mut self,
        stmt: &StatementIR,
        next: Option<usize>,
        loops: &[ScalarCfgLoopTargetV2],
        label: Option<String>,
    ) -> Option<usize> {
        match stmt {
            StatementIR::ScalarProjection { target, value, .. } => {
                let mut defs = HashSet::from([target.clone()]);
                let mut uses = HashSet::new();
                self.collect_expr_uses(value, &mut uses);
                self.def_exprs.insert(target.clone(), value.clone());
                if let ScalarExprIR::Symbol(source) = value {
                    self.copy_preferences.insert(target.clone(), source.clone());
                }
                Some(self.push_cfg_node_with_call(
                    std::mem::take(&mut defs),
                    uses,
                    next,
                    scalar_expr_has_call(value),
                ))
            }
            StatementIR::ScalarReturn { value, .. } => {
                let mut uses = HashSet::new();
                self.collect_expr_uses(value, &mut uses);
                Some(self.push_cfg_node_with_call(
                    HashSet::new(),
                    uses,
                    std::iter::empty(),
                    scalar_expr_has_call(value),
                ))
            }
            StatementIR::ScalarExpr { value, .. } => {
                let mut uses = HashSet::new();
                self.collect_expr_uses(value, &mut uses);
                Some(self.push_cfg_node_with_call(
                    scalar_expr_written_symbols(value),
                    uses,
                    next,
                    scalar_expr_has_call(value),
                ))
            }
            StatementIR::Print { value, .. } => {
                let mut uses = HashSet::new();
                self.collect_expr_uses(value, &mut uses);
                Some(self.push_cfg_node_with_call(HashSet::new(), uses, next, true))
            }
            StatementIR::Defer { body } => self.build_block(body, next, loops),
            StatementIR::If {
                condition,
                then_body,
                else_body,
                ..
            } => {
                let then_entry = self.build_block(then_body, next, loops);
                let else_entry = self.build_block(else_body, next, loops);
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(condition) = condition {
                    self.collect_expr_uses(condition, &mut uses);
                    has_call = scalar_expr_has_call(condition);
                }
                let mut successors = Vec::new();
                if let Some(entry) = then_entry.or(next) {
                    successors.push(entry);
                }
                if let Some(entry) = else_entry.or(next) {
                    successors.push(entry);
                }
                Some(self.push_cfg_node_with_call(HashSet::new(), uses, successors, has_call))
            }
            StatementIR::While {
                condition, body, ..
            } => {
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(condition) = condition {
                    self.collect_expr_uses(condition, &mut uses);
                    has_call = scalar_expr_has_call(condition);
                }
                let header = self.push_cfg_node_with_call(HashSet::new(), uses, next, has_call);
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(header),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(header), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(header, entry);
                } else {
                    self.add_successor(header, header);
                }
                Some(header)
            }
            StatementIR::DoWhile {
                condition, body, ..
            }
            | StatementIR::RepeatUntil {
                condition, body, ..
            } => {
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(condition) = condition {
                    self.collect_expr_uses(condition, &mut uses);
                    has_call = scalar_expr_has_call(condition);
                }
                let condition_node =
                    self.push_cfg_node_with_call(HashSet::new(), uses, next, has_call);
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(condition_node),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(condition_node), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(condition_node, entry);
                    Some(entry)
                } else {
                    Some(condition_node)
                }
            }
            StatementIR::ForClassic {
                init,
                condition,
                step,
                body,
                ..
            } => {
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(condition) = condition {
                    self.collect_expr_uses(condition, &mut uses);
                    has_call = scalar_expr_has_call(condition);
                }
                let header = self.push_cfg_node_with_call(HashSet::new(), uses, next, has_call);
                let mut step_loop_stack = loops.to_vec();
                step_loop_stack.push(ScalarCfgLoopTargetV2 {
                    label: label.clone(),
                    break_target: next,
                    continue_target: Some(header),
                });
                self.loop_depth += 1;
                let step_entry = step
                    .as_deref()
                    .and_then(|step| self.build_stmt(step, Some(header), &step_loop_stack, None))
                    .unwrap_or(header);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(step_entry),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(step_entry), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(header, entry);
                }
                init.as_deref()
                    .and_then(|init| self.build_stmt(init, Some(header), loops, None))
                    .or(Some(header))
            }
            StatementIR::ForRange {
                item,
                start,
                end,
                step,
                body,
                ..
            } => {
                let defs = HashSet::from([item.clone()]);
                let mut uses = HashSet::new();
                let mut has_call = false;
                for expr in [start.as_ref(), end.as_ref(), step.as_ref()]
                    .into_iter()
                    .flatten()
                {
                    self.collect_expr_uses(expr, &mut uses);
                    has_call |= scalar_expr_has_call(expr);
                }
                let mut header_uses = HashSet::new();
                header_uses.insert(item.clone());
                let header = self.push_cfg_node(HashSet::new(), header_uses, next);
                let step_entry = self.push_cfg_node(
                    HashSet::from([item.clone()]),
                    HashSet::from([item.clone()]),
                    Some(header),
                );
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(step_entry),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(step_entry), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(header, entry);
                }
                Some(self.push_cfg_node_with_call(defs, uses, Some(header), has_call))
            }
            StatementIR::Loop { body } => {
                let header = self.push_cfg_node(HashSet::new(), HashSet::new(), None);
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(header),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(header), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(header, entry);
                } else {
                    self.add_successor(header, header);
                }
                Some(header)
            }
            StatementIR::RepeatCount { count, body, .. } => {
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(count) = count {
                    self.collect_expr_uses(count, &mut uses);
                    has_call = scalar_expr_has_call(count);
                }
                let header = self.push_cfg_node(HashSet::new(), HashSet::new(), next);
                let step_entry = self.push_cfg_node(HashSet::new(), HashSet::new(), Some(header));
                let mut loop_stack = loops.to_vec();
                loop_stack.push(ScalarCfgLoopTargetV2 {
                    label,
                    break_target: next,
                    continue_target: Some(step_entry),
                });
                self.loop_depth += 1;
                let body_entry = self.build_block(body, Some(step_entry), &loop_stack);
                self.loop_depth = self.loop_depth.saturating_sub(1);
                if let Some(entry) = body_entry {
                    self.add_successor(header, entry);
                }
                Some(self.push_cfg_node_with_call(HashSet::new(), uses, Some(header), has_call))
            }
            StatementIR::Break { label } => {
                let target = scalar_cfg_find_loop_target(loops, label.as_deref(), true);
                Some(self.push_cfg_node(HashSet::new(), HashSet::new(), target))
            }
            StatementIR::Continue { label } => {
                let target = scalar_cfg_find_loop_target(loops, label.as_deref(), false);
                Some(self.push_cfg_node(HashSet::new(), HashSet::new(), target))
            }
            StatementIR::Labeled { label, stmt } => {
                self.build_stmt(stmt, next, loops, Some(label.clone()))
            }
            StatementIR::Match {
                value,
                cases,
                default,
                ..
            } => {
                let default_entry = self.build_block(default, next, loops);
                let mut successors = Vec::new();
                for (_, body) in cases {
                    if let Some(entry) = self.build_block(body, next, loops) {
                        successors.push(entry);
                    } else if let Some(next) = next {
                        successors.push(next);
                    }
                }
                if let Some(entry) = default_entry.or(next) {
                    successors.push(entry);
                }
                let mut uses = HashSet::new();
                let mut has_call = false;
                if let Some(value) = value {
                    self.collect_expr_uses(value, &mut uses);
                    has_call |= scalar_expr_has_call(value);
                }
                for (case, _) in cases {
                    self.collect_expr_uses(case, &mut uses);
                    has_call |= scalar_expr_has_call(case);
                }
                Some(self.push_cfg_node_with_call(HashSet::new(), uses, successors, has_call))
            }
            StatementIR::Return(_)
            | StatementIR::Dev(_)
            | StatementIR::MainRef { .. }
            | StatementIR::FnLink { .. }
            | StatementIR::Expr(_) => {
                Some(self.push_cfg_node(HashSet::new(), HashSet::new(), std::iter::empty()))
            }
        }
    }

    fn push_cfg_node<I>(
        &mut self,
        defs: HashSet<String>,
        uses: HashSet<String>,
        successors: I,
    ) -> usize
    where
        I: IntoIterator<Item = usize>,
    {
        self.push_cfg_node_with_call(defs, uses, successors, false)
    }

    fn push_cfg_node_with_call<I>(
        &mut self,
        defs: HashSet<String>,
        uses: HashSet<String>,
        successors: I,
        has_call: bool,
    ) -> usize
    where
        I: IntoIterator<Item = usize>,
    {
        let index = self.nodes.len();
        for symbol in &defs {
            self.defs.entry(symbol.clone()).or_insert(index);
            *self.def_counts.entry(symbol.clone()).or_default() += 1;
        }
        for symbol in &uses {
            self.uses
                .entry(symbol.clone())
                .and_modify(|last| *last = (*last).max(index))
                .or_insert(index);
        }
        let mut successors = successors.into_iter().collect::<Vec<_>>();
        successors.sort_unstable();
        successors.dedup();
        self.nodes.push(ScalarCfgNodeV2 {
            defs,
            uses,
            successors,
            has_call,
        });
        index
    }

    fn collect_expr_uses(&mut self, expr: &ScalarExprIR, uses: &mut HashSet<String>) {
        let mut occurrence_counts = HashMap::new();
        scalar_register_collect_expr_symbols(
            expr,
            uses,
            &mut occurrence_counts,
            &mut self.address_taken,
        );
        let depth_weight = 1usize.saturating_add(self.loop_depth.saturating_mul(8));
        for (symbol, count) in occurrence_counts {
            let weighted = count.saturating_mul(depth_weight);
            *self.use_weights.entry(symbol.clone()).or_default() += weighted;
            if self.loop_depth > 0 {
                *self.loop_use_weights.entry(symbol).or_default() += weighted;
            }
        }
    }

    fn add_successor(&mut self, node: usize, successor: usize) {
        if let Some(cfg_node) = self.nodes.get_mut(node) {
            if !cfg_node.successors.contains(&successor) {
                cfg_node.successors.push(successor);
                cfg_node.successors.sort_unstable();
            }
        }
    }
}

fn scalar_cfg_find_loop_target(
    loops: &[ScalarCfgLoopTargetV2],
    label: Option<&str>,
    is_break: bool,
) -> Option<usize> {
    loops
        .iter()
        .rev()
        .find(|target| {
            label
                .map(|label| target.label.as_deref() == Some(label))
                .unwrap_or(true)
        })
        .and_then(|target| {
            if is_break {
                target.break_target
            } else {
                target.continue_target
            }
        })
}

fn scalar_register_solve_cfg_liveness(
    nodes: &[ScalarCfgNodeV2],
) -> (Vec<HashSet<String>>, Vec<HashSet<String>>) {
    let mut live_in = vec![HashSet::new(); nodes.len()];
    let mut live_out = vec![HashSet::new(); nodes.len()];
    let mut changed = true;

    while changed {
        changed = false;
        for index in (0..nodes.len()).rev() {
            let mut next_out = HashSet::new();
            for successor in &nodes[index].successors {
                if let Some(successor_live_in) = live_in.get(*successor) {
                    next_out.extend(successor_live_in.iter().cloned());
                }
            }

            let mut next_in = nodes[index].uses.clone();
            next_in.extend(
                next_out
                    .iter()
                    .filter(|symbol| !nodes[index].defs.contains(*symbol))
                    .cloned(),
            );

            if next_out != live_out[index] || next_in != live_in[index] {
                live_out[index] = next_out;
                live_in[index] = next_in;
                changed = true;
            }
        }
    }

    (live_in, live_out)
}

fn scalar_register_call_crossing_symbols(
    call_nodes: &HashSet<usize>,
    live_in: &[HashSet<String>],
    live_out: &[HashSet<String>],
) -> HashSet<String> {
    let mut out = HashSet::new();
    for index in call_nodes {
        let Some(in_set) = live_in.get(*index) else {
            continue;
        };
        let Some(out_set) = live_out.get(*index) else {
            continue;
        };
        out.extend(in_set.intersection(out_set).cloned());
    }
    out
}

fn scalar_register_apply_cfg_interference(
    graph: &mut HashMap<String, HashSet<String>>,
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    liveness: &ScalarCfgLivenessV2,
) {
    for index in 0..liveness.nodes.len() {
        let mut live_in = HashSet::new();
        if let Some(in_set) = liveness.live_in.get(index) {
            live_in.extend(
                in_set
                    .iter()
                    .filter(|s| intervals.contains_key(*s))
                    .cloned(),
            );
        }
        scalar_register_add_interference_clique(graph, &live_in);

        let mut live_out = HashSet::new();
        if let Some(out_set) = liveness.live_out.get(index) {
            live_out.extend(
                out_set
                    .iter()
                    .filter(|s| intervals.contains_key(*s))
                    .cloned(),
            );
        }
        scalar_register_add_interference_clique(graph, &live_out);

        for def in &liveness.nodes[index].defs {
            if !intervals.contains_key(def) {
                continue;
            }
            for live_symbol in &live_out {
                scalar_register_add_interference_edge(graph, def, live_symbol);
            }
        }
    }
}

fn scalar_register_add_interference_clique(
    graph: &mut HashMap<String, HashSet<String>>,
    symbols: &HashSet<String>,
) {
    let symbols = symbols.iter().cloned().collect::<Vec<_>>();
    for left in 0..symbols.len() {
        for right in (left + 1)..symbols.len() {
            scalar_register_add_interference_edge(graph, &symbols[left], &symbols[right]);
        }
    }
}

fn scalar_register_add_interference_edge(
    graph: &mut HashMap<String, HashSet<String>>,
    left: &str,
    right: &str,
) {
    if left == right {
        return;
    }
    graph
        .entry(left.to_string())
        .or_default()
        .insert(right.to_string());
    graph
        .entry(right.to_string())
        .or_default()
        .insert(left.to_string());
}

fn scalar_register_ssa_values_v2(
    f: &FunctionIR,
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    liveness: &ScalarCfgLivenessV2,
) -> HashMap<String, ScalarSsaValueV2> {
    intervals
        .keys()
        .map(|symbol| {
            let expr = liveness.def_exprs.get(symbol).cloned();
            let dependencies = expr
                .as_ref()
                .map(scalar_expr_dependencies)
                .unwrap_or_default();
            let pure = expr.as_ref().is_some_and(scalar_expr_is_pure_ssa_remat);
            let rematerializable =
                scalar_register_symbol_is_rematerializable(symbol, f, liveness, &mut Vec::new());
            (
                symbol.clone(),
                ScalarSsaValueV2 {
                    symbol: symbol.clone(),
                    version: 0,
                    expr,
                    dependencies,
                    pure,
                    rematerializable,
                },
            )
        })
        .collect()
}

fn scalar_register_global_copy_groups(
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    graph: &HashMap<String, HashSet<String>>,
    liveness: &ScalarCfgLivenessV2,
) -> Vec<Vec<String>> {
    let mut groups = intervals
        .keys()
        .map(|symbol| {
            let mut group = HashSet::new();
            group.insert(symbol.clone());
            group
        })
        .collect::<Vec<_>>();

    let mut edges = liveness
        .copy_preferences
        .iter()
        .filter(|(target, source)| {
            intervals.contains_key(*target) && intervals.contains_key(*source)
        })
        .map(|(target, source)| (target.clone(), source.clone()))
        .collect::<Vec<_>>();
    edges.sort();

    for (target, source) in edges {
        let Some(target_group) = scalar_register_find_group_index(&groups, &target) else {
            continue;
        };
        let Some(source_group) = scalar_register_find_group_index(&groups, &source) else {
            continue;
        };
        if target_group == source_group {
            continue;
        }
        let mut candidate = groups[target_group].clone();
        candidate.extend(groups[source_group].iter().cloned());
        if !scalar_register_group_is_non_interfering(&candidate, graph) {
            continue;
        }
        let keep = target_group.min(source_group);
        let remove = target_group.max(source_group);
        groups[keep] = candidate;
        groups.remove(remove);
    }

    let mut out = groups
        .into_iter()
        .filter(|group| group.len() > 1)
        .map(|group| {
            let mut symbols = group.into_iter().collect::<Vec<_>>();
            symbols.sort();
            symbols
        })
        .collect::<Vec<_>>();
    out.sort();
    out
}

fn scalar_register_find_group_index(groups: &[HashSet<String>], symbol: &str) -> Option<usize> {
    groups.iter().position(|group| group.contains(symbol))
}

fn scalar_register_group_is_non_interfering(
    group: &HashSet<String>,
    graph: &HashMap<String, HashSet<String>>,
) -> bool {
    let symbols = group.iter().collect::<Vec<_>>();
    for left in 0..symbols.len() {
        for right in (left + 1)..symbols.len() {
            if graph
                .get(symbols[left])
                .map(|neighbors| neighbors.contains(symbols[right]))
                .unwrap_or(false)
            {
                return false;
            }
        }
    }
    true
}

fn scalar_register_coalesced_group_by_symbol(
    groups: &[Vec<String>],
) -> HashMap<String, Vec<String>> {
    let mut out = HashMap::new();
    for group in groups {
        for symbol in group {
            out.insert(symbol.clone(), group.clone());
        }
    }
    out
}

fn scalar_register_spill_costs(
    intervals: &HashMap<String, ScalarLiveIntervalV2>,
    graph: &HashMap<String, HashSet<String>>,
    ssa_values: &HashMap<String, ScalarSsaValueV2>,
    liveness: &ScalarCfgLivenessV2,
    profile: &ScalarRegisterProfileGuidanceV2,
) -> HashMap<String, ScalarSpillCostV2> {
    intervals
        .iter()
        .map(|(symbol, interval)| {
            let use_weight = liveness.use_weights.get(symbol).copied().unwrap_or(0);
            let loop_use_weight = liveness.loop_use_weights.get(symbol).copied().unwrap_or(0);
            let profile_weight = profile.symbol_weights.get(symbol).copied().unwrap_or(0);
            let interval_len = interval.end.abs_diff(interval.start).saturating_add(1);
            let interference_degree = graph.get(symbol).map(|edges| edges.len()).unwrap_or(0);
            let rematerializable = ssa_values
                .get(symbol)
                .map(|value| value.rematerializable)
                .unwrap_or(false);
            let estimated_stack_bytes = liveness
                .def_counts
                .get(symbol)
                .copied()
                .unwrap_or(1)
                .saturating_add(use_weight.max(1))
                .saturating_mul(8);
            let rematerialization_cost = ssa_values
                .get(symbol)
                .and_then(|value| value.expr.as_ref())
                .map(scalar_expr_rematerialization_cost)
                .unwrap_or(usize::MAX / 4);
            let raw_score = use_weight
                .saturating_mul(32)
                .saturating_add(loop_use_weight.saturating_mul(64))
                .saturating_add(profile_weight.saturating_mul(128))
                .saturating_add(interval_len.saturating_mul(4))
                .saturating_add(interference_degree.saturating_mul(8))
                .saturating_add(estimated_stack_bytes);
            let score = if rematerializable {
                raw_score
                    .saturating_div(rematerialization_cost.saturating_add(8))
                    .max(1)
            } else {
                raw_score.max(1)
            };
            (
                symbol.clone(),
                ScalarSpillCostV2 {
                    use_weight,
                    loop_use_weight,
                    profile_weight,
                    interval_len,
                    interference_degree,
                    rematerializable,
                    estimated_stack_bytes,
                    rematerialization_cost,
                    score,
                },
            )
        })
        .collect()
}

fn scalar_expr_rematerialization_cost(expr: &ScalarExprIR) -> usize {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => {
            16 + fields
                .iter()
                .map(|(_, value)| scalar_expr_rematerialization_cost(value))
                .sum::<usize>()
        }
        ScalarExprIR::Number(_) | ScalarExprIR::CharLiteral(_) | ScalarExprIR::Bool(_) => 1,
        ScalarExprIR::Symbol(_) => 2,
        ScalarExprIR::Unary { expr, .. } => 1 + scalar_expr_rematerialization_cost(expr),
        ScalarExprIR::Binary { left, right, .. } => {
            2 + scalar_expr_rematerialization_cost(left) + scalar_expr_rematerialization_cost(right)
        }
        ScalarExprIR::ArrayLiteral(items) => {
            8 + items
                .iter()
                .map(scalar_expr_rematerialization_cost)
                .sum::<usize>()
        }
        ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::EnumConstruct { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::RuntimeRender { .. }
        | ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::PtrRead { .. }
        | ScalarExprIR::PtrWrite { .. }
        | ScalarExprIR::PtrOffset { .. }
        | ScalarExprIR::PtrDiff { .. }
        | ScalarExprIR::RegionFromPtr { .. }
        | ScalarExprIR::RegionPtrAt { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::ArrayFieldRead { .. }
        | ScalarExprIR::ArrayFieldWrite { .. }
        | ScalarExprIR::FieldWrite { .. }
        | ScalarExprIR::ArrayRead { .. }
        | ScalarExprIR::ArrayWrite { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPush { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::DinArrayRealloc { .. }
        | ScalarExprIR::Call { .. }
        | ScalarExprIR::IfElse { .. }
        | ScalarExprIR::DevTrap { .. }
        | ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. } => 64,
    }
}

fn scalar_register_symbol_is_rematerializable(
    symbol: &str,
    f: &FunctionIR,
    liveness: &ScalarCfgLivenessV2,
    visiting: &mut Vec<String>,
) -> bool {
    if liveness.address_taken.contains(symbol) {
        return false;
    }
    if liveness.def_counts.get(symbol).copied().unwrap_or_default() != 1 {
        return false;
    }
    if visiting.iter().any(|entry| entry == symbol) {
        return false;
    }
    let Some(expr) = liveness.def_exprs.get(symbol) else {
        return false;
    };
    visiting.push(symbol.to_string());
    let rematerializable = scalar_expr_is_rematerializable(expr, f, liveness, visiting);
    visiting.pop();
    rematerializable
}

fn scalar_expr_is_rematerializable(
    expr: &ScalarExprIR,
    f: &FunctionIR,
    liveness: &ScalarCfgLivenessV2,
    visiting: &mut Vec<String>,
) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { .. } => false,
        ScalarExprIR::Number(_) | ScalarExprIR::CharLiteral(_) | ScalarExprIR::Bool(_) => true,
        ScalarExprIR::Symbol(name) => {
            if f.params.iter().any(|param| param.name == *name) {
                return true;
            }
            if !f
                .symbol_types
                .get(name)
                .map(|ty| scalar_type_is_register_resident(ty))
                .unwrap_or(false)
            {
                return false;
            }
            scalar_register_symbol_is_rematerializable(name, f, liveness, visiting)
        }
        ScalarExprIR::Unary { expr, .. } => {
            scalar_expr_is_rematerializable(expr, f, liveness, visiting)
        }
        ScalarExprIR::Binary { left, op, right } => {
            if matches!(op, ScalarBinaryOpIR::Slash | ScalarBinaryOpIR::Percent) {
                return false;
            }
            scalar_expr_is_rematerializable(left, f, liveness, visiting)
                && scalar_expr_is_rematerializable(right, f, liveness, visiting)
        }
        ScalarExprIR::ArrayLiteral(_)
        | ScalarExprIR::EnumConstruct { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. }
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::RuntimeRender { .. }
        | ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::PtrRead { .. }
        | ScalarExprIR::PtrWrite { .. }
        | ScalarExprIR::PtrOffset { .. }
        | ScalarExprIR::PtrDiff { .. }
        | ScalarExprIR::RegionFromPtr { .. }
        | ScalarExprIR::RegionPtrAt { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::ArrayFieldRead { .. }
        | ScalarExprIR::ArrayFieldWrite { .. }
        | ScalarExprIR::FieldWrite { .. }
        | ScalarExprIR::ArrayRead { .. }
        | ScalarExprIR::ArrayWrite { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPush { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::DinArrayRealloc { .. }
        | ScalarExprIR::Call { .. }
        | ScalarExprIR::IfElse { .. }
        | ScalarExprIR::DevTrap { .. } => false,
    }
}

fn scalar_expr_is_pure_ssa_remat(expr: &ScalarExprIR) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { .. } => false,
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::Symbol(_) => true,
        ScalarExprIR::PostIncrement { .. }
        | ScalarExprIR::FieldPostIncrement { .. }
        | ScalarExprIR::PointerPostIncrementRead { .. } => false,
        ScalarExprIR::Unary { expr, .. } => scalar_expr_is_pure_ssa_remat(expr),
        ScalarExprIR::Binary { left, op, right } => {
            !matches!(op, ScalarBinaryOpIR::Slash | ScalarBinaryOpIR::Percent)
                && scalar_expr_is_pure_ssa_remat(left)
                && scalar_expr_is_pure_ssa_remat(right)
        }
        ScalarExprIR::ArrayLiteral(_)
        | ScalarExprIR::EnumConstruct { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::RuntimeRender { .. }
        | ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::PtrRead { .. }
        | ScalarExprIR::PtrWrite { .. }
        | ScalarExprIR::PtrOffset { .. }
        | ScalarExprIR::PtrDiff { .. }
        | ScalarExprIR::RegionFromPtr { .. }
        | ScalarExprIR::RegionPtrAt { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::ArrayFieldRead { .. }
        | ScalarExprIR::ArrayFieldWrite { .. }
        | ScalarExprIR::FieldWrite { .. }
        | ScalarExprIR::ArrayRead { .. }
        | ScalarExprIR::ArrayWrite { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPush { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::DinArrayRealloc { .. }
        | ScalarExprIR::Call { .. }
        | ScalarExprIR::IfElse { .. }
        | ScalarExprIR::DevTrap { .. } => false,
    }
}

fn scalar_expr_dependencies(expr: &ScalarExprIR) -> Vec<String> {
    let mut uses = HashSet::new();
    let mut counts = HashMap::new();
    let mut address_taken = HashSet::new();
    scalar_register_collect_expr_symbols(expr, &mut uses, &mut counts, &mut address_taken);
    let mut out = uses.into_iter().collect::<Vec<_>>();
    out.sort();
    out
}

fn scalar_expr_written_symbols(expr: &ScalarExprIR) -> HashSet<String> {
    let mut out = HashSet::new();
    scalar_expr_collect_written_symbols(expr, &mut out);
    out
}

fn scalar_expr_collect_written_symbols(expr: &ScalarExprIR, out: &mut HashSet<String>) {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => {
            for (_, value) in fields {
                scalar_expr_collect_written_symbols(value, out);
            }
        }
        ScalarExprIR::PostIncrement { target, .. }
        | ScalarExprIR::PointerPostIncrementRead { target, .. } => {
            out.insert(target.clone());
        }
        ScalarExprIR::FieldPostIncrement { base, .. } => {
            out.insert(base.clone());
        }
        ScalarExprIR::ArrayLiteral(items) => {
            for item in items {
                scalar_expr_collect_written_symbols(item, out);
            }
        }
        ScalarExprIR::EnumConstruct { payload, .. } => {
            for item in payload {
                scalar_expr_collect_written_symbols(item, out);
            }
        }
        ScalarExprIR::PtrRead { ptr, .. } | ScalarExprIR::Unary { expr: ptr, .. } => {
            scalar_expr_collect_written_symbols(ptr, out);
        }
        ScalarExprIR::PtrWrite { ptr, value, .. }
        | ScalarExprIR::PtrDiff {
            left: ptr,
            right: value,
            ..
        }
        | ScalarExprIR::Binary {
            left: ptr,
            right: value,
            ..
        }
        | ScalarExprIR::RegionPtrAt {
            region: ptr,
            index: value,
            ..
        } => {
            scalar_expr_collect_written_symbols(ptr, out);
            scalar_expr_collect_written_symbols(value, out);
        }
        ScalarExprIR::PtrOffset { ptr, index, .. }
        | ScalarExprIR::RegionFromPtr {
            ptr, len: index, ..
        } => {
            scalar_expr_collect_written_symbols(ptr, out);
            scalar_expr_collect_written_symbols(index, out);
        }
        ScalarExprIR::ArrayFieldRead { index, .. } | ScalarExprIR::ArrayRead { index, .. } => {
            scalar_expr_collect_written_symbols(index, out);
        }
        ScalarExprIR::ArrayFieldWrite { index, value, .. }
        | ScalarExprIR::ArrayWrite { index, value, .. } => {
            scalar_expr_collect_written_symbols(index, out);
            scalar_expr_collect_written_symbols(value, out);
        }
        ScalarExprIR::FieldWrite { value, .. } | ScalarExprIR::DinArrayPush { value, .. } => {
            scalar_expr_collect_written_symbols(value, out);
        }
        ScalarExprIR::DinArrayRealloc { capacity, .. } => {
            scalar_expr_collect_written_symbols(capacity, out);
        }
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            scalar_expr_collect_written_symbols(value, out);
            if let Some(precision) = precision {
                scalar_expr_collect_written_symbols(precision, out);
            }
        }
        ScalarExprIR::Call { args, .. } => {
            for arg in args {
                scalar_expr_collect_written_symbols(arg, out);
            }
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_expr_collect_written_symbols(condition, out);
            scalar_expr_collect_written_symbols(then_expr, out);
            scalar_expr_collect_written_symbols(else_expr, out);
        }
        ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::FieldRead { .. }
        | ScalarExprIR::EnumTagRead { .. }
        | ScalarExprIR::EnumPayloadRead { .. }
        | ScalarExprIR::EnumPayloadFieldRead { .. }
        | ScalarExprIR::EnumPayloadArrayRead { .. }
        | ScalarExprIR::DinArrayLen { .. }
        | ScalarExprIR::DinArrayCapacity { .. }
        | ScalarExprIR::DinArrayPop { .. }
        | ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::Symbol(_)
        | ScalarExprIR::DevTrap { .. } => {}
    }
}

fn scalar_expr_uses_different_symbol_in_register(
    expr: &ScalarExprIR,
    target: &str,
    target_reg: &BackendRegisterIR,
    resident_locals: &HashMap<String, BackendRegisterIR>,
) -> bool {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => fields.iter().any(|(_, value)| {
            scalar_expr_uses_different_symbol_in_register(
                value,
                target,
                target_reg,
                resident_locals,
            )
        }),
        ScalarExprIR::Symbol(name) => {
            name != target && resident_locals.get(name) == Some(target_reg)
        }
        ScalarExprIR::PostIncrement {
            target: increment_target,
            ..
        } => {
            increment_target != target && resident_locals.get(increment_target) == Some(target_reg)
        }
        ScalarExprIR::FieldPostIncrement { base, .. } => {
            base != target && resident_locals.get(base) == Some(target_reg)
        }
        ScalarExprIR::PointerPostIncrementRead {
            target: pointer_target,
            ..
        } => pointer_target != target && resident_locals.get(pointer_target) == Some(target_reg),
        ScalarExprIR::ArrayLiteral(items) => items.iter().any(|item| {
            scalar_expr_uses_different_symbol_in_register(item, target, target_reg, resident_locals)
        }),
        ScalarExprIR::PtrRead { ptr, .. }
        | ScalarExprIR::PtrOffset { ptr, .. }
        | ScalarExprIR::RegionFromPtr { ptr, .. } => {
            scalar_expr_uses_different_symbol_in_register(ptr, target, target_reg, resident_locals)
        }
        ScalarExprIR::PtrWrite { ptr, value, .. } => {
            scalar_expr_uses_different_symbol_in_register(ptr, target, target_reg, resident_locals)
                || scalar_expr_uses_different_symbol_in_register(
                    value,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::PtrDiff { left, right, .. } | ScalarExprIR::Binary { left, right, .. } => {
            scalar_expr_uses_different_symbol_in_register(left, target, target_reg, resident_locals)
                || scalar_expr_uses_different_symbol_in_register(
                    right,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::RegionPtrAt { region, index, .. } => {
            scalar_expr_uses_different_symbol_in_register(
                region,
                target,
                target_reg,
                resident_locals,
            ) || scalar_expr_uses_different_symbol_in_register(
                index,
                target,
                target_reg,
                resident_locals,
            )
        }
        ScalarExprIR::FieldRead { base, .. } => {
            base != target && resident_locals.get(base) == Some(target_reg)
        }
        ScalarExprIR::ArrayFieldRead {
            target: array_target,
            index,
            ..
        } => {
            (array_target != target && resident_locals.get(array_target) == Some(target_reg))
                || scalar_expr_uses_different_symbol_in_register(
                    index,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::EnumConstruct { payload, .. } => payload.iter().any(|item| {
            scalar_expr_uses_different_symbol_in_register(item, target, target_reg, resident_locals)
        }),
        ScalarExprIR::EnumTagRead {
            target: enum_target,
        }
        | ScalarExprIR::EnumPayloadRead {
            target: enum_target,
            ..
        }
        | ScalarExprIR::EnumPayloadFieldRead {
            target: enum_target,
            ..
        }
        | ScalarExprIR::EnumPayloadArrayRead {
            target: enum_target,
            ..
        } => enum_target != target && resident_locals.get(enum_target) == Some(target_reg),
        ScalarExprIR::ArrayFieldWrite {
            target: array_target,
            index,
            value,
            ..
        } => {
            (array_target != target && resident_locals.get(array_target) == Some(target_reg))
                || scalar_expr_uses_different_symbol_in_register(
                    index,
                    target,
                    target_reg,
                    resident_locals,
                )
                || scalar_expr_uses_different_symbol_in_register(
                    value,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::FieldWrite { base, value, .. } => {
            (base != target && resident_locals.get(base) == Some(target_reg))
                || scalar_expr_uses_different_symbol_in_register(
                    value,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::ArrayRead { index, .. } => scalar_expr_uses_different_symbol_in_register(
            index,
            target,
            target_reg,
            resident_locals,
        ),
        ScalarExprIR::ArrayWrite { index, value, .. } => {
            scalar_expr_uses_different_symbol_in_register(
                index,
                target,
                target_reg,
                resident_locals,
            ) || scalar_expr_uses_different_symbol_in_register(
                value,
                target,
                target_reg,
                resident_locals,
            )
        }
        ScalarExprIR::DinArrayLen {
            target: dinarray_target,
        }
        | ScalarExprIR::DinArrayCapacity {
            target: dinarray_target,
        }
        | ScalarExprIR::DinArrayPop {
            target: dinarray_target,
            ..
        } => dinarray_target != target && resident_locals.get(dinarray_target) == Some(target_reg),
        ScalarExprIR::DinArrayPush {
            target: dinarray_target,
            value,
            ..
        } => {
            (dinarray_target != target && resident_locals.get(dinarray_target) == Some(target_reg))
                || scalar_expr_uses_different_symbol_in_register(
                    value,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::DinArrayRealloc {
            target: dinarray_target,
            capacity,
        } => {
            (dinarray_target != target && resident_locals.get(dinarray_target) == Some(target_reg))
                || scalar_expr_uses_different_symbol_in_register(
                    capacity,
                    target,
                    target_reg,
                    resident_locals,
                )
        }
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            scalar_expr_uses_different_symbol_in_register(
                value,
                target,
                target_reg,
                resident_locals,
            ) || precision.as_ref().is_some_and(|precision| {
                scalar_expr_uses_different_symbol_in_register(
                    precision,
                    target,
                    target_reg,
                    resident_locals,
                )
            })
        }
        ScalarExprIR::Call { args, .. } => args.iter().any(|arg| {
            scalar_expr_uses_different_symbol_in_register(arg, target, target_reg, resident_locals)
        }),
        ScalarExprIR::Unary { expr, .. } => {
            scalar_expr_uses_different_symbol_in_register(expr, target, target_reg, resident_locals)
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_expr_uses_different_symbol_in_register(
                condition,
                target,
                target_reg,
                resident_locals,
            ) || scalar_expr_uses_different_symbol_in_register(
                then_expr,
                target,
                target_reg,
                resident_locals,
            ) || scalar_expr_uses_different_symbol_in_register(
                else_expr,
                target,
                target_reg,
                resident_locals,
            )
        }
        ScalarExprIR::AddressOf { .. }
        | ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::DevTrap { .. } => false,
    }
}

fn scalar_body_is_v2_resident_eligible(stmts: &[StatementIR]) -> bool {
    stmts.iter().all(scalar_stmt_is_v2_resident_eligible)
}

fn scalar_stmt_is_v2_resident_eligible(stmt: &StatementIR) -> bool {
    match stmt {
        StatementIR::ScalarProjection { .. }
        | StatementIR::ScalarReturn { .. }
        | StatementIR::ScalarExpr { .. } => true,
        StatementIR::If {
            condition,
            then_body,
            else_body,
            ..
        } => {
            condition.is_some()
                && scalar_body_is_v2_resident_eligible(then_body)
                && scalar_body_is_v2_resident_eligible(else_body)
        }
        StatementIR::While {
            condition, body, ..
        }
        | StatementIR::DoWhile {
            condition, body, ..
        }
        | StatementIR::RepeatUntil {
            condition, body, ..
        } => condition.is_some() && scalar_body_is_v2_resident_eligible(body),
        StatementIR::ForClassic {
            init,
            condition: _,
            step,
            body,
            ..
        } => {
            init.as_deref()
                .map(scalar_stmt_is_v2_resident_eligible)
                .unwrap_or(true)
                && step
                    .as_deref()
                    .map(scalar_stmt_is_v2_resident_eligible)
                    .unwrap_or(true)
                && scalar_body_is_v2_resident_eligible(body)
        }
        StatementIR::ForRange {
            start,
            end,
            step: _,
            body,
            ..
        } => start.is_some() && end.is_some() && scalar_body_is_v2_resident_eligible(body),
        StatementIR::Loop { body } => scalar_body_is_v2_resident_eligible(body),
        StatementIR::Defer { body } => scalar_body_is_v2_resident_eligible(body),
        StatementIR::RepeatCount { count, body, .. } => {
            count.is_some() && scalar_body_is_v2_resident_eligible(body)
        }
        StatementIR::Break { .. } | StatementIR::Continue { .. } => true,
        StatementIR::Expr(_) => false,
        StatementIR::Print { .. } => false,
        StatementIR::Labeled { stmt, .. } => scalar_stmt_is_v2_resident_eligible(stmt),
        StatementIR::Match {
            value,
            cases,
            default,
            ..
        } => {
            value.is_some()
                && cases
                    .iter()
                    .all(|(_, body)| scalar_body_is_v2_resident_eligible(body))
                && scalar_body_is_v2_resident_eligible(default)
        }
        StatementIR::Return(_)
        | StatementIR::Dev(_)
        | StatementIR::MainRef { .. }
        | StatementIR::FnLink { .. } => false,
    }
}

fn scalar_type_is_register_resident(ty: &str) -> bool {
    let compact = ty.trim().replace(' ', "");
    if scalar_pointer_elem_type_from_type(&compact).is_some() {
        return true;
    }
    matches!(
        compact.to_ascii_lowercase().as_str(),
        "int"
            | "bool"
            | "byte"
            | "word"
            | "dword"
            | "qword"
            | "sbyte"
            | "sword"
            | "sdword"
            | "sqword"
            | "u8"
            | "u16"
            | "u32"
            | "u64"
            | "i8"
            | "i16"
            | "i32"
            | "i64"
            | "addr"
            | "str"
    )
}

fn vector_type_is_register_resident(ty: &str) -> bool {
    let normalized = ty.trim().replace(' ', "").to_ascii_lowercase();
    if normalized.starts_with("vector<") {
        return backend_vector_llvm_type(&normalized).is_some();
    }
    normalized.starts_with("simd<") || normalized.starts_with("vec<")
}

fn vector_register_pool(target: &BackendTargetIR) -> Vec<BackendVectorRegisterIR> {
    match target {
        BackendTargetIR::X86_64 => (0..16).map(BackendVectorRegisterIR::Xmm).collect(),
        BackendTargetIR::AArch64 => (0..32).map(BackendVectorRegisterIR::V).collect(),
        BackendTargetIR::Wasm32 => Vec::new(),
    }
}

fn vector_register_class(target: &BackendTargetIR) -> &'static str {
    match target {
        BackendTargetIR::X86_64 => "xmm",
        BackendTargetIR::AArch64 => "v",
        BackendTargetIR::Wasm32 => "none",
    }
}

fn vector_register_allocation_v2(
    f: &FunctionIR,
    target: &BackendTargetIR,
) -> VectorRegisterAllocationV2 {
    let pool = vector_register_pool(target);
    let mut vector_symbols = f
        .symbol_types
        .iter()
        .filter(|(_, ty)| vector_type_is_register_resident(ty))
        .map(|(symbol, _)| symbol.clone())
        .collect::<Vec<_>>();
    vector_symbols.sort();

    if vector_symbols.is_empty() || pool.is_empty() {
        return VectorRegisterAllocationV2 {
            register_class: vector_register_class(target).to_string(),
            ..VectorRegisterAllocationV2::default()
        };
    }

    let mut resident_vectors = HashMap::new();
    let mut spilled_vectors = Vec::new();
    for symbol in vector_symbols {
        if let Some(reg) = pool.get(resident_vectors.len()).cloned() {
            resident_vectors.insert(symbol, reg);
        } else {
            spilled_vectors.push(symbol);
        }
    }

    VectorRegisterAllocationV2 {
        resident_vectors,
        spilled_vectors,
        register_class: vector_register_class(target).to_string(),
        enabled: true,
    }
}

fn scalar_register_collect_expr_symbols(
    expr: &ScalarExprIR,
    uses: &mut HashSet<String>,
    use_counts: &mut HashMap<String, usize>,
    address_taken: &mut HashSet<String>,
) {
    match expr {
        ScalarExprIR::StructConstruct { fields, .. } => {
            for (_, value) in fields {
                scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
            }
        }
        ScalarExprIR::Symbol(name) => {
            uses.insert(name.clone());
            *use_counts.entry(name.clone()).or_default() += 1;
        }
        ScalarExprIR::PostIncrement { target, .. } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 2;
        }
        ScalarExprIR::FieldPostIncrement { base, .. } => {
            uses.insert(base.clone());
            *use_counts.entry(base.clone()).or_default() += 2;
        }
        ScalarExprIR::PointerPostIncrementRead { target, .. } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 2;
        }
        ScalarExprIR::ArrayLiteral(items) => {
            for item in items {
                scalar_register_collect_expr_symbols(item, uses, use_counts, address_taken);
            }
        }
        ScalarExprIR::AddressOf { target } => {
            address_taken.insert(target.clone());
        }
        ScalarExprIR::PtrRead { ptr, .. } => {
            scalar_register_collect_expr_symbols(ptr, uses, use_counts, address_taken);
        }
        ScalarExprIR::PtrWrite { ptr, value, .. } => {
            scalar_register_collect_expr_symbols(ptr, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
        }
        ScalarExprIR::PtrOffset {
            ptr, index: idx, ..
        }
        | ScalarExprIR::PtrDiff {
            left: ptr,
            right: idx,
            ..
        }
        | ScalarExprIR::RegionFromPtr { ptr, len: idx, .. }
        | ScalarExprIR::RegionPtrAt {
            region: ptr,
            index: idx,
            ..
        } => {
            scalar_register_collect_expr_symbols(ptr, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(idx, uses, use_counts, address_taken);
        }
        ScalarExprIR::FieldRead { base, .. } => {
            uses.insert(base.clone());
            *use_counts.entry(base.clone()).or_default() += 1;
        }
        ScalarExprIR::ArrayFieldRead {
            target, index: idx, ..
        } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
            scalar_register_collect_expr_symbols(idx, uses, use_counts, address_taken);
        }
        ScalarExprIR::EnumConstruct { payload, .. } => {
            for item in payload {
                scalar_register_collect_expr_symbols(item, uses, use_counts, address_taken);
            }
        }
        ScalarExprIR::EnumTagRead { target }
        | ScalarExprIR::EnumPayloadRead { target, .. }
        | ScalarExprIR::EnumPayloadFieldRead { target, .. }
        | ScalarExprIR::EnumPayloadArrayRead { target, .. } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
        }
        ScalarExprIR::ArrayFieldWrite {
            target,
            index: idx,
            value,
            ..
        } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
            scalar_register_collect_expr_symbols(idx, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
        }
        ScalarExprIR::FieldWrite { base, value, .. } => {
            uses.insert(base.clone());
            *use_counts.entry(base.clone()).or_default() += 1;
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
        }
        ScalarExprIR::ArrayRead { index: idx, .. } => {
            scalar_register_collect_expr_symbols(idx, uses, use_counts, address_taken);
        }
        ScalarExprIR::ArrayWrite {
            index: idx, value, ..
        } => {
            scalar_register_collect_expr_symbols(idx, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
        }
        ScalarExprIR::DinArrayLen { target }
        | ScalarExprIR::DinArrayCapacity { target }
        | ScalarExprIR::DinArrayPop { target, .. } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
        }
        ScalarExprIR::DinArrayPush { target, value, .. } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
        }
        ScalarExprIR::DinArrayRealloc { target, capacity } => {
            uses.insert(target.clone());
            *use_counts.entry(target.clone()).or_default() += 1;
            scalar_register_collect_expr_symbols(capacity, uses, use_counts, address_taken);
        }
        ScalarExprIR::RuntimeRender {
            value, precision, ..
        } => {
            scalar_register_collect_expr_symbols(value, uses, use_counts, address_taken);
            if let Some(precision) = precision {
                scalar_register_collect_expr_symbols(precision, uses, use_counts, address_taken);
            }
        }
        ScalarExprIR::Call { args, .. } => {
            for arg in args {
                scalar_register_collect_expr_symbols(arg, uses, use_counts, address_taken);
            }
        }
        ScalarExprIR::Unary { expr, .. } => {
            scalar_register_collect_expr_symbols(expr, uses, use_counts, address_taken);
        }
        ScalarExprIR::Binary { left, right, .. } => {
            scalar_register_collect_expr_symbols(left, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(right, uses, use_counts, address_taken);
        }
        ScalarExprIR::IfElse {
            condition,
            then_expr,
            else_expr,
        } => {
            scalar_register_collect_expr_symbols(condition, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(then_expr, uses, use_counts, address_taken);
            scalar_register_collect_expr_symbols(else_expr, uses, use_counts, address_taken);
        }
        ScalarExprIR::Number(_)
        | ScalarExprIR::CharLiteral(_)
        | ScalarExprIR::Bool(_)
        | ScalarExprIR::StringLiteral(_)
        | ScalarExprIR::DevTrap { .. } => {}
    }
}

