#[allow(clippy::too_many_arguments)]
fn function_scalar_reg_stack_plan(
    f: &FunctionIR,
    source_contract: &SourceExecutionContract,
    symbol: &str,
    container: &str,
    local_functions: &HashSet<String>,
    local_function_return_types: &HashMap<String, String>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
    scalar_globals: &[BackendFunctionGlobalSymbolIR],
    array_globals: &[BackendFunctionArrayGlobalSymbolIR],
    dynamic_globals: &[BackendFunctionDynamicGlobalSymbolIR],
    struct_globals: &[BackendFunctionStructGlobalSymbolIR],
) -> Option<FunctionScalarRegStackPlan> {
    if f.backend_plan.target != BackendTargetIR::X86_64
        || !matches!(
            f.backend_plan.calling_convention,
            BackendCallingConventionIR::NcSysV64
                | BackendCallingConventionIR::NcWin64
                | BackendCallingConventionIR::NcSovereign
        )
    {
        return None;
    }
    let allocation = scalar_register_allocation_v2(f);
    function_scalar_reg_stack_plan_with_allocation(
        f,
        source_contract,
        symbol,
        container,
        local_functions,
        local_function_return_types,
        struct_layouts,
        scalar_globals,
        array_globals,
        dynamic_globals,
        struct_globals,
        allocation,
    )
    .or_else(|| {
        function_scalar_reg_stack_plan_with_allocation(
            f,
            source_contract,
            symbol,
            container,
            local_functions,
            local_function_return_types,
            struct_layouts,
            scalar_globals,
            array_globals,
            dynamic_globals,
            struct_globals,
            ScalarRegisterAllocationV2::default(),
        )
    })
}

#[allow(clippy::too_many_arguments)]
fn function_scalar_reg_stack_plan_with_allocation(
    f: &FunctionIR,
    source_contract: &SourceExecutionContract,
    symbol: &str,
    container: &str,
    local_functions: &HashSet<String>,
    local_function_return_types: &HashMap<String, String>,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
    scalar_globals: &[BackendFunctionGlobalSymbolIR],
    array_globals: &[BackendFunctionArrayGlobalSymbolIR],
    dynamic_globals: &[BackendFunctionDynamicGlobalSymbolIR],
    struct_globals: &[BackendFunctionStructGlobalSymbolIR],
    allocation: ScalarRegisterAllocationV2,
) -> Option<FunctionScalarRegStackPlan> {
    let vector_allocation = vector_register_allocation_v2(f, &f.backend_plan.target);
    let _vector_allocation_summary = (
        vector_allocation.enabled,
        vector_allocation.register_class.clone(),
        vector_allocation.resident_vectors.len(),
        vector_allocation.spilled_vectors.len(),
    );
    let callee_saved_registers = allocation.callee_saved_registers.clone();
    let mut register_allocation = scalar_register_allocation_backend_report(&allocation);
    let mut builder = ScalarRegStackBuilder::new(
        f,
        source_contract,
        symbol,
        container,
        local_functions,
        local_function_return_types,
        struct_layouts,
        scalar_globals,
        array_globals,
        dynamic_globals,
        struct_globals,
        allocation,
    );
    let epilogue = builder.new_label("epilogue");
    let cleanup_epilogue = builder.new_label("cleanup_epilogue");
    builder.prepare_deferred_cleanups(&f.body, &cleanup_epilogue, &epilogue);
    if statements_have_scalar_call(&f.body) || statements_have_scalar_text_concat(f, &f.body) {
        builder.spill_register_params_to_stack();
    }
    builder.predeclare_scalar_projection_slots(&f.body);
    builder.compile_statements(&f.body, &epilogue)?;
    builder.emit_default_return_to_cleanup();
    if !builder.deferred_cleanups.is_empty() {
        builder.ops.push(BackendScalarOpIR::Label {
            name: cleanup_epilogue,
        });
        builder.emit_pending_deferred_cleanups(&epilogue)?;
        if let Some(return_slot) = builder.return_slot {
            builder.ops.push(BackendScalarOpIR::LoadStack {
                dst: BackendRegisterIR::Rax,
                base: BackendRegisterIR::Rsp,
                offset: return_slot,
            });
        }
    }
    builder
        .ops
        .push(BackendScalarOpIR::Label { name: epilogue });
    let outgoing_arg_bytes = builder.scalar_outgoing_arg_bytes();
    let discovered_local_base =
        outgoing_arg_bytes + f.backend_plan.frame_layout.bridge_scratch_bytes;
    if discovered_local_base > builder.local_base_offset {
        rebase_scalar_stack_offsets(
            &mut builder.ops,
            discovered_local_base - builder.local_base_offset,
        );
    }
    let stack_bytes = align_up(builder.next_local_offset, 16);
    register_allocation.stack_traffic_bytes_emitted = register_allocation
        .stack_traffic_bytes_emitted
        .saturating_add(stack_bytes);
    Some(FunctionScalarRegStackPlan {
        ops: builder.ops,
        function_markers: builder.function_markers,
        stack_bytes,
        outgoing_arg_bytes,
        callee_saved_registers,
        register_allocation,
    })
}

fn rebase_scalar_stack_offsets(ops: &mut [BackendScalarOpIR], delta: usize) {
    if delta == 0 {
        return;
    }
    for op in ops {
        match op {
            BackendScalarOpIR::LoadStack {
                base: BackendRegisterIR::Rsp,
                offset,
                ..
            }
            | BackendScalarOpIR::StoreStack {
                base: BackendRegisterIR::Rsp,
                offset,
                ..
            }
            | BackendScalarOpIR::LeaStack {
                base: BackendRegisterIR::Rsp,
                offset,
                ..
            } => *offset += delta,
            _ => {}
        }
    }
}

fn scalar_is_compare_op(op: ScalarBinaryOpIR) -> bool {
    matches!(
        op,
        ScalarBinaryOpIR::Greater
            | ScalarBinaryOpIR::Less
            | ScalarBinaryOpIR::GreaterEq
            | ScalarBinaryOpIR::LessEq
            | ScalarBinaryOpIR::EqEq
            | ScalarBinaryOpIR::NotEq
    )
}

fn scalar_binary_op_supports_immediate(op: ScalarBinaryOpIR) -> bool {
    matches!(
        op,
        ScalarBinaryOpIR::Plus
            | ScalarBinaryOpIR::Minus
            | ScalarBinaryOpIR::Star
            | ScalarBinaryOpIR::BitAnd
            | ScalarBinaryOpIR::BitOr
            | ScalarBinaryOpIR::BitXor
            | ScalarBinaryOpIR::ShiftLeft
            | ScalarBinaryOpIR::ShiftRight
            | ScalarBinaryOpIR::ShiftRightLogical
    )
}

fn invert_scalar_compare_op(op: ScalarBinaryOpIR) -> Option<ScalarBinaryOpIR> {
    match op {
        ScalarBinaryOpIR::Greater => Some(ScalarBinaryOpIR::LessEq),
        ScalarBinaryOpIR::Less => Some(ScalarBinaryOpIR::GreaterEq),
        ScalarBinaryOpIR::GreaterEq => Some(ScalarBinaryOpIR::Less),
        ScalarBinaryOpIR::LessEq => Some(ScalarBinaryOpIR::Greater),
        ScalarBinaryOpIR::EqEq => Some(ScalarBinaryOpIR::NotEq),
        ScalarBinaryOpIR::NotEq => Some(ScalarBinaryOpIR::EqEq),
        _ => None,
    }
}

