fn required_legalization_issues_for_lane(
    lane: &BackendLaneIR,
) -> &'static [BackendLegalizationIssueIR] {
    const HOSTED: &[BackendLegalizationIssueIR] = &[
        BackendLegalizationIssueIR::AggregatePassing,
        BackendLegalizationIssueIR::IntegerWidthNonNative,
        BackendLegalizationIssueIR::RelocationModelUnsupported,
        BackendLegalizationIssueIR::RuntimeBuiltinBoundary,
        BackendLegalizationIssueIR::PointerRegionBoundary,
        BackendLegalizationIssueIR::ConsoleRenderSurface,
        BackendLegalizationIssueIR::StructuredControlFlowSurface,
        BackendLegalizationIssueIR::PrimitiveBridgeHostedConflict,
    ];
    const PORTABLE: &[BackendLegalizationIssueIR] = &[
        BackendLegalizationIssueIR::AggregatePassing,
        BackendLegalizationIssueIR::IntegerWidthNonNative,
        BackendLegalizationIssueIR::RelocationModelUnsupported,
        BackendLegalizationIssueIR::RuntimeBuiltinBoundary,
        BackendLegalizationIssueIR::PointerRegionBoundary,
        BackendLegalizationIssueIR::ConsoleRenderSurface,
        BackendLegalizationIssueIR::StructuredControlFlowSurface,
        BackendLegalizationIssueIR::VectorSurfaceUnsupported,
    ];
    const FREESTANDING: &[BackendLegalizationIssueIR] = &[
        BackendLegalizationIssueIR::AggregatePassing,
        BackendLegalizationIssueIR::IntegerWidthNonNative,
        BackendLegalizationIssueIR::RelocationModelUnsupported,
        BackendLegalizationIssueIR::RuntimeBuiltinBoundary,
        BackendLegalizationIssueIR::PointerRegionBoundary,
        BackendLegalizationIssueIR::ConsoleRenderSurface,
        BackendLegalizationIssueIR::StructuredControlFlowSurface,
        BackendLegalizationIssueIR::PrimitiveBridgeHostedConflict,
    ];
    const SOVEREIGN: &[BackendLegalizationIssueIR] = &[
        BackendLegalizationIssueIR::AggregatePassing,
        BackendLegalizationIssueIR::IntegerWidthNonNative,
        BackendLegalizationIssueIR::RelocationModelUnsupported,
        BackendLegalizationIssueIR::RuntimeBuiltinBoundary,
        BackendLegalizationIssueIR::PointerRegionBoundary,
        BackendLegalizationIssueIR::ConsoleRenderSurface,
        BackendLegalizationIssueIR::StructuredControlFlowSurface,
        BackendLegalizationIssueIR::VectorSurfaceUnsupported,
    ];

    match lane {
        BackendLaneIR::Hosted => HOSTED,
        BackendLaneIR::Portable => PORTABLE,
        BackendLaneIR::Freestanding => FREESTANDING,
        BackendLaneIR::Sovereign => SOVEREIGN,
    }
}

