fn render_function_call_arg_source(source: &FunctionCallArgSourceIR) -> String {
    match source {
        FunctionCallArgSourceIR::Symbol(name) => format!("symbol({name})"),
        FunctionCallArgSourceIR::NumberLiteral(value) => format!("number({value})"),
        FunctionCallArgSourceIR::StringLiteral(value) => format!("string({value:?})"),
        FunctionCallArgSourceIR::BoolLiteral(value) => format!("bool({value})"),
        FunctionCallArgSourceIR::ClosureValue {
            param_count,
            capture_count,
            ..
        } => format!("closure(params={param_count},captures={capture_count})"),
        FunctionCallArgSourceIR::Expr(value) => format!("expr({value})"),
        FunctionCallArgSourceIR::MissingGenerated => "generated-missing-arg".to_string(),
    }
}

fn render_call_arg_location(location: &BackendCallArgLocationIR) -> String {
    match location {
        BackendCallArgLocationIR::Register(reg) => format!("reg({})", render_backend_register(reg)),
        BackendCallArgLocationIR::Registers {
            registers,
            byte_size,
        } => format!(
            "regs({} size={}B)",
            registers
                .iter()
                .map(render_backend_register)
                .collect::<Vec<_>>()
                .join(","),
            byte_size
        ),
        BackendCallArgLocationIR::Stack {
            byte_offset,
            byte_size,
        } => format!("stack(off={} size={}B)", byte_offset, byte_size),
        BackendCallArgLocationIR::StackByValue {
            byte_offset,
            byte_size,
            align_bytes,
        } => format!(
            "stack-byval(off={} size={}B align={}B)",
            byte_offset, byte_size, align_bytes
        ),
        BackendCallArgLocationIR::IndirectRegister {
            pointer_register,
            pointee_size,
            align_bytes,
        } => format!(
            "indirect-reg({} pointee={}B align={}B)",
            render_backend_register(pointer_register),
            pointee_size,
            align_bytes
        ),
        BackendCallArgLocationIR::IndirectStack {
            byte_offset,
            pointer_size,
            pointee_size,
            align_bytes,
        } => format!(
            "indirect-stack(off={} ptr={}B pointee={}B align={}B)",
            byte_offset, pointer_size, pointee_size, align_bytes
        ),
    }
}

