fn emit_function_static_globals_unit(
    container: &str,
    function: &FunctionIR,
    struct_layouts: &HashMap<String, LlvmStructLayout>,
) -> Option<BackendStcGlobalsUnitIR> {
    let mut declarations = Vec::new();
    collect_scalar_projection_declarations(&function.body, &mut declarations);
    let mut globals = Vec::new();
    let mut const_env = HashMap::new();
    let mut unsupported_init_count = 0usize;
    let container_symbol = sanitize_symbol_component(container);
    let function_symbol = sanitize_symbol_component(&function.name);

    for (name, ty, storage, value) in declarations {
        let Some(storage) = storage else {
            continue;
        };
        let Some(init) = backend_stc_global_init_from_scalar_expr(
            container,
            &ty,
            &value,
            &const_env,
            struct_layouts,
        ) else {
            unsupported_init_count += 1;
            continue;
        };
        if let Some(eval_value) = backend_stc_global_init_eval_value(&init) {
            const_env.insert(name.clone(), eval_value);
        }
        globals.push(BackendStcGlobalIR {
            name: name.clone(),
            symbol: format!(
                "__ncc_static_{}_{}_{}",
                container_symbol,
                function_symbol,
                sanitize_symbol_component(&name)
            ),
            ty: ty.clone(),
            storage_size_bytes: stc_global_storage_size_bytes(container, &ty, struct_layouts),
            init,
            storage,
            symbol_visibility: BackendSymbolVisibilityIR::Local,
        });
    }

    if globals.is_empty() && unsupported_init_count == 0 {
        return None;
    }
    globals.sort_by(|left, right| left.name.cmp(&right.name));
    Some(BackendStcGlobalsUnitIR {
        container: format!("{container}.{}.static", function.name),
        init_symbol: format!("__ncc_static_init.{}.{}", container_symbol, function_symbol),
        globals,
        unsupported_init_count,
    })
}

