#[cfg(test)]
mod compact_kernel_system_ir_tests {
    use super::*;

    const SOURCE: &str = r#"
kernelApicSmpGuestBoot {
    configureXapic() -> bool {
        lapic  at 0xFEE00000;
        ioapic at 0xFEC00000;
        hpet   at 0xFED00000;
        source at 0x70000;
        destination at 0x71000;

        guard load32(lapic + 0x30) >= 0 else return false;
        *32(lapic + 0xF0, 0x1FF);
        *32(lapic + 0x320, 0x61);
        *32(lapic + 0x3E0, 0x0B);
        route = load32(ioapic + 0x10);
        *32(ioapic + 0x10, route);
        counter = load64(hpet + 0xF0);
        *64(hpet + 0xF0, counter);
        *128(hpet + 0x100, source);
        *256(hpet + 0x120, source);
        *512(hpet + 0x160, source);
        guard load128(hpet + 0x100, destination) else return false;
        guard load256(hpet + 0x120, destination) else return false;
        guard load512(hpet + 0x160, destination) else return false;
        sendIpi(lapic, 1, 0x4042);
        32(lapic + 0xB0, 0);
        return true;
    }

    configureX2apic() -> bool {
        guard msrRead(0x803) >= 0 else return false;
        msrWrite(0x80F, 0x1FF);
        tscDeadline(tscRead() + 1_000_000);
        return true;
    }

    main: configureXapic;
}
"#;

    #[test]
    fn compact_kernel_surface_reaches_typed_ir_llvm_machine_and_object_bytes() {
        let tokens = ncc_lexer::lex(SOURCE).expect("kernel compact fixture must lex");
        let program = ncc_parser::parse(tokens).expect("kernel compact fixture must parse");
        ncc_sema::analyze(&program).expect("kernel compact fixture must pass sema");
        let mut profile = BackendLoweringProfileIR::nc_sovereign();
        profile.target_spec.target_triple = "x86_64-unknown-none".into();
        let ir = lower_with_backend_profile_exact(program, profile);
        let debug = format!("{ir:#?}");
        assert!(!debug.contains("__nC_infer_projection_type"), "{debug}");

        let module = mct_emit_llvm_module(&ir);
        assert!(
            module.diagnostics.is_empty(),
            "diagnostics={:#?}\n{}",
            module.diagnostics,
            module.llvm_ir
        );
        for symbol in [
            "__ncc_kernel_mmio_read32",
            "__ncc_kernel_mmio_read64",
            "__ncc_kernel_mmio_read128",
            "__ncc_kernel_mmio_read256",
            "__ncc_kernel_mmio_read512",
            "__ncc_kernel_mmio_write32",
            "__ncc_kernel_mmio_write64",
            "__ncc_kernel_mmio_write128",
            "__ncc_kernel_mmio_write256",
            "__ncc_kernel_mmio_write512",
            "__ncc_kernel_apic_send_ipi",
            "__ncc_kernel_cpu_read_msr",
            "__ncc_kernel_cpu_write_msr",
            "__ncc_kernel_arch_cycle_counter",
            "__ncc_kernel_tsc_deadline_write",
        ] {
            assert!(
                module.llvm_ir.contains(symbol),
                "missing {symbol}\n{}",
                module.llvm_ir
            );
        }
        assert!(
            module.llvm_ir.contains("%counter.addr = alloca i64")
                && module.llvm_ir.contains("store i64 %")
                && module.llvm_ir.contains("ptr %counter.addr"),
            "load64 first-write inference must retain all 64 bits\n{}",
            module.llvm_ir
        );
        assert!(
            !module.llvm_ir.contains("@ncc_rt_"),
            "hosted runtime leaked into kernel"
        );

        let backend = emit_backend(&ir);
        let rendered = render_backend_text(&backend);
        for target in [
            "mmio_read32",
            "mmio_read64",
            "mmio_read128",
            "mmio_read256",
            "mmio_read512",
            "mmio_write32",
            "mmio_write64",
            "mmio_write128",
            "mmio_write256",
            "mmio_write512",
            "apic_send_ipi",
            "x2apic_read",
            "x2apic_write",
            "tsc_read",
            "tsc_deadline_write",
        ] {
            assert!(
                rendered.contains(&format!("call {target} ;")),
                "missing {target}\n{rendered}"
            );
        }

        let object = emit_object(&backend);
        assert!(
            object.sections.iter().any(|section| {
                section.kind == BackendObjectSectionKindIR::Text
                    && section
                        .bytes
                        .as_ref()
                        .is_some_and(|bytes| !bytes.is_empty())
            }),
            "compact kernel functions must materialize native text bytes: {object:#?}"
        );
    }
}

