#[cfg(test)]
mod machine_load_store_ir_tests {
    use super::*;
    use ncc_ast::{Context, MachineMemRef};

    #[test]
    fn lower_machine_load_store_into_machine_ir() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "machineLoadStore".into(),
                context: Some(Context::Machine),
                sections: vec![
                    Section::Reg(vec!["ax".into(), "bx".into()]),
                    Section::Inst(vec![
                        MachineInst::Load {
                            dst: "ax".into(),
                            src: MachineMemRef::MemReg { base: "bx".into() },
                        },
                        MachineInst::Store {
                            dst: MachineMemRef::MemReg { base: "bx".into() },
                            src: "ax".into(),
                        },
                    ]),
                    Section::MachineFinal(vec![MachineFinalOp::Ret]),
                ],
            }],
        };

        let ir = lower(program);
        let ContainerIR::Machine(machine) = &ir.containers[0] else {
            panic!("expected Machine IR");
        };

        assert!(matches!(
            &machine.insts[0],
            MachineInstIR::Load {
                dst,
                src: MachineMemRefIR::MemReg { base }
            } if dst == "ax" && base == "bx"
        ));
        assert!(matches!(
            &machine.insts[1],
            MachineInstIR::Store {
                dst: MachineMemRefIR::MemReg { base },
                src
            } if src == "ax" && base == "bx"
        ));
    }

    #[test]
    fn lower_machine_indexed_mem_ref_into_machine_ir() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "machineLoadStoreIndexed".into(),
                context: Some(Context::Machine),
                sections: vec![
                    Section::Reg(vec!["ax".into(), "bx".into(), "cx".into(), "dx".into()]),
                    Section::Inst(vec![
                        MachineInst::Load {
                            dst: "ax".into(),
                            src: MachineMemRef::MemAddr {
                                base: "bx".into(),
                                index: Some("cx".into()),
                                scale: 4,
                                disp: 16,
                            },
                        },
                        MachineInst::Store {
                            dst: MachineMemRef::MemAddr {
                                base: "bx".into(),
                                index: Some("cx".into()),
                                scale: 2,
                                disp: -8,
                            },
                            src: "dx".into(),
                        },
                    ]),
                    Section::MachineFinal(vec![MachineFinalOp::Ret]),
                ],
            }],
        };

        let ir = lower(program);
        let ContainerIR::Machine(machine) = &ir.containers[0] else {
            panic!("expected Machine IR");
        };

        assert!(matches!(
            &machine.insts[0],
            MachineInstIR::Load {
                dst,
                src: MachineMemRefIR::MemAddr {
                    base,
                    index,
                    scale,
                    disp,
                }
            } if dst == "ax"
                && base == "bx"
                && index.as_deref() == Some("cx")
                && *scale == 4
                && *disp == 16
        ));
        assert!(matches!(
            &machine.insts[1],
            MachineInstIR::Store {
                dst: MachineMemRefIR::MemAddr {
                    base,
                    index,
                    scale,
                    disp,
                },
                src
            } if src == "dx"
                && base == "bx"
                && index.as_deref() == Some("cx")
                && *scale == 2
                && *disp == -8
        ));
    }
}

#[cfg(test)]
mod machine_inline_label_ir_tests {
    use super::*;
    use ncc_ast::Context;

    #[test]
    fn lower_machine_inline_labels_into_machine_ir() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "machineInlineLabelOk".into(),
                context: Some(Context::Machine),
                sections: vec![
                    Section::Reg(vec!["ax".into()]),
                    Section::Inst(vec![
                        MachineInst::Label {
                            name: "entryPoint".into(),
                        },
                        MachineInst::Call {
                            target: ncc_ast::MachineCallTarget::Label("worker".into()),
                        },
                        MachineInst::Jmp {
                            target: "end".into(),
                        },
                        MachineInst::Label {
                            name: "worker".into(),
                        },
                        MachineInst::Inc { reg: "ax".into() },
                        MachineInst::Label { name: "end".into() },
                        MachineInst::Dec { reg: "ax".into() },
                    ]),
                    Section::MachineFinal(vec![MachineFinalOp::Ret]),
                ],
            }],
        };

        let ir = lower(program);
        let ContainerIR::Machine(machine) = &ir.containers[0] else {
            panic!("expected Machine IR");
        };

        assert!(matches!(&machine.insts[0], MachineInstIR::Label { name } if name == "entryPoint"));
        assert!(matches!(
            &machine.insts[1],
            MachineInstIR::Call {
                target: MachineCallTargetIR::Label(target)
            } if target == "worker"
        ));
        assert!(matches!(&machine.insts[2], MachineInstIR::Jmp { target } if target == "end"));
        assert!(matches!(&machine.insts[3], MachineInstIR::Label { name } if name == "worker"));
        assert!(matches!(&machine.insts[4], MachineInstIR::Inc { reg } if reg == "ax"));
        assert!(matches!(&machine.insts[5], MachineInstIR::Label { name } if name == "end"));
        assert!(matches!(&machine.insts[6], MachineInstIR::Dec { reg } if reg == "ax"));
    }
}

