    #[test]
    fn ir_consumes_nc_raw_abi_v1_for_every_native_target_family() {
        for triple in [
            "x86_64-unknown-linux-gnu",
            "i386-unknown-linux-gnu",
            "aarch64-unknown-linux-gnu",
            "armv7-unknown-linux-gnueabihf",
            "riscv32imac-unknown-none-elf",
            "riscv64gc-unknown-linux-gnu",
        ] {
            let contract = ncc_machine::nc_abi_contract_for_triple(triple)
                .expect("native IR target must expose an nC ABI");
            assert_eq!(contract.version, ncc_machine::NC_RAW_ABI_VERSION);
            assert_eq!(contract.pointer_bits, contract.function_pointer_bits);
            assert!(contract.tls_is_explicit && contract.per_cpu_is_explicit);
        }
        let profile = BackendLoweringProfileIR::nc_sysv64();
        assert_eq!(
            profile
                .target_spec
                .nc_raw_abi_contract()
                .expect("profile ABI")
                .version,
            ncc_machine::NC_RAW_ABI_VERSION
        );
    }

    #[test]
    fn backend_legalization_matrix_for_hosted_contains_official_runtime_and_primitive_diagnostics()
    {
        let profile = BackendLoweringProfileIR::nc_sysv64();
        let matrix = profile.target_spec.legalization_matrix();
        assert_eq!(matrix.lane, BackendLaneIR::Hosted);
        assert!(matrix
            .rules
            .iter()
            .any(|r| r.diagnostic == "profile incompatible with selected runtime model"));
        assert!(matrix
            .rules
            .iter()
            .any(|r| r.diagnostic == "primitive lowering unavailable for hosted backend"));
    }

    #[test]
    fn backend_legalization_matrix_for_freestanding_contains_runtime_missing_guard() {
        let spec = BackendTargetSpecIR::from_target_and_calling_convention(
            &BackendTargetIR::X86_64,
            &BackendCallingConventionIR::NcAapcs64,
        );
        let matrix = spec.legalization_matrix();
        assert_eq!(matrix.lane, BackendLaneIR::Freestanding);
        assert!(matrix
            .rules
            .iter()
            .any(|r| r.diagnostic == "backend target declared but runtime model missing"));
    }

    #[test]
    fn backend_legalization_matrix_for_portable_contains_capability_safe_pointer_console_and_vector_rules(
    ) {
        let profile = BackendLoweringProfileIR::nc_portable();
        let matrix = profile.target_spec.legalization_matrix();
        assert_eq!(matrix.lane, BackendLaneIR::Portable);
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::PointerRegionBoundary)
                .expect("portable matrix must expose pointer/region rule")
                .action,
            BackendLegalizationActionIR::LowerToRuntimeCall
        );
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::ConsoleRenderSurface)
                .expect("portable matrix must expose console render rule")
                .action,
            BackendLegalizationActionIR::LowerToRuntimeCall
        );
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::VectorSurfaceUnsupported)
                .expect("portable matrix must expose vector legalization rule")
                .action,
            BackendLegalizationActionIR::ExpandToScalarOps
        );
        matrix
            .validate_official_shape()
            .expect("portable legalization matrix must satisfy official shape");
    }

    #[test]
    fn backend_legalization_matrix_for_sovereign_contains_native_boundary_rules_and_vector_reject()
    {
        let profile = BackendLoweringProfileIR::nc_sovereign();
        let matrix = profile.target_spec.legalization_matrix();
        assert_eq!(matrix.lane, BackendLaneIR::Sovereign);
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::PointerRegionBoundary)
                .expect("sovereign matrix must expose pointer/region rule")
                .action,
            BackendLegalizationActionIR::KeepNative
        );
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::ConsoleRenderSurface)
                .expect("sovereign matrix must expose console render rule")
                .action,
            BackendLegalizationActionIR::KeepNative
        );
        assert_eq!(
            matrix
                .rule_for_issue(BackendLegalizationIssueIR::VectorSurfaceUnsupported)
                .expect("sovereign matrix must expose vector legalization rule")
                .action,
            BackendLegalizationActionIR::Reject
        );
        matrix
            .validate_official_shape()
            .expect("sovereign legalization matrix must satisfy official shape");
    }

    #[test]
    fn backend_legalization_matrix_shape_validation_rejects_duplicate_issue() {
        let matrix = BackendLegalizationMatrixIR {
            lane: BackendLaneIR::Hosted,
            rules: vec![
                BackendLegalizationRuleIR {
                    issue: BackendLegalizationIssueIR::AggregatePassing,
                    action: BackendLegalizationActionIR::RewriteByRef,
                    diagnostic: "x",
                },
                BackendLegalizationRuleIR {
                    issue: BackendLegalizationIssueIR::AggregatePassing,
                    action: BackendLegalizationActionIR::RewriteByRef,
                    diagnostic: "y",
                },
            ],
        };
        let err = matrix
            .validate_official_shape()
            .expect_err("duplicate issue must fail official matrix validation");
        assert!(err.contains("duplicate rule"));
    }

    #[test]
    fn backend_legalization_matrix_shape_validation_rejects_missing_required_issue() {
        let matrix = BackendLegalizationMatrixIR {
            lane: BackendLaneIR::Portable,
            rules: vec![BackendLegalizationRuleIR {
                issue: BackendLegalizationIssueIR::AggregatePassing,
                action: BackendLegalizationActionIR::RewriteByRef,
                diagnostic: "aggregate lowering requires by-ref legalization in current ABI lane",
            }],
        };
        let err = matrix
            .validate_official_shape()
            .expect_err("missing required issues must fail official matrix validation");
        assert!(err.contains("missing required issue"));
        assert!(err.contains("integer-width-non-native"));
    }

