    #[test]
    fn backend_lane_contract_matrix_covers_all_four_lanes() {
        let hosted = BackendLoweringProfileIR::nc_sysv64().target_spec;
        let portable = BackendLoweringProfileIR::nc_portable().target_spec;
        let freestanding = BackendTargetSpecIR::from_target_and_calling_convention(
            &BackendTargetIR::X86_64,
            &BackendCallingConventionIR::NcAapcs64,
        );
        let sovereign = sovereign_spec();

        let matrix = [hosted, portable, freestanding, sovereign];
        let mut lanes = matrix
            .iter()
            .map(|spec| spec.lane())
            .collect::<Vec<BackendLaneIR>>();
        lanes.sort_by_key(|lane| match lane {
            BackendLaneIR::Hosted => 0,
            BackendLaneIR::Portable => 1,
            BackendLaneIR::Freestanding => 2,
            BackendLaneIR::Sovereign => 3,
        });
        lanes.dedup();
        assert_eq!(
            lanes,
            vec![
                BackendLaneIR::Hosted,
                BackendLaneIR::Portable,
                BackendLaneIR::Freestanding,
                BackendLaneIR::Sovereign
            ]
        );

        for spec in &matrix {
            let legal = spec.legalization_matrix();
            let link = spec.linking_contract();
            let exec = spec.link_execution_contract();
            assert_eq!(legal.lane, spec.lane());
            assert_eq!(link.lane, spec.lane());
            assert_eq!(exec.lane, spec.lane());
            legal
                .validate_official_shape()
                .expect("lane legalization matrix must satisfy official shape");
            assert!(
                !legal.rules.is_empty(),
                "every lane must expose at least one legalization rule"
            );
            assert!(
                !link.supported_artifacts.is_empty(),
                "every lane must expose at least one artifact"
            );
        }
    }

