    #[test]
    fn explicit_binary_layout_uses_target_pointer_width() {
        let source = r#"
targetPointerLayout {
    type:
        Link {
            public:
                tag: byte;
                next: ptr<byte>;
            layout:
                repr(C);
        }

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(source).expect("layout fixture must lex");
        let program = ncc_parser::parse(tokens).expect("layout fixture must parse");

        let lp64 =
            lower_with_backend_profile(program.clone(), BackendLoweringProfileIR::nc_sysv64());
        let ilp32 = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_portable());

        let lp64_layout = collect_type_abi_layouts(&lp64)
            .into_iter()
            .find(|layout| layout.name == "Link")
            .expect("LP64 Link layout");
        let ilp32_layout = collect_type_abi_layouts(&ilp32)
            .into_iter()
            .find(|layout| layout.name == "Link")
            .expect("ILP32 Link layout");

        assert_eq!((lp64_layout.size_bytes, lp64_layout.align_bytes), (16, 8));
        assert_eq!(lp64_layout.fields[1].offset_bytes, 8);
        assert_eq!((ilp32_layout.size_bytes, ilp32_layout.align_bytes), (8, 4));
        assert_eq!(ilp32_layout.fields[1].offset_bytes, 4);
    }

    #[test]
    fn lower_function_abi_tag_for_root_marks_foreign_boundary_and_param_classes() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "rootAbi".into(),
                context: Some(Context::Root),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "touch_heap".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![
                        Param {
                            name: "p".into(),
                            ty: TypeName::Simple("addr".into()),
                        },
                        Param {
                            name: "n".into(),
                            ty: TypeName::Simple("int".into()),
                        },
                    ],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![
                        Stmt::Expr(Expr::QualifiedCall {
                            path: vec![
                                "memory".into(),
                                "heap".into(),
                                "manager".into(),
                                "zero".into(),
                            ],
                            args: vec![
                                Expr::ContextRef(ContextRef::plain(vec!["p".into()])),
                                Expr::ContextRef(ContextRef::plain(vec!["n".into()])),
                            ],
                        }),
                        Stmt::Return(Expr::Bool(true)),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let ContainerIR::Root(root) = &ir.containers[0] else {
            panic!("expected root IR");
        };
        let f = &root.functions[0];

        assert_eq!(f.return_type, "bool");
        assert_eq!(f.params.len(), 2);
        assert_eq!(f.params[0].pass_class, AbiPassClassIR::PointerWord);
        assert_eq!(f.params[1].pass_class, AbiPassClassIR::Register);

        assert_eq!(f.abi.tag.version, ncc_machine::NC_RAW_ABI_VERSION);
        assert_eq!(f.abi.tag.call_class, AbiCallClassIR::Root);
        assert_eq!(f.abi.tag.mode_class, AbiModeClassIR::Root);
        assert_eq!(f.abi.tag.return_class, AbiReturnClassIR::Scalar);
        assert_eq!(f.abi.tag.unwind_policy, AbiUnwindPolicyIR::MayUnwind);
        assert!(f.abi.tag.foreign_boundary);
        assert_eq!(f.abi.frame_class, AbiFrameClassIR::NonLeaf);

        assert_eq!(f.backend_plan.target, BackendTargetIR::X86_64);
        assert_eq!(
            f.backend_plan.calling_convention,
            BackendCallingConventionIR::NcSysV64
        );
        assert_eq!(
            f.backend_plan.param_locations[0].location,
            BackendValueLocationIR::Register(BackendRegisterIR::Rdi)
        );
        assert_eq!(
            f.backend_plan.param_locations[1].location,
            BackendValueLocationIR::Register(BackendRegisterIR::Rsi)
        );
        assert_eq!(
            f.backend_plan.return_location.location,
            BackendValueLocationIR::Register(BackendRegisterIR::Rax)
        );
        assert_eq!(f.backend_plan.call_sites.len(), 1);
        assert_eq!(
            f.backend_plan.call_sites[0].bridge,
            BackendBridgeKindIR::ImportBoundary
        );
        assert_eq!(f.backend_plan.call_sites[0].stack_arg_bytes, 0);
        assert_eq!(f.backend_plan.call_sites[0].bridge_scratch_bytes, 16);
        assert_eq!(
            f.backend_plan.frame_layout.callee_saved,
            vec![
                BackendRegisterIR::Rbp,
                BackendRegisterIR::R12,
                BackendRegisterIR::R13
            ]
        );
        assert_eq!(f.backend_plan.frame_layout.total_bytes, 48);
    }

