    #[test]
    fn lower_function_backend_plan_classifies_c_like_aggregate_abi_costs() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![ncc_ast::UseDecl {
                path: vec!["system".into(), "io".into(), "core".into()],
                wildcard: false,
                alias: None,
            }],
            containers: vec![Container {
                visibility: None,
                name: "aggregateAbi".into(),
                context: Some(Context::System),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "scan".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![
                        Param {
                            name: "items".into(),
                            ty: TypeName::Generic {
                                base: "slice".into(),
                                args: vec![TypeName::Simple("int".into())],
                            },
                        },
                        Param {
                            name: "events".into(),
                            ty: TypeName::Generic {
                                base: "dinArray".into(),
                                args: vec![TypeName::Simple("int".into())],
                            },
                        },
                        Param {
                            name: "p".into(),
                            ty: TypeName::Simple("ptr<int>".into()),
                        },
                    ],
                    return_type: TypeName::Generic {
                        base: "slice".into(),
                        args: vec![TypeName::Simple("int".into())],
                    },
                    public_body: vec![
                        Stmt::Expr(Expr::QualifiedCall {
                            path: vec![
                                "system".into(),
                                "io".into(),
                                "core".into(),
                                "consume".into(),
                            ],
                            args: vec![Expr::ContextRef(ContextRef::plain(vec!["items".into()]))],
                        }),
                        Stmt::Return(Expr::ContextRef(ContextRef::plain(vec!["items".into()]))),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular IR");
        };
        let f = &container.functions[0];

        assert_eq!(f.params[0].pass_class, AbiPassClassIR::ByValue);
        assert_eq!(
            f.backend_plan.param_locations[0].location,
            BackendValueLocationIR::Registers {
                registers: vec![BackendRegisterIR::Rdi, BackendRegisterIR::Rsi],
                byte_size: 16,
            }
        );
        assert_eq!(f.params[1].pass_class, AbiPassClassIR::ByValue);
        assert_eq!(
            f.backend_plan.param_locations[1].location,
            BackendValueLocationIR::StackByValue {
                byte_offset: 0,
                byte_size: 24,
                align_bytes: 8,
            }
        );
        assert_eq!(
            f.backend_plan.param_locations[2].location,
            BackendValueLocationIR::Register(BackendRegisterIR::Rdx)
        );
        assert_eq!(f.abi.tag.return_class, AbiReturnClassIR::AggregateByValue);
        assert_eq!(
            f.backend_plan.return_location.location,
            BackendValueLocationIR::Registers {
                registers: vec![BackendRegisterIR::Rax, BackendRegisterIR::Rdx],
                byte_size: 16,
            }
        );

        let import = f
            .backend_plan
            .call_sites
            .iter()
            .find(|site| site.target == "system.io.core.consume")
            .expect("import backend call site");
        assert_eq!(
            import.arg_locations[0].location,
            BackendCallArgLocationIR::Registers {
                registers: vec![BackendRegisterIR::Rdi, BackendRegisterIR::Rsi],
                byte_size: 16,
            }
        );
    }

