    fn dword_mem() -> ScalarMemTypeIR {
        ScalarMemTypeIR {
            width: ScalarMemWidthIR::Dword,
            extension: ScalarMemExtensionIR::Sign,
        }
    }

    fn symbol_expr(name: &str) -> ScalarExprIR {
        ScalarExprIR::Symbol(name.into())
    }

    fn array_read_expr(target: &str, index: ScalarExprIR) -> ScalarExprIR {
        ScalarExprIR::ArrayRead {
            target: target.into(),
            index: Box::new(index),
            mem_type: dword_mem(),
        }
    }

    fn array_write_expr(target: &str, index: ScalarExprIR, value: ScalarExprIR) -> StatementIR {
        StatementIR::ScalarExpr {
            raw: format!("{target}[i] = ..."),
            value: ScalarExprIR::ArrayWrite {
                target: target.into(),
                index: Box::new(index),
                value: Box::new(value),
                mem_type: dword_mem(),
            },
        }
    }

    #[test]
    fn auto_vectorizer_detects_contiguous_zip_loop_and_selects_simd() {
        let mut function = backend_auto_vector_test_function(BackendLoweringProfileIR::nc_sysv64());
        let value = ScalarExprIR::Binary {
            left: Box::new(array_read_expr("a", symbol_expr("i"))),
            op: ScalarBinaryOpIR::Plus,
            right: Box::new(array_read_expr("b", symbol_expr("i"))),
        };
        function.body = vec![StatementIR::ForRange {
            item: "i".into(),
            start: Some(ScalarExprIR::Number("0".into())),
            end: Some(symbol_expr("n")),
            inclusive: false,
            step: Some(ScalarExprIR::Number("1".into())),
            body: vec![array_write_expr("c", symbol_expr("i"), value)],
        }];

        let report = analyze_backend_auto_vectorization(&function);
        assert_eq!(report.loops_seen, 1);
        assert!(!report.arbitrary_pattern_parity);
        assert_eq!(report.rejected_loops.len(), 0);
        let row = report
            .vectorized_loops
            .iter()
            .find(|row| row.pattern == BackendAutoVectorPatternIR::ContiguousZip)
            .expect("contiguous zip loop must vectorize");
        assert_eq!(row.simd_op, BackendSimdOpIR::Add);
        assert_eq!(row.feature, BackendSimdFeatureIR::X86Sse);
        assert_eq!(row.selected_mnemonic, "paddd");
        assert_eq!(row.induction_symbol.as_deref(), Some("i"));
        assert_eq!(row.trip_count_symbol.as_deref(), Some("n"));
        assert!(row.source_symbols.contains(&"a".to_string()));
        assert!(row.source_symbols.contains(&"b".to_string()));
        assert!(row.source_symbols.contains(&"c".to_string()));
    }

    #[test]
    fn auto_vectorizer_detects_gather_scatter_and_schedule() {
        let mut profile = BackendLoweringProfileIR::nc_sysv64();
        profile
            .set_cpu_tuning(
                backend_cpu_tuning_profile_from_name_for_target(
                    "x86_64-v4",
                    &BackendTargetIR::X86_64,
                    "throughput",
                )
                .expect("x86_64-v4 CPU tuning must be accepted for sysv64"),
            )
            .expect("x86_64-v4 must match sysv64 target");
        let mut function = backend_auto_vector_test_function(profile);
        let gather_value = array_read_expr("base", array_read_expr("idx", symbol_expr("i")));
        let scatter_index = array_read_expr("idx", symbol_expr("i"));
        function.body = vec![StatementIR::ForRange {
            item: "i".into(),
            start: Some(ScalarExprIR::Number("0".into())),
            end: Some(symbol_expr("n")),
            inclusive: false,
            step: Some(ScalarExprIR::Number("1".into())),
            body: vec![
                array_write_expr("out", symbol_expr("i"), gather_value),
                array_write_expr(
                    "dst",
                    scatter_index,
                    array_read_expr("value", symbol_expr("i")),
                ),
            ],
        }];

        let report = analyze_backend_auto_vectorization(&function);
        assert_eq!(report.loops_seen, 1);
        let gather = report
            .vectorized_loops
            .iter()
            .find(|row| row.pattern == BackendAutoVectorPatternIR::Gather)
            .expect("indexed read must vectorize as gather");
        assert_eq!(gather.feature, BackendSimdFeatureIR::X86Avx2);
        assert_eq!(gather.selected_mnemonic, "vgatherdps");
        assert_eq!(gather.schedule.issue_domain, "vector-memory");

        let scatter = report
            .vectorized_loops
            .iter()
            .find(|row| row.pattern == BackendAutoVectorPatternIR::Scatter)
            .expect("indexed write must vectorize as scatter");
        assert_eq!(scatter.feature, BackendSimdFeatureIR::X86Avx512F);
        assert_eq!(scatter.selected_mnemonic, "vscatterdps");
        assert_eq!(scatter.schedule.issue_domain, "vector-memory-store");
    }

    #[test]
    fn auto_vectorizer_detects_reduction_and_rejects_unknown_loop() {
        let mut function =
            backend_auto_vector_test_function(BackendLoweringProfileIR::nc_aapcs64());
        function.body = vec![
            StatementIR::ForRange {
                item: "i".into(),
                start: Some(ScalarExprIR::Number("0".into())),
                end: Some(symbol_expr("n")),
                inclusive: false,
                step: Some(ScalarExprIR::Number("1".into())),
                body: vec![StatementIR::ScalarProjection {
                    target: "sum".into(),
                    ty: "int".into(),
                    raw: "sum = sum + a[i]".into(),
                    value: ScalarExprIR::Binary {
                        left: Box::new(symbol_expr("sum")),
                        op: ScalarBinaryOpIR::Plus,
                        right: Box::new(array_read_expr("a", symbol_expr("i"))),
                    },
                    storage: None,
                }],
            },
            StatementIR::While {
                condition_raw: "keepGoing".into(),
                condition: Some(symbol_expr("keepGoing")),
                body: vec![StatementIR::ScalarProjection {
                    target: "x".into(),
                    ty: "int".into(),
                    raw: "x = opaque(x)".into(),
                    value: ScalarExprIR::Call {
                        target: "opaque".into(),
                        args: vec![symbol_expr("x")],
                    },
                    storage: None,
                }],
            },
        ];

        let report = analyze_backend_auto_vectorization(&function);
        assert_eq!(report.loops_seen, 2);
        let reduction = report
            .vectorized_loops
            .iter()
            .find(|row| row.pattern == BackendAutoVectorPatternIR::ReductionSum)
            .expect("sum reduction must vectorize");
        assert_eq!(reduction.feature, BackendSimdFeatureIR::AArch64Neon);
        assert_eq!(reduction.selected_mnemonic, "add v0.4s");
        assert_eq!(reduction.cost.lanes_per_chunk, 4);
        assert_eq!(report.rejected_loops.len(), 1);
        assert_eq!(
            report.rejected_loops[0].diagnostics[0].code,
            "E_AUTO_VEC_PATTERN_001"
        );
    }

    #[test]
    fn mct_translation_reports_modal_units_and_provider_contracts() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "mctFixture".into(),
                context: None,
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "boot".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("int".into()),
                    public_body: vec![Stmt::Return(Expr::Number("0".into()))],
                }])],
            }],
        };
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let report = mct_translate_program(&ir);
        assert_eq!(report.schema, "nc.mct.translation.v1");
        assert_eq!(report.status, "mct_infrastructure_contract_ready");
        assert!(report.ncc_native_integrated);
        assert!(!report.full_llvm_parity);
        assert!(!report.full_gcc_parity);
        assert!(!report.full_rustc_parity);
        assert_eq!(report.units.len(), 1);
        assert_eq!(report.units[0].mode, "regular");
        assert_eq!(
            report.units[0].primary_provider,
            MctBackendProviderIR::NccNative
        );
        assert!(report.units[0]
            .eligible_providers
            .contains(&MctBackendProviderIR::Llvm));
        assert!(report.backend_contracts.iter().any(|contract| {
            contract.provider == MctBackendProviderIR::NccNative
                && contract.status == MctBackendStatusIR::Integrated
                && contract.capabilities.contains(&MctCapabilityIR::PointerOps)
        }));
        assert!(report.backend_contracts.iter().any(|contract| {
            contract.provider == MctBackendProviderIR::Llvm
                && contract.status == MctBackendStatusIR::AdapterIntegrated
        }));
    }

