        assert_eq!(module.rejected_function_count, 0);
        assert!(module.diagnostics.is_empty(), "{:?}", module.diagnostics);
        assert!(module
            .llvm_ir
            .contains("call i32 @llvmCallScopeLeft_text(i32 40)"));
        assert!(module
            .llvm_ir
            .contains("call i32 @llvmCallScopeRight_text(i32 20, i32 22)"));
