    #[test]
    fn mct_llvm_construct_coverage_represents_adapter_boundaries() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "llvmConstructCoverageFixture".into(),
                context: None,
                sections: vec![
                    Section::TypeContracts(vec![
                        TypeContractDecl {
                            name: "Mode".into(),
                            kind: TypeContractKind::Enum,
                            generic_params: Vec::new(),
                            variants: Vec::new(),
                            clauses: Vec::new(),
                        },
                        TypeContractDecl {
                            name: "Packet".into(),
                            kind: TypeContractKind::TaggedUnion,
                            generic_params: Vec::new(),
                            variants: vec![
                                ncc_ast::TypeContractVariant {
                                    name: "None".into(),
                                    payload: Vec::new(),
                                },
                                ncc_ast::TypeContractVariant {
                                    name: "Value".into(),
                                    payload: vec![ncc_ast::TypeContractField {
                                        name: "data".into(),
                                        ty: TypeName::Simple("qword".into()),
                                    }],
                                },
                            ],
                            clauses: Vec::new(),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("int".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "items".into()
                                ])),
                                ty: TypeName::Generic {
                                    base: "array".into(),
                                    args: vec![
                                        TypeName::Simple("int".into()),
                                        TypeName::Simple("2".into()),
                                    ],
                                },
                                value: Expr::ArrayLiteral(vec![
                                    Expr::Number("1".into()),
                                    Expr::Number("2".into()),
                                ]),
                            },
                            Stmt::Return(Expr::Number("7".into())),
                        ],
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        let coverage = &module.construct_coverage;
        assert_eq!(coverage.schema, "nc.mct.llvm.construct_coverage.v1");
        assert_eq!(coverage.status, "llvm_construct_coverage_closed");
        assert_eq!(coverage.present_not_represented_count, 0);
        assert_eq!(coverage.not_represented_count, 0);
        assert!(coverage.rows.iter().any(|row| {
            row.construct == "statement.scalar_return"
                && row.status == MctLlvmConstructRepresentationIR::Represented
                && row.present_in_module
        }));
        assert!(coverage.rows.iter().any(|row| {
            row.construct == "expr.array_literal_projection"
                && row.status == MctLlvmConstructRepresentationIR::Represented
                && row.present_in_module
        }));
        assert!(coverage.rows.iter().any(|row| {
            row.construct == "type.enum"
                && row.status == MctLlvmConstructRepresentationIR::Represented
                && row.present_in_module
                && row.diagnostic.is_none()
        }));
        assert!(coverage.rows.iter().any(|row| {
            row.construct == "type.tagged_union"
                && row.status == MctLlvmConstructRepresentationIR::Represented
                && row.present_in_module
                && row.diagnostic.is_none()
        }));
        assert!(coverage.rows.iter().any(|row| {
            row.construct == "container.machine"
                && row.status == MctLlvmConstructRepresentationIR::ForbiddenByMode
                && !row.present_in_module
                && row.diagnostic == Some("E_MCT_LLVM_MACHINE_FORBIDDEN_001")
        }));
    }

    #[test]
    fn regular_local_const_initializers_prefix_function_body() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "regularLocalConstFixture".into(),
                context: None,
                sections: vec![
                    Section::Local(ncc_ast::LocalSection {
                        decls: vec![ncc_ast::LocalDecl::Const {
                            visibility: None,
                            name: "Limit".into(),
                            ty: TypeName::Simple("int".into()),
                            value: Expr::Number("7".into()),
                        }],
                    }),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "run".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("int".into()),
                        public_body: vec![Stmt::Return(Expr::ContextRef(ContextRef::plain(vec![
                            "Limit".into(),
                        ])))],
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let first_stmt = container.functions[0]
            .body
            .first()
            .expect("local const initializer must be emitted before function body");
        assert!(matches!(
            first_stmt,
            StatementIR::ScalarProjection {
                target,
                value: ScalarExprIR::Number(value),
                ..
            } if target == "Limit" && value == "7"
        ));
    }

    #[test]
    fn mct_surface_descriptors_materialize_high_level_constructs_as_bytes() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: Some(Visibility::Public),
                name: "surfaceMaterialFixture".into(),
                context: Some(Context::Runtime),
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: Some(Visibility::Public),
                            strictly: true,
                            name: "contador".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Number("1".into())),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: Some(Visibility::Private),
                            strictly: false,
                            name: "cache".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![
                                    TypeName::Simple("int".into()),
                                    TypeName::Simple("100".into()),
                                ],
                            },
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: Some(Visibility::Private),
                            strictly: false,
                            name: "seed".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![
                                    TypeName::Simple("int".into()),
                                    TypeName::Simple("3".into()),
                                ],
                            },
                            init: Some(Expr::ArrayLiteral(vec![
                                Expr::Number("1".into()),
                                Expr::Number("2".into()),
                                Expr::Number("3".into()),
                            ])),
                        },
                    ]),
                    Section::Local(ncc_ast::LocalSection {
                        decls: vec![
                            ncc_ast::LocalDecl::Var {
                                visibility: Some(Visibility::Private),
                                name: "tmp".into(),
                                ty: TypeName::Simple("int".into()),
                                init: Some(Expr::Number("0".into())),
                            },
                            ncc_ast::LocalDecl::Const {
                                visibility: Some(Visibility::Internal),
                                name: "max".into(),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("9".into()),
                            },
                            ncc_ast::LocalDecl::TypeAlias {
                                visibility: Some(Visibility::Public),
                                name: "Nothing".into(),
                                ty: TypeName::Simple("void".into()),
                            },
                            ncc_ast::LocalDecl::TypeRecord {
                                visibility: Some(Visibility::Strictly),
                                name: "Alumno".into(),
                                fields: vec![
                                    ncc_ast::LocalTypeField {
                                        visibility: Some(Visibility::Public),
                                        name: "id".into(),
                                        ty: TypeName::Simple("int".into()),
                                    },
                                    ncc_ast::LocalTypeField {
                                        visibility: Some(Visibility::Private),
                                        name: "nombre".into(),
                                        ty: TypeName::Simple("str".into()),
                                    },
                                ],
                            },
                            ncc_ast::LocalDecl::Metadata {
                                visibility: Some(Visibility::Public),
                                name: "audit".into(),
                                value: Expr::String("material".into()),
                            },
                        ],
                    }),
                    Section::TypeContracts(vec![TypeContractDecl {
                        name: "Packet".into(),
                        kind: TypeContractKind::Struct,
                        generic_params: Vec::new(),
                        variants: Vec::new(),
                        clauses: vec![
                            TypeContractClause::Fields {
                                visibility: Visibility::Public,
                                fields: vec![TypeContractField {
                                    name: "flag".into(),
                                    ty: TypeName::Simple("bool".into()),
                                }],
                            },
                            TypeContractClause::Fields {
                                visibility: Visibility::Strictly,
                                fields: vec![TypeContractField {
                                    name: "unit".into(),
                                    ty: TypeName::Simple("void".into()),
                                }],
                            },
                        ],
                    }]),
                    Section::Fn(vec![FunctionDecl {
                        visibility: Some(Visibility::Public),
                        is_async: false,
                        effects: vec![],
                        name: "run".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                    Section::MoveFn(vec![FunctionDecl {
                        visibility: Some(Visibility::Private),
                        is_async: false,
                        effects: vec![],
                        name: "mover".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("void".into()),
                        public_body: Vec::new(),
                    }]),
                    Section::ConstFn(vec![FunctionDecl {
                        visibility: Some(Visibility::Public),
                        is_async: false,
                        effects: vec![],
                        name: "cte".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("int".into()),
                        public_body: vec![Stmt::Return(Expr::Number("1".into()))],
                    }]),
                    Section::Probe(vec![Stmt::Expr(Expr::Identifier("probeAudit".into()))]),
                    Section::Final(vec![Stmt::Return(Expr::Bool(true))]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let has_descriptor = |construct: &str| {
            ir.surface_descriptors
                .iter()
                .any(|descriptor| descriptor.construct == construct)
        };

        for construct in [
            "container.surface",
            "section.stc",
            "section.local",
            "section.fn",
            "section.move_fn",
            "section.const_fn",
            "section.probe",
            "stc.symbol",
            "stc.array.zero_fill",
            "stc.array.literal",
            "local.var",
            "local.const",
            "local.metadata",
            "type.alias",
            "type.record",
            "type.field",
            "type.contract",
            "function.fn",
            "function.move_fn",
            "function.const_fn",
            "visibility.public",
            "visibility.private",
            "visibility.internal",
            "visibility.strictly",
            "modifier.strictly",
            "type.void",
        ] {
            assert!(has_descriptor(construct), "missing {construct}");
        }

        let descriptor = ir
            .surface_descriptors
            .iter()
            .find(|descriptor| descriptor.construct == "stc.symbol")
            .expect("stc symbol descriptor must exist");
        assert_eq!(&descriptor.bytes[0..4], b"NCSD");
        assert_eq!(descriptor.container, "surfaceMaterialFixture");
        assert_eq!(descriptor.symbol.as_deref(), Some("contador"));
        assert_eq!(descriptor.fingerprint.len(), 16);

        let zero_fill_descriptor = ir
            .surface_descriptors
            .iter()
            .find(|descriptor| {
                descriptor.construct == "stc.array.zero_fill"
                    && descriptor.symbol.as_deref() == Some("cache")
            })
            .expect("fixed array stc descriptor must expose zero-fill storage");
        assert_eq!(&zero_fill_descriptor.bytes[0..4], b"NCSD");
        assert_eq!(
            zero_fill_descriptor.nc_type.as_deref(),
            Some("array<int, 100>")
        );
        assert!(zero_fill_descriptor.payload.contains("elements=100"));
        assert!(zero_fill_descriptor.payload.contains("storage_bytes=400"));
        assert!(zero_fill_descriptor
            .payload
            .contains("native_bytes_status=aggregate_storage_bytes_real"));

        let literal_descriptor = ir
            .surface_descriptors
            .iter()
            .find(|descriptor| {
                descriptor.construct == "stc.array.literal"
                    && descriptor.symbol.as_deref() == Some("seed")
            })
            .expect("fixed array stc descriptor must expose literal storage");
        assert_eq!(&literal_descriptor.bytes[0..4], b"NCSD");
        assert_eq!(literal_descriptor.nc_type.as_deref(), Some("array<int, 3>"));
        assert!(literal_descriptor.payload.contains("literal=true"));
        assert!(literal_descriptor.payload.contains("elements=3"));
        assert!(literal_descriptor.payload.contains("storage_bytes=12"));

        let report = mct_translate_program(&ir);
        assert_eq!(
            report.surface_descriptor_count,
            ir.surface_descriptors.len()
        );
        assert_eq!(
            report.surface_descriptor_bytes,
            ir.surface_descriptors
                .iter()
                .map(|descriptor| descriptor.bytes.len())
                .sum::<usize>()
        );

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(
            module.surface_descriptor_count,
            ir.surface_descriptors.len()
        );
        assert!(module.construct_coverage.rows.iter().any(|row| {
            row.construct == "section.move_fn"
                && row.present_in_module
                && row.status == MctLlvmConstructRepresentationIR::Represented
        }));
        assert!(module.construct_coverage.rows.iter().any(|row| {
            row.construct == "type.void"
                && row.present_in_module
                && row.status == MctLlvmConstructRepresentationIR::Represented
        }));
        assert!(module.construct_coverage.rows.iter().any(|row| {
            row.construct == "stc.array.zero_fill"
                && row.present_in_module
                && row.status == MctLlvmConstructRepresentationIR::Represented
        }));
        assert!(module.construct_coverage.rows.iter().any(|row| {
            row.construct == "stc.array.literal"
                && row.present_in_module
                && row.status == MctLlvmConstructRepresentationIR::Represented
        }));
    }

