    #[test]
    fn mct_llvm_lowers_pointer_intrinsics_to_load_store_gep_and_diff() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "llvmPointerFixture".into(),
                context: None,
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "delta".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![
                        ncc_ast::Param {
                            name: "left".into(),
                            ty: TypeName::Simple("ptr<int>".into()),
                        },
                        ncc_ast::Param {
                            name: "right".into(),
                            ty: TypeName::Simple("ptr<int>".into()),
                        },
                    ],
                    return_type: TypeName::Simple("int".into()),
                    public_body: vec![
                        Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec!["next".into()])),
                            ty: TypeName::Simple("ptr<int>".into()),
                            value: Expr::Call {
                                callee: "ptrOffset<int>".into(),
                                args: vec![
                                    Expr::ContextRef(ContextRef::plain(vec!["left".into()])),
                                    Expr::Number("1".into()),
                                ],
                            },
                        },
                        Stmt::Expr(Expr::Call {
                            callee: "ptrWrite<int>".into(),
                            args: vec![
                                Expr::ContextRef(ContextRef::plain(vec!["next".into()])),
                                Expr::Number("7".into()),
                            ],
                        }),
                        Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec!["value".into()])),
                            ty: TypeName::Simple("int".into()),
                            value: Expr::Call {
                                callee: "ptrRead<int>".into(),
                                args: vec![Expr::ContextRef(ContextRef::plain(
                                    vec!["next".into()],
                                ))],
                            },
                        },
                        Stmt::Return(Expr::Call {
                            callee: "ptrDiff<int>".into(),
                            args: vec![
                                Expr::ContextRef(ContextRef::plain(vec!["next".into()])),
                                Expr::ContextRef(ContextRef::plain(vec!["right".into()])),
                            ],
                        }),
                    ],
                }])],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert!(module.llvm_ir.contains("getelementptr i8"));
        assert!(module.llvm_ir.contains("store i32"));
        assert!(module.llvm_ir.contains("load i32"));
        assert!(module.llvm_ir.contains("ptrtoint ptr"));
        assert!(module.llvm_ir.contains("sdiv i64"));
    }

    #[test]
    fn mct_llvm_lowers_compact_pointer_reads_with_declared_projection_types() {
        let src = r#"
compactPtrIr {
    stc:
        value >> int = 0;
        sum >> int = 0;

    fn:
        public:
            run(p: ptr<int>, q: ptr<int>) -> int {
                value = *p;
                sum = ptrRead<int>(q);
                sum = value + sum;
                return sum;
            }

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let regular = match &ir.containers[0] {
            ContainerIR::Regular(regular) => regular,
            other => panic!("expected regular container, got {other:?}"),
        };
        let run = regular
            .functions
            .iter()
            .find(|function| function.name == "run")
            .expect("run function must lower");

        let compact_reads = run
            .body
            .iter()
            .filter(|stmt| {
                matches!(
                    stmt,
                    StatementIR::ScalarProjection {
                        ty,
                        value: ScalarExprIR::PtrRead { .. },
                        ..
                    } if ty == "int"
                )
            })
            .count();
        assert_eq!(
            compact_reads, 2,
            "both *p and ptrRead<int>(q) must lower as typed int pointer loads"
        );
        assert!(
            run.body.iter().all(|stmt| !matches!(
                stmt,
                StatementIR::ScalarProjection { ty, .. }
                    if ty == INFER_PROJECTION_TYPE_NAME
            )),
            "inferred projection marker must not reach IR scalar projections"
        );

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert!(module.llvm_ir.contains("load i32"));
    }

