    #[test]
    fn mct_llvm_lowers_struct_layout_and_field_access() {
        let packet_ty = TypeName::Simple("Packet".into());
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "llvmStructFixture".into(),
                context: None,
                sections: vec![
                    Section::TypeContracts(vec![TypeContractDecl {
                        name: "Packet".into(),
                        kind: TypeContractKind::Struct,
                        generic_params: Vec::new(),
                        variants: Vec::new(),
                        clauses: vec![TypeContractClause::Fields {
                            visibility: Visibility::Public,
                            fields: vec![
                                TypeContractField {
                                    name: "tag".into(),
                                    ty: TypeName::Simple("int".into()),
                                },
                                TypeContractField {
                                    name: "count".into(),
                                    ty: TypeName::Simple("int".into()),
                                },
                                TypeContractField {
                                    name: "total".into(),
                                    ty: TypeName::Simple("qword".into()),
                                },
                            ],
                        }],
                    }]),
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "packet".into(),
                            ty: packet_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "got".into(),
                            ty: TypeName::Simple("int".into()),
                            init: None,
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "packet".into(),
                                    "tag".into(),
                                ])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("7".into()),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["got".into()],
                                )),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::ContextRef(ContextRef::plain(vec![
                                    "packet".into(),
                                    "tag".into(),
                                ])),
                            },
                            Stmt::Return(Expr::Binary {
                                left: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                    "got".into()
                                ]))),
                                op: BinaryOp::EqEq,
                                right: Box::new(Expr::Number("7".into())),
                            }),
                        ],
                    }]),
                    Section::Final(vec![Stmt::MainRefFn {
                        kind: MainKind::Ref,
                        fn_ref: ncc_ast::FnRef {
                            path: vec!["boot".into()],
                        },
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.structs.len(), 1);
        let layout = &module.structs[0];
        assert_eq!(layout.source_name, "llvmStructFixture.Packet");
        assert_eq!(layout.field_count, 3);
        assert_eq!(layout.size_bytes, 16);
        assert_eq!(layout.align_bytes, 8);
        assert_eq!(layout.fields[0].offset_bytes, 0);
        assert_eq!(layout.fields[1].offset_bytes, 4);
        assert_eq!(layout.fields[2].offset_bytes, 8);
        assert_eq!(module.type_abi_layouts.len(), 1);
        let abi = &module.type_abi_layouts[0];
        assert_eq!(abi.schema, "nc.type_abi.layout.v1");
        assert_eq!(abi.status, "stable_type_abi_v1");
        assert_eq!(abi.qualified_name, "llvmStructFixture.Packet");
        assert_eq!(abi.kind, TypeContractKindIR::Struct);
        assert_eq!(abi.size_bytes, 16);
        assert_eq!(abi.align_bytes, 8);
        assert_eq!(abi.field_count, 3);
        assert_eq!(abi.fields[0].offset_bytes, 0);
        assert_eq!(abi.fields[1].offset_bytes, 4);
        assert_eq!(abi.fields[2].offset_bytes, 8);
        assert_eq!(abi.fields[2].size_bytes, 8);
        assert_eq!(abi.fields[2].align_bytes, 8);
        assert_eq!(abi.fields[2].llvm_type, "i64");
        assert_eq!(abi.fingerprint.len(), 16);
        assert!(module
            .llvm_ir
            .contains("%struct.llvmStructFixture_Packet = type { i32, i32, i64 }"));
        assert!(module
            .llvm_ir
            .contains("; ncc-type-abi llvmStructFixture.Packet kind=struct status=stable_type_abi_v1 size=16 align=8 fingerprint="));
        assert!(module
            .llvm_ir
            .contains("; ncc-type-abi-field llvmStructFixture.Packet.total index=2 offset=8 size=8 align=8 ty=qword"));
        assert!(module.llvm_ir.contains(
            "@__ncc_stc_llvmStructFixture_packet = global %struct.llvmStructFixture_Packet"
        ));
        assert!(module.llvm_ir.contains("i32 0"));
        assert!(module.llvm_ir.contains("store i32 7"));
        assert!(module.llvm_ir.contains("load i32"));
        assert!(module.llvm_ir.contains("define i32 @main()"));
    }

    #[test]
    fn mct_llvm_calculates_nested_forward_struct_layout() {
        let program = Program {
            modules: Vec::new(),
            packages: Vec::new(),
            uses: Vec::new(),
            containers: vec![Container {
                visibility: None,
                name: "llvmNestedStructLayoutFixture".into(),
                context: None,
                sections: vec![
                    Section::TypeContracts(vec![
                        TypeContractDecl {
                            name: "Envelope".into(),
                            kind: TypeContractKind::Struct,
                            generic_params: Vec::new(),
                            variants: Vec::new(),
                            clauses: vec![TypeContractClause::Fields {
                                visibility: Visibility::Public,
                                fields: vec![
                                    TypeContractField {
                                        name: "kind".into(),
                                        ty: TypeName::Simple("byte".into()),
                                    },
                                    TypeContractField {
                                        name: "footer".into(),
                                        ty: TypeName::Simple("Footer".into()),
                                    },
                                    TypeContractField {
                                        name: "tail".into(),
                                        ty: TypeName::Simple("int".into()),
                                    },
                                ],
                            }],
                        },
                        TypeContractDecl {
                            name: "Footer".into(),
                            kind: TypeContractKind::Struct,
                            generic_params: Vec::new(),
                            variants: Vec::new(),
                            clauses: vec![TypeContractClause::Fields {
                                visibility: Visibility::Public,
                                fields: vec![
                                    TypeContractField {
                                        name: "code".into(),
                                        ty: TypeName::Simple("qword".into()),
                                    },
                                    TypeContractField {
                                        name: "flag".into(),
                                        ty: TypeName::Simple("byte".into()),
                                    },
                                ],
                            }],
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: Vec::new(),
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                    Section::Final(vec![Stmt::MainRefFn {
                        kind: MainKind::Ref,
                        fn_ref: ncc_ast::FnRef {
                            path: vec!["boot".into()],
                        },
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");

        let footer = module
            .structs
            .iter()
            .find(|layout| layout.source_name == "llvmNestedStructLayoutFixture.Footer")
            .expect("Footer layout");
        assert_eq!(footer.field_count, 2);
        assert_eq!(footer.size_bytes, 16);
        assert_eq!(footer.align_bytes, 8);
        assert_eq!(footer.fields[0].offset_bytes, 0);
        assert_eq!(footer.fields[0].size_bytes, 8);
        assert_eq!(footer.fields[0].align_bytes, 8);
        assert_eq!(footer.fields[1].offset_bytes, 8);
        assert_eq!(footer.fields[1].size_bytes, 1);
        assert_eq!(footer.fields[1].align_bytes, 1);

        let envelope = module
            .structs
            .iter()
            .find(|layout| layout.source_name == "llvmNestedStructLayoutFixture.Envelope")
            .expect("Envelope layout");
        assert_eq!(envelope.field_count, 3);
        assert_eq!(envelope.size_bytes, 32);
        assert_eq!(envelope.align_bytes, 8);
        assert_eq!(envelope.fields[0].offset_bytes, 0);
        assert_eq!(envelope.fields[0].size_bytes, 1);
        assert_eq!(envelope.fields[1].offset_bytes, 8);
        assert_eq!(envelope.fields[1].size_bytes, 16);
        assert_eq!(envelope.fields[1].align_bytes, 8);
        assert_eq!(envelope.fields[1].llvm_type, footer.llvm_type);
        assert_eq!(envelope.fields[2].offset_bytes, 24);
        assert_eq!(envelope.fields[2].size_bytes, 4);
        assert_eq!(envelope.fields[2].align_bytes, 4);
        let envelope_abi = module
            .type_abi_layouts
            .iter()
            .find(|layout| layout.qualified_name == "llvmNestedStructLayoutFixture.Envelope")
            .expect("Envelope ABI layout");
        assert_eq!(envelope_abi.status, "stable_type_abi_v1");
        assert_eq!(envelope_abi.size_bytes, envelope.size_bytes);
        assert_eq!(envelope_abi.align_bytes, envelope.align_bytes);
        assert_eq!(envelope_abi.fields[1].offset_bytes, 8);
        assert_eq!(envelope_abi.fields[1].size_bytes, 16);
        assert_eq!(envelope_abi.fields[1].llvm_type, footer.llvm_type);
        assert!(module.llvm_ir.contains(&format!(
            "{} = type {{ i8, {}, i32 }}",
            envelope.llvm_type, footer.llvm_type
        )));
    }

    #[test]
    fn mct_llvm_lowers_nested_struct_field_access() {
        let src = r#"
llvmNestedStructFieldAccess {
    type:
        Header {
            public:
                mark: int;
                code: int;
        }

        Packet {
            public:
                id: int;
                header: Header;
                total: qword;
        }

    stc:
        packet: Packet;
        got: int;
        old: int;

    fn:
        boot() -> bool {
            public:
                @packet.header.mark >> int : 41;
                @got >> int : @packet.header.mark;
                @old >> int : @packet.header.mark++;
                return @got == 41 && @old == 41;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let boot = container
            .functions
            .iter()
            .find(|function| function.name == "boot")
            .expect("boot function");
        let nested_fields = vec!["header".to_string(), "mark".to_string()];
        assert!(boot.body.iter().any(|stmt| {
            matches!(
                stmt,
                StatementIR::ScalarExpr {
                    value: ScalarExprIR::FieldWrite { base, fields, .. },
                    ..
                } if base == "packet" && fields == &nested_fields
            )
        }));
        assert!(boot.body.iter().any(|stmt| {
            matches!(
                stmt,
                StatementIR::ScalarProjection {
                    value: ScalarExprIR::FieldRead { base, fields },
                    ..
                } if base == "packet" && fields == &nested_fields
            )
        }));
        assert!(boot.body.iter().any(|stmt| {
            matches!(
                stmt,
                StatementIR::ScalarProjection {
                    value: ScalarExprIR::FieldPostIncrement { base, fields },
                    ..
                } if base == "packet" && fields == &nested_fields
            )
        }));

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(module.diagnostics.is_empty());
        let packet_ty = "%struct.llvmNestedStructFieldAccess_Packet";
        let header_ty = "%struct.llvmNestedStructFieldAccess_Header";
        assert!(module
            .llvm_ir
            .contains(&format!("{header_ty} = type {{ i32, i32 }}")));
        assert!(module
            .llvm_ir
            .contains(&format!("{packet_ty} = type {{ i32, {header_ty}, i64 }}")));
        let packet_header_geps = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(&format!("getelementptr inbounds {packet_ty}")))
            .filter(|line| line.contains("i32 1"))
            .count();
        let header_mark_geps = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(&format!("getelementptr inbounds {header_ty}")))
            .filter(|line| line.contains("i32 0"))
            .count();
        assert!(
            packet_header_geps >= 3 && header_mark_geps >= 3,
            "nested field lowering must emit Packet.header and Header.mark GEPs; IR:\n{}",
            module.llvm_ir
        );
        assert!(module.llvm_ir.contains("store i32 41, ptr"));
        assert!(module.llvm_ir.contains("load i32, ptr"));
    }

    #[test]
    fn mct_llvm_lowers_posix_sleep_family_to_c_usleep() {
        let src = r#"
use::stoud::time::<sleep>;
use nC.runtime.sleep;

llvmPosixSleepBackend[@runtime] {
    fn:
        boot() -> bool {
            public:
                sleep(0);
                sleepMs(0);
                sleepSec(0);
                yieldRuntime();
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);

        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(module.diagnostics.is_empty(), "{:?}", module.diagnostics);
        assert!(module.llvm_ir.contains("declare i32 @usleep(i32)"));
        assert_eq!(module.llvm_ir.matches("call i32 @usleep(i32").count(), 4);
        assert!(module.llvm_ir.contains("icmp slt i64"));
        assert!(module.llvm_ir.contains("select i1"));
        assert!(!module.llvm_ir.contains("@Sleep("), "{}", module.llvm_ir);
    }

