    #[test]
    fn mct_llvm_lowers_dynamic_arrays_and_memregion_views() {
        let array_int = TypeName::Generic {
            base: "array".into(),
            args: vec![TypeName::Simple("int".into())],
        };
        let region_int = TypeName::Generic {
            base: "memRegion".into(),
            args: vec![TypeName::Simple("int".into())],
        };
        let queue_int = TypeName::Generic {
            base: "queue".into(),
            args: vec![TypeName::Simple("int".into())],
        };
        let program = Program {
            modules: Vec::new(),
            packages: Vec::new(),
            uses: Vec::new(),
            containers: vec![Container {
                visibility: None,
                name: "llvmDynamicArraySliceFixture".into(),
                context: None,
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "arr".into(),
                            ty: array_int.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "view".into(),
                            ty: region_int.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "q".into(),
                            ty: queue_int,
                            init: None,
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: Vec::new(),
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["arr".into()],
                                )),
                                ty: array_int.clone(),
                                value: Expr::ArrayLiteral(vec![
                                    Expr::Number("10".into()),
                                    Expr::Number("20".into()),
                                    Expr::Number("30".into()),
                                    Expr::Number("40".into()),
                                ]),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "view".into()
                                ])),
                                ty: region_int,
                                value: Expr::Call {
                                    callee: "regionFromPtr<int>".into(),
                                    args: vec![
                                        Expr::ContextRef(ContextRef::plain(vec!["arr".into()])),
                                        Expr::Number("4".into()),
                                    ],
                                },
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec!["i".into()])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("2".into()),
                            },
                            Stmt::Expr(Expr::MethodCall {
                                receiver: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                    "view".into(),
                                ]))),
                                method: "writeAt".into(),
                                args: vec![
                                    Expr::ContextRef(ContextRef::plain(vec!["i".into()])),
                                    Expr::Number("77".into()),
                                ],
                            }),
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["out".into()],
                                )),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Index {
                                    target: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "arr".into(),
                                    ]))),
                                    index: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "i".into()
                                    ]))),
                                },
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "count".into()
                                ])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::MethodCall {
                                    receiver: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "view".into(),
                                    ]))),
                                    method: "len".into(),
                                    args: Vec::new(),
                                },
                            },
                            Stmt::Expr(Expr::Call {
                                callee: "regionFill".into(),
                                args: vec![
                                    Expr::ContextRef(ContextRef::plain(vec!["view".into()])),
                                    Expr::Number("9".into()),
                                ],
                            }),
                            Stmt::Expr(Expr::Call {
                                callee: "regionZero".into(),
                                args: vec![Expr::ContextRef(ContextRef::plain(
                                    vec!["view".into()],
                                ))],
                            }),
                            Stmt::Return(Expr::Binary {
                                left: Box::new(Expr::Binary {
                                    left: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "out".into(),
                                    ]))),
                                    op: BinaryOp::EqEq,
                                    right: Box::new(Expr::Number("77".into())),
                                }),
                                op: BinaryOp::AndAnd,
                                right: Box::new(Expr::Binary {
                                    left: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "count".into(),
                                    ]))),
                                    op: BinaryOp::EqEq,
                                    right: Box::new(Expr::Number("4".into())),
                                }),
                            }),
                        ],
                    }]),
                    Section::Final(vec![Stmt::MainRefFn {
                        kind: MainKind::Ref,
                        fn_ref: ncc_ast::FnRef {
                            path: vec!["boot".into()],
                        },
                    }]),
                ],
            }],
        };
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert_eq!(module.dynamic_views.len(), 3);
        assert!(module
            .dynamic_views
            .iter()
            .any(|view| view.kind == "dynamic_array" && view.field_count == 2));
        assert!(module
            .dynamic_views
            .iter()
            .any(|view| view.kind == "memregion" && view.field_count == 2));
        let queue_view = module
            .dynamic_views
            .iter()
            .find(|view| view.source_type == "queue<int>")
            .expect("queue<int> dynamic view");
        assert_eq!(queue_view.kind, "dinarray");
        assert_eq!(queue_view.field_count, 3);
        assert_eq!(queue_view.size_bytes, 24);
        assert_eq!(queue_view.align_bytes, 8);
        assert!(queue_view.has_capacity);
        assert!(module
            .llvm_ir
            .contains("%nC.dynamic_array_i32 = type { ptr, i64 }"));
        assert!(module
            .llvm_ir
            .contains("%nC.memregion_i32 = type { ptr, i64 }"));
        assert!(module
            .llvm_ir
            .contains("%nC.dinarray_i32 = type { ptr, i64, i64 }"));
        assert!(module.llvm_ir.contains("alloca [16 x i8]"));
        assert!(
            !module.llvm_ir.contains("call ptr @malloc"),
            "manual/raw array literals must remain caller-owned stack storage:\n{}",
            module.llvm_ir
        );
        assert!(module.llvm_ir.contains("store i32 77"));
        assert!(module.llvm_ir.contains("store i32 9"));
        assert!(module.llvm_ir.contains("@llvm.memset.p0.i64"));
        assert!(module.llvm_ir.contains("load i64"));
        assert!(module.llvm_ir.contains("getelementptr i8"));
    }

    #[test]
    fn mct_llvm_maps_vector_struct_to_dinarray_descriptor() {
        let packet_ty = TypeName::Simple("Packet".into());
        let vector_packet_ty = TypeName::Generic {
            base: "vector".into(),
            args: vec![packet_ty.clone()],
        };
        let program = Program {
            modules: Vec::new(),
            packages: vec![ncc_ast::PackageDecl {
                name: "vector_struct_owned_storage".into(),
                version: None,
                profile: Some("raw".into()),
                modules: Vec::new(),
            }],
            uses: Vec::new(),
            containers: vec![Container {
                visibility: None,
                name: "llvmVectorStructFixture".into(),
                context: None,
                sections: vec![
                    Section::TypeContracts(vec![
                        TypeContractDecl {
                            name: "Packet".into(),
                            kind: TypeContractKind::Struct,
                            generic_params: Vec::new(),
                            variants: Vec::new(),
                            clauses: vec![TypeContractClause::Fields {
                                visibility: Visibility::Public,
                                fields: vec![
                                    TypeContractField {
                                        name: "id".into(),
                                        ty: TypeName::Simple("int".into()),
                                    },
                                    TypeContractField {
                                        name: "tag".into(),
                                        ty: TypeName::Simple("qword".into()),
                                    },
                                ],
                            }],
                        },
                        TypeContractDecl {
                            name: "PacketBatch".into(),
                            kind: TypeContractKind::Struct,
                            generic_params: Vec::new(),
                            variants: Vec::new(),
                            clauses: vec![TypeContractClause::Fields {
                                visibility: Visibility::Public,
                                fields: vec![
                                    TypeContractField {
                                        name: "items".into(),
                                        ty: vector_packet_ty.clone(),
                                    },
                                    TypeContractField {
                                        name: "count".into(),
                                        ty: TypeName::Simple("int".into()),
                                    },
                                ],
                            }],
                        },
                    ]),
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "packets".into(),
                            ty: vector_packet_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "packet".into(),
                            ty: packet_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "got".into(),
                            ty: packet_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "i".into(),
                            ty: TypeName::Simple("int".into()),
                            init: None,
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: Vec::new(),
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "packets".into()
                                ])),
                                ty: vector_packet_ty.clone(),
                                value: Expr::ArrayLiteral(Vec::new()),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "packet".into(),
                                    "id".into(),
                                ])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("42".into()),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec![
                                    "packet".into(),
                                    "tag".into(),
                                ])),
                                ty: TypeName::Simple("qword".into()),
                                value: Expr::Number("9001".into()),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec!["i".into()])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("0".into()),
                            },
                            Stmt::Expr(Expr::MethodCall {
                                receiver: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                    "packets".into(),
                                ]))),
                                method: "push".into(),
                                args: vec![Expr::ContextRef(ContextRef::plain(vec![
                                    "packet".into()
                                ]))],
                            }),
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["got".into()],
                                )),
                                ty: packet_ty,
                                value: Expr::MethodCall {
                                    receiver: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "packets".into(),
                                    ]))),
                                    method: "get".into(),
                                    args: vec![Expr::ContextRef(ContextRef::plain(vec![
                                        "i".into()
                                    ]))],
                                },
                            },
                            Stmt::Expr(Expr::MethodCall {
                                receiver: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                    "packets".into(),
                                ]))),
                                method: "set".into(),
                                args: vec![
                                    Expr::ContextRef(ContextRef::plain(vec!["i".into()])),
                                    Expr::ContextRef(ContextRef::plain(vec!["got".into()])),
                                ],
                            }),
                            Stmt::Return(Expr::Bool(true)),
                        ],
                    }]),
                    Section::Final(vec![Stmt::MainRefFn {
                        kind: MainKind::Ref,
                        fn_ref: ncc_ast::FnRef {
                            path: vec!["boot".into()],
                        },
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);

        let packet_layout = module
            .structs
            .iter()
            .find(|layout| layout.source_name == "llvmVectorStructFixture.Packet")
            .expect("Packet struct layout");
        let batch_layout = module
            .structs
            .iter()
            .find(|layout| layout.source_name == "llvmVectorStructFixture.PacketBatch")
            .expect("PacketBatch struct layout");
        let items_field = batch_layout
            .fields
            .iter()
            .find(|field| field.name == "items")
            .expect("PacketBatch.items field");
        assert_eq!(items_field.nc_type, "vector<Packet>");
        assert_eq!(items_field.size_bytes, 24);
        assert_eq!(items_field.align_bytes, 8);

        let view = module
            .dynamic_views
            .iter()
            .find(|view| view.source_type == "vector<Packet>")
            .expect("vector<Packet> dynamic view");
        assert_eq!(view.kind, "dinarray");
        assert_eq!(view.element_nc_type, "Packet");
        assert_eq!(view.element_llvm_type, packet_layout.llvm_type);
        assert_eq!(view.field_count, 3);
        assert_eq!(view.size_bytes, 24);
        assert_eq!(view.align_bytes, 8);
        assert!(view.has_capacity);
        assert_eq!(items_field.llvm_type, view.llvm_type);
        assert!(module
            .llvm_ir
            .contains(&format!("{} = type {{ ptr, i64, i64 }}", view.llvm_type)));
        assert!(module.llvm_ir.contains(&format!(
            "@__ncc_stc_llvmVectorStructFixture_packets = global {}",
            view.llvm_type
        )));
        assert!(module.llvm_ir.contains("store ptr null"));
        assert!(!module.llvm_ir.contains("call ptr @malloc(i64 16)"));
        assert!(module.llvm_ir.contains(&format!(
            "getelementptr inbounds {}, ptr @__ncc_stc_llvmVectorStructFixture_packets, i64 0, i32 0",
            view.llvm_type
        )));
        let zero_descriptor_stores = module
            .llvm_ir
            .lines()
            .filter(|line| line.trim_start().starts_with("store i64 0, ptr"))
            .count();
        assert!(
            zero_descriptor_stores >= 2,
            "an empty raw descriptor must initialize both len and cap to zero; IR:\n{}",
            module.llvm_ir
        );
        let stride_muls = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(" = mul i64 ") && line.contains(", 16"))
            .count();
        assert!(
            stride_muls >= 3,
            "push/get/set must scale vector<Packet> indexes by sizeof(Packet); IR:\n{}",
            module.llvm_ir
        );
        assert!(module
            .llvm_ir
            .contains(&format!("store {} ", packet_layout.llvm_type)));
        assert!(module
            .llvm_ir
            .contains(&format!("load {}, ptr", packet_layout.llvm_type)));
        assert!(!module.llvm_ir.contains("<2 x %struct."));
    }

    #[test]
    fn mct_llvm_lowers_vector_struct_field_access_by_index_and_get() {
        let src = r#"
llvmVectorStructFieldAccess {
    type:
        Packet {
            public:
                id: int;
                tag: int;
                total: qword;
        }

    stc:
        packets: vector<Packet>;
        packet: Packet;
        i: int;
        byIndex: int;
        byGet: int;

    fn:
        boot() -> bool {
            public:
                @mark >> p<byte> : stackMark();
                @storage >> p<Packet> : cast<Packet>(stackAlloc(64, 16));
                @packets >> vector<Packet> : vectorAt<Packet>(@storage, 4);
                @packet.id >> int : 7;
                @packet.tag >> int : 9001;
                @i >> int : 0;
                @packets.push(@packet);
                @packets[@i].tag >> int : 42;
                @byIndex >> int : @packets[@i].tag;
                @byGet >> int : @packets.get(@i).tag;
                stackRestore(@mark);
                return @byIndex == 42 && @byGet == 42;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let boot = container
            .functions
            .iter()
            .find(|function| function.name == "boot")
            .expect("boot function");
        let ir_field_reads = boot
            .body
            .iter()
            .filter(|stmt| {
                matches!(
                    stmt,
                    StatementIR::ScalarProjection {
                        value: ScalarExprIR::ArrayFieldRead { target, fields, .. },
                        ..
                    } if target == "packets" && fields == &vec!["tag".to_string()]
                )
            })
            .count();
        assert_eq!(
            ir_field_reads, 2,
            "packets[i].tag and packets.get(i).tag must lower to ArrayFieldRead"
        );
        let ir_field_writes = boot
            .body
            .iter()
            .filter(|stmt| {
                matches!(
                    stmt,
                    StatementIR::ScalarExpr {
                        value: ScalarExprIR::ArrayFieldWrite { target, fields, .. },
                        ..
                    } if target == "packets" && fields == &vec!["tag".to_string()]
                )
            })
            .count();
        assert_eq!(
            ir_field_writes, 1,
            "packets[i].tag assignment must lower to ArrayFieldWrite"
        );

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        let packet_ty = "%struct.llvmVectorStructFieldAccess_Packet";
        assert!(module
            .llvm_ir
            .contains("%struct.llvmVectorStructFieldAccess_Packet = type { i32, i32, i64 }"));
        let view = module
            .dynamic_views
            .iter()
            .find(|view| view.source_type == "vector<Packet>")
            .expect("vector<Packet> dynamic view");
        assert_eq!(view.kind, "dinarray");
        assert!(module
            .llvm_ir
            .contains(&format!("{} = type {{ ptr, i64, i64 }}", view.llvm_type)));
        let field_geps = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(&format!("getelementptr inbounds {packet_ty}")))
            .filter(|line| line.contains("i32 1"))
            .count();
        assert!(
            field_geps >= 3,
            "field read/write must GEP to Packet.tag after element address; IR:\n{}",
            module.llvm_ir
        );
        let stride_muls = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(" = mul i64 ") && line.contains(", 16"))
            .count();
        assert!(
            stride_muls >= 4,
            "push/index/get field access must scale by sizeof(Packet)=16; IR:\n{}",
            module.llvm_ir
        );
        assert!(module.llvm_ir.contains("store i32 42, ptr"));
        assert!(module.llvm_ir.contains("load i32, ptr"));
    }

    #[test]
    fn mct_llvm_lowers_vector_struct_nested_field_access_by_index_and_get() {
        let src = r#"
llvmVectorNestedStructFieldAccess {
    type:
        Header {
            public:
                mark: int;
                code: int;
        }

        Packet {
            public:
                id: int;
                header: Header;
                total: qword;
        }

    stc:
        packets: vector<Packet>;
        packet: Packet;
        i: int;
        byIndex: int;
        byGet: int;

    fn:
        boot() -> bool {
            public:
                @mark >> p<byte> : stackMark();
                @storage >> p<Packet> : cast<Packet>(stackAlloc(64, 16));
                @packets >> vector<Packet> : vectorAt<Packet>(@storage, 4);
                @packet.header.mark >> int : 7;
                @i >> int : 0;
                @packets.push(@packet);
                @packets[@i].header.mark >> int : 42;
                @packets.get(@i).header.mark >> int : 43;
                @byIndex >> int : @packets[@i].header.mark;
                @byGet >> int : @packets.get(@i).header.mark;
                stackRestore(@mark);
                return @byIndex == 43 && @byGet == 43;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let boot = container
            .functions
            .iter()
            .find(|function| function.name == "boot")
            .expect("boot function");
        let nested_fields = vec!["header".to_string(), "mark".to_string()];
        let ir_field_reads = boot
            .body
            .iter()
            .filter(|stmt| {
                matches!(
                    stmt,
                    StatementIR::ScalarProjection {
                        value: ScalarExprIR::ArrayFieldRead { target, fields, .. },
                        ..
                    } if target == "packets" && fields == &nested_fields
                )
            })
            .count();
        assert_eq!(
            ir_field_reads, 2,
            "packets[i].header.mark and packets.get(i).header.mark must lower to ArrayFieldRead"
        );
        let ir_field_writes = boot
            .body
            .iter()
            .filter(|stmt| {
                matches!(
                    stmt,
                    StatementIR::ScalarExpr {
                        value: ScalarExprIR::ArrayFieldWrite { target, fields, .. },
                        ..
                    } if target == "packets" && fields == &nested_fields
                )
            })
            .count();
        assert_eq!(
            ir_field_writes, 2,
            "packets[i].header.mark/get(i).header.mark assignments must lower to ArrayFieldWrite"
        );

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(module.diagnostics.is_empty());
        let packet_ty = "%struct.llvmVectorNestedStructFieldAccess_Packet";
        let header_ty = "%struct.llvmVectorNestedStructFieldAccess_Header";
        assert!(module
            .llvm_ir
            .contains(&format!("{header_ty} = type {{ i32, i32 }}")));
        assert!(module
            .llvm_ir
            .contains(&format!("{packet_ty} = type {{ i32, {header_ty}, i64 }}")));
        let field_geps = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(&format!("getelementptr inbounds {packet_ty}")))
            .filter(|line| line.contains("i32 1"))
            .count();
        let nested_geps = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(&format!("getelementptr inbounds {header_ty}")))
            .filter(|line| line.contains("i32 0"))
            .count();
        assert!(
            field_geps >= 4 && nested_geps >= 4,
            "field read/write must GEP through Packet.header then Header.mark; IR:\n{}",
            module.llvm_ir
        );
        let stride_muls = module
            .llvm_ir
            .lines()
            .filter(|line| line.contains(" = mul i64 ") && line.contains(", 24"))
            .count();
        assert!(
            stride_muls >= 4,
            "push/index/get field access must scale by sizeof(Packet)=24; IR:\n{}",
            module.llvm_ir
        );
        assert!(module.llvm_ir.contains("store i32 42, ptr"));
        assert!(module.llvm_ir.contains("load i32, ptr"));
    }

    #[test]
    fn mct_llvm_lowers_print_family_to_host_bytes() {
        let src = r#"
llvmPrintBytes {
    stc:
        label: str;
        value: int;

    fn:
        boot() -> bool {
            public:
                @label >> str : "WORD";
                @value >> int : 42;
                print("A");
                print(" ");
                print(@label);
                println();
                print("value=");
                println(@value);
                println();
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let boot = container
            .functions
            .iter()
            .find(|function| function.name == "boot")
            .expect("boot function");
        let print_count = boot
            .body
            .iter()
            .filter(|stmt| matches!(stmt, StatementIR::Print { .. }))
            .count();
        assert_eq!(print_count, 7);

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(module.diagnostics.is_empty());
        assert!(module.llvm_ir.contains("declare i64 @write(i32, ptr, i64)"));
        assert!(module.llvm_ir.contains("declare i64 @strlen(ptr)"));
        assert!(module
            .llvm_ir
            .contains("declare i32 @snprintf(ptr, i64, ptr, ...)"));
        assert!(
            !module.llvm_ir.contains("@printf("),
            "print lowering must avoid buffered printf so write ordering stays byte-stable"
        );
        assert!(module.llvm_ir.contains("constant [1 x i8] c\"A\""));
        assert!(module.llvm_ir.contains("constant [5 x i8] c\"WORD\\00\""));
        assert!(module.llvm_ir.contains("constant [6 x i8] c\"value=\""));
        assert!(!module.llvm_ir.contains("alloca [1 x i8]"));
        assert!(!module.llvm_ir.contains("alloca [6 x i8]"));
        assert!(module
            .llvm_ir
            .contains("constant [6 x i8] c\"%lld\\0A\\00\""));
        assert!(module.llvm_ir.contains("call i64 @write(i32 1, ptr"));
        assert!(module.llvm_ir.contains("call i64 @strlen(ptr"));
        assert!(module
            .llvm_ir
            .contains("call i32 (ptr, i64, ptr, ...) @snprintf"));
    }

