    #[test]
    fn mct_llvm_fp_optimizer_folds_finite_literals_and_prunes_intrinsics() {
        let src = r#"
use::stoud::math::<core, trig, numeric>;

mctLlvmFpOptimizer[@runtime] {
    stc:
        a: ft64;
        b: ft64;
        c: ft64;
        d: ft64;
        e: ft64;
        f: ft64;
        g: ft64;

    fn:
        boot() -> bool {
            public:
                @a >> ft64 : sinFloat(0.0);
                @b >> ft64 : cosFloat(0.0);
                @c >> ft64 : logFloat(1.0);
                @d >> ft64 : sqrtFloat(81.0);
                @e >> ft64 : expFloat(0.0);
                @f >> ft64 : atan2Float(0.0, 1.0);
                @g >> ft64 : 2.0 * 3.0 + 4.0;
                return @a == 0.0
                    && @b == 1.0
                    && @c == 0.0
                    && @d == 9.0
                    && @e == 1.0
                    && @f == 0.0
                    && @g == 10.0;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let pipeline = mct_llvm_pass_pipeline(MctLlvmOptimizationLevelIR::O2);
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| { pass.name == "mct-fp-intrinsic-canonicalization" && pass.enabled }));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "mct-fp-finite-constant-fold" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "mct-fp-dead-declaration-prune" && pass.enabled));
        let module = mct_emit_llvm_module_with_pass_pipeline(&ir, pipeline);

        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(
            module.diagnostics.is_empty(),
            "FP optimizer lowering must not emit diagnostics: {:?}",
            module.diagnostics
        );
        for callee in [
            "@llvm.sqrt.f64",
            "@llvm.exp.f64",
            "@llvm.sin.f64",
            "@llvm.cos.f64",
            "@llvm.log.f64",
            "@atan2",
        ] {
            assert!(
                !module.llvm_ir.contains(&format!("call double {callee}(")),
                "folded FP literal call must not remain in LLVM IR for {callee}:\n{}",
                module.llvm_ir
            );
            assert!(
                !module
                    .llvm_ir
                    .contains(&format!("declare double {callee}(")),
                "folded-away FP callee must not leave a dead declaration for {callee}:\n{}",
                module.llvm_ir
            );
        }
        assert!(module.llvm_ir.contains("store double 0x0000000000000000"));
        assert!(module.llvm_ir.contains("store double 0x3FF0000000000000"));
        assert!(module.llvm_ir.contains("store double 0x4022000000000000"));
        assert!(module.llvm_ir.contains("store double 0x4024000000000000"));
        assert!(!module.llvm_ir.contains(" = fadd double"));
        assert!(!module.llvm_ir.contains(" = fmul double"));
    }

    #[test]
    fn mct_llvm_lowers_runtime_string_ops_to_host_bytes() {
        let src = r#"
package runtime_strings { profile: performance_lab; }

use nC.runtime.output;
use nC.runtime.render;
use nC.runtime.string;

mctLlvmRuntimeString[@runtime] {
    stc:
        text: str;
        part: str;
        joined: str;
        len: int;
        cmp: int;
        ok: bool;

    fn:
        boot() -> bool {
            public:
                @text >> str : "abcdef";
                @part >> str : strSubstring(@text, 2, 3);
                @joined >> str : strConcat(@part, "-x");
                @len >> int : strByteLen(@joined);
                @cmp >> int : strCompare(@part, "cde");
                @ok >> bool : strEq(@part, "cde")
                    && strStartsWith(@joined, "c")
                    && strEndsWith(@joined, "x")
                    && strContains(@joined, "-")
                    && strIndexOf(@joined, "-") == 3;
                println(@joined + ":" + renderInt(@len) + ":" + renderInt(@cmp));
                @partReleased >> bool : strRelease(@part);
                @joinedReleased >> bool : strRelease(@joined);
                return @ok && @partReleased && @joinedReleased;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("fixture must lex");
        let program = ncc_parser::parse(tokens).expect("fixture must parse");
        ncc_sema::analyze(&program).expect("fixture must pass sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);

        assert_eq!(module.status, "llvm_adapter_emitted");
        assert_eq!(module.rejected_function_count, 0);
        assert!(
            module.diagnostics.is_empty(),
            "runtime string lowering must not emit diagnostics: {:?}",
            module.diagnostics
        );
        assert!(!module.llvm_ir.contains("declare ptr @malloc(i64)"));
        assert!(!module.llvm_ir.contains("declare i64 @strlen(ptr)"));
        assert!(!module
            .llvm_ir
            .contains("declare void @llvm.memcpy.p0.p0.i64(ptr, ptr, i64, i1)"));
        assert!(!module.llvm_ir.contains("declare i32 @strcmp(ptr, ptr)"));
        assert!(!module
            .llvm_ir
            .contains("declare i32 @strncmp(ptr, ptr, i64)"));
        assert!(!module.llvm_ir.contains("declare ptr @strstr(ptr, ptr)"));
        assert!(!module.llvm_ir.contains("declare void @free(ptr)"));
        assert!(!module.llvm_ir.contains("call ptr @malloc(i64"));
        assert!(!module.llvm_ir.contains("call void @llvm.memcpy.p0.p0.i64"));
        assert!(!module.llvm_ir.contains("call i32 @strcmp(ptr"));
        assert!(!module.llvm_ir.contains("call i32 @strncmp(ptr"));
        assert!(!module.llvm_ir.contains("call ptr @strstr(ptr"));
        assert_eq!(
            module
                .llvm_ir
                .matches("call i1 @nccTextFormatRuntime_releaseRaw(ptr")
                .count(),
            2
        );
        for provider in [
            "@nccTextFormatRuntime_sliceRaw",
            "@nccTextFormatRuntime_concatRaw",
            "@nccTextFormatRuntime_lengthRaw",
            "@nccTextFormatRuntime_startsWithRaw",
            "@nccTextFormatRuntime_endsWithRaw",
            "@nccTextFormatRuntime_containsRaw",
            "@nccTextFormatRuntime_indexOfRaw",
        ] {
            assert!(module.llvm_ir.contains(provider), "missing {provider}");
        }
        for typed_call in [
            "call i32 @nccTextFormatRuntime_lengthRaw(ptr",
            "call ptr @nccTextFormatRuntime_sliceRaw(ptr",
            "call i32 @nccTextFormatRuntime_compareRaw(ptr",
            "call i32 @nccTextFormatRuntime_indexOfRaw(ptr",
        ] {
            assert!(
                module.llvm_ir.contains(typed_call),
                "missing ABI-exact nC call {typed_call}:\n{}",
                module.llvm_ir
            );
        }
        for mistyped_call in [
            "call i64 @nccTextFormatRuntime_lengthRaw(ptr",
            "call i64 @nccTextFormatRuntime_compareRaw(ptr",
            "call i64 @nccTextFormatRuntime_indexOfRaw(ptr",
            "@ncc_rt_str_",
        ] {
            assert!(
                !module.llvm_ir.contains(mistyped_call),
                "forbidden legacy or ABI-mismatched call {mistyped_call}:\n{}",
                module.llvm_ir
            );
        }
        let backend = emit_backend(&ir);
        let native_release_calls = backend
            .units
            .iter()
            .filter_map(|unit| match unit {
                BackendUnitIR::Function(function) => Some(function),
                _ => None,
            })
            .flat_map(|function| function.ops.iter())
            .filter_map(|op| match op {
                BackendFuncOpIR::ScalarOps { ops } => Some(ops),
                _ => None,
            })
            .flatten()
            .filter(|op| {
                matches!(
                    op,
                    BackendScalarOpIR::Call { target, .. }
                        if target == "nccTextFormatRuntime_releaseRaw"
                )
            })
            .count();
        assert_eq!(native_release_calls, 2, "native nC ownership barrier");
        assert!(
            !module.llvm_ir.contains("unknown LLVM call target 'str"),
            "string runtime calls must lower without opaque call diagnostics:\n{}",
            module.llvm_ir
        );
    }

