    #[test]
    fn mct_llvm_pass_pipeline_owns_o2_passes() {
        let pipeline = mct_llvm_pass_pipeline(MctLlvmOptimizationLevelIR::O2);
        assert_eq!(pipeline.schema, "nc.mct.llvm.pass_pipeline.v1");
        assert_eq!(pipeline.status, "mct_llvm_pass_pipeline_owned");
        assert_eq!(pipeline.owner, "ncc-mct");
        assert_eq!(pipeline.clang_opt_arg, "-O2");
        assert_eq!(pipeline.opt_passes_arg, "default<O2>");
        assert!(pipeline.full_llvm_pass_manager_parity);
        assert!(pipeline
            .clang_pass_manager_args
            .contains(&"<clang-default-new-pass-manager>"));
        assert!(pipeline.clang_lto_args.contains(&"-flto=thin"));
        assert!(pipeline
            .clang_pgo_generate_args
            .contains(&"-fdebug-info-for-profiling"));
        assert_eq!(
            pipeline.clang_pgo_use_arg_template,
            "-fprofile-use=<profdata>"
        );
        assert!(pipeline.clang_debug_args.contains(&"-gdwarf-5"));
        assert!(pipeline.pass_count >= 10);
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "mem2reg" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "mct-fp-finite-constant-fold" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "licm" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "loop-vectorize" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "thinlto-prelink" && pass.enabled));
        assert!(pipeline
            .passes
            .iter()
            .any(|pass| pass.name == "instrprof-use" && pass.enabled));
    }

