    #[test]
    fn mct_llvm_debug_locations_use_exact_source_spans() {
        let source = r#"llvmDebugDwarfFixture {
    stc:
        x: int;
        y: int;

    fn:
        boot() -> int {
            public:
                @x >> int : 40;
                @y >> int : @x + 2;
                return @y;
        }
}
"#;
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "llvmDebugDwarfFixture".into(),
                context: None,
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "x".into(),
                            ty: TypeName::Simple("int".into()),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "y".into(),
                            ty: TypeName::Simple("int".into()),
                            init: None,
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: Vec::new(),
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: Vec::new(),
                        return_type: TypeName::Simple("int".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec!["x".into()])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("40".into()),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(vec!["y".into()])),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Binary {
                                    left: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                        "x".into()
                                    ]))),
                                    op: BinaryOp::Plus,
                                    right: Box::new(Expr::Number("2".into())),
                                },
                            },
                            Stmt::Return(Expr::ContextRef(ContextRef::plain(vec!["y".into()]))),
                        ],
                    }]),
                ],
            }],
        };
        let ir = lower_with_backend_profile_and_source(
            program,
            BackendLoweringProfileIR::nc_sysv64(),
            "mct_llvm_debug_dwarf.n",
            source,
        );
        assert_eq!(ir.source_map.status, "exact_source_span_parity");
        assert_eq!(ir.source_map.statement_count, 3);
        assert_eq!(ir.source_map.exact_span_count, 3);
        assert_eq!(
            ir.source_map.entries[0].span.as_ref().unwrap().start_line,
            9
        );
        assert_eq!(
            ir.source_map.entries[1].span.as_ref().unwrap().start_line,
            10
        );
        assert_eq!(
            ir.source_map.entries[2].span.as_ref().unwrap().start_line,
            11
        );

        let module = mct_emit_llvm_module_with_debug_config(
            &ir,
            mct_llvm_pass_pipeline(MctLlvmOptimizationLevelIR::O2),
            mct_llvm_debug_config_for_source("mct_llvm_debug_dwarf.n", "examples/backend"),
        );
        assert!(module.debug_metadata.source_span_parity);
        assert!(module.llvm_ir.contains("!DILocation(line: 9, column: 17"));
        assert!(module.llvm_ir.contains("!DILocation(line: 10, column: 17"));
        assert!(module.llvm_ir.contains("!DILocation(line: 11, column: 17"));
    }

