    #[test]
    fn mct_llvm_attribute_catalog_covers_attributes_td_universe() {
        let catalog = mct_llvm_attribute_catalog();
        assert_eq!(catalog.len(), MCT_LLVM_ATTRIBUTE_CATALOG_EXPECTED_COUNT);
        assert!(mct_llvm_attribute_catalog_closed());

        for required in [
            "align",
            "allockind",
            "allocsize",
            "byval",
            "dereferenceable",
            "memory",
            "nofpclass",
            "range",
            "sret",
            "sanitize_address",
            "vscale_range",
            "marked_for_windows_hot_patching",
        ] {
            assert!(
                catalog.iter().any(|entry| entry.llvm_ir_name == required),
                "LLVM attribute catalog must include {required}"
            );
        }

        let byval = catalog
            .iter()
            .find(|entry| entry.llvm_ir_name == "byval")
            .expect("byval must be cataloged");
        assert_eq!(byval.kind, MctLlvmAttributeKindIR::Type);
        assert!(byval.parameter_position);
        assert!(!byval.function_position);

        let uwtable = catalog
            .iter()
            .find(|entry| entry.llvm_ir_name == "uwtable")
            .expect("uwtable must be cataloged");
        assert_eq!(uwtable.kind, MctLlvmAttributeKindIR::Int);
        assert!(uwtable.function_position);

        let string_attr = catalog
            .iter()
            .find(|entry| entry.llvm_ir_name == "no-jump-tables")
            .expect("known LLVM string bool attribute must be cataloged");
        assert_eq!(string_attr.kind, MctLlvmAttributeKindIR::StringBool);
        assert!(string_attr.function_position);
        assert_eq!(string_attr.policy, "known_string_function_attribute");
    }

    #[test]
    fn mct_llvm_rejects_third_party_string_function_attributes() {
        let target_cpu = try_llvm_function_attr_kv("target-cpu", "x86-64", "target")
            .expect("known LLVM target string attribute must be accepted");
        assert_eq!(target_cpu.llvm_ir, "\"target-cpu\"=\"x86-64\"");

        let no_jump_tables = try_llvm_function_attr_kv("no-jump-tables", "true", "optimizer")
            .expect("known LLVM string-bool function attribute must be accepted");
        assert_eq!(no_jump_tables.name, "no-jump-tables");

        let err = try_llvm_function_attr_kv("ncc-fine-tuning-profile", "throughput", "ncc-tuning")
            .expect_err("ncc metadata must not be smuggled as an LLVM string attribute");
        assert!(err.contains("E_MCT_LLVM_ATTR_STRING_001"));
        assert!(err.contains("outside the known LLVM catalog"));

        let diagnostics = llvm_validate_function_attributes(&[MctLlvmFunctionAttributeIR {
            name: "vendor.magic".into(),
            value: Some("1".into()),
            category: "third-party",
            llvm_ir: "\"vendor.magic\"=\"1\"".into(),
        }]);
        assert_eq!(diagnostics.len(), 1);
        assert!(diagnostics[0].is_error());
    }

    #[test]
    fn mct_llvm_target_attribute_matrix_covers_official_targets() {
        let profiles = [
            BackendLoweringProfileIR::nc_sysv64(),
            BackendLoweringProfileIR::nc_win64(),
            BackendLoweringProfileIR::nc_aapcs64(),
            BackendLoweringProfileIR::nc_portable(),
            BackendLoweringProfileIR::nc_sovereign(),
        ];
        for profile in profiles {
            let attributes = mct_llvm_target_attributes_for_spec(&profile.target_spec);
            assert_eq!(attributes.status, "mct_llvm_target_attributes_closed");
            assert_eq!(attributes.attribute_group, "#0");
            assert!(attributes.applies_to_emitted_functions);
            assert!(attributes
                .function_attributes
                .iter()
                .any(|attribute| attribute.name == "target-cpu"));
            match profile.target_spec.isa {
                BackendIsaIR::X86 => {
                    assert_eq!(attributes.target_cpu, "i686");
                    assert!(attributes.target_features.is_empty());
                }
                BackendIsaIR::X86_64 => {
                    assert_eq!(attributes.target_cpu, "x86-64");
                    assert!(attributes.target_features.iter().any(|f| f == "+sse2"));
                }
                BackendIsaIR::ArmV7 => {
                    assert_eq!(attributes.target_cpu, "generic");
                    assert!(attributes.target_features.iter().any(|f| f == "+thumb2"));
                }
                BackendIsaIR::AArch64 => {
                    assert_eq!(attributes.target_cpu, "generic");
                    assert!(attributes.target_features.iter().any(|f| f == "+neon"));
                }
                BackendIsaIR::Wasm32 => {
                    assert_eq!(attributes.target_cpu, "generic");
                    assert!(attributes
                        .target_features
                        .iter()
                        .any(|f| f == "+mutable-globals"));
                }
                BackendIsaIR::RiscV32 => {
                    assert_eq!(attributes.target_cpu, "generic-rv32");
                    assert!(attributes.target_features.iter().any(|f| f == "+m"));
                    assert!(attributes.target_features.iter().any(|f| f == "+a"));
                    assert!(attributes.target_features.iter().any(|f| f == "+c"));
                }
                BackendIsaIR::RiscV64 => {}
            }
        }
    }

    #[test]
    fn mct_official_target_matrix_closes_f10_without_global_llvm_tuning_claim() {
        let matrix = mct_official_target_matrix();
        assert_eq!(matrix.schema, "nc.mct.official_target_matrix.v1");
        assert_eq!(matrix.status, "mct_official_target_matrix_closed");
        assert_eq!(matrix.phase, "F10");
        assert_eq!(matrix.row_count, 6);
        assert_eq!(matrix.closed_profile_count, 6);
        assert!(!matrix.full_llvm_microarch_universe);
        assert!(!matrix.full_llvm_tuning_parity);

        let ids = matrix.rows.iter().map(|row| row.id).collect::<Vec<_>>();
        assert_eq!(
            ids,
            vec![
                "nC.sysv64",
                "nC.win64",
                "nC.aapcs64",
                "nC.portable",
                "nC.sovereign",
                "nC.destructive"
            ]
        );

        for row in &matrix.rows {
            assert_eq!(row.status, "closed");
            assert!(!row.target_triple.is_empty());
            assert_eq!(
                row.llvm_attribute_status,
                "mct_llvm_target_attributes_closed"
            );
            assert!(!row.target_cpu.is_empty());
            assert!(!row.tuning_policy.contains("full-llvm"));
            assert!(!row.full_llvm_microarch_universe);
        }

        let sysv64 = matrix
            .rows
            .iter()
            .find(|row| row.id == "nC.sysv64")
            .unwrap();
        assert_eq!(sysv64.target_triple, "x86_64-unknown-linux-gnu");
        assert_eq!(sysv64.abi, "sysv64");
        assert_eq!(sysv64.object_format, "elf64");
        assert!(sysv64
            .target_features
            .iter()
            .any(|feature| feature == "+sse2"));

        let win64 = matrix.rows.iter().find(|row| row.id == "nC.win64").unwrap();
        assert_eq!(win64.target_triple, "x86_64-pc-windows-msvc");
        assert_eq!(win64.abi, "win64");
        assert_eq!(win64.object_format, "coff");

        let aapcs64 = matrix
            .rows
            .iter()
            .find(|row| row.id == "nC.aapcs64")
            .unwrap();
        assert_eq!(aapcs64.target_triple, "aarch64-apple-darwin");
        assert!(aapcs64
            .target_features
            .iter()
            .any(|feature| feature == "+neon"));

        let portable = matrix
            .rows
            .iter()
            .find(|row| row.id == "nC.portable")
            .unwrap();
        assert_eq!(portable.target_triple, "wasm32-wasi");
        assert_eq!(portable.pointer_width, 32);
        assert!(portable
            .target_features
            .iter()
            .any(|feature| feature == "+mutable-globals"));

        let sovereign = matrix
            .rows
            .iter()
            .find(|row| row.id == "nC.sovereign")
            .unwrap();
        assert_eq!(sovereign.target_triple, "x86_64-unknown-sovereign-nc");
        assert_eq!(sovereign.runtime_model, "sovereign");
        assert_eq!(sovereign.support_tier, "tier3");
    }

    #[test]
    fn mct_cpu_tuning_matrix_closes_f11_profiles_without_global_llvm_claim() {
        let matrix = mct_cpu_tuning_matrix();
        assert_eq!(matrix.schema, "nc.mct.cpu_tuning_matrix.v1");
        assert_eq!(matrix.status, "mct_cpu_tuning_matrix_closed");
        assert_eq!(matrix.phase, "F11");
        assert_eq!(matrix.microarchitecture_count, 16);
        assert_eq!(matrix.fine_tuning_profile_count, 5);
        assert_eq!(matrix.scheduling_profile_count, 80);
        assert!(!matrix.full_llvm_cpu_universe);
        assert!(!matrix.full_llvm_scheduler_parity);

        let ids = matrix
            .microarchitectures
            .iter()
            .map(|profile| profile.id)
            .collect::<Vec<_>>();
        for required in [
            "x86_64-v3",
            "x86_64-v4",
            "intel-skylake",
            "intel-icelake-client",
            "amd-znver4",
            "apple-m1",
            "neoverse-v1",
            "riscv64-generic",
            "sifive-u74",
            "wasm32-generic",
        ] {
            assert!(
                ids.contains(&required),
                "F11 tuning matrix must include {required}"
            );
        }
        assert!(matrix
            .fine_tuning_profiles
            .iter()
            .any(|profile| profile.id == "throughput"
                && profile.vectorize_policy == "prefer-wide-vectorization"));
        assert!(matrix
            .scheduling_profiles
            .iter()
            .any(|profile| profile.microarchitecture_id == "intel-skylake"
                && profile.fine_tuning_profile_id == "throughput"
                && profile.llvm_args.iter().any(|arg| arg == "-O3")));
    }

    #[test]
    fn mct_llvm_target_attributes_accept_cpu_tuning() {
        let spec = BackendLoweringProfileIR::nc_sysv64().target_spec;
        let attributes =
            mct_llvm_target_attributes_for_cpu_tuning(&spec, "intel-skylake", "throughput")
                .expect("skylake throughput tuning must be accepted for sysv64");
        assert_eq!(attributes.status, "mct_llvm_target_attributes_tuned");
        assert_eq!(attributes.target_cpu, "skylake");
        assert_eq!(attributes.tune_cpu.as_deref(), Some("skylake"));
        assert_eq!(attributes.microarchitecture, Some("intel-skylake"));
        assert_eq!(attributes.fine_tuning_profile, Some("throughput"));
        assert!(attributes.target_features.iter().any(|f| f == "+avx2"));
        assert!(attributes
            .function_attributes
            .iter()
            .any(|attribute| attribute.name == "tune-cpu"
                && attribute.value.as_deref() == Some("skylake")));
        assert!(attributes
            .attribute_group_ir
            .contains("\"target-cpu\"=\"skylake\""));
        assert!(attributes
            .attribute_group_ir
            .contains("\"tune-cpu\"=\"skylake\""));
        assert!(attributes
            .attribute_group_ir
            .contains("\"target-features\"="));
        assert!(
            !attributes
                .attribute_group_ir
                .contains("ncc-fine-tuning-profile"),
            "ncc tuning metadata is reported through fine_tuning_profile, not LLVM attributes"
        );
    }

    #[test]
    fn mct_cpu_tuning_bridges_to_native_simd_scheduler_rows() {
        let skylake = backend_native_cpu_tuning_bridge_for_mct_cpu("intel-skylake")
            .expect("intel-skylake must bridge into the native SIMD scheduler");
        assert_eq!(skylake.schema, "nc.backend.native_cpu_tuning_bridge.v1");
        assert_eq!(skylake.status, "backend_native_cpu_tuning_bridge_closed");
        assert_eq!(skylake.phase, "F12");
        assert_eq!(
            skylake.native_microarchitecture,
            Some(BackendSimdMicroarchitectureIR::X86IntelSkylake)
        );
        assert!(skylake.schedule_row_count > 0);
        assert!(skylake.schedule_rows.iter().any(|row| {
            row.microarchitecture == BackendSimdMicroarchitectureIR::X86IntelSkylake
                && row.feature == BackendSimdFeatureIR::X86Avx2
        }));
        assert!(
            !skylake
                .schedule_rows
                .iter()
                .any(|row| row.feature == BackendSimdFeatureIR::X86Avx512F),
            "plain Skylake must not inherit AVX-512 rows"
        );
        assert!(!skylake.full_native_scheduler_parity);

        let neoverse = backend_native_cpu_tuning_bridge_for_mct_cpu("neoverse-v1")
            .expect("neoverse-v1 must bridge into the native SIMD scheduler");
        assert_eq!(
            neoverse.native_microarchitecture,
            Some(BackendSimdMicroarchitectureIR::AArch64NeoverseN1)
        );
        assert!(neoverse
            .schedule_rows
            .iter()
            .any(|row| row.feature == BackendSimdFeatureIR::AArch64Neon));

        let wasm = backend_native_cpu_tuning_bridge_for_mct_cpu("wasm32-generic")
            .expect("wasm32-generic is known but intentionally unsupported by native SIMD bridge");
        assert_eq!(
            wasm.status,
            "backend_native_cpu_tuning_bridge_unsupported_target"
        );
        assert_eq!(wasm.native_microarchitecture, None);
        assert_eq!(wasm.schedule_row_count, 0);
    }

    #[test]
    fn mct_cpu_tuning_policy_selects_native_simd_decisions() {
        let skylake = backend_native_cpu_tuning_policy_for_mct_cpu("intel-skylake", "throughput")
            .expect("intel-skylake throughput must produce a native CPU tuning policy");
        assert_eq!(skylake.schema, "nc.backend.native_cpu_tuning_policy.v1");
        assert_eq!(skylake.status, "backend_native_cpu_tuning_policy_closed");
        assert_eq!(skylake.preferred_vector_width_bits, 256);
        assert_eq!(
            skylake.native_microarchitecture,
            Some(BackendSimdMicroarchitectureIR::X86IntelSkylake)
        );
        assert!(skylake.decisions.iter().any(|decision| {
            decision.op == BackendSimdOpIR::Add
                && decision.feature == BackendSimdFeatureIR::X86Avx2
                && decision.lane == BackendSimdLaneIR::I32x8
                && decision.selected_mnemonic == "vpaddd"
        }));
        assert!(skylake.decisions.iter().any(|decision| {
            decision.op == BackendSimdOpIR::Gather
                && decision.feature == BackendSimdFeatureIR::X86Avx2
                && decision.schedule.issue_domain == "vector-memory"
        }));
        assert!(skylake.decisions.iter().any(|decision| {
            decision.op == BackendSimdOpIR::VZeroUpper
                && decision.feature == BackendSimdFeatureIR::X86Avx
        }));
        assert!(
            !skylake
                .decisions
                .iter()
                .any(|decision| decision.feature == BackendSimdFeatureIR::X86Avx512F),
            "plain Skylake policy must not silently upgrade to AVX-512 decisions"
        );

        let apple = backend_native_cpu_tuning_policy_for_mct_cpu("apple-m1", "throughput")
            .expect("apple-m1 throughput must produce a native CPU tuning policy");
        assert_eq!(apple.preferred_vector_width_bits, 128);
        assert_eq!(
            apple.native_microarchitecture,
            Some(BackendSimdMicroarchitectureIR::AArch64Generic)
        );
        assert!(apple.decisions.iter().any(|decision| {
            decision.op == BackendSimdOpIR::Mul
                && decision.feature == BackendSimdFeatureIR::AArch64Neon
                && decision.lane == BackendSimdLaneIR::I32x4
                && decision.selected_mnemonic == "mul v0.4s"
        }));
        assert!(
            !apple.decisions.iter().any(|decision| matches!(
                decision.op,
                BackendSimdOpIR::Gather | BackendSimdOpIR::Scatter
            )),
            "Apple M1 policy must not claim physical gather/scatter without profile support"
        );
    }

    #[test]
    fn scalar_register_spill_cost_model_prioritizes_loop_hot_locals() {
        let mut body = vec![
            Stmt::Projection {
                target: AssignTarget::Context(ContextRef::plain(vec!["acc".into()])),
                ty: TypeName::Simple("int".into()),
                value: Expr::Number("0".into()),
            },
            Stmt::Projection {
                target: AssignTarget::Context(ContextRef::plain(vec!["i".into()])),
                ty: TypeName::Simple("int".into()),
                value: Expr::Number("0".into()),
            },
        ];
        for idx in 0..8 {
            body.push(Stmt::Projection {
                target: AssignTarget::Context(ContextRef::plain(vec![format!("cold{idx}")])),
                ty: TypeName::Simple("int".into()),
                value: Expr::Number(format!("{}", 100 + idx)),
            });
        }
        body.push(Stmt::While {
            condition: Expr::Binary {
                left: Box::new(Expr::ContextRef(ContextRef::plain(vec!["i".into()]))),
                op: BinaryOp::Less,
                right: Box::new(Expr::Number("16".into())),
            },
            body: vec![
                Stmt::Projection {
                    target: AssignTarget::Context(ContextRef::plain(vec!["acc".into()])),
                    ty: TypeName::Simple("int".into()),
                    value: Expr::Binary {
                        left: Box::new(Expr::ContextRef(ContextRef::plain(vec!["acc".into()]))),
                        op: BinaryOp::Plus,
                        right: Box::new(Expr::ContextRef(ContextRef::plain(vec!["i".into()]))),
                    },
                },
                Stmt::Projection {
                    target: AssignTarget::Context(ContextRef::plain(vec!["i".into()])),
                    ty: TypeName::Simple("int".into()),
                    value: Expr::Binary {
                        left: Box::new(Expr::ContextRef(ContextRef::plain(vec!["i".into()]))),
                        op: BinaryOp::Plus,
                        right: Box::new(Expr::Number("1".into())),
                    },
                },
            ],
        });
        let mut sum = Expr::ContextRef(ContextRef::plain(vec!["acc".into()]));
        for idx in 0..8 {
            sum = Expr::Binary {
                left: Box::new(sum),
                op: BinaryOp::Plus,
                right: Box::new(Expr::ContextRef(ContextRef::plain(vec![format!(
                    "cold{idx}"
                )]))),
            };
        }
        body.push(Stmt::Return(sum));

        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "spillCostHotLoop".into(),
                context: None,
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "mix".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("int".into()),
                    public_body: body,
                }])],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let allocation = scalar_register_allocation_v2(&container.functions[0]);
        let acc_cost = allocation
            .spill_costs
            .get("acc")
            .expect("acc must have spill cost");
        let cold_cost = allocation
            .spill_costs
            .get("cold7")
            .expect("cold literal must have spill cost");

        assert!(
            acc_cost.loop_use_weight > cold_cost.loop_use_weight,
            "loop-local accumulator must carry higher loop-weight than cold literals"
        );
        assert!(
            acc_cost.score > cold_cost.score,
            "spill-cost score must prioritize hot loop locals over rematerializable cold literals"
        );
        assert!(
            acc_cost.estimated_stack_bytes > 0 && cold_cost.estimated_stack_bytes > 0,
            "spill-cost model must estimate concrete spill/reload byte traffic"
        );
        assert!(cold_cost.rematerializable);
        assert!(!acc_cost.rematerializable);
        assert!(
            allocation
                .live_segments
                .values()
                .map(Vec::len)
                .sum::<usize>()
                >= allocation.intervals.len(),
            "industrial allocator must retain live segment evidence for intervals"
        );
        assert!(
            allocation.peak_live > 0 && allocation.interference_edges > 0,
            "industrial allocator must account peak live pressure and interference edges"
        );
        assert!(
            allocation.resident_locals.contains_key("acc"),
            "hot accumulator should remain register-resident under pressure"
        );
        assert!(
            allocation.rematerialized_locals.len() >= 2,
            "cold literal pressure should be handled through rematerialization"
        );
        assert!(
            allocation.stack_traffic_bytes_avoided > 0,
            "resident/rematerialized locals must account avoided stack traffic"
        );
        assert!(
            allocation
                .decisions
                .iter()
                .any(|decision| decision.symbol == "acc" && decision.assigned_register.is_some()),
            "allocation decisions must expose the hot accumulator register assignment"
        );
        assert!(
            allocation
                .decisions
                .iter()
                .any(|decision| decision.rematerialized && decision.stack_traffic_bytes > 0),
            "allocation decisions must expose rematerialized stack traffic savings"
        );

        let mut profile = ScalarRegisterProfileGuidanceV2::default();
        profile.symbol_weights.insert("cold7".into(), 1024);
        let profiled_allocation =
            scalar_register_allocation_v2_with_profile(&container.functions[0], &profile);
        let profiled_cold_cost = profiled_allocation
            .spill_costs
            .get("cold7")
            .expect("profiled cold literal must have spill cost");
        assert_eq!(profiled_cold_cost.profile_weight, 1024);
        assert!(
            profiled_cold_cost.score > acc_cost.score,
            "profile-guided allocation must be able to promote a profiled cold symbol above static loop cost"
        );
        assert!(
            profiled_allocation.resident_locals.contains_key("cold7"),
            "profile-hot locals should become resident before unprofiled pressure candidates"
        );
    }

    #[test]
    fn emit_backend_register_allocation_v2_rematerializes_literal_spills() {
        let mut body = Vec::new();
        for idx in 0..8 {
            body.push(Stmt::Projection {
                target: AssignTarget::Context(ContextRef::plain(vec![format!("c{idx}")])),
                ty: TypeName::Simple("int".into()),
                value: Expr::Number(format!("{}", 1000 + idx)),
            });
        }
        let mut sum = Expr::ContextRef(ContextRef::plain(vec!["c0".into()]));
        for idx in 1..8 {
            sum = Expr::Binary {
                left: Box::new(sum),
                op: BinaryOp::Plus,
                right: Box::new(Expr::ContextRef(ContextRef::plain(vec![format!("c{idx}")]))),
            };
        }
        sum = Expr::Binary {
            left: Box::new(sum),
            op: BinaryOp::Plus,
            right: Box::new(Expr::ContextRef(ContextRef::plain(vec!["x".into()]))),
        };
        body.push(Stmt::Return(sum));

        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "rematerializePressure".into(),
                context: None,
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "mix".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![ncc_ast::Param {
                        name: "x".into(),
                        ty: TypeName::Simple("int".into()),
                    }],
                    return_type: TypeName::Simple("int".into()),
                    public_body: body,
                }])],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let allocation = scalar_register_allocation_v2(&container.functions[0]);
        assert!(
            allocation.spilled_locals.is_empty(),
            "single-definition literal locals should rematerialize instead of becoming stack spills"
        );
        let rematerialized_value = allocation
            .rematerialized_locals
            .values()
            .find_map(|expr| match expr {
                ScalarExprIR::Number(raw) => parse_backend_number_literal(raw),
                _ => None,
            })
            .expect("pressure fixture must rematerialize at least one literal");

        let backend = emit_backend(&ir);
        let BackendUnitIR::Function(func) = &backend.units[0] else {
            panic!("expected function backend unit");
        };
        let scalar_ops = func
            .ops
            .iter()
            .find_map(|op| match op {
                BackendFuncOpIR::ScalarOps { ops } => Some(ops),
                _ => None,
            })
            .expect("rematerialization fixture must lower through scalar ops");
        let load_count = scalar_ops
            .iter()
            .filter(|op| {
                matches!(
                    op,
                    BackendScalarOpIR::LoadImm { value, .. } if *value == rematerialized_value
                )
            })
            .count();
        assert_eq!(
            load_count, 1,
            "rematerialized literal should be loaded at use-site only, not first stored to a stack slot"
        );
    }

    #[test]
    fn emit_object_lowers_high_level_if_while_over_stc_globals_to_real_branches() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "standaloneFlow".into(),
                context: None,
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "active".into(),
                            ty: TypeName::Simple("bool".into()),
                            init: Some(Expr::Bool(true)),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "counter".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Number("0".into())),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "run".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::While {
                                condition: Expr::ContextRef(ContextRef::plain(vec![
                                    "active".into()
                                ])),
                                body: vec![
                                    Stmt::Projection {
                                        target: AssignTarget::Context(ContextRef::plain(vec![
                                            "counter".into(),
                                        ])),
                                        ty: TypeName::Simple("int".into()),
                                        value: Expr::Binary {
                                            left: Box::new(Expr::ContextRef(ContextRef::plain(
                                                vec!["counter".into()],
                                            ))),
                                            op: BinaryOp::Plus,
                                            right: Box::new(Expr::Number("1".into())),
                                        },
                                    },
                                    Stmt::If {
                                        condition: Expr::Binary {
                                            left: Box::new(Expr::ContextRef(ContextRef::plain(
                                                vec!["counter".into()],
                                            ))),
                                            op: BinaryOp::EqEq,
                                            right: Box::new(Expr::Number("2".into())),
                                        },
                                        then_block: vec![Stmt::Projection {
                                            target: AssignTarget::Context(ContextRef::plain(vec![
                                                "active".into(),
                                            ])),
                                            ty: TypeName::Simple("bool".into()),
                                            value: Expr::Bool(false),
                                        }],
                                        else_block: vec![],
                                    },
                                ],
                            },
                            Stmt::Return(Expr::Binary {
                                left: Box::new(Expr::ContextRef(ContextRef::plain(vec![
                                    "counter".into(),
                                ]))),
                                op: BinaryOp::EqEq,
                                right: Box::new(Expr::Number("2".into())),
                            }),
                        ],
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let backend = emit_backend(&ir);
        let func = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(func) if func.symbol == "standaloneFlow.run" => Some(func),
                _ => None,
            })
            .expect("standaloneFlow.run backend unit");
        let scalar_ops = func
            .ops
            .iter()
            .find_map(|op| match op {
                BackendFuncOpIR::ScalarOps { ops } => Some(ops),
                _ => None,
            })
            .expect("if/while over stc globals must stay on scalar native lowering path");
        assert!(scalar_ops
            .iter()
            .any(|op| matches!(op, BackendScalarOpIR::LoadGlobal { .. })));
        assert!(scalar_ops
            .iter()
            .any(|op| matches!(op, BackendScalarOpIR::StoreGlobal { .. })));
        assert!(scalar_ops.iter().any(|op| matches!(
            op,
            BackendScalarOpIR::CompareJump { .. } | BackendScalarOpIR::CompareJumpImm { .. }
        )));
        assert!(scalar_ops
            .iter()
            .any(|op| matches!(op, BackendScalarOpIR::Jump { .. })));

        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|section| section.name == ".text.standaloneFlow.run")
            .expect("run text section");
        assert!(
            text.bytes.as_ref().is_some_and(|bytes| !bytes.is_empty()),
            "standalone if/while path must emit physical text bytes"
        );
        let global_relocs = object
            .relocations
            .iter()
            .filter(|rel| {
                rel.section == ".text.standaloneFlow.run"
                    && rel.kind == BackendObjectRelocationKindIR::Abs64
                    && rel.symbol.starts_with("__ncc_stc_standaloneFlow_")
            })
            .count();
        assert!(
            global_relocs >= 2,
            "native object must relocate stc global loads/stores through data symbols"
        );
    }

    #[test]
    fn advanced_loop_surfaces_lower_to_real_range_backend_ops() {
        fn ctx(name: &str) -> Expr {
            Expr::ContextRef(ContextRef::plain(vec![name.into()]))
        }

        let arr_ty = TypeName::Generic {
            base: "array".into(),
            args: vec![TypeName::Simple("int".into()), TypeName::Simple("3".into())],
        };
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "advancedLoopLowering".into(),
                context: None,
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "arr".into(),
                            ty: arr_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "sum".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Number("0".into())),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "run".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["arr".into()],
                                )),
                                ty: arr_ty,
                                value: Expr::VectorLiteral(vec![
                                    Expr::Number("1".into()),
                                    Expr::Number("2".into()),
                                    Expr::Number("3".into()),
                                ]),
                            },
                            Stmt::Projection {
                                target: AssignTarget::Context(ContextRef::plain(
                                    vec!["sum".into()],
                                )),
                                ty: TypeName::Simple("int".into()),
                                value: Expr::Number("0".into()),
                            },
                            Stmt::ForIn {
                                item: "value".into(),
                                iterable: ctx("arr"),
                                body: vec![Stmt::Projection {
                                    target: AssignTarget::Context(ContextRef::plain(vec![
                                        "sum".into()
                                    ])),
                                    ty: TypeName::Simple("int".into()),
                                    value: Expr::Binary {
                                        left: Box::new(ctx("sum")),
                                        op: BinaryOp::Plus,
                                        right: Box::new(ctx("value")),
                                    },
                                }],
                            },
                            Stmt::ForRange {
                                item: "d".into(),
                                start: Expr::Number("3".into()),
                                end: Expr::Number("1".into()),
                                inclusive: true,
                                step: Some(Expr::Unary {
                                    op: UnaryOp::Minus,
                                    expr: Box::new(Expr::Number("1".into())),
                                }),
                                body: vec![Stmt::Projection {
                                    target: AssignTarget::Context(ContextRef::plain(vec![
                                        "sum".into()
                                    ])),
                                    ty: TypeName::Simple("int".into()),
                                    value: Expr::Binary {
                                        left: Box::new(ctx("sum")),
                                        op: BinaryOp::Plus,
                                        right: Box::new(ctx("d")),
                                    },
                                }],
                            },
                            Stmt::Return(Expr::Binary {
                                left: Box::new(ctx("sum")),
                                op: BinaryOp::EqEq,
                                right: Box::new(Expr::Number("12".into())),
                            }),
                        ],
                    }]),
                ],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let function = &container.functions[0];
        let lowered = format!("{:?}", function.body);
        assert!(
            !lowered.contains("ForIn"),
            "for-in must lower to material range/index form before backend emission"
        );
        assert!(
            lowered.contains("__ncc_forin_value_idx"),
            "for-in lowering must introduce a stable induction index"
        );

        let backend = emit_backend(&ir);
        let func = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(func) if func.symbol == "advancedLoopLowering.run" => {
                    Some(func)
                }
                _ => None,
            })
            .expect("advancedLoopLowering.run backend unit");
        let scalar_ops = func
            .ops
            .iter()
            .find_map(|op| match op {
                BackendFuncOpIR::ScalarOps { ops } => Some(ops),
                _ => None,
            })
            .expect("advanced loop lowering must use scalar backend ops");
        assert!(scalar_ops.iter().any(|op| {
            matches!(
                op,
                BackendScalarOpIR::CompareJump {
                    op: ScalarBinaryOpIR::Less,
                    ..
                }
            )
        }));

        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|section| section.name == ".text.advancedLoopLowering.run")
            .expect("run text section");
        assert!(
            text.bytes.as_ref().is_some_and(|bytes| !bytes.is_empty()),
            "advanced loop lowering must emit physical backend bytes"
        );

        let module = mct_emit_llvm_module(&ir);
        assert!(
            module.llvm_ir.contains("icmp sge i64"),
            "descending inclusive ranges must lower to LLVM signed-greater-or-equal loop checks"
        );
    }

    #[test]
    fn classic_loop_step_remains_loop_carried_through_release_ssa() {
        let src = r#"
classicBackedge {
    stc:
        k: int;
        sum: int;
    fn:
        run() -> int {
            public:
                for (@k = 0; @k < 4; @k = @k + 1) {
                    if (@k == 1) {
                        continue;
                    }
                    @sum = @sum + @k;
                }
                return @sum;
        }
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(src).expect("lex")).expect("parse");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let loop_stmt = container.functions[0]
            .body
            .iter()
            .find_map(|stmt| match stmt {
                StatementIR::ForClassic { step, body, .. } => Some((step, body)),
                _ => None,
            })
            .expect("classic loop must survive release optimization");
        let Some(step) = loop_stmt.0.as_deref() else {
            panic!("classic loop must retain its step");
        };
        assert!(matches!(
            step,
            StatementIR::ScalarProjection {
                target,
                value: ScalarExprIR::Binary { left, op: ScalarBinaryOpIR::Plus, right },
                ..
            } if target == "k"
                && matches!(left.as_ref(), ScalarExprIR::Symbol(name) if name == "k")
                && matches!(right.as_ref(), ScalarExprIR::Number(value) if value == "1")
        ));
        assert!(
            loop_stmt
                .1
                .iter()
                .any(|stmt| matches!(stmt, StatementIR::If { .. })),
            "loop-carried induction values must not fold away body conditions"
        );
    }

