    #[test]
    fn each_do_while_lowers_continue_through_post_condition_to_native_bytes() {
        let src = r#"
eachPostCondition {
    stc:
        values: array<int, 3>;
        sum: int;
    fn:
        run() -> int {
            public:
                @values >> array<int, 3> : [2, 4, 6];
                each value in @values do {
                    @sum = @sum + @value;
                    if (@value == 2) {
                        continue;
                    }
                } while (@value < 4);
                return @sum;
        }
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(src).expect("lex")).expect("parse");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular container");
        };
        let each_loop = container.functions[0]
            .body
            .iter()
            .find_map(|stmt| match stmt {
                StatementIR::ForClassic {
                    init,
                    condition,
                    step,
                    ..
                } if format!("{init:?}").contains("__ncc_each_value_idx") => {
                    Some((condition, step))
                }
                _ => None,
            })
            .expect("each loop must lower to a material indexed loop");
        assert!(each_loop.0.is_some(), "each loop requires an index bound");
        assert!(
            matches!(each_loop.1.as_deref(), Some(StatementIR::If { else_body, .. })
                if matches!(else_body.first(), Some(StatementIR::Break { label: None }))),
            "post-condition false path must break after both normal flow and continue"
        );

        let backend = emit_backend(&ir);
        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|section| section.name == ".text.eachPostCondition.run")
            .expect("each run text section");
        assert!(
            text.bytes.as_ref().is_some_and(|bytes| !bytes.is_empty()),
            "each do-while must materialize as native text bytes"
        );
    }

    #[test]
    fn llvm_caches_range_bounds_step_and_repeat_count_once() {
        let src = r#"
loopEvalOnce {
    stc:
        total: int;
        endCalls: int;
        stepCalls: int;
        countCalls: int;
    fn:
        nextEnd() -> int {
            public:
                @endCalls = @endCalls + 1;
                return 3;
        }
        nextStep() -> int {
            public:
                @stepCalls = @stepCalls + 1;
                return 1;
        }
        nextCount() -> int {
            public:
                @countCalls = @countCalls + 1;
                return 2;
        }
        run() -> int {
            public:
                for value in 0..=nextEnd() step nextStep() {
                    @total = @total + @value;
                }
                same for (nextCount()) {
                    @total = @total + 1;
                }
                return @total;
        }
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(src).expect("lex")).expect("parse");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let module = mct_emit_llvm_module(&ir);
        for callee in ["nextEnd", "nextStep", "nextCount"] {
            let symbol = format!("@loopEvalOnce_{callee}(");
            let call_count = module
                .llvm_ir
                .lines()
                .filter(|line| line.contains("call ") && line.contains(&symbol))
                .count();
            assert_eq!(
                call_count, 1,
                "{callee} must be evaluated once before its loop"
            );
        }
        assert!(module.llvm_ir.contains("__range_end"));
        assert!(module.llvm_ir.contains("__range_step"));
        assert!(module.llvm_ir.contains("__repeat_limit"));
        assert!(module.llvm_ir.contains("call void @llvm.trap()"));
    }

