    #[test]
    fn emit_backend_win64_materializes_convention_specific_frame_and_native_push_pop() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![ncc_ast::UseDecl {
                path: vec!["system".into(), "net".into(), "core".into()],
                wildcard: false,
                alias: None,
            }],
            containers: vec![
                Container {
                    visibility: None,
                    name: "worker".into(),
                    context: Some(Context::Runtime),
                    sections: vec![Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }])],
                },
                Container {
                    visibility: None,
                    name: "entry".into(),
                    context: Some(Context::System),
                    sections: vec![Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Expr(Expr::QualifiedCall {
                                path: vec!["worker".into(), "boot".into()],
                                args: vec![],
                            }),
                            Stmt::Expr(Expr::QualifiedCall {
                                path: vec!["root".into(), "policy".into(), "bind".into()],
                                args: vec![],
                            }),
                            Stmt::Return(Expr::Bool(true)),
                        ],
                    }])],
                },
            ],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_win64());
        let backend = emit_backend(&ir);
        let entry_boot = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(f) if f.symbol == "entry.boot" => Some(f),
                _ => None,
            })
            .expect("entry.boot backend unit");

        assert_eq!(
            entry_boot.plan.calling_convention,
            BackendCallingConventionIR::NcWin64
        );
        assert_eq!(
            entry_boot.plan.frame_layout.callee_saved,
            vec![
                BackendRegisterIR::Rbp,
                BackendRegisterIR::R14,
                BackendRegisterIR::R15
            ]
        );
        assert!(
            entry_boot
                .ops
                .iter()
                .any(|op| matches!(op, BackendFuncOpIR::ReserveStack(bytes) if *bytes >= 32)),
            "win64 profile must materialize shadow-space-aware stack reserve"
        );
        assert!(
            entry_boot.plan.frame_layout.outgoing_arg_bytes >= 32,
            "the stable frame must reserve Win64 shadow space once for all call sites"
        );
        assert!(!entry_boot
            .ops
            .iter()
            .any(|op| matches!(op, BackendFuncOpIR::ReserveCallStack(_)
                | BackendFuncOpIR::ReleaseCallStack(_))),
            "scalar lowering must reuse the stable outgoing frame instead of adjusting rsp per call"
        );

        let rendered = render_backend_text(&backend);
        assert!(rendered.contains(".fn entry.boot ; mode=system cc=nC.win64"));
        assert!(rendered.contains("mov rbp, rsp ; frame-pointer"));
        assert!(rendered.contains("push r14"));
        assert!(rendered.contains("push r15"));
        assert!(rendered.contains("sub rsp, "));
        assert!(!rendered.contains("; call-stack"));

        let object = emit_object(&backend);
        let section = object
            .sections
            .iter()
            .find(|sec| sec.name == ".text.entry.boot")
            .expect("entry.boot text section");
        let bytes = section
            .bytes
            .as_ref()
            .expect("win64 function section must stay in native bytes");
        assert!(
            bytes.starts_with(&[
                0x55, // push rbp
                0x48, 0x89, 0xE5, // mov rbp, rsp
                0x41, 0x56, // push r14
                0x41, 0x57, // push r15
            ]),
            "win64 function prologue must encode convention-specific callee-saved sequence"
        );
        assert!(
            bytes.windows(3).any(|window| window == [0x48, 0x81, 0xEC]),
            "win64 function prologue must encode a native stack reserve"
        );
    }

    #[test]
    fn text_literal_lowering_maps_each_scalar_to_real_utf8_bytes() {
        let lowered = lower_text_literal_to_bytes("Añe🙂");
        assert_eq!(lowered.schema, "ncc.text_literal_bytes.v1");
        assert_eq!(lowered.status, "closed");
        assert_eq!(lowered.encoding, TextByteEncodingIR::Utf8);
        assert_eq!(lowered.scalar_count, 4);
        assert_eq!(lowered.byte_len, 8);
        assert_eq!(lowered.nul_terminated_byte_len, 9);
        assert_eq!(
            lowered.bytes,
            vec![0x41, 0xC3, 0xB1, 0x65, 0xF0, 0x9F, 0x99, 0x82]
        );
        assert_eq!(
            lowered.nul_terminated_bytes,
            vec![0x41, 0xC3, 0xB1, 0x65, 0xF0, 0x9F, 0x99, 0x82, 0x00]
        );
        let offsets = lowered
            .units
            .iter()
            .map(|unit| {
                (
                    unit.scalar.as_str(),
                    unit.byte_offset,
                    unit.byte_len,
                    unit.hex.as_str(),
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            offsets,
            vec![
                ("A", 0, 1, "41"),
                ("ñ", 1, 2, "C3 B1"),
                ("e", 3, 1, "65"),
                ("🙂", 4, 4, "F0 9F 99 82"),
            ]
        );
    }

    #[test]
    fn text_literal_lowering_classifies_weird_scalars_with_backend_functions() {
        let lowered = lower_text_literal_to_bytes("ñ€≤→🙂e\u{0301}\0\\");
        let roles = lowered
            .units
            .iter()
            .map(|unit| (unit.scalar.as_str(), unit.role, unit.backend_action))
            .collect::<Vec<_>>();

        assert!(roles.contains(&(
            "ñ",
            TextScalarRoleIR::NonAsciiLetter,
            "emit_utf8_payload_bytes"
        )));
        assert!(roles.contains(&(
            "€",
            TextScalarRoleIR::CurrencySymbol,
            "emit_utf8_payload_bytes"
        )));
        assert!(roles.contains(&("≤", TextScalarRoleIR::MathSymbol, "emit_utf8_payload_bytes")));
        assert!(roles.contains(&(
            "→",
            TextScalarRoleIR::ArrowSymbol,
            "emit_utf8_payload_bytes"
        )));
        assert!(roles.contains(&(
            "🙂",
            TextScalarRoleIR::EmojiOrPictograph,
            "emit_utf8_payload_bytes"
        )));
        assert!(roles.contains(&(
            "\u{0301}",
            TextScalarRoleIR::CombiningMark,
            "emit_utf8_payload_bytes"
        )));
        assert!(roles.contains(&("\0", TextScalarRoleIR::Nul, "emit_payload_byte_00")));
        assert!(roles.contains(&("\\", TextScalarRoleIR::Backslash, "emit_utf8_payload_bytes")));
    }

    #[test]
    fn emit_backend_materializes_string_literal_call_arg_with_abs64_reloc() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![ncc_ast::UseDecl {
                path: vec!["system".into(), "net".into(), "core".into()],
                wildcard: false,
                alias: None,
            }],
            containers: vec![Container {
                visibility: None,
                name: "entry".into(),
                context: Some(Context::System),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "boot".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![
                        Stmt::Expr(Expr::QualifiedCall {
                            path: vec![
                                "system".into(),
                                "net".into(),
                                "core".into(),
                                "connect".into(),
                            ],
                            args: vec![Expr::String("nC-ñ-🙂".into()), Expr::Number("8080".into())],
                        }),
                        Stmt::Return(Expr::Bool(true)),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let object = emit_object(&backend);
        let section = object
            .sections
            .iter()
            .find(|sec| sec.name == ".text.entry.boot")
            .expect("entry.boot text section");
        let bytes = section
            .bytes
            .as_ref()
            .expect("string-literal call marshalling must keep native function bytes");

        let call_site = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(func) if func.symbol == "entry.boot" => {
                    func.plan.call_sites.first()
                }
                _ => None,
            })
            .expect("entry.boot call site");
        assert_eq!(
            call_site.arg_pass_classes,
            vec![AbiPassClassIR::PointerWord, AbiPassClassIR::Register]
        );
        assert_eq!(
            call_site
                .arg_locations
                .iter()
                .map(|arg| arg.location.clone())
                .collect::<Vec<_>>(),
            vec![
                BackendCallArgLocationIR::Register(BackendRegisterIR::Rdi),
                BackendCallArgLocationIR::Register(BackendRegisterIR::Rsi),
            ]
        );
        assert!(
            bytes.windows(2).any(|w| w == [0x48, 0xB8]),
            "string literal argument evaluation must materialize a relocatable descriptor address"
        );

        let literal_reloc = object
            .relocations
            .iter()
            .find(|rel| {
                rel.section == ".text.entry.boot"
                    && rel.kind == BackendObjectRelocationKindIR::Abs64
            })
            .expect("abs64 relocation for string literal");
        assert!(
            literal_reloc.symbol.starts_with("entry.boot.__strlit"),
            "literal relocation must target function-local string descriptor"
        );
        let rodata = object
            .sections
            .iter()
            .find(|sec| sec.name == ".rodata.entry.boot")
            .expect("entry.boot rodata section");
        assert_eq!(rodata.kind, BackendObjectSectionKindIR::ReadOnlyData);
        let literal = lower_text_literal_to_bytes("nC-ñ-🙂");
        let literal_payload = literal.nul_terminated_bytes;
        let rodata_bytes = rodata.bytes.as_ref().expect("rodata must carry bytes");
        let descriptor_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == literal_reloc.symbol)
            .expect("string descriptor symbol");
        assert_eq!(descriptor_symbol.section, ".rodata.entry.boot");
        assert_eq!(
            descriptor_symbol.visibility,
            BackendSymbolVisibilityIR::Local
        );
        let descriptor_offset = descriptor_symbol.offset;
        assert_eq!(
            u64::from_le_bytes(
                rodata_bytes[descriptor_offset + 8..descriptor_offset + 16]
                    .try_into()
                    .unwrap()
            ),
            literal.byte_len as u64,
            "string descriptor must record byte length without final NUL"
        );
        let payload_symbol_name = format!("{}.__bytes", literal_reloc.symbol);
        let payload_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == payload_symbol_name)
            .expect("string payload symbol");
        assert_eq!(payload_symbol.section, ".rodata.entry.boot");
        assert_eq!(payload_symbol.visibility, BackendSymbolVisibilityIR::Local);
        assert!(
            object.relocations.iter().any(|rel| {
                rel.section == ".rodata.entry.boot"
                    && rel.offset == descriptor_offset
                    && rel.kind == BackendObjectRelocationKindIR::Abs64
                    && rel.symbol == payload_symbol_name
            }),
            "string descriptor must relocate its payload pointer to the byte symbol"
        );
        assert!(
            rodata_bytes
                .windows(literal_payload.len())
                .any(|w| w == literal_payload.as_slice()),
            "string literal UTF-8 bytes plus NUL must be emitted into read-only data"
        );
        assert!(
            !bytes
                .windows(literal_payload.len())
                .any(|w| w == literal_payload.as_slice()),
            "function text must not embed string literal payload bytes"
        );
        assert!(
            rodata_bytes[payload_symbol.offset..].starts_with(literal_payload.as_slice()),
            "payload symbol must point at UTF-8 bytes plus final NUL"
        );
    }

    #[test]
    fn emit_backend_materializes_closure_call_arg_with_real_invoke_body() {
        let closure = Expr::Closure(ncc_ast::ClosureExpr {
            is_async: false,
            is_move: false,
            params: vec![ncc_ast::ClosureParam {
                name: "value".into(),
                ty: TypeName::Simple("int".into()),
            }],
            return_type: TypeName::Simple("bool".into()),
            captures: vec![],
            effects: vec![],
            body: vec![Stmt::Return(Expr::Bool(true))],
        });
        let Expr::Closure(closure_contract) = &closure else {
            unreachable!();
        };
        let closure_key = stable_closure_value_key(closure_contract);
        let invoke_symbol = format!("entry.boot.__closure_{closure_key}.__invoke");
        let program = Program {
            modules: vec![],
            packages: vec![ncc_ast::PackageDecl {
                name: "closure_owned_storage".into(),
                version: None,
                profile: Some("raw".into()),
                modules: vec![],
            }],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "entry".into(),
                context: Some(Context::System),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "boot".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![
                        Stmt::Expr(Expr::Call {
                            callee: "accept".into(),
                            args: vec![Expr::Call {
                                callee: "closureAt".into(),
                                args: vec![
                                    Expr::Call {
                                        callee: "alloc".into(),
                                        args: vec![Expr::Number("256".into())],
                                    },
                                    closure,
                                ],
                            }],
                        }),
                        Stmt::Return(Expr::Bool(true)),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|sec| sec.name == ".text.entry.boot")
            .expect("entry.boot text section");
        let text_bytes = text.bytes.as_ref().expect("text must carry native bytes");
        let invoke_text = object
            .sections
            .iter()
            .find(|sec| sec.name == format!(".text.{invoke_symbol}"))
            .expect("closure invoke text section");
        let invoke_bytes = invoke_text
            .bytes
            .as_ref()
            .expect("closure invoke body must carry native bytes");
        assert!(
            !invoke_bytes.is_empty(),
            "closure invoke body is materialized"
        );
        assert!(
            !invoke_bytes.windows(2).any(|bytes| bytes == [0x0F, 0x0B]),
            "valid closure body must not contain ud2"
        );
        assert!(
            object
                .symbols
                .iter()
                .any(|symbol| symbol.name == invoke_symbol
                    && symbol.section == format!(".text.{invoke_symbol}")
                    && symbol.visibility == BackendSymbolVisibilityIR::Global),
            "closure invoke function must be link-visible"
        );
        assert!(
            object.relocations.iter().any(|rel| {
                rel.section == ".text.entry.boot"
                    && rel.kind == BackendObjectRelocationKindIR::Abs64
                    && rel.symbol == invoke_symbol
            }),
            "runtime descriptor construction must relocate its code word to the invoke body"
        );
        assert!(
            object
                .relocations
                .iter()
                .any(|rel| { rel.section == ".text.entry.boot" && rel.symbol == "malloc" }),
            "the explicit alloc call must remain visible in machine relocations"
        );
        assert!(
            !object
                .symbols
                .iter()
                .any(|symbol| symbol.name.ends_with(".__invoke_trap")),
            "legacy closure trap symbols are forbidden"
        );
        assert!(
            !text_bytes.windows(2).any(|bytes| bytes == [0x0F, 0x0B]),
            "closure construction path must not use ud2"
        );
        let closure_code_reloc = object
            .relocations
            .iter()
            .find(|rel| rel.section == ".text.entry.boot" && rel.symbol == invoke_symbol)
            .expect("closure code relocation");
        assert!(closure_code_reloc.offset < text_bytes.len());
    }

    #[test]
    fn canonical_compact_manual_raw_source_reaches_llvm_and_machine_bytes() {
        let source = include_str!("../../../examples/06_memory/manual_raw_api_abi_layout.n");
        let tokens = ncc_lexer::lex(source).expect("canonical compact source must lex");
        let program = ncc_parser::parse(tokens).expect("canonical compact source must parse");
        ncc_sema::analyze(&program).expect("canonical compact source must pass sema");

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        assert!(ir.source_contract.is_manual_raw());

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(llvm.status, "llvm_adapter_emitted", "{:#?}", llvm.functions);
        assert_eq!(llvm.rejected_function_count, 0, "{:#?}", llvm.functions);
        assert!(llvm.diagnostics.is_empty(), "{:?}", llvm.diagnostics);
        assert!(!llvm.llvm_ir.contains("__nC_uninit"));
        assert!(!llvm.llvm_ir.contains("__ncc_named_closure_make"));
        assert!(llvm.llvm_ir.contains("manualRawApiAbiLayout_twiceBody"));
        assert!(
            llvm.llvm_ir.contains("manualRawApiAbiLayout___ncc_fa"),
            "fa must materialize as a native finalizer function"
        );
        assert!(
            llvm.llvm_ir.contains("@llvm.global_dtors"),
            "fa must be registered in the native module lifecycle"
        );

        let backend = emit_backend(&ir);
        let run = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function)
                    if function.symbol == "manualRawApiAbiLayout.run" =>
                {
                    Some(function)
                }
                _ => None,
            })
            .expect("canonical run function must reach the native backend");
        assert!(
            run.lowering_coverage.is_complete(),
            "canonical run lowering must be complete: {:?}",
            run.lowering_coverage
        );
        let fa = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function)
                    if function.symbol == "manualRawApiAbiLayout.__ncc_fa" =>
                {
                    Some(function)
                }
                _ => None,
            })
            .expect("fa must reach the native backend as a function");
        assert!(
            fa.effects.iter().any(|effect| effect == "module.fini"),
            "fa must retain its machine lifecycle effect"
        );
        assert!(
            fa.lowering_coverage.is_complete(),
            "fa lowering must be complete: {:?}",
            fa.lowering_coverage
        );

        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|section| section.name == ".text.manualRawApiAbiLayout.run")
            .expect("canonical run text section");
        let bytes = text
            .bytes
            .as_ref()
            .expect("canonical run must carry machine bytes");
        assert!(!bytes.is_empty());
        assert!(
            !bytes.windows(2).any(|window| window == [0x0F, 0x0B]),
            "canonical run must not contain a deferred ud2 trap"
        );
        assert!(object.relocations.iter().any(|relocation| {
            relocation.section == ".text.manualRawApiAbiLayout.makeTwice"
                && relocation.symbol == "manualRawApiAbiLayout.twiceBody"
        }));
        assert!(
            !object
                .relocations
                .iter()
                .any(|relocation| relocation.symbol.ends_with("ptrCast")),
            "raw pointer casts must move address bits without an external ABI call"
        );
        assert!(object.relocations.iter().any(|relocation| {
            relocation.section.starts_with(".fini_array")
                && relocation.symbol == "manualRawApiAbiLayout.__ncc_fa"
        }));
    }

    #[test]
    fn native_machine_pop_materializes_global_dynamic_descriptors() {
        let source = r#"
package global_dinarray_pop { profile: release_fast; }

globalDinArrayPop {
    stc:
        values: dinArray.binary<int>;
        result: int;
    fn:
        run() -> bool {
            public:
                @storage !> p<int> : cast<int>(alloc(8));
                @values >> dinArray.binary<int> : dinAt<int>(@storage, 2);
                @values.push(7);
                @result >> int : @values.pop();
                free(@storage);
                return @result == 7;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(source).expect("global dinArray lex"))
            .expect("global dinArray parse");
        ncc_sema::analyze(&program).expect("global dinArray sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let backend = emit_backend(&ir);
        let run = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function) if function.symbol == "globalDinArrayPop.run" => {
                    Some(function)
                }
                _ => None,
            })
            .expect("global dinArray run function");
        assert!(
            run.lowering_coverage.is_complete(),
            "global dinArray bind/push/pop must be fully materialized: {:?}",
            run.lowering_coverage
        );
        let scalar_ops = run.ops.iter().flat_map(|op| match op {
            BackendFuncOpIR::ScalarOps { ops } => ops.as_slice(),
            _ => &[],
        });
        let scalar_ops = scalar_ops.collect::<Vec<_>>();
        assert!(!scalar_ops.iter().any(|op| {
            matches!(op, BackendScalarOpIR::Call { target, .. } if target == "realloc")
        }));
        assert!(scalar_ops.iter().any(|op| {
            matches!(op, BackendScalarOpIR::LoadGlobalAddr { symbol, .. } if symbol.contains("values"))
        }));
    }

    #[test]
    fn raw_string_array_push_requires_capacity_and_borrows_the_stored_text() {
        let source = r#"
package raw_string_array_push { profile: raw; }

rawStringArrayPush {
    stc:
        values >> Array<str>;
    fn:
        add(value >> str) -> bool {
            values.push(value);
            return values.len == 1;
        }
        run() -> bool {
            return add("stable");
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(source).expect("raw string array lex"))
            .expect("raw string array parse");
        ncc_sema::analyze(&program).expect("raw string array sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        assert!(ir.source_contract.is_manual_raw());

        let llvm = mct_emit_llvm_module(&ir);
        assert_eq!(
            llvm.status, "llvm_adapter_emitted",
            "{:?}",
            llvm.diagnostics
        );
        assert_eq!(llvm.rejected_function_count, 0, "{:?}", llvm.diagnostics);
        assert!(
            !llvm.llvm_ir.contains("call ptr @realloc(ptr"),
            "raw push must not grow an empty descriptor"
        );
        assert!(
            !llvm.llvm_ir.contains("call ptr @ncc_rt_str_concat(ptr"),
            "Array<str>.push must store a borrowed raw pointer"
        );
        assert!(
            llvm.llvm_ir.contains("[ false, %dinarray_push_fail")
                && llvm.llvm_ir.contains("icmp ult i64")
                && !llvm.llvm_ir.contains(".dinarray_push = alloca i1"),
            "a full descriptor must produce push=false directly in SSA: {}",
            llvm.llvm_ir
        );

        let backend = emit_backend(&ir);
        let add = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function)
                    if function.symbol == "rawStringArrayPush.add" =>
                {
                    Some(function)
                }
                _ => None,
            })
            .expect("raw string array add function");
        assert!(
            add.lowering_coverage.is_complete(),
            "raw string push must be machine-materialized: {:?}",
            add.lowering_coverage
        );
        let calls = add.ops.iter().flat_map(|op| match op {
            BackendFuncOpIR::ScalarOps { ops } => ops
                .iter()
                .filter_map(|op| match op {
                    BackendScalarOpIR::Call { target, .. } => Some(target.as_str()),
                    _ => None,
                })
                .collect::<Vec<_>>(),
            _ => Vec::new(),
        });
        let calls = calls.collect::<Vec<_>>();
        assert!(
            !calls.contains(&"realloc") && !calls.contains(&"ncc_rt_str_concat"),
            "machine calls={calls:?}"
        );
    }

    #[test]
    fn raw_string_projection_into_stc_lowers_native_concat() {
        let source = r#"
package raw_string_stc_escape { profile: raw; }

rawStringStcEscape {
    stc:
        decision >> str <- "NONE";
    fn:
        public:
            set(value >> str) -> bool {
                decision <- "BLOCKED|" + value;
                return true;
            }
            get() -> str {
                return decision;
            }
            run() -> bool {
                return set("+34900111222");
            }
    ref main ->> run;
    fa:
        return true;
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(source).expect("raw stc string lex"))
            .expect("raw stc string parse");
        ncc_sema::analyze(&program).expect("raw stc string addition must pass sema");
        let ir = lower(program);
        let module = mct_emit_llvm_module(&ir);
        assert!(module.diagnostics.is_empty(), "{:#?}", module.diagnostics);
        for material in [
            "call ptr @malloc",
            "call i64 @strlen",
            "@llvm.memcpy",
            "store ptr",
            "@__ncc_stc_rawStringStcEscape_decision",
        ] {
            assert!(
                module.llvm_ir.contains(material),
                "native concat material '{material}' missing:\n{}",
                module.llvm_ir
            );
        }
        assert!(!module.llvm_ir.contains("@ncc_rt_str_concat"));
    }

