    #[test]
    fn returned_closure_uses_caller_owned_storage_in_llvm_and_machine_plans() {
        let source = r#"
package closure_return_abi { profile: vendor_lab; }

closureReturnAbi {
    fn:
        make() -> fn() -> int {
            public:
                value >> int = 41;
                return move || -> int captures(move @value) {
                    return @value + 1;
                };
        }

        run() -> bool {
            public:
                mark >> p<byte> = stackMark();
                storage >> p<byte> = stackAlloc(64, 16);
                owned >> fn() -> int = callAt(storage, make());
                answer >> int = owned();
                stackRestore(mark);
                return answer == 42;
        }

    ref main ->> @fn(run);
    fa:
        return true;
}
"#;
        let program = ncc_parser::parse(ncc_lexer::lex(source).expect("closure ABI lex"))
            .expect("closure ABI parse");
        ncc_sema::analyze(&program).expect("closure ABI sema");
        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let ContainerIR::Regular(container) = &ir.containers[0] else {
            panic!("expected regular closure container");
        };
        let make = container
            .functions
            .iter()
            .find(|function| function.name == "make")
            .expect("make function");
        let layout = make
            .closure_storage_layout
            .as_ref()
            .expect("program closure storage envelope");
        assert_eq!(layout.descriptor_size_bytes, 32);
        assert_eq!(layout.environment_offset_bytes, 32);
        assert_eq!(layout.environment_size_bytes, 8);
        assert_eq!(layout.total_size_bytes, 40);
        assert_eq!(make.params[0].name, "__ncc_closure_return_storage");
        assert_eq!(
            make.backend_plan.param_locations[0].location,
            BackendValueLocationIR::Register(BackendRegisterIR::Rdi)
        );

        let backend = emit_backend(&ir);
        let run = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(function) if function.symbol == "closureReturnAbi.run" => {
                    Some(function)
                }
                _ => None,
            })
            .expect("machine run function");
        let make_call = run
            .plan
            .call_sites
            .iter()
            .find(|site| site.target.ends_with("make"))
            .expect("machine make call");
        assert_eq!(make_call.arg_count, 1);
        assert!(matches!(
            &make_call.arg_locations[0].source,
            FunctionCallArgSourceIR::Symbol(name)
                if name == "storage"
        ));
        assert_eq!(
            make_call.arg_locations[0].location,
            BackendCallArgLocationIR::Register(BackendRegisterIR::Rdi)
        );

        let module = mct_emit_llvm_module(&ir);
        assert_eq!(module.status, "llvm_adapter_emitted");
        assert!(module.diagnostics.is_empty(), "{:?}", module.diagnostics);
        assert!(module
            .llvm_ir
            .contains("define ptr @closureReturnAbi_make(ptr %__ncc_closure_return_storage)"));
        assert!(module
            .llvm_ir
            .contains("call ptr @closureReturnAbi_make(ptr "));
        let make_start = module
            .llvm_ir
            .find("define ptr @closureReturnAbi_make(")
            .expect("LLVM make definition");
        let make_body = &module.llvm_ir[make_start..];
        let make_end = make_body.find("\n}\n").expect("LLVM make end");
        let make_body = &make_body[..make_end];
        assert!(make_body.contains("ret ptr"));
        assert!(make_body.contains("getelementptr i8, ptr"));
        assert!(make_body.contains("i64 32"));
        assert!(
            !make_body.contains("alloca [40 x i8]"),
            "callee must not return its own stack allocation:\n{make_body}"
        );
    }

    #[test]
    fn emit_backend_lowers_dev_trap_to_native_ud2() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "entry".into(),
                context: Some(Context::System),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "boot".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("int".into()),
                    public_body: vec![Stmt::Return(Expr::Dev(vec!["panic".into()]))],
                }])],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let rendered = render_backend_text(&backend);
        assert!(
            rendered.contains("ud2 ; scalar-trap"),
            "backend text must expose native trap op"
        );
        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|sec| sec.name == ".text.entry.boot")
            .expect("entry.boot text section");
        let bytes = text.bytes.as_ref().expect("text must carry native bytes");
        assert!(
            bytes.windows(2).any(|w| w == [0x0F, 0x0B]),
            "DevTrap must encode x86_64 ud2"
        );
    }

    #[test]
    fn emit_backend_materializes_stc_globals_data_rodata_and_init_wrapper() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "stateful".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "counter".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Number("7".into())),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "ready".into(),
                            ty: TypeName::Simple("bool".into()),
                            init: Some(Expr::Bool(true)),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "label".into(),
                            ty: TypeName::Simple("str".into()),
                            init: Some(Expr::String("line\nhexA".into())),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "ptr".into(),
                            ty: TypeName::Simple("ptr<int>".into()),
                            init: None,
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "stateful" => Some(stc),
                _ => None,
            })
            .expect("stateful stc globals unit");
        assert_eq!(stc.init_symbol, "__ncc_stc_init.stateful");
        assert_eq!(stc.globals.len(), 4);
        assert_eq!(stc.unsupported_init_count, 0);

        let object = emit_object(&backend);
        let init_text = object
            .sections
            .iter()
            .find(|sec| sec.name == ".text.__ncc_stc_init.stateful")
            .expect("stc init wrapper text section");
        assert_eq!(init_text.kind, BackendObjectSectionKindIR::Text);
        assert_eq!(
            init_text.bytes.as_deref(),
            Some(&[0xC3][..]),
            "x86_64 stc init wrapper must be a real ret"
        );
        assert!(
            object.symbols.iter().any(|sym| {
                sym.name == "__ncc_stc_init.stateful"
                    && sym.section == ".text.__ncc_stc_init.stateful"
                    && sym.visibility == BackendSymbolVisibilityIR::Global
            }),
            "stc init wrapper must be a global native symbol"
        );

        let counter_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_stateful_counter")
            .expect("counter symbol");
        let counter_section = object
            .sections
            .iter()
            .find(|sec| sec.name == counter_symbol.section)
            .expect("counter data section");
        assert_eq!(counter_section.kind, BackendObjectSectionKindIR::Data);
        assert_eq!(counter_symbol.offset, 0);
        assert_eq!(counter_symbol.visibility, BackendSymbolVisibilityIR::Global);
        assert_eq!(
            counter_section.bytes.as_deref(),
            Some(&7i32.to_le_bytes()[..])
        );

        let ready_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_stateful_ready")
            .expect("ready symbol");
        let ready_section = object
            .sections
            .iter()
            .find(|sec| sec.name == ready_symbol.section)
            .expect("ready data section");
        assert_eq!(ready_section.bytes.as_deref(), Some(&[1][..]));

        let label_slot_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_stateful_label")
            .expect("stc string mutable slot symbol");
        let label_slot_section = object
            .sections
            .iter()
            .find(|sec| sec.name == label_slot_symbol.section)
            .expect("label pointer section");
        assert_eq!(label_slot_section.kind, BackendObjectSectionKindIR::Data);
        assert_eq!(label_slot_section.bytes.as_deref(), Some(&[0; 8][..]));
        assert_eq!(label_slot_symbol.offset, 0);
        assert_eq!(
            label_slot_symbol.visibility,
            BackendSymbolVisibilityIR::Global
        );
        let pointer_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_stateful_ptr")
            .expect("ptr<T> stc symbol");
        let pointer_section = object
            .sections
            .iter()
            .find(|sec| sec.name == pointer_symbol.section)
            .expect("ptr<T> bss section");
        assert_eq!(pointer_section.kind, BackendObjectSectionKindIR::Bss);
        assert_eq!(pointer_section.size_bytes, 8);
        assert_eq!(pointer_symbol.offset, 0);
        assert_eq!(pointer_symbol.visibility, BackendSymbolVisibilityIR::Global);

        let literal = lower_text_literal_to_bytes("line\nhexA");
        let bytes_symbol = "__ncc_stc_stateful_label.__bytes";
        let payload_symbol = object
            .symbols
            .iter()
            .find(|sym| sym.name == bytes_symbol)
            .expect("stc string payload symbol");
        let rodata = object
            .sections
            .iter()
            .find(|sec| sec.name == payload_symbol.section)
            .expect("stc string rodata section");
        assert_eq!(rodata.kind, BackendObjectSectionKindIR::ReadOnlyData);
        let rodata_bytes = rodata.bytes.as_ref().expect("stc rodata must carry bytes");
        assert_eq!(payload_symbol.visibility, BackendSymbolVisibilityIR::Local);
        assert!(
            rodata_bytes[payload_symbol.offset..].starts_with(&literal.nul_terminated_bytes),
            "stc string payload must preserve escaped UTF-8 bytes plus final NUL"
        );
        assert!(
            object.relocations.iter().any(|rel| {
                rel.section == label_slot_symbol.section
                    && rel.offset == label_slot_symbol.offset
                    && rel.kind == BackendObjectRelocationKindIR::Abs64
                    && rel.symbol == bytes_symbol
            }),
            "stc string mutable slot must relocate to its payload bytes"
        );
        let elf = emit_object_elf64(&object).expect("ELF64 writer must serialize stc sections");
        assert!(
            elf.windows(counter_symbol.section.len())
                .any(|w| w == counter_symbol.section.as_bytes())
                && elf
                    .windows(payload_symbol.section.len())
                    .any(|w| w == payload_symbol.section.as_bytes()),
            "ELF section string table must include native stc data and rodata sections"
        );
    }

    #[test]
    fn emit_backend_materializes_projected_stc_constant_expressions_as_data_bytes() {
        let int_ty = TypeName::Simple("int".into());
        let stc = |name: &str, init: Expr| ncc_ast::StcDecl::Typed {
            visibility: None,
            strictly: false,
            name: name.into(),
            ty: int_ty.clone(),
            init: Some(init),
        };
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "projected".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::Stc(vec![
                        stc(
                            "base",
                            Expr::Unary {
                                op: ncc_ast::UnaryOp::Minus,
                                expr: Box::new(Expr::Number("8".into())),
                            },
                        ),
                        stc("limit", Expr::Number("4".into())),
                        stc("copy", Expr::Identifier("base".into())),
                        stc(
                            "delta",
                            Expr::Binary {
                                left: Box::new(Expr::Identifier("base".into())),
                                op: ncc_ast::BinaryOp::Plus,
                                right: Box::new(Expr::Identifier("limit".into())),
                            },
                        ),
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "projected" => Some(stc),
                _ => None,
            })
            .expect("projected stc globals unit");
        assert_eq!(stc.unsupported_init_count, 0);
        assert!(stc.globals.iter().any(|global| {
            global.name == "base" && global.init == BackendStcGlobalInitIR::Integer(-8)
        }));
        assert!(stc.globals.iter().any(|global| {
            global.name == "copy" && global.init == BackendStcGlobalInitIR::Integer(-8)
        }));
        assert!(stc.globals.iter().any(|global| {
            global.name == "delta" && global.init == BackendStcGlobalInitIR::Integer(-4)
        }));

        let object = emit_object(&backend);
        let read_i32 = |symbol: &str| -> i32 {
            let sym = object
                .symbols
                .iter()
                .find(|sym| sym.name == symbol)
                .unwrap_or_else(|| panic!("missing symbol {symbol}"));
            let section = object
                .sections
                .iter()
                .find(|section| section.name == sym.section)
                .unwrap_or_else(|| panic!("missing section {}", sym.section));
            let bytes = section.bytes.as_ref().expect("projected data bytes");
            i32::from_le_bytes(bytes[sym.offset..sym.offset + 4].try_into().unwrap())
        };
        assert_eq!(read_i32("__ncc_stc_projected_base"), -8);
        assert_eq!(read_i32("__ncc_stc_projected_copy"), -8);
        assert_eq!(read_i32("__ncc_stc_projected_delta"), -4);
        assert_eq!(read_i32("__ncc_stc_projected_limit"), 4);
    }

    #[test]
    fn emit_backend_materializes_projected_stc_fixed_array_literals_as_data_bytes() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "arrayProjected".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "base".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Unary {
                                op: ncc_ast::UnaryOp::Minus,
                                expr: Box::new(Expr::Number("8".into())),
                            }),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "series".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![
                                    TypeName::Simple("int".into()),
                                    TypeName::Simple("3".into()),
                                ],
                            },
                            init: Some(Expr::ArrayLiteral(vec![
                                Expr::Number("1".into()),
                                Expr::Unary {
                                    op: ncc_ast::UnaryOp::Minus,
                                    expr: Box::new(Expr::Number("2".into())),
                                },
                                Expr::Binary {
                                    left: Box::new(Expr::Identifier("base".into())),
                                    op: ncc_ast::BinaryOp::Plus,
                                    right: Box::new(Expr::Number("11".into())),
                                },
                            ])),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "arrayProjected" => Some(stc),
                _ => None,
            })
            .expect("arrayProjected stc globals unit");
        assert_eq!(stc.unsupported_init_count, 0);
        let series = stc
            .globals
            .iter()
            .find(|global| global.name == "series")
            .expect("series stc global");
        assert_eq!(
            series.init,
            BackendStcGlobalInitIR::FixedArrayLiteral {
                elem_ty: "int".into(),
                len: 3,
                bytes: [1i32, -2, 3]
                    .into_iter()
                    .flat_map(i32::to_le_bytes)
                    .collect()
            }
        );

        let object = emit_object(&backend);
        let series_sym = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_arrayProjected_series")
            .expect("series symbol");
        let data = object
            .sections
            .iter()
            .find(|section| section.name == series_sym.section)
            .expect("arrayProjected symbol section");
        let bytes = data.bytes.as_ref().expect("arrayProjected data bytes");
        let read_i32_at = |index: usize| -> i32 {
            let offset = series_sym.offset + index * 4;
            i32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
        };
        assert_eq!(read_i32_at(0), 1);
        assert_eq!(read_i32_at(1), -2);
        assert_eq!(read_i32_at(2), 3);
    }

    #[test]
    fn emit_backend_materializes_fixed_string_arrays_as_pointer_table_and_rodata() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "stringArrayBytes".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "names".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![
                                    TypeName::Simple("str".into()),
                                    TypeName::Simple("3".into()),
                                ],
                            },
                            init: Some(Expr::ArrayLiteral(vec![
                                Expr::String("Ada".into()),
                                Expr::String("Linus".into()),
                                Expr::String("nC".into()),
                            ])),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "aliases".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![
                                    TypeName::Simple("str".into()),
                                    TypeName::Simple("3".into()),
                                ],
                            },
                            init: Some(Expr::ArrayLiteral(vec![Expr::String("same".into())])),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "stringArrayBytes" => Some(stc),
                _ => None,
            })
            .expect("stringArrayBytes stc globals unit");
        let names = stc
            .globals
            .iter()
            .find(|global| global.name == "names")
            .expect("names stc global");
        assert_eq!(names.storage_size_bytes, 24);
        assert!(matches!(
            &names.init,
            BackendStcGlobalInitIR::FixedStringArrayLiteral { len, values }
                if *len == 3 && values == &["Ada", "Linus", "nC"]
        ));
        assert!(matches!(
            stc.globals
                .iter()
                .find(|global| global.name == "aliases")
                .map(|global| &global.init),
            Some(BackendStcGlobalInitIR::FixedStringArrayLiteral { len, values })
                if *len == 3 && values == &["same", "same", "same"]
        ));

        let object = emit_object(&backend);
        let names_symbol = object
            .symbols
            .iter()
            .find(|symbol| symbol.name == "__ncc_stc_stringArrayBytes_names")
            .expect("names symbol");
        let names_section = object
            .sections
            .iter()
            .find(|section| section.name == names_symbol.section)
            .expect("names pointer-table section");
        let data_bytes = names_section
            .bytes
            .as_ref()
            .expect("string array data bytes");
        assert!(data_bytes[names_symbol.offset..names_symbol.offset + 24]
            .iter()
            .all(|byte| *byte == 0));

        let relocs = object
            .relocations
            .iter()
            .filter(|rel| {
                rel.section == names_symbol.section && rel.symbol.contains("_names.__str.")
            })
            .collect::<Vec<_>>();
        assert_eq!(relocs.len(), 3);
        for (index, rel) in relocs.iter().enumerate() {
            assert_eq!(rel.offset, names_symbol.offset + index * 8);
            assert_eq!(rel.kind, BackendObjectRelocationKindIR::Abs64);
            assert_eq!(
                rel.symbol,
                format!("__ncc_stc_stringArrayBytes_names.__str.{index}")
            );
        }

        let aliases_symbol = object
            .symbols
            .iter()
            .find(|symbol| symbol.name == "__ncc_stc_stringArrayBytes_aliases")
            .expect("aliases symbol");
        let aliases_relocs = object
            .relocations
            .iter()
            .filter(|rel| {
                rel.section == aliases_symbol.section && rel.symbol.contains("_aliases.__str.")
            })
            .collect::<Vec<_>>();
        assert_eq!(aliases_relocs.len(), 3);
        assert!(aliases_relocs
            .iter()
            .all(|rel| rel.symbol == "__ncc_stc_stringArrayBytes_aliases.__str.0"));

        for (symbol_name, expected) in [
            ("__ncc_stc_stringArrayBytes_aliases.__str.0", &b"same\0"[..]),
            ("__ncc_stc_stringArrayBytes_names.__str.0", &b"Ada\0"[..]),
            ("__ncc_stc_stringArrayBytes_names.__str.1", &b"Linus\0"[..]),
            ("__ncc_stc_stringArrayBytes_names.__str.2", &b"nC\0"[..]),
        ] {
            let symbol = object
                .symbols
                .iter()
                .find(|symbol| symbol.name == symbol_name)
                .unwrap_or_else(|| panic!("missing literal symbol {symbol_name}"));
            let section = object
                .sections
                .iter()
                .find(|section| section.name == symbol.section)
                .unwrap_or_else(|| panic!("missing literal section {}", symbol.section));
            assert_eq!(section.kind, BackendObjectSectionKindIR::ReadOnlyData);
            let bytes = section.bytes.as_ref().expect("literal rodata bytes");
            assert_eq!(
                &bytes[symbol.offset..symbol.offset + expected.len()],
                expected
            );
        }
    }

    #[test]
    fn emit_backend_materializes_projected_stc_dynamic_array_literals_as_backing_bytes() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "dynamicProjected".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "base".into(),
                            ty: TypeName::Simple("int".into()),
                            init: Some(Expr::Number("4".into())),
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "items".into(),
                            ty: TypeName::Generic {
                                base: "list".into(),
                                args: vec![TypeName::Simple("int".into())],
                            },
                            init: Some(Expr::ArrayLiteral(vec![
                                Expr::Binary {
                                    left: Box::new(Expr::Identifier("base".into())),
                                    op: ncc_ast::BinaryOp::Plus,
                                    right: Box::new(Expr::Number("7".into())),
                                },
                                Expr::Unary {
                                    op: ncc_ast::UnaryOp::Minus,
                                    expr: Box::new(Expr::Number("2".into())),
                                },
                            ])),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "dynamicProjected" => Some(stc),
                _ => None,
            })
            .expect("dynamicProjected stc globals unit");
        assert_eq!(stc.unsupported_init_count, 0);
        let items = stc
            .globals
            .iter()
            .find(|global| global.name == "items")
            .expect("items stc global");
        assert!(matches!(
            &items.init,
            BackendStcGlobalInitIR::DynamicArrayLiteral { elem_ty, items, bytes }
                if elem_ty == "int"
                    && items.len() == 2
                    && *bytes == [11i32, -2]
                        .into_iter()
                        .flat_map(i32::to_le_bytes)
                        .collect::<Vec<_>>()
        ));

        let object = emit_object(&backend);
        let data_sym = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_dynamicProjected_items.__data")
            .expect("items backing symbol");
        let data = object
            .sections
            .iter()
            .find(|section| section.name == data_sym.section)
            .expect("dynamicProjected backing section");
        let bytes = data.bytes.as_ref().expect("dynamicProjected data bytes");
        let read_i32_at = |index: usize| -> i32 {
            let offset = data_sym.offset + index * 4;
            i32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
        };
        assert_eq!(read_i32_at(0), 11);
        assert_eq!(read_i32_at(1), -2);
    }

    #[test]
    fn emit_backend_materializes_stc_struct_and_struct_array_storage_bytes() {
        let cell_ty = TypeName::Simple("Cell".into());
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "structBytes".into(),
                context: Some(Context::System),
                sections: vec![
                    Section::TypeContracts(vec![TypeContractDecl {
                        name: "Cell".into(),
                        kind: TypeContractKind::Struct,
                        generic_params: Vec::new(),
                        variants: Vec::new(),
                        clauses: vec![TypeContractClause::Fields {
                            visibility: Visibility::Public,
                            fields: vec![
                                TypeContractField {
                                    name: "value".into(),
                                    ty: TypeName::Simple("int".into()),
                                },
                                TypeContractField {
                                    name: "code".into(),
                                    ty: TypeName::Simple("char".into()),
                                },
                            ],
                        }],
                    }]),
                    Section::Stc(vec![
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "single".into(),
                            ty: cell_ty.clone(),
                            init: None,
                        },
                        ncc_ast::StcDecl::Typed {
                            visibility: None,
                            strictly: false,
                            name: "cells".into(),
                            ty: TypeName::Generic {
                                base: "array".into(),
                                args: vec![cell_ty, TypeName::Simple("2".into())],
                            },
                            init: Some(Expr::ArrayLiteral(vec![Expr::Number("0".into())])),
                        },
                    ]),
                    Section::Fn(vec![FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "boot".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![Stmt::Return(Expr::Bool(true))],
                    }]),
                ],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let stc = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::StcGlobals(stc) if stc.container == "structBytes" => Some(stc),
                _ => None,
            })
            .expect("structBytes stc globals unit");
        assert_eq!(stc.unsupported_init_count, 0);
        let single = stc
            .globals
            .iter()
            .find(|global| global.name == "single")
            .expect("single struct global");
        assert_eq!(single.storage_size_bytes, 8);
        let cells = stc
            .globals
            .iter()
            .find(|global| global.name == "cells")
            .expect("cells struct-array global");
        assert_eq!(cells.storage_size_bytes, 16);
        assert!(matches!(
            &cells.init,
            BackendStcGlobalInitIR::FixedArrayLiteral { elem_ty, len, bytes }
                if elem_ty == "Cell" && *len == 2 && bytes.len() == 16 && bytes.iter().all(|byte| *byte == 0)
        ));

        let object = emit_object(&backend);
        let single_sym = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_structBytes_single")
            .expect("single symbol");
        let cells_sym = object
            .symbols
            .iter()
            .find(|sym| sym.name == "__ncc_stc_structBytes_cells")
            .expect("cells symbol");
        let single_section = object
            .sections
            .iter()
            .find(|section| section.name == single_sym.section)
            .expect("single struct bss section");
        assert_eq!(single_section.kind, BackendObjectSectionKindIR::Bss);
        assert_eq!(single_section.size_bytes, 8);
        let cells_section = object
            .sections
            .iter()
            .find(|section| section.name == cells_sym.section)
            .expect("struct array data section");
        let cells_bytes = cells_section
            .bytes
            .as_ref()
            .expect("struct array data bytes");
        assert!(cells_bytes[cells_sym.offset..cells_sym.offset + 16]
            .iter()
            .all(|byte| *byte == 0));
    }

    #[test]
    fn emit_backend_materializes_machine_and_primitive_units() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![
                Container {
                    visibility: None,
                    name: "devMachine".into(),
                    context: Some(Context::Machine),
                    sections: vec![
                        Section::Reg(vec!["ax".into()]),
                        Section::Inst(vec![
                            MachineInst::Label {
                                name: "entryPoint".into(),
                            },
                            MachineInst::Nop,
                            MachineInst::Jmp {
                                target: "entryPoint".into(),
                            },
                        ]),
                        Section::MachineFinal(vec![MachineFinalOp::Ret]),
                    ],
                },
                Container {
                    visibility: None,
                    name: "devPrimitive".into(),
                    context: Some(Context::Primitive),
                    sections: vec![
                        Section::PrimitiveTarget("x86_64".into()),
                        Section::Bridge(vec![
                            PrimitiveBridgeTarget::MachinePath(vec!["devMachine".into()]),
                            PrimitiveBridgeTarget::RootPath(vec![
                                "root".into(),
                                "policy".into(),
                                "bind".into(),
                            ]),
                        ]),
                        Section::Capability(PrimitiveCapabilitySection {
                            name: "boot_serial_io".into(),
                            rules: vec![],
                        }),
                        Section::Operation(PrimitiveOperationSection {
                            name: vec!["uart0".into(), "emit_byte".into()],
                            params: vec![],
                            clauses: vec![],
                        }),
                    ],
                },
            ],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);

        let machine = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Machine(m) if m.symbol == "devMachine.machine" => Some(m),
                _ => None,
            })
            .expect("machine backend unit");
        assert!(machine.ops.iter().any(|op| {
            matches!(
                op,
                BackendMachineOpIR::Inst(MachineInstIR::Jmp { target }) if target == "entryPoint"
            )
        }));
        assert!(machine
            .ops
            .iter()
            .any(|op| matches!(op, BackendMachineOpIR::Final(MachineFinalOpIR::Ret))));

        let primitive = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Primitive(p) if p.symbol == "devPrimitive.primitive" => Some(p),
                _ => None,
            })
            .expect("primitive backend unit");
        assert_eq!(primitive.target.as_deref(), Some("x86_64"));
        assert_eq!(primitive.bridges.len(), 2);
        assert_eq!(primitive.capabilities, vec!["boot_serial_io".to_string()]);
        assert_eq!(
            primitive.operations,
            vec![vec!["uart0".to_string(), "emit_byte".to_string()]]
        );

        let rendered = render_backend_text(&backend);
        assert!(rendered.contains(".machine devMachine.machine"));
        assert!(rendered.contains("final ret"));
        assert!(rendered.contains(".primitive devPrimitive.primitive"));

        let object = emit_object(&backend);
        assert!(object
            .sections
            .iter()
            .any(|sec| sec.name == ".machine.devMachine.machine"
                && sec.kind == BackendObjectSectionKindIR::Machine));
        let machine_section = object
            .sections
            .iter()
            .find(|sec| sec.name == ".machine.devMachine.machine")
            .expect("machine section");
        let machine_bytes = machine_section
            .bytes
            .as_ref()
            .expect("machine section must have native bytes");
        assert_eq!(
            machine_bytes.first().copied(),
            Some(0x90),
            "starts with nop"
        );
        assert!(
            machine_bytes.contains(&0xE9),
            "must include near jmp opcode"
        );
        assert_eq!(machine_bytes.last().copied(), Some(0xC3), "ends with ret");
        assert!(object
            .sections
            .iter()
            .any(|sec| sec.name == ".meta.devPrimitive.primitive"
                && sec.kind == BackendObjectSectionKindIR::PrimitiveMeta));
        assert!(object
            .relocations
            .iter()
            .any(|rel| rel.kind == BackendObjectRelocationKindIR::JumpNear32));
        assert!(
            object
                .relocations
                .iter()
                .any(|rel| rel.kind == BackendObjectRelocationKindIR::JumpNear32
                    && rel.symbol == "devMachine.machine.entryPoint"),
            "local machine label relocations must target qualified local symbol"
        );
    }

    #[test]
    fn emit_backend_materializes_typed_primitive_contracts_for_boot_serial_fixture() {
        let program = parse_primitive_fixture("primitive_at_boot_serial_short_header_ok.n");
        let ir = lower(program);
        let backend = emit_backend(&ir);
        let primitive = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Primitive(p) => Some(p),
                _ => None,
            })
            .expect("primitive backend unit");

        assert_eq!(primitive.target.as_deref(), Some("x86_64"));
        assert_eq!(primitive.capability_contracts.len(), 1);
        assert_eq!(primitive.bitfield_contracts.len(), 1);
        assert_eq!(primitive.operation_contracts.len(), 1);
        assert_eq!(primitive.window_contracts.len(), 1);
        assert_eq!(primitive.signal_contracts.len(), 1);
        assert_eq!(primitive.port_contracts.len(), 2);
        assert_eq!(primitive.signature_contracts.len(), 1);
        assert_eq!(primitive.entry_contracts.len(), 0);

        let cap = &primitive.capability_contracts[0];
        assert_eq!(cap.name, "boot_serial_io");
        assert_eq!(cap.allow.len(), 3);
        assert_eq!(cap.deny.len(), 3);

        let op = &primitive.operation_contracts[0];
        assert_eq!(op.name, vec!["uart0".to_string(), "emit_byte".to_string()]);
        assert_eq!(op.capability_refs, vec![vec!["boot_serial_io".to_string()]]);
        assert_eq!(
            op.reads_refs,
            vec![vec!["uart0".to_string(), "status".to_string()]]
        );
        assert_eq!(
            op.writes_refs,
            vec![vec!["uart0".to_string(), "data".to_string()]]
        );

        let signal = &primitive.signal_contracts[0];
        assert_eq!(
            signal.source_refs,
            vec![vec!["uart0".to_string(), "status".to_string()]]
        );
        assert_eq!(
            signal.field_refs,
            vec![vec!["uart_status".to_string(), "tx_empty".to_string()]]
        );

        let window = &primitive.window_contracts[0];
        assert_eq!(window.name, vec!["boot_sector".to_string()]);
        assert_eq!(
            window.requires_signature_refs,
            vec![vec!["boot_magic".to_string()]]
        );

        let rendered = render_backend_text(&backend);
        assert!(rendered.contains("cap_contracts=1"));
        assert!(rendered.contains("window_contracts=1"));
        assert!(rendered.contains("; capability boot_serial_io allow=3 deny=3"));
        assert!(rendered.contains("; operation uart0.emit_byte clauses="));
        assert!(rendered.contains("; window boot_sector clauses="));
        assert!(rendered.contains("; signal uart0.tx_ready clauses="));

        let object = emit_object(&backend);
        let section = object
            .sections
            .iter()
            .find(|sec| sec.kind == BackendObjectSectionKindIR::PrimitiveMeta)
            .expect("primitive meta section");
        let text = String::from_utf8(section.bytes.clone().expect("meta payload bytes"))
            .expect("meta bytes should stay utf8");
        assert!(text.contains("capability_contracts 1"));
        assert!(text.contains("bitfield uart_status base=byte entries=8"));
        assert!(text.contains("bridge root.policy.bind"));
        assert!(text.contains("operation uart0.emit_byte clauses="));
        assert!(text.contains("window boot_sector clauses="));

        let entry_program = parse_primitive_fixture("primitive_at_anchor_inline_clause_ok.n");
        let entry_backend = emit_backend(&lower(entry_program));
        let entry_primitive = entry_backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Primitive(p) => Some(p),
                _ => None,
            })
            .expect("primitive backend unit for entry fixture");
        assert_eq!(entry_primitive.entry_contracts.len(), 1);
        let entry = &entry_primitive.entry_contracts[0];
        assert_eq!(entry.name, vec!["boot_entry".to_string()]);
        assert_eq!(entry.anchor_refs, vec![vec!["boot0".to_string()]]);
        assert_eq!(entry.requires_refs, vec![vec!["boot_magic".to_string()]]);
    }

    #[test]
    fn emit_backend_materializes_type_contract_clause_opcodes() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "typespace".into(),
                context: Some(Context::Runtime),
                sections: vec![Section::TypeContracts(vec![TypeContractDecl {
                    name: "Account".into(),
                    kind: TypeContractKind::Struct,
                    generic_params: vec![],
                    variants: vec![],
                    clauses: vec![
                        TypeContractClause::Fields {
                            visibility: Visibility::Public,
                            fields: vec![
                                TypeContractField {
                                    name: "id".into(),
                                    ty: TypeName::Simple("int".into()),
                                },
                                TypeContractField {
                                    name: "balance".into(),
                                    ty: TypeName::Simple("int".into()),
                                },
                            ],
                        },
                        TypeContractClause::Fields {
                            visibility: Visibility::Private,
                            fields: vec![TypeContractField {
                                name: "pin".into(),
                                ty: TypeName::Simple("qword".into()),
                            }],
                        },
                        TypeContractClause::Fields {
                            visibility: Visibility::Internal,
                            fields: vec![TypeContractField {
                                name: "checksum".into(),
                                ty: TypeName::Simple("qword".into()),
                            }],
                        },
                        TypeContractClause::Fields {
                            visibility: Visibility::Strictly,
                            fields: vec![TypeContractField {
                                name: "owner".into(),
                                ty: TypeName::Simple("int".into()),
                            }],
                        },
                        TypeContractClause::Layout(vec!["kind: binary;".into()]),
                        TypeContractClause::Bounds(vec!["balance: range(0..1000);".into()]),
                        TypeContractClause::Invariant(vec!["@balance >= 0;".into()]),
                        TypeContractClause::Constructure(vec![
                            "static(id: int, balance: int) -> Account;".into(),
                        ]),
                        TypeContractClause::Destructure(vec!["static -> { id, balance };".into()]),
                        TypeContractClause::Copy(vec!["shallow denied;".into()]),
                        TypeContractClause::Clone(vec!["deep allowed;".into()]),
                        TypeContractClause::Move(vec!["allowed;".into()]),
                        TypeContractClause::Ffi(vec!["repr: C;".into()]),
                        TypeContractClause::Ownership(vec!["balance: owned;".into()]),
                        TypeContractClause::Nullability(vec!["pin: nonNull;".into()]),
                        TypeContractClause::Methods(vec![
                            "debit(self: ref<Account>, amount: int) -> bool;".into(),
                        ]),
                        TypeContractClause::Associated(vec![
                            "open(id: int, balance: int) -> Account;".into(),
                        ]),
                        TypeContractClause::Validate(vec!["balance: range(0..1000);".into()]),
                        TypeContractClause::Drop(vec!["release(balance);".into()]),
                        TypeContractClause::Default(vec!["zero;".into()]),
                        TypeContractClause::Compare(vec![
                            "eq(self: ref<Account>, other: ref<Account>) -> bool;".into(),
                        ]),
                        TypeContractClause::Hash(vec!["stable;".into()]),
                        TypeContractClause::Debug(vec!["printable;".into()]),
                        TypeContractClause::Stable(vec!["deterministic;".into()]),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let type_unit = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::TypeContract(u) if u.container == "typespace" => Some(u),
                _ => None,
            })
            .expect("type contract backend unit");

        assert_eq!(type_unit.abi_layouts.len(), 1);
        let abi = &type_unit.abi_layouts[0];
        assert_eq!(abi.qualified_name, "typespace.Account");
        assert_eq!(abi.status, "stable_type_abi_v1");
        assert_eq!(abi.size_bytes, 32);
        assert_eq!(abi.align_bytes, 8);
        assert_eq!(abi.field_count, 5);
        assert_eq!(abi.fields[0].name, "id");
        assert_eq!(abi.fields[0].offset_bytes, 0);
        assert_eq!(abi.fields[1].name, "balance");
        assert_eq!(abi.fields[1].offset_bytes, 4);
        assert_eq!(abi.fields[2].name, "pin");
        assert_eq!(abi.fields[2].offset_bytes, 8);
        assert_eq!(abi.fields[3].name, "checksum");
        assert_eq!(abi.fields[3].offset_bytes, 16);
        assert_eq!(abi.fields[4].name, "owner");
        assert_eq!(abi.fields[4].offset_bytes, 24);
        assert_eq!(abi.fingerprint.len(), 16);

        assert!(type_unit.ops.iter().any(
            |op| matches!(op, BackendTypeContractOpIR::TypeDeclStart { ty, .. } if ty == "Account")
        ));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::FieldsPublicField {
                ty,
                field,
                field_ty
            } if ty == "Account" && field == "balance" && field_ty == "int"
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::FieldsPrivateField {
                ty,
                field,
                field_ty
            } if ty == "Account" && field == "pin" && field_ty == "qword"
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::FieldsInternalField {
                ty,
                field,
                field_ty
            } if ty == "Account" && field == "checksum" && field_ty == "qword"
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::FieldsStrictlyField {
                ty,
                field,
                field_ty
            } if ty == "Account" && field == "owner" && field_ty == "int"
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::LayoutClause { ty, item } if ty == "Account" && item.as_deref() == Some("kind: binary;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::BoundsClause { ty, item } if ty == "Account" && item.as_deref() == Some("balance: range(0..1000);")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::InvariantClause { ty, item } if ty == "Account" && item.as_deref() == Some("@balance >= 0;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::ConstructureClause { ty, item } if ty == "Account" && item.as_deref() == Some("static(id: int, balance: int) -> Account;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::DestructureClause { ty, item } if ty == "Account" && item.as_deref() == Some("static -> { id, balance };")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::CopyClause { ty, item } if ty == "Account" && item.as_deref() == Some("shallow denied;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::CloneClause { ty, item } if ty == "Account" && item.as_deref() == Some("deep allowed;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::MoveClause { ty, item } if ty == "Account" && item.as_deref() == Some("allowed;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::FfiClause { ty, item } if ty == "Account" && item.as_deref() == Some("repr: C;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::OwnershipClause { ty, item } if ty == "Account" && item.as_deref() == Some("balance: owned;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::NullabilityClause { ty, item } if ty == "Account" && item.as_deref() == Some("pin: nonNull;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::MethodsClause { ty, item } if ty == "Account" && item.as_deref() == Some("debit(self: ref<Account>, amount: int) -> bool;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::AssociatedClause { ty, item } if ty == "Account" && item.as_deref() == Some("open(id: int, balance: int) -> Account;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::ValidateClause { ty, item } if ty == "Account" && item.as_deref() == Some("balance: range(0..1000);")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::DropClause { ty, item } if ty == "Account" && item.as_deref() == Some("release(balance);")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::DefaultClause { ty, item } if ty == "Account" && item.as_deref() == Some("zero;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::CompareClause { ty, item } if ty == "Account" && item.as_deref() == Some("eq(self: ref<Account>, other: ref<Account>) -> bool;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::HashClause { ty, item } if ty == "Account" && item.as_deref() == Some("stable;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::DebugClause { ty, item } if ty == "Account" && item.as_deref() == Some("printable;")
        )));
        assert!(type_unit.ops.iter().any(|op| matches!(
            op,
            BackendTypeContractOpIR::StableClause { ty, item } if ty == "Account" && item.as_deref() == Some("deterministic;")
        )));

        let rendered = render_backend_text(&backend);
        assert!(rendered.contains(".type_contracts typespace.type_contracts"));
        assert!(rendered.contains("abi typespace.Account kind=struct status=stable_type_abi_v1 size=32 align=8 fields=5 fingerprint="));
        assert!(
            rendered.contains(
                "abi_field typespace.Account.pin index=2 ty=qword llvm=i64 offset=8 size=8 align=8"
            ),
            "rendered type ABI must expose the validated pin field layout:\n{rendered}"
        );
        assert!(rendered.contains("TC_LAYOUT Account"));
        assert!(rendered.contains("TC_BOUNDS Account"));
        assert!(rendered.contains("TC_INVARIANT Account"));
        assert!(rendered.contains("TC_CONSTRUCTURE Account"));
        assert!(rendered.contains("TC_DESTRUCTURE Account"));
        assert!(rendered.contains("TC_COPY Account"));
        assert!(rendered.contains("TC_CLONE Account"));
        assert!(rendered.contains("TC_MOVE Account"));
        assert!(rendered.contains("TC_FFI Account"));
        assert!(rendered.contains("TC_OWNERSHIP Account"));
        assert!(rendered.contains("TC_NULLABILITY Account"));
        assert!(rendered.contains("TC_METHODS Account"));
        assert!(rendered.contains("TC_ASSOCIATED Account"));
        assert!(rendered.contains("TC_VALIDATE Account"));
        assert!(rendered.contains("TC_DROP Account"));
        assert!(rendered.contains("TC_DEFAULT Account"));
        assert!(rendered.contains("TC_COMPARE Account"));
        assert!(rendered.contains("TC_HASH Account"));
        assert!(rendered.contains("TC_DEBUG Account"));
        assert!(rendered.contains("TC_STABLE Account"));

        let object = emit_object(&backend);
        let meta = object
            .sections
            .iter()
            .find(|sec| sec.name == ".meta.type.typespace")
            .expect("type meta section");
        let payload = String::from_utf8(meta.bytes.clone().expect("meta payload bytes"))
            .expect("type meta payload utf8");
        assert!(payload.contains("type_abi typespace.Account kind=struct status=stable_type_abi_v1 size=32 align=8 fields=5 fingerprint="));
        assert!(payload.contains(
            "type_abi_field typespace.Account.owner index=4 ty=int llvm=i32 offset=24 size=4 align=4"
        ));
        assert!(payload.contains("tc_op TC_LAYOUT Account"));
        assert!(payload.contains("tc_op TC_BOUNDS Account"));
        assert!(payload.contains("tc_op TC_CONSTRUCTURE Account"));
        assert!(payload.contains("tc_op TC_FFI Account"));
        assert!(payload.contains("tc_op TC_DROP Account"));
        assert!(payload.contains("tc_op TC_STABLE Account"));
    }

    #[test]
    fn verify_type_contract_backend_enforcement_rejects_missing_type_opcode() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "typespace".into(),
                context: Some(Context::Runtime),
                sections: vec![Section::TypeContracts(vec![TypeContractDecl {
                    name: "OnlyDrop".into(),
                    kind: TypeContractKind::Struct,
                    generic_params: vec![],
                    variants: vec![],
                    clauses: vec![
                        TypeContractClause::Fields {
                            visibility: Visibility::Public,
                            fields: vec![TypeContractField {
                                name: "id".into(),
                                ty: TypeName::Simple("int".into()),
                            }],
                        },
                        TypeContractClause::Drop(vec!["release(id);".into()]),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let mut backend = emit_backend(&ir);
        for unit in &mut backend.units {
            if let BackendUnitIR::TypeContract(type_unit) = unit {
                type_unit
                    .ops
                    .retain(|op| !matches!(op, BackendTypeContractOpIR::DropClause { .. }));
            }
        }

        let err = verify_type_contract_backend_enforcement(&ir, &backend)
            .expect_err("missing drop opcode must fail backend contract verification");
        assert!(
            err.contains("E_TYPE_CONTRACT_SECTION_001"),
            "expected section/opcode mismatch diagnostic, got {err}"
        );
    }

    #[test]
    fn emit_object_elf64_materializes_relocatable_header_and_tables() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![ncc_ast::UseDecl {
                path: vec!["system".into(), "net".into(), "core".into()],
                wildcard: false,
                alias: None,
            }],
            containers: vec![Container {
                visibility: None,
                name: "entry".into(),
                context: Some(Context::System),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "boot".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![
                        Stmt::Expr(Expr::QualifiedCall {
                            path: vec![
                                "system".into(),
                                "net".into(),
                                "core".into(),
                                "connect".into(),
                            ],
                            args: vec![
                                Expr::String("127.0.0.1".into()),
                                Expr::Number("8080".into()),
                            ],
                        }),
                        Stmt::Return(Expr::Bool(true)),
                    ],
                }])],
            }],
        };

        let ir = lower(program);
        let backend = emit_backend(&ir);
        let object = emit_object(&backend);
        let elf = emit_object_elf64(&object).expect("ELF64 emission must succeed");

        assert!(elf.len() > 64, "ELF must be larger than header");
        assert_eq!(&elf[0..4], b"\x7fELF");
        assert_eq!(elf[4], 2, "must be ELFCLASS64");
        assert_eq!(
            u16::from_le_bytes([elf[16], elf[17]]),
            1,
            "must be relocatable ET_REL"
        );
        assert_eq!(
            u16::from_le_bytes([elf[18], elf[19]]),
            62,
            "must be EM_X86_64"
        );

        let bytes = String::from_utf8_lossy(&elf);
        assert!(bytes.contains(".symtab"));
        assert!(bytes.contains(".strtab"));
        assert!(bytes.contains(".rela.text.entry.boot"));
        assert!(
            bytes.contains(".note.GNU-stack"),
            "ELF object must carry non-executable stack marker"
        );
    }

