    #[test]
    fn scalar_standalone_lowers_string_params_returns_and_nested_modulo() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "textFlow".into(),
                context: Some(Context::Runtime),
                sections: vec![Section::Fn(vec![
                    FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "name".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![Param {
                            name: "id".into(),
                            ty: TypeName::Simple("int".into()),
                        }],
                        return_type: TypeName::Simple("str".into()),
                        public_body: vec![
                            Stmt::If {
                                condition: Expr::Binary {
                                    left: Box::new(Expr::Identifier("id".into())),
                                    op: BinaryOp::EqEq,
                                    right: Box::new(Expr::Number("1".into())),
                                },
                                then_block: vec![Stmt::Return(Expr::String("uno".into()))],
                                else_block: vec![],
                            },
                            Stmt::Return(Expr::String("otro".into())),
                        ],
                    },
                    FunctionDecl {
                        is_async: false,
                        effects: vec![],
                        visibility: None,
                        name: "show".into(),
                        generic_params: Vec::new(),
                        generic_bounds: Vec::new(),
                        params: vec![
                            Param {
                                name: "label".into(),
                                ty: TypeName::Simple("str".into()),
                            },
                            Param {
                                name: "id".into(),
                                ty: TypeName::Simple("int".into()),
                            },
                        ],
                        return_type: TypeName::Simple("bool".into()),
                        public_body: vec![
                            Stmt::Print {
                                kind: PrintKind::Ln,
                                value: Expr::Binary {
                                    left: Box::new(Expr::Binary {
                                        left: Box::new(Expr::Binary {
                                            left: Box::new(Expr::String("item=".into())),
                                            op: BinaryOp::Plus,
                                            right: Box::new(Expr::Identifier("label".into())),
                                        }),
                                        op: BinaryOp::Plus,
                                        right: Box::new(Expr::Call {
                                            callee: "name".into(),
                                            args: vec![Expr::Identifier("id".into())],
                                        }),
                                    }),
                                    op: BinaryOp::Plus,
                                    right: Box::new(Expr::Call {
                                        callee: "renderInt".into(),
                                        args: vec![Expr::Binary {
                                            left: Box::new(Expr::Number("10".into())),
                                            op: BinaryOp::Plus,
                                            right: Box::new(Expr::Binary {
                                                left: Box::new(Expr::Identifier("id".into())),
                                                op: BinaryOp::Percent,
                                                right: Box::new(Expr::Number("7".into())),
                                            }),
                                        }],
                                    }),
                                },
                            },
                            Stmt::Return(Expr::Bool(true)),
                        ],
                    },
                ])],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let backend = emit_backend(&ir);
        let rendered = render_backend_text(&backend);
        assert!(rendered.contains(".fn textFlow.name"));
        assert!(rendered.contains("lea rax, cstr(\"uno\") ; scalar-load-cstr"));
        assert!(rendered.contains("mov [rsp+0], rdi ; scalar-store-stack"));
        assert!(rendered.contains("mov [rsp+8], rsi ; scalar-store-stack"));
        assert!(rendered.contains("call textFlow.name ; argc=1 stack_args=0B scalar-call"));
        assert!(rendered.contains("idiv r10 ; scalar-div"));

        let object = emit_object(&backend);
        let show = object
            .sections
            .iter()
            .find(|section| section.name == ".text.textFlow.show")
            .expect("show text section");
        let bytes = show.bytes.as_ref().expect("show must have native bytes");
        assert_eq!(bytes.first().copied(), Some(0x55));
        assert!(bytes.windows(2).any(|pair| pair == [0x48, 0x89]));
    }

    #[test]
    fn scalar_standalone_lowers_interactive_runtime_wrappers_inside_if_while() {
        let idx_ref = || Expr::Identifier("idx".into());
        let value_ref = || Expr::Identifier("value".into());
        let render_idx = || Expr::Call {
            callee: "renderInt".into(),
            args: vec![idx_ref()],
        };
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "interactiveRich".into(),
                context: Some(Context::Runtime),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "run".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![
                        Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec!["idx".into()])),
                            ty: TypeName::Simple("int".into()),
                            value: Expr::Number("0".into()),
                        },
                        Stmt::Projection {
                            target: AssignTarget::Context(ContextRef::plain(vec!["value".into()])),
                            ty: TypeName::Simple("int".into()),
                            value: Expr::Call {
                                callee: "readInt".into(),
                                args: vec![],
                            },
                        },
                        Stmt::While {
                            condition: Expr::Binary {
                                left: Box::new(idx_ref()),
                                op: BinaryOp::Less,
                                right: Box::new(Expr::Number("2".into())),
                            },
                            body: vec![
                                Stmt::If {
                                    condition: Expr::Binary {
                                        left: Box::new(value_ref()),
                                        op: BinaryOp::Greater,
                                        right: Box::new(idx_ref()),
                                    },
                                    then_block: vec![Stmt::Print {
                                        kind: PrintKind::Ln,
                                        value: Expr::Call {
                                            callee: "color".into(),
                                            args: vec![
                                                Expr::Call {
                                                    callee: "concat".into(),
                                                    args: vec![
                                                        Expr::String("slot=".into()),
                                                        render_idx(),
                                                    ],
                                                },
                                                Expr::String("green".into()),
                                            ],
                                        },
                                    }],
                                    else_block: vec![Stmt::Print {
                                        kind: PrintKind::Ln,
                                        value: Expr::Call {
                                            callee: "colorBold".into(),
                                            args: vec![
                                                Expr::String("skip".into()),
                                                Expr::String("yellow".into()),
                                            ],
                                        },
                                    }],
                                },
                                Stmt::Print {
                                    kind: PrintKind::Ln,
                                    value: Expr::Call {
                                        callee: "concat".into(),
                                        args: vec![
                                            Expr::String("emoji=".into()),
                                            Expr::Call {
                                                callee: "emoji".into(),
                                                args: vec![Expr::String("rocket".into())],
                                            },
                                        ],
                                    },
                                },
                                Stmt::Print {
                                    kind: PrintKind::Ln,
                                    value: Expr::Call {
                                        callee: "bgColor".into(),
                                        args: vec![
                                            Expr::String("cabecera".into()),
                                            Expr::String("blue".into()),
                                        ],
                                    },
                                },
                                Stmt::Print {
                                    kind: PrintKind::Ln,
                                    value: Expr::Call {
                                        callee: "style".into(),
                                        args: vec![
                                            Expr::String("subrayado".into()),
                                            Expr::String("underline".into()),
                                        ],
                                    },
                                },
                                Stmt::Projection {
                                    target: AssignTarget::Context(ContextRef::plain(vec![
                                        "idx".into()
                                    ])),
                                    ty: TypeName::Simple("int".into()),
                                    value: Expr::Binary {
                                        left: Box::new(idx_ref()),
                                        op: BinaryOp::Plus,
                                        right: Box::new(Expr::Number("1".into())),
                                    },
                                },
                            ],
                        },
                        Stmt::Return(Expr::Bool(true)),
                    ],
                }])],
            }],
        };

        let ir = lower_with_backend_profile(program, BackendLoweringProfileIR::nc_sysv64());
        let backend = emit_backend(&ir);
        let rendered = render_backend_text(&backend);
        let func = backend
            .units
            .iter()
            .find_map(|unit| match unit {
                BackendUnitIR::Function(func) if func.symbol == "interactiveRich.run" => Some(func),
                _ => None,
            })
            .expect("interactiveRich.run backend unit");
        let scalar_ops = func
            .ops
            .iter()
            .find_map(|op| match op {
                BackendFuncOpIR::ScalarOps { ops } => Some(ops),
                _ => None,
            })
            .expect("interactive rich flow must use scalar native lowering");

        assert!(scalar_ops
            .iter()
            .any(|op| matches!(op, BackendScalarOpIR::CompareJump { .. })));
        assert!(scalar_ops
            .iter()
            .any(|op| matches!(op, BackendScalarOpIR::Jump { .. })));
        assert!(
            rendered.contains("call nC.runtime.input.readInt ; argc=0 stack_args=0B scalar-call")
        );
        assert!(rendered.contains("call printf ; argc=2 stack_args=0B scalar-call"));
        for unexpected in ["concat", "color", "colorBold", "bgColor", "style", "emoji"] {
            assert!(
                !rendered.contains(&format!("call {unexpected} ")),
                "rich text wrapper '{unexpected}' must not escape as a standalone symbol"
            );
        }

        let object = emit_object(&backend);
        let text = object
            .sections
            .iter()
            .find(|section| section.name == ".text.interactiveRich.run")
            .expect("run text section");
        assert!(
            text.bytes.as_ref().is_some_and(|bytes| !bytes.is_empty()),
            "interactive if/while runtime flow must emit physical text bytes"
        );
        let unresolved = object.unresolved_symbols();
        assert!(unresolved.contains(&"printf".to_string()));
        assert!(unresolved.contains(&"nC.runtime.input.readInt".to_string()));
        for unexpected in ["concat", "color", "colorBold", "bgColor", "style", "emoji"] {
            assert!(
                !unresolved.contains(&unexpected.to_string()),
                "rich text wrapper '{unexpected}' must lower before object linking"
            );
        }
    }

