    #[test]
    fn emit_image_sovereign_materializes_native_image_header_and_counts() {
        let program = Program {
            modules: vec![],
            packages: vec![],
            uses: vec![],
            containers: vec![Container {
                visibility: None,
                name: "rootBoot".into(),
                context: Some(Context::Root),
                sections: vec![Section::Fn(vec![FunctionDecl {
                    is_async: false,
                    effects: vec![],
                    visibility: None,
                    name: "main".into(),
                    generic_params: Vec::new(),
                    generic_bounds: Vec::new(),
                    params: vec![],
                    return_type: TypeName::Simple("bool".into()),
                    public_body: vec![Stmt::Return(Expr::Bool(true))],
                }])],
            }],
        };

        let ir = lower_with_backend_profile(program, sovereign_profile());
        let backend = emit_backend(&ir);
        let object = emit_object(&backend);
        let image = emit_image_sovereign(&object).expect("sovereign image emission must succeed");

        assert!(image.len() > 28);
        assert_eq!(&image[0..8], b"NCSOVIMG");
        assert_eq!(u16::from_le_bytes([image[8], image[9]]), 1);
        assert_eq!(u16::from_le_bytes([image[10], image[11]]), 64);

        let sections = u32::from_le_bytes([image[12], image[13], image[14], image[15]]);
        let symbols = u32::from_le_bytes([image[16], image[17], image[18], image[19]]);
        let relocs = u32::from_le_bytes([image[20], image[21], image[22], image[23]]);
        assert!(sections >= 1);
        assert!(symbols >= 1);
        assert_eq!(relocs, 0);
    }

