    #[test]
    fn link_image_sovereign_materializes_linked_header_and_entry_address() {
        let object = BackendObjectIR {
            target: BackendTargetIR::X86_64,
            target_spec: sovereign_profile().target_spec,
            sections: vec![BackendObjectSectionIR {
                name: ".text.demo".into(),
                kind: BackendObjectSectionKindIR::Text,
                unit: "demo".into(),
                lines: vec![],
                bytes: Some(vec![0xE8, 0x00, 0x00, 0x00, 0x00, 0xC3]),
                size_bytes: 6,
                align_bytes: 16,
                comdat: None,
            }],
            symbols: vec![
                BackendObjectSymbolIR {
                    name: "root.main".into(),
                    section: ".text.demo".into(),
                    offset: 0,
                    visibility: BackendSymbolVisibilityIR::Global,
                },
                BackendObjectSymbolIR {
                    name: "demo.callee".into(),
                    section: ".text.demo".into(),
                    offset: 5,
                    visibility: BackendSymbolVisibilityIR::Local,
                },
            ],
            relocations: vec![BackendObjectRelocationIR {
                section: ".text.demo".into(),
                offset: 1,
                kind: BackendObjectRelocationKindIR::CallNear32,
                symbol: "demo.callee".into(),
                addend: -4,
            }],
        };

        let image = link_image_sovereign(&object, Some("root.main"))
            .expect("sovereign link image emission must succeed");
        assert!(image.len() > 56);
        assert_eq!(&image[0..8], b"NCSOVLNK");
        assert_eq!(u16::from_le_bytes([image[8], image[9]]), 1);
        let entry_addr = u64::from_le_bytes([
            image[24], image[25], image[26], image[27], image[28], image[29], image[30], image[31],
        ]);
        assert_eq!(entry_addr, 0x0010_0000);

        // Relocation should patch call disp32 to zero when target is exactly next instruction.
        assert!(image
            .windows(6)
            .any(|w| w == [0xE8, 0x00, 0x00, 0x00, 0x00, 0xC3]));
    }

